INSERT INTO `galleries` (`id`, `name`, `description`, `is_featured`, `order`, `image`, `user_id`, `status`, `created_at`, `updated_at`) VALUES
(6, 'ẢNH TOÀN CẢNH', '<p>Khám phá không gian tổng thể tinh tế và đẳng cấp, nơi từng chi tiết được chăm chút nhằm mang đến trải nghiệm nghỉ dưỡng trọn vẹn và khác biệt.</p>', 0, 0, NULL, NULL, 'published', '2026-04-01 07:58:59', '2026-04-07 07:27:12'),
(7, 'ẢNH PHÒNG', '<p>Không gian lưu trú sang trọng, tiện nghi tinh tế, mang đến cảm giác thư thái tuyệt đối và sự riêng tư trọn vẹn.</p>', 0, 1, NULL, NULL, 'published', '2026-04-01 08:00:17', '2026-06-15 06:49:35'),
(8, 'ẢNH NHÀ HÀNG', '<p>Hành trình ẩm thực đặc sắc với những hương vị tinh tuyển, được chế biến công phu trong không gian đẳng cấp.</p>', 0, 2, NULL, NULL, 'published', '2026-04-01 08:00:46', '2026-04-07 07:25:01'),
(9, 'GIẢI TRÍ', '<p>Chuỗi tiện ích giải trí đa dạng, nơi tái tạo năng lượng và tận hưởng những khoảnh khắc thư giãn trọn vẹn.</p>', 0, 3, NULL, NULL, 'published', '2026-04-01 08:02:55', '2026-06-19 02:19:15'),
(10, 'SPA', '<p>Không gian trị liệu yên bình, kết hợp liệu pháp chuyên sâu giúp cân bằng thân – tâm – trí.</p>', 0, 4, NULL, NULL, 'published', '2026-04-01 08:09:00', '2026-04-03 08:37:32'),
(11, 'SỰ KIỆN', '<p><br><br><br><br><br>Không gian tổ chức sự kiện sang trọng, linh hoạt, lý tưởng cho những khoảnh khắc đáng nhớ và thành công trọn vẹn.</p>', 0, 5, NULL, NULL, 'published', '2026-04-01 08:09:29', '2026-07-28 06:56:49');
INSERT INTO `galleries_translations` (`lang_code`, `galleries_id`, `name`, `description`) VALUES
('en_US', 6, 'PANORAMIC VIEW', '<p>Discover an exquisitely refined and prestigious overall space, where every detail is meticulously crafted to deliver a complete and distinctive relaxation retreat experience.</p>'),
('en_US', 7, 'ROOM PHOTOGRAPHS', '<p>Luxurious accommodations with exquisite amenities, offering an unparalleled sense of tranquility and complete privacy.</p>'),
('en_US', 8, 'RESTAURANT PHOTOS', '<p>An exquisite culinary journey featuring carefully selected flavors, masterfully crafted within a sophisticated ambiance.</p>'),
('en_US', 9, 'ENTERTAINMENT', '<p>A diverse array of entertainment amenities, where you can rejuvenate your energy and savor moments of complete relaxation.</p>'),
('en_US', 10, 'SPA', '<p>Không gian trị liệu yên bình, kết hợp liệu pháp chuyên sâu giúp cân bằng thân – tâm – trí.</p>'),
('en_US', 11, 'EVENTS', '<p><br><br><br><br><br>An elegant and versatile event space, ideal for creating memorable moments and ensuring complete success.</p>');
