INSERT INTO `ht_services` (`id`, `name`, `description`, `content`, `price`, `price_type`, `currency_id`, `image`, `custom_url`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Sảnh Lễ Tân', 'Quầy lễ tân phục vụ 24/7, hỗ trợ nhận phòng, trả phòng, giữ hành lý và tư vấn thông tin du lịch Vũng Tàu. Khu vực chờ có ghế ngồi thoải mái và nước uống miễn phí.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Quầy lễ tân phục vụ 24/7, hỗ trợ nhận phòng, trả phòng, giữ hành lý và tư vấn thông tin du lịch Vũng Tàu. Khu vực chờ có ghế ngồi thoải mái và nước uống miễn phí.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1621293954908-907159247fc8?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Sảnh Lễ Tân\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Sảnh Lễ Tân\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL, 'once', NULL, 'https://api.iconify.design/mdi/room-service-outline.svg?width=256&color=%230E4D97', NULL, 'published', '2025-06-10 10:38:07', '2026-04-07 07:04:47'),
(2, 'Hồ Bơi', 'Hồ bơi ngoài trời dành riêng cho khách lưu trú, mở cửa từ 6h00 đến 21h00. Có ghế nằm, dù che nắng và khăn tắm miễn phí.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Hồ bơi ngoài trời dành riêng cho khách lưu trú, mở cửa từ 6h00 đến 21h00. Có ghế nằm, dù che nắng và khăn tắm miễn phí.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Hồ Bơi\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1527359443443-84a48aec73d2?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Hồ Bơi\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL, 'once', NULL, 'https://api.iconify.design/mdi/pool.svg?width=256&color=%230E4D97', NULL, 'published', '2025-06-10 10:38:07', '2026-04-04 07:32:58'),
(3, 'Sauna &amp; Jacuzzi', 'Tọa lạc tại tầng 7, Sauna Zone - Ruby 68 Hotel là không gian thư giãn lý tưởng giúp tái tạo năng lượng sau một ngày dài khám phá Vũng Tàu. Khu vực được trang bị sauna khô, sauna ướt và jacuzzi nóng – lạnh, mang đến trải nghiệm thư giãn toàn diện, hỗ trợ tuần hoàn và phục hồi cơ thể hiệu quả.', '<div class=\"service-detail\"><div class=\"content-box\"><h2>Sauna &amp; Jacuzzi</h2><p>Tọa lạc tại tầng 7, Sauna Zone tại Ruby 68 Hotel là không gian thư giãn lý tưởng giúp tái tạo năng lượng sau một ngày dài khám phá Vũng Tàu.</p><div class=\"two-column\"><div class=\"row\"><div class=\"image-column col-xl-6 col-lg-12 col-md-12\"><figure class=\"image\"><img src=\"https://images.unsplash.com/photo-1507652313519-d4e9174996dd?auto=format&fit=crop&w=1600&q=80\" alt=\"Sauna &amp; Jacuzzi - Ruby 68 Hotel\"></figure></div><div class=\"text-column col-xl-6 col-lg-12 col-md-12\"><figure class=\"image\"><img src=\"https://images.unsplash.com/photo-1631889993959-41b4e9c6e3c5?auto=format&fit=crop&w=1600&q=80\" alt=\"Sauna &amp; Jacuzzi - Ruby 68 Hotel\"></figure></div></div></div><h3>Thư giãn toàn diện cho cơ thể</h3><p>Khu vực được trang bị sauna khô, sauna ướt và jacuzzi nóng – lạnh, mang đến trải nghiệm thư giãn toàn diện, hỗ trợ tuần hoàn và phục hồi cơ thể hiệu quả.</p><p>Không gian yên tĩnh, riêng tư kết hợp cùng tiện nghi chuẩn 3 sao giúp mỗi khoảnh khắc thư giãn trở nên trọn vẹn và tinh tế.</p><h3>Giờ mở cửa</h3><p>Mở cửa hàng ngày từ 10:00 đến 23:00.</p><div class=\"two-column\"><div class=\"row\"><div class=\"image-column col-xl-12 col-lg-12 col-md-12\"><figure class=\"image\"><img src=\"https://images.unsplash.com/photo-1560750588-73207b1ef5b8?auto=format&fit=crop&w=1600&q=80\" alt=\"Sauna &amp; Jacuzzi - Ruby 68 Hotel\"></figure></div></div></div></div></div>', '50', 'once', NULL, 'https://images.unsplash.com/photo-1600334089648-b0d9d3028eb2?auto=format&fit=crop&w=1320&h=1020&q=80', NULL, 'draft', '2025-06-10 10:38:07', '2026-04-06 01:33:56'),
(4, 'Bãi Đỗ Xe', 'Bãi đỗ xe miễn phí cho khách lưu trú, có mái che và bảo vệ trực 24/7. Nhận giữ cả ô tô và xe máy.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Bãi đỗ xe miễn phí cho khách lưu trú, có mái che và bảo vệ trực 24/7. Nhận giữ cả ô tô và xe máy.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1470224114660-3f6686c562eb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Bãi Đỗ Xe\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1590674899484-d5640e854abe?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Bãi Đỗ Xe\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL, 'once', NULL, 'https://api.iconify.design/mdi/parking.svg?width=256&color=%230E4D97', NULL, 'published', '2025-06-10 10:38:07', '2026-04-06 01:43:32'),
(5, 'Ruby Spa', 'Tọa lạc tại tầng 6 khách sạn, trong không gian yên tĩnh và riêng tư, Ruby Spa là điểm đến lý tưởng để tái tạo năng lượng và cân bằng cảm xúc.', '<div class=\"service-detail\"><div class=\"content-box\"><h2>Ruby Spa</h2><p>Tọa lạc tại tầng 6 khách sạn, trong không gian yên tĩnh và riêng tư, Ruby Spa là điểm đến lý tưởng để tái tạo năng lượng và cân bằng cảm xúc.</p><div class=\"two-column\"><div class=\"row\"><div class=\"image-column col-xl-6 col-lg-12 col-md-12\"><figure class=\"image\"><img src=\"https://images.unsplash.com/photo-1560750588-73207b1ef5b8?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa - Ruby 68 Hotel\"></figure></div><div class=\"text-column col-xl-6 col-lg-12 col-md-12\"><figure class=\"image\"><img src=\"https://images.unsplash.com/photo-1620733723572-11c53f73a416?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa - Ruby 68 Hotel\"></figure></div></div></div><h3>Liệu trình trị liệu chuyên sâu</h3><p>Các liệu trình được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuyên sâu và nguyên liệu cao cấp, mang đến trải nghiệm thư giãn toàn diện cho cơ thể và tâm trí.</p><p>Từ massage thư giãn, chăm sóc da đến các liệu pháp phục hồi, mỗi hành trình tại Ruby Spa đều được chăm chút tỉ mỉ, giúp bạn tận hưởng trọn vẹn sự an yên trong chuẩn mực dịch vụ 3 sao.</p><h3>Giờ mở cửa</h3><p>Mở cửa hàng ngày từ 10:00 đến 21:00.</p><div class=\"two-column\"><div class=\"row\"><div class=\"image-column col-xl-12 col-lg-12 col-md-12\"><figure class=\"image\"><img src=\"https://images.unsplash.com/photo-1620733723572-11c53f73a416?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa - Ruby 68 Hotel\"></figure></div></div></div></div></div>', '10', 'once', NULL, 'https://images.unsplash.com/photo-1560750588-73207b1ef5b8?auto=format&fit=crop&w=1320&h=1020&q=80', NULL, 'draft', '2025-06-10 10:38:07', '2026-04-03 03:10:57'),
(7, 'Ruby Sky Lounge', 'Tọa lạc trên tầng cao nhất của Ruby 68 Hotel, Ruby Sky Lounge mang đến trải nghiệm giải trí đẳng cấp với tầm nhìn toàn cảnh biển Bãi Sau rực rỡ về đêm.', '<div class=\"ts-hero\" style=\"background-color:rgb(11,11,11);color:rgb(204,204,204);font-family:Arial, Helvetica, sans-serif;font-size:medium;font-style:normal;font-weight:400;margin:0px auto;max-width:1320px;padding:130px 30px 40px;word-spacing:0px;\"><div class=\"ts-hero-welcome\" style=\"color:rgb(201,168,76);font-family:Antonio, sans-serif;font-size:14px;font-weight:300;margin:0px 0px 10px;padding:0px;\">Welcome to</div><div class=\"ts-hero-main\" style=\"margin:0px;padding:0px;\"><h1 style=\"color:rgb(255,255,255);font-family:Antonio, sans-serif;font-weight:200;line-height:0.95;margin:0px;padding:0px;\">Ruby Sky Lounge</h1><figure class=\"image\"><img style=\"margin:0px;padding:0px;\" src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\" width=\"708\" height=\"471\"></figure></div></div><div class=\"ts-about\" style=\"color:rgb(204,204,204);font-family:Arial, Helvetica, sans-serif;font-size:medium;font-style:normal;font-weight:400;margin:0px auto;max-width:1320px;padding:50px 30px 40px;word-spacing:0px;\"><div class=\"ts-about-images\" style=\"margin:0px auto;max-width:500px;padding:0px;\"><figure class=\"image\"><img style=\"margin:0px;padding:0px;\" src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\" width=\"245\" height=\"435\"></figure><figure class=\"image\"><img style=\"margin:0px;padding:0px;\" src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\" width=\"245\" height=\"245\"></figure><figure class=\"image\"><img style=\"margin:0px;padding:0px;\" src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\" width=\"245\" height=\"245\"></figure></div><div class=\"ts-about-text\" style=\"margin:0px;padding:0px;\"><div class=\"ts-section-label\" style=\"color:rgb(201,168,76);font-family:Antonio, sans-serif;font-size:16px;font-weight:300;margin:0px 0px 14px;padding:0px;\">About</div><div class=\"ts-section-title\" style=\"color:rgb(255,255,255);font-family:Antonio, sans-serif;font-size:65px;font-weight:200;line-height:1.2;margin:0px 0px 24px;padding:0px;\">Where the Sky Meets the Sea</div><p style=\"color:rgb(153,153,153);font-family:Arial, Helvetica, sans-serif;font-size:18px;line-height:2;margin:0px 0px 14px;padding:0px;\">Tọa lạc trên tầng cao nhất của Ruby 68 Hotel, Ruby Sky Lounge mang đến trải nghiệm giải trí đẳng cấp với tầm nhìn toàn cảnh biển Bãi Sau rực rỡ về đêm.</p><p style=\"color:rgb(153,153,153);font-family:Arial, Helvetica, sans-serif;font-size:18px;line-height:2;margin:0px 0px 14px;padding:0px;\">Không gian rooftop hiện đại, âm nhạc sôi động cùng thực đơn cocktail sáng tạo tạo nên điểm hẹn lý tưởng cho những buổi tối đầy cảm hứng.</p><p style=\"color:rgb(153,153,153);font-family:Arial, Helvetica, sans-serif;font-size:18px;line-height:2;margin:0px 0px 14px;padding:0px;\">Dù là thư giãn nhẹ nhàng hay hòa mình vào nhịp sống về đêm, Ruby Sky Lounge luôn là nơi lưu giữ những khoảnh khắc đáng nhớ giữa bầu trời và biển cả.</p></div></div><section class=\"ts-gallery-section\" style=\"background-color:rgb(11,11,11);color:rgb(204,204,204);font-family:Arial, Helvetica, sans-serif;font-size:medium;font-style:normal;font-weight:400;margin:0px auto;max-width:1320px;padding:0px 30px 60px;word-spacing:0px;\"><div class=\"ts-gallery-heading\" style=\"margin:0px 0px 30px;padding:0px;text-align:center;\"><div class=\"ts-heading-label\" style=\"color:rgb(201,168,76);font-family:Antonio, sans-serif;font-size:16px;font-weight:300;margin:0px 0px 12px;padding:0px;\">Ruby Sky Lounge</div><div class=\"ts-heading-title\" style=\"color:rgb(255,255,255);font-family:Antonio, sans-