INSERT INTO `ht_services_translations` (`lang_code`, `ht_services_id`, `name`, `description`, `content`, `custom_url`) VALUES
('de_DE', 1, 'Empfangshalle', 'Rezeption rund um die Uhr: Check-in, Check-out, Gepäckaufbewahrung und Reisetipps. Sitzbereich mit kostenlosem Trinkwasser.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Rezeption rund um die Uhr: Check-in, Check-out, Gepäckaufbewahrung und Reisetipps. Sitzbereich mit kostenlosem Trinkwasser.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1621293954908-907159247fc8?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Empfangshalle\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Empfangshalle\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('de_DE', 2, 'Swimmingpool', 'Außenpool für Hotelgäste, geöffnet von 6:00 bis 21:00 Uhr. Liegen, Sonnenschirme und kostenlose Handtücher stehen bereit.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Außenpool für Hotelgäste, geöffnet von 6:00 bis 21:00 Uhr. Liegen, Sonnenschirme und kostenlose Handtücher stehen bereit.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Swimmingpool\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1527359443443-84a48aec73d2?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Swimmingpool\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('de_DE', 4, 'Parkplatz', 'Kostenloser überdachter Parkplatz für Hotelgäste, rund um die Uhr bewacht. Für Autos und Motorräder.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Kostenloser überdachter Parkplatz für Hotelgäste, rund um die Uhr bewacht. Für Autos und Motorräder.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1470224114660-3f6686c562eb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Parkplatz\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1590674899484-d5640e854abe?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Parkplatz\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('en_US', 1, 'Reception Lobby', 'Front desk open 24/7 for check-in, check-out, luggage storage and local travel tips. Comfortable seating area with complimentary drinking water.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Front desk open 24/7 for check-in, check-out, luggage storage and local travel tips. Comfortable seating area with complimentary drinking water.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1621293954908-907159247fc8?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Reception Lobby\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Reception Lobby\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('en_US', 2, 'Swimming Pool', 'Outdoor pool for in-house guests, open from 6:00 to 21:00. Sun loungers, parasols and free towels are available.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Outdoor pool for in-house guests, open from 6:00 to 21:00. Sun loungers, parasols and free towels are available.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Swimming Pool\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1527359443443-84a48aec73d2?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Swimming Pool\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('en_US', 4, 'Parking', 'Free covered parking for in-house guests with 24/7 security. Both cars and motorbikes are welcome.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Free covered parking for in-house guests with 24/7 security. Both cars and motorbikes are welcome.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1470224114660-3f6686c562eb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Parking\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1590674899484-d5640e854abe?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Parking\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ja', 1, 'フロントロビー', '24時間対応のフロントデスクでチェックイン・チェックアウト、荷物預かり、観光案内を承ります。無料の飲料水をご用意した休憩スペースがあります。', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">24時間対応のフロントデスクでチェックイン・チェックアウト、荷物預かり、観光案内を承ります。無料の飲料水をご用意した休憩スペースがあります。</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1621293954908-907159247fc8?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"フロントロビー\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"フロントロビー\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ja', 2, 'プール', '宿泊者専用の屋外プールで、6:00から21:00まで営業しています。サンベッド、パラソル、無料タオルをご用意しています。', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">宿泊者専用の屋外プールで、6:00から21:00まで営業しています。サンベッド、パラソル、無料タオルをご用意しています。</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"プール\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1527359443443-84a48aec73d2?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"プール\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ja', 4, '駐車場', '宿泊者は屋根付き駐車場を無料でご利用いただけます。24時間警備。車・バイクどちらも駐車可能です。', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">宿泊者は屋根付き駐車場を無料でご利用いただけます。24時間警備。車・バイクどちらも駐車可能です。</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1470224114660-3f6686c562eb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"駐車場\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1590674899484-d5640e854abe?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"駐車場\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ko_KR', 1, '리셉션 로비', '24시간 운영하는 프런트 데스크에서 체크인·체크아웃, 수하물 보관, 여행 안내를 제공합니다. 편안한 좌석과 무료 생수가 준비되어 있습니다.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">24시간 운영하는 프런트 데스크에서 체크인·체크아웃, 수하물 보관, 여행 안내를 제공합니다. 편안한 좌석과 무료 생수가 준비되어 있습니다.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1621293954908-907159247fc8?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"리셉션 로비\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"리셉션 로비\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ko_KR', 2, '수영장', '투숙객 전용 야외 수영장으로 6:00부터 21:00까지 운영합니다. 선베드, 파라솔, 무료 수건을 제공합니다.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">투숙객 전용 야외 수영장으로 6:00부터 21:00까지 운영합니다. 선베드, 파라솔, 무료 수건을 제공합니다.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"수영장\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1527359443443-84a48aec73d2?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"수영장\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ko_KR', 4, '주차장', '투숙객을 위한 무료 지붕형 주차장이며 24시간 경비가 상주합니다. 자동차와 오토바이 모두 주차 가능합니다.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">투숙객을 위한 무료 지붕형 주차장이며 24시간 경비가 상주합니다. 자동차와 오토바이 모두 주차 가능합니다.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1470224114660-3f6686c562eb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"주차장\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1590674899484-d5640e854abe?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"주차장\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ru_RU', 1, 'Лобби и ресепшн', 'Стойка регистрации работает круглосуточно: заселение, выезд, хранение багажа и советы для туристов. Зона отдыха с бесплатной питьевой водой.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Стойка регистрации работает круглосуточно: заселение, выезд, хранение багажа и советы для туристов. Зона отдыха с бесплатной питьевой водой.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1621293954908-907159247fc8?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Лобби и ресепшн\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Лобби и ресепшн\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ru_RU', 2, 'Бассейн', 'Открытый бассейн для гостей отеля, работает с 6:00 до 21:00. Шезлонги, зонты и бесплатные полотенца.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Открытый бассейн для гостей отеля, работает с 6:00 до 21:00. Шезлонги, зонты и бесплатные полотенца.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Бассейн\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1527359443443-84a48aec73d2?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Бассейн\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('ru_RU', 4, 'Парковка', 'Бесплатная крытая парковка для гостей отеля с круглосуточной охраной. Для автомобилей и мотоциклов.', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">Бесплатная крытая парковка для гостей отеля с круглосуточной охраной. Для автомобилей и мотоциклов.</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1470224114660-3f6686c562eb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Парковка\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1590674899484-d5640e854abe?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"Парковка\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('zh_CN', 1, '前台大堂', '24小时前台服务，办理入住退房、行李寄存及旅游咨询。休息区提供舒适座椅和免费饮用水。', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">24小时前台服务，办理入住退房、行李寄存及旅游咨询。休息区提供舒适座椅和免费饮用水。</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1621293954908-907159247fc8?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"前台大堂\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1554995207-c18c203602cb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"前台大堂\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('zh_CN', 2, '游泳池', '供住店客人使用的室外泳池，开放时间 6:00–21:00，提供躺椅、遮阳伞和免费毛巾。', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">供住店客人使用的室外泳池，开放时间 6:00–21:00，提供躺椅、遮阳伞和免费毛巾。</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1576013551627-0cc20b96c2a7?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"游泳池\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1527359443443-84a48aec73d2?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"游泳池\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL),
('zh_CN', 4, '停车场', '为住店客人提供免费带顶棚停车位，24小时保安值守，可停放汽车和摩托车。', '<div style=\"max-width:1100px;margin:0 auto\"><p style=\"font-size:17px;line-height:1.9;color:#555;margin-bottom:24px\">为住店客人提供免费带顶棚停车位，24小时保安值守，可停放汽车和摩托车。</p><div style=\"display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px\"><img src=\"https://images.unsplash.com/photo-1470224114660-3f6686c562eb?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"停车场\" style=\"width:100%;height:100%;object-fit:cover;display:block\"><img src=\"https://images.unsplash.com/photo-1590674899484-d5640e854abe?auto=format&fit=crop&w=1200&h=800&q=80\" alt=\"停车场\" style=\"width:100%;height:100%;object-fit:cover;display:block\"></div></div>', NULL);
