(47, 'Botble\\Page\\Models\\Page', 16, 1, 'custom_html', NULL, '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Asian Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====ASIAN RESTAURANT=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .as-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .as-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .as-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-title-section .as-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .as-title-divider::before,\r\n    .as-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-title-divider .as-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .as-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .as-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .as-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n      border-radius: 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .as-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line::before,\r\n    .as-gallery-heading .as-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      border-radius: 8px;\r\n      cursor: pointer;\r\n      background: #e8f0f8;\r\n      position: relative;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /* Placeholder squares (no image yet) */\r\n    .as-gallery-grid .as-photo.placeholder::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      inset: 0;\r\n      background: linear-gradient(135deg, #e8f0f8 0%, #d0e2f3 50%, #e8f0f8 100%);\r\n    }\r\n\r\n    .as-gallery-grid .as-photo.placeholder::after {\r\n      content: \"\\1F3E8\";\r\n      position: absolute;\r\n      top: 50%;\r\n      left: 50%;\r\n      transform: translate(-50%, -50%);\r\n      font-size: 40px;\r\n      opacity: 0.25;\r\n    }\r\n\r\n    /*--Sec5: Menu Carousel--*/\r\n    .as-menu-section {\r\n      background: #0e4d97;\r\n      padding: 50px 0 0;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .as-menu-heading {\r\n      text-align: center;\r\n      padding: 0 30px 40px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line::before,\r\n    .as-menu-heading .as-mh-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, rgba(255,255,255,0.5), #00adef, transparent);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #fff);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 52px;\r\n      font-weight: 200;\r\n      letter-spacing: 10px;\r\n      color: #fff;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 12px;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::before,\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 50px;\r\n      background: linear-gradient(to right, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      background: linear-gradient(to left, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 11px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      color: rgba(0, 173, 239, 0.7);\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .as-carousel-wrapper {\r\n      position: relative;\r\n      height: 620px;\r\n      perspective: 1400px;\r\n      cursor: grab;\r\n      user-select: none;\r\n      overflow: visible;\r\n    }\r\n\r\n    .as-carousel-wrapper:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-carousel {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n      transform-style: preserve-3d;\r\n    }\r\n\r\n    .as-carousel-item {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      width: 380px;\r\n      height: 540px;\r\n      margin-left: -190px;\r\n      margin-top: -270px;\r\n      border-radius: 8px;\r\n      overflow: hidden;\r\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.5);\r\n      cursor: pointer;\r\n      transition: transform 0.5s ease, opacity 0.5s ease, z-index 0s;\r\n      opacity: 0;\r\n    }\r\n\r\n    .as-carousel-item img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n    }\r\n\r\n    .as-carousel-nav {\r\n      display: flex;\r\n      justify-content: center;\r\n      gap: 30px;\r\n      padding: 20px 0 40px;\r\n    }\r\n\r\n    .as-carousel-nav button {\r\n      background: rgba(0, 0, 0, 0.4);\r\n      border: 1.5px solid #00adef;\r\n      color: #00adef;\r\n      font-size: 24px;\r\n      width: 50px;\r\n      height: 50px;\r\n      border-radius: 50%;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n      box-shadow: 0 0 12px rgba(0, 173, 239, 0.15), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    .as-carousel-nav button:hover {\r\n      background: #083a72;\r\n      border-color: #fff;\r\n      color: #fff;\r\n      box-shadow: 0 0 18px rgba(0, 173, 239, 0.3), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    /*--Reservation Bar--*/\r\n    .as-reservation-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #083a72;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 3.33vw;\r\n      font-weight: 100;\r\n      height: 6.6vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease, color .35s ease;\r\n      margin-top: 30px;\r\n      position: relative;\r\n      z-index: 3;\r\n    }\r\n\r\n    .as-reservation-bar:hover {\r\n      background: #00adef;\r\n      color: #fff;\r\n    }\r\n\r\n    /*--LIGHTBOX--*/\r\n    .as-lightbox {\r\n      display: none;\r\n      position: fixed;\r\n      inset: 0;\r\n      background: rgba(0, 0, 0, 0.92);\r\n      z-index: 9999;\r\n      justify-content: center;\r\n      align-items: center;\r\n    }\r\n\r\n    .as-lightbox.active {\r\n      display: flex;\r\n    }\r\n\r\n    .as-lightbox img {\r\n      max-width: 90vw;\r\n      max-height: 90vh;\r\n      object-fit: contain;\r\n      border-radius: 6px;\r\n      cursor: grab;\r\n    }\r\n\r\n    .as-lightbox img:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-lightbox-close {\r\n      position: absolute;\r\n      top: 20px;\r\n      right: 30px;\r\n      font-size: 40px;\r\n      color: white;\r\n      background: none;\r\n      border: none;\r\n      cursor: pointer;\r\n      z-index: 10000;\r\n      transition: color 0.3s;\r\n    }\r\n\r\n    .as-lightbox-close:hover {\r\n      color: #00adef;\r\n    }\r\n\r\n    .as-lightbox-hint {\r\n      position: absolute;\r\n      bottom: 30px;\r\n      left: 50%;\r\n      transform: translateX(-50%);\r\n      background: rgba(0, 0, 0, 0.7);\r\n      color: rgba(255, 255, 255, 0.85);\r\n      font-size: 13px;\r\n      padding: 8px 20px;\r\n      border-radius: 20px;\r\n      pointer-events: none;\r\n      opacity: 0;\r\n      transition: opacity 0.5s ease;\r\n      white-space: nowrap;\r\n      z-index: 10000;\r\n    }\r\n\r\n    .as-lightbox-hint.show {\r\n      opacity: 1;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 350px;\r\n        margin-left: -120px;\r\n        margin-top: -175px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .as-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 36px;\r\n        letter-spacing: 6px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n        perspective: 800px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 340px;\r\n        margin-left: -120px;\r\n        margin-top: -170px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 5.5vw;\r\n        height: auto;\r\n        padding: 15px 0;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .as-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-title-section .as-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .as-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 28px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-sub {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 380px;\r\n        perspective: 600px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 200px;\r\n        height: 290px;\r\n        margin-left: -100px;\r\n        margin-top: -145px;\r\n      }\r\n\r\n      .as-carousel-nav button {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 18px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 6vw;\r\n        padding: 12px 0;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"as-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"as-title-section\">\r\n    <div class=\"as-label\">Ruby 68 Hotel</div>\r\n    <h1>Asian Restaurant</h1>\r\n    <div class=\"as-title-divider\">\r\n      <div class=\"as-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"as-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 8 khách sạn Ruby 68 với tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu, nhà hàng Asian mang đến hành trình ẩm thực tinh tế, nơi vị giác và cảm xúc được nâng tầm trong không gian sang trọng và đầy cảm hứng.\r\n    </p>\r\n    <p>\r\n      Thực đơn à la carte đa dạng từ Á đến Âu, được chế biến bởi đội ngũ đầu bếp chuẩn 3 sao, kết hợp hài hòa giữa nguyên liệu cao cấp và nghệ thuật trình bày tinh xảo. Mỗi món ăn không chỉ là hương vị, mà còn là một trải nghiệm ẩm thực trọn vẹn.\r\n    </p>\r\n    <p>\r\n      Dù là bữa tối lãng mạn, buổi gặp gỡ đối tác hay khoảnh khắc thư giãn bên gia đình, Asian Restaurant luôn là lựa chọn hoàn hảo để tận hưởng ẩm thực đẳng cấp giữa khung cảnh biển trời tuyệt đẹp.\r\n    </p>\r\n    <div class=\"as-time\">Mở cửa hàng ngày từ 6:30 đến 11:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"as-gallery-section\">\r\n    <div class=\"as-gallery-heading\">\r\n      <div class=\"as-heading-line\">\r\n        <div class=\"as-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-heading-sub\">Asian</div>\r\n      <div class=\"as-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"as-gallery-grid\">\r\n      <div class=\"as-photo\" onclick=\"asOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\" alt=\"Asian Restaurant\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec5: Menu Carousel -->\r\n  <section class=\"as-menu-section\">\r\n    <div class=\"as-menu-heading\">\r\n      <div class=\"as-mh-line\">\r\n        <div class=\"as-mh-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-mh-sub\">Asian</div>\r\n      <div class=\"as-mh-main\">Our Menu</div>\r\n      <div class=\"as-mh-bottom\"><span>Signature Dishes</span></div>\r\n    </div>\r\n    <div class=\"as-carousel-wrapper\" id=\"asCarouselWrapper\">\r\n      <div class=\"as-carousel\" id=\"asCarousel\">\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/1.jpg\" alt=\"Menu 1\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/2.jpg\" alt=\"Menu 2\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/3.jpg\" alt=\"Menu 3\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"as-carousel-nav\">\r\n      <button id=\"asCarPrev\">&#10094;</button>\r\n      <button id=\"asCarNext\">&#10095;</button>\r\n    </div>\r\n    <a class=\"as-reservation-bar\" href=\"/reservation\"><span>MAKE A RESERVATION</span></a>\r\n  </section>\r\n\r\n  <!-- Lightbox -->\r\n  <div class=\"as-lightbox\" id=\"asLightbox\">\r\n    <button class=\"as-lightbox-close\" onclick=\"asCloseLightbox()\">&times;</button>\r\n    <img id=\"asLightboxImg\" src=\"\" alt=\"Zoom\">\r\n    <div class=\"as-lightbox-hint\" id=\"asLightboxHint\">Scroll to zoom · Drag to pan · Double-click to reset</div>\r\n  </div>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX WITH ZOOM ========= */\r\n    var asZoom = { scale: 1, x: 0, y: 0, dragging: false, startX: 0, startY: 0, lastX: 0, lastY: 0, hasDragged: false }\r\n    var asLightboxCount = 0\r\n\r\n    function asOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\')\r\n      if (!img) return\r\n      document.getElementById(\'asLightboxImg\').src = img.src\r\n      asResetZoom()\r\n      document.getElementById(\'asLightbox\').classList.add(\'active\')\r\n      asLightboxCount++\r\n      if (asLightboxCount === 1) {\r\n        var hint = document.getElementById(\'asLightboxHint\')\r\n        hint.classList.add(\'show\')\r\n        setTimeout(function () { hint.classList.remove(\'show\') }, 3500)\r\n      }\r\n    }\r\n\r\n    function asCloseLightbox() {\r\n      document.getElementById(\'asLightbox\').classList.remove(\'active\')\r\n      asResetZoom()\r\n    }\r\n\r\n    function asResetZoom() {\r\n      asZoom.scale = 1; asZoom.x = 0; asZoom.y = 0\r\n      var lbImg = document.getElementById(\'asLightboxImg\')\r\n      lbImg.style.transform = \'scale(1) translate(0px, 0px)\'\r\n    }\r\n\r\n    function asApplyZoom() {\r\n      var lbImg = document.getElementById(\'asLightboxImg\')\r\n      lbImg.style.transform = \'scale(\' + asZoom.scale + \') translate(\' + asZoom.x + \'px, \' + asZoom.y + \'px)\'\r\n    }\r\n\r\n    document.getElementById(\'asLightbox\').addEventListener(\'wheel\', function (e) {\r\n      e.preventDefault()\r\n      asZoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n      if (asZoom.scale < 1) { asZoom.scale = 1; asZoom.x = 0; asZoom.y = 0 }\r\n      if (asZoom.scale > 5) asZoom.scale = 5\r\n      asApplyZoom()\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'dblclick\', function (e) {\r\n      e.stopPropagation()\r\n      asResetZoom()\r\n    })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'mousedown\', function (e) {\r\n      e.preventDefault()\r\n      asZoom.dragging = true\r\n      asZoom.hasDragged = false\r\n      asZoom.startX = e.clientX; asZoom.startY = e.clientY\r\n      asZoom.lastX = asZoom.x; asZoom.lastY = asZoom.y\r\n    })\r\n\r\n    document.addEventListener(\'mousemove\', function (e) {\r\n      if (!asZoom.dragging) return\r\n      var dx = e.clientX - asZoom.startX\r\n      var dy = e.clientY - asZoom.startY\r\n      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) asZoom.hasDragged = true\r\n      asZoom.x = asZoom.lastX + dx / asZoom.scale\r\n      asZoom.y = asZoom.lastY + dy / asZoom.scale\r\n      asApplyZoom()\r\n    })\r\n\r\n    document.addEventListener(\'mouseup\', function () { asZoom.dragging = false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'click\', function (e) {\r\n      e.stopPropagation()\r\n    })\r\n\r\n    // Touch pinch zoom & pan\r\n    var asTouches = { dist: 0, scale0: 1 }\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchstart\', function (e) {\r\n      if (e.touches.length === 2) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - e.touches[1].clientX\r\n        var dy = e.touches[0].clientY - e.touches[1].clientY\r\n        asTouches.dist = Math.sqrt(dx * dx + dy * dy)\r\n        asTouches.scale0 = asZoom.scale\r\n      } else if (e.touches.length === 1) {\r\n        asZoom.dragging = true\r\n        asZoom.hasDragged = false\r\n        asZoom.startX = e.touches[0].clientX; asZoom.startY = e.touches[0].clientY\r\n        asZoom.lastX = asZoom.x; asZoom.lastY = asZoom.y\r\n      }\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchmove\', function (e) {\r\n      if (e.touches.length === 2) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - e.touches[1].clientX\r\n        var dy = e.touches[0].clientY - e.touches[1].clientY\r\n        var dist = Math.sqrt(dx * dx + dy * dy)\r\n        asZoom.scale = asTouches.scale0 * (dist / asTouches.dist)\r\n        if (asZoom.scale < 1) asZoom.scale = 1\r\n        if (asZoom.scale > 5) asZoom.scale = 5\r\n        asApplyZoom()\r\n      } else if (e.touches.length === 1 && asZoom.dragging) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - asZoom.startX\r\n        var dy = e.touches[0].clientY - asZoom.startY\r\n        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) asZoom.hasDragged = true\r\n        asZoom.x = asZoom.lastX + dx / asZoom.scale\r\n        asZoom.y = asZoom.lastY + dy / asZoom.scale\r\n        asApplyZoom()\r\n      }\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchend\', function (e) {\r\n      asZoom.dragging = false\r\n      if (e.touches.length < 2) asTouches.dist = 0\r\n    })\r\n\r\n    document.getElementById(\'asLightbox\').addEventListener(\'click\', function (e) {\r\n      if (e.target === this) asCloseLightbox()\r\n    })\r\n\r\n    document.addEventListener(\'keydown\', function (e) {\r\n      if (e.key === \'Escape\') asCloseLightbox()\r\n    })\r\n\r\n    /* ========= COVERFLOW CAROUSEL ========= */\r\n    ;(function () {\r\n      var wrapper = document.getElementById(\'asCarouselWrapper\')\r\n      var items = document.querySelectorAll(\'.as-carousel-item\')\r\n      var total = items.length\r\n      var current = 0\r\n      var VISIBLE = total >= 5 ? 5 : total\r\n\r\n      function layout(animated) {\r\n        var w = window.innerWidth\r\n        var half = Math.floor(VISIBLE / 2)\r\n        for (var i = 0; i < total; i++) {\r\n          var offset = i - current\r\n          if (offset > total / 2) offset -= total\r\n          if (offset < -total / 2) offset += total\r\n          var abs = Math.abs(offset)\r\n          var item = items[i]\r\n\r\n          if (abs > half) {\r\n            item.style.opacity = \'0\'\r\n            item.style.zIndex = \'0\'\r\n            item.style.transform = \'translateX(\' + (offset > 0 ? 800 : -800) + \'px) rotateY(0deg) scale(0.5)\'\r\n            item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n            continue\r\n          }\r\n\r\n          var spacing = w <= 480 ? 160 : (w <= 768 ? 190 : (w <= 1024 ? 220 : 280))\r\n          var tx = offset * spacing\r\n          var rotY = offset === 0 ? 0 : (offset < 0 ? 40 : -40)\r\n          var sc = offset === 0 ? 1 : 0.72 - abs * 0.06\r\n          var z = 100 - abs * 20\r\n\r\n          item.style.opacity = \'1\'\r\n          item.style.zIndex = \'\' + z\r\n          item.style.transform = \'translateX(\' + tx + \'px) rotateY(\' + rotY + \'deg) scale(\' + sc + \')\'\r\n          item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n          item.classList.toggle(\'as-active\', offset === 0)\r\n        }\r\n      }\r\n\r\n      function goTo(idx) {\r\n        current = ((idx % total) + total) % total\r\n        layout(true)\r\n      }\r\n\r\n      layout(false)\r\n\r\n      document.getElementById(\'asCarNext\').addEventListener(\'click\', function () {\r\n        goTo(current + 1)\r\n      })\r\n      document.getElementById(\'asCarPrev\').addEventListener(\'click\', function () {\r\n        goTo(current - 1)\r\n      })\r\n\r\n      for (var i = 0; i < total; i++) {\r\n        ;(function (idx) {\r\n          items[idx].addEventListener(\'click\', function () {\r\n            if (idx === current) {\r\n              document.getElementById(\'asLightboxImg\').src = items[idx].querySelector(\'img\').src\r\n              document.getElementById(\'asLightbox\').classList.add(\'active\')\r\n            } else {\r\n              var diff = idx - current\r\n              if (diff > total / 2) diff -= total\r\n              if (diff < -total / 2) diff += total\r\n              goTo(current + diff)\r\n            }\r\n          })\r\n        })(i)\r\n      }\r\n\r\n      /* Drag / Swipe */\r\n      var dragging = false, startX = 0, moved = false\r\n\r\n      wrapper.addEventListener(\'mousedown\', function (e) {\r\n        dragging = true; startX = e.clientX; moved = false\r\n      })\r\n      window.addEventListener(\'mousemove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.clientX - startX) > 10) moved = true\r\n      })\r\n      window.addEventListener(\'mouseup\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = e.clientX - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      wrapper.addEventListener(\'touchstart\', function (e) {\r\n        dragging = true; startX = e.touches[0].clientX; moved = false\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchmove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.touches[0].clientX - startX) > 10) moved = true\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchend\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = (e.changedTouches[0] ? e.changedTouches[0].clientX : startX) - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      function adjustSpacing() {\r\n        var w = window.innerWidth\r\n        if (w <= 480) VISIBLE = Math.min(3, total)\r\n        else if (w <= 768) VISIBLE = Math.min(3, total)\r\n        else VISIBLE = Math.min(5, total)\r\n        layout(false)\r\n      }\r\n      window.addEventListener(\'resize\', adjustSpacing)\r\n      adjustSpacing()\r\n    })()\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 07:32:16', '2026-03-25 07:32:16'),
(48, 'Botble\\Page\\Models\\Page', 16, 1, 'description', 'Tọa lạc tại tầng 8 khách sạn Ruby 68 với tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu, nhà hàng Asian mang đến hành trình ẩm thực tinh tế, nơi vị giác và cảm xúc được nâng tầm trong không gian sang trọng và đầy cảm hứng.', 'Tọa lạc tại tầng 8 khách sạn Ruby 68 cùng tầm nhìn bao quát ra hồ bơi vô cực cùng đại dương xanh mênh mông hứa hẹn sẽ đem đến cho Quý khách những giây phút thưởng thức ẩm thực tuyệt vời bên cạnh bạn bè và người thân.', '2026-03-25 07:32:16', '2026-03-25 07:32:16');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(49, 'Botble\\Page\\Models\\Page', 16, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Asian Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====ASIAN RESTAURANT=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .as-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .as-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .as-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-title-section .as-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .as-title-divider::before,\r\n    .as-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-title-divider .as-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .as-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .as-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .as-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n      border-radius: 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .as-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line::before,\r\n    .as-gallery-heading .as-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      border-radius: 8px;\r\n      cursor: pointer;\r\n      background: #e8f0f8;\r\n      position: relative;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /* Placeholder squares (no image yet) */\r\n    .as-gallery-grid .as-photo.placeholder::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      inset: 0;\r\n      background: linear-gradient(135deg, #e8f0f8 0%, #d0e2f3 50%, #e8f0f8 100%);\r\n    }\r\n\r\n    .as-gallery-grid .as-photo.placeholder::after {\r\n      content: \"\\1F3E8\";\r\n      position: absolute;\r\n      top: 50%;\r\n      left: 50%;\r\n      transform: translate(-50%, -50%);\r\n      font-size: 40px;\r\n      opacity: 0.25;\r\n    }\r\n\r\n    /*--Sec5: Menu Carousel--*/\r\n    .as-menu-section {\r\n      background: #0e4d97;\r\n      padding: 50px 0 0;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .as-menu-heading {\r\n      text-align: center;\r\n      padding: 0 30px 40px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line::before,\r\n    .as-menu-heading .as-mh-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, rgba(255,255,255,0.5), #00adef, transparent);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #fff);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 52px;\r\n      font-weight: 200;\r\n      letter-spacing: 10px;\r\n      color: #fff;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 12px;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::before,\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 50px;\r\n      background: linear-gradient(to right, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      background: linear-gradient(to left, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 11px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      color: rgba(0, 173, 239, 0.7);\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .as-carousel-wrapper {\r\n      position: relative;\r\n      height: 620px;\r\n      perspective: 1400px;\r\n      cursor: grab;\r\n      user-select: none;\r\n      overflow: visible;\r\n    }\r\n\r\n    .as-carousel-wrapper:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-carousel {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n      transform-style: preserve-3d;\r\n    }\r\n\r\n    .as-carousel-item {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      width: 380px;\r\n      height: 540px;\r\n      margin-left: -190px;\r\n      margin-top: -270px;\r\n      border-radius: 8px;\r\n      overflow: hidden;\r\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.5);\r\n      cursor: pointer;\r\n      transition: transform 0.5s ease, opacity 0.5s ease, z-index 0s;\r\n      opacity: 0;\r\n    }\r\n\r\n    .as-carousel-item img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n    }\r\n\r\n    .as-carousel-nav {\r\n      display: flex;\r\n      justify-content: center;\r\n      gap: 30px;\r\n      padding: 20px 0 40px;\r\n    }\r\n\r\n    .as-carousel-nav button {\r\n      background: rgba(0, 0, 0, 0.4);\r\n      border: 1.5px solid #00adef;\r\n      color: #00adef;\r\n      font-size: 24px;\r\n      width: 50px;\r\n      height: 50px;\r\n      border-radius: 50%;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n      box-shadow: 0 0 12px rgba(0, 173, 239, 0.15), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    .as-carousel-nav button:hover {\r\n      background: #083a72;\r\n      border-color: #fff;\r\n      color: #fff;\r\n      box-shadow: 0 0 18px rgba(0, 173, 239, 0.3), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    /*--Reservation Bar--*/\r\n    .as-reservation-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #083a72;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 3.33vw;\r\n      font-weight: 100;\r\n      height: 6.6vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease, color .35s ease;\r\n      margin-top: 30px;\r\n      position: relative;\r\n      z-index: 3;\r\n    }\r\n\r\n    .as-reservation-bar:hover {\r\n      background: #00adef;\r\n      color: #fff;\r\n    }\r\n\r\n    /*--LIGHTBOX--*/\r\n    .as-lightbox {\r\n      display: none;\r\n      position: fixed;\r\n      inset: 0;\r\n      background: rgba(0, 0, 0, 0.92);\r\n      z-index: 9999;\r\n      justify-content: center;\r\n      align-items: center;\r\n    }\r\n\r\n    .as-lightbox.active {\r\n      display: flex;\r\n    }\r\n\r\n    .as-lightbox img {\r\n      max-width: 90vw;\r\n      max-height: 90vh;\r\n      object-fit: contain;\r\n      border-radius: 6px;\r\n      cursor: grab;\r\n    }\r\n\r\n    .as-lightbox img:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-lightbox-close {\r\n      position: absolute;\r\n      top: 20px;\r\n      right: 30px;\r\n      font-size: 40px;\r\n      color: white;\r\n      background: none;\r\n      border: none;\r\n      cursor: pointer;\r\n      z-index: 10000;\r\n      transition: color 0.3s;\r\n    }\r\n\r\n    .as-lightbox-close:hover {\r\n      color: #00adef;\r\n    }\r\n\r\n    .as-lightbox-hint {\r\n      position: absolute;\r\n      bottom: 30px;\r\n      left: 50%;\r\n      transform: translateX(-50%);\r\n      background: rgba(0, 0, 0, 0.7);\r\n      color: rgba(255, 255, 255, 0.85);\r\n      font-size: 13px;\r\n      padding: 8px 20px;\r\n      border-radius: 20px;\r\n      pointer-events: none;\r\n      opacity: 0;\r\n      transition: opacity 0.5s ease;\r\n      white-space: nowrap;\r\n      z-index: 10000;\r\n    }\r\n\r\n    .as-lightbox-hint.show {\r\n      opacity: 1;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 350px;\r\n        margin-left: -120px;\r\n        margin-top: -175px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .as-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 36px;\r\n        letter-spacing: 6px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n        perspective: 800px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 340px;\r\n        margin-left: -120px;\r\n        margin-top: -170px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 5.5vw;\r\n        height: auto;\r\n        padding: 15px 0;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .as-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-title-section .as-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .as-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 28px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-sub {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 380px;\r\n        perspective: 600px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 200px;\r\n        height: 290px;\r\n        margin-left: -100px;\r\n        margin-top: -145px;\r\n      }\r\n\r\n      .as-carousel-nav button {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 18px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 6vw;\r\n        padding: 12px 0;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"as-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"as-title-section\">\r\n    <div class=\"as-label\">Ruby 68 Hotel</div>\r\n    <h1>Asian Restaurant</h1>\r\n    <div class=\"as-title-divider\">\r\n      <div class=\"as-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"as-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 8 khách sạn Ruby 68 với tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu, nhà hàng Asian mang đến hành trình ẩm thực tinh tế, nơi vị giác và cảm xúc được nâng tầm trong không gian sang trọng và đầy cảm hứng.\r\n    </p>\r\n    <p>\r\n      Thực đơn à la carte đa dạng từ Á đến Âu, được chế biến bởi đội ngũ đầu bếp chuẩn 3 sao, kết hợp hài hòa giữa nguyên liệu cao cấp và nghệ thuật trình bày tinh xảo. Mỗi món ăn không chỉ là hương vị, mà còn là một trải nghiệm ẩm thực trọn vẹn.\r\n    </p>\r\n    <p>\r\n      Dù là bữa tối lãng mạn, buổi gặp gỡ đối tác hay khoảnh khắc thư giãn bên gia đình, Asian Restaurant luôn là lựa chọn hoàn hảo để tận hưởng ẩm thực đẳng cấp giữa khung cảnh biển trời tuyệt đẹp.\r\n    </p>\r\n    <div class=\"as-time\">Mở cửa hàng ngày từ 6:30 đến 11:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"as-gallery-section\">\r\n    <div class=\"as-gallery-heading\">\r\n      <div class=\"as-heading-line\">\r\n        <div class=\"as-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-heading-sub\">Asian</div>\r\n      <div class=\"as-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"as-gallery-grid\">\r\n      <div class=\"as-photo\" onclick=\"asOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\" alt=\"Asian Restaurant\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec5: Menu Carousel -->\r\n  <section class=\"as-menu-section\">\r\n    <div class=\"as-menu-heading\">\r\n      <div class=\"as-mh-line\">\r\n        <div class=\"as-mh-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-mh-sub\">Asian</div>\r\n      <div class=\"as-mh-main\">Our Menu</div>\r\n      <div class=\"as-mh-bottom\"><span>Signature Dishes</span></div>\r\n    </div>\r\n    <div class=\"as-carousel-wrapper\" id=\"asCarouselWrapper\">\r\n      <div class=\"as-carousel\" id=\"asCarousel\">\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/1.jpg\" alt=\"Menu 1\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/2.jpg\" alt=\"Menu 2\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/3.jpg\" alt=\"Menu 3\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"as-carousel-nav\">\r\n      <button id=\"asCarPrev\">&#10094;</button>\r\n      <button id=\"asCarNext\">&#10095;</button>\r\n    </div>\r\n    <a class=\"as-reservation-bar\" href=\"/reservation\"><span>MAKE A RESERVATION</span></a>\r\n  </section>\r\n\r\n  <!-- Lightbox -->\r\n  <div class=\"as-lightbox\" id=\"asLightbox\">\r\n    <button class=\"as-lightbox-close\" onclick=\"asCloseLightbox()\">&times;</button>\r\n    <img id=\"asLightboxImg\" src=\"\" alt=\"Zoom\">\r\n    <div class=\"as-lightbox-hint\" id=\"asLightboxHint\">Scroll to zoom · Drag to pan · Double-click to reset</div>\r\n  </div>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX WITH ZOOM ========= */\r\n    var asZoom = { scale: 1, x: 0, y: 0, dragging: false, startX: 0, startY: 0, lastX: 0, lastY: 0, hasDragged: false }\r\n    var asLightboxCount = 0\r\n\r\n    function asOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\')\r\n      if (!img) return\r\n      document.getElementById(\'asLightboxImg\').src = img.src\r\n      asResetZoom()\r\n      document.getElementById(\'asLightbox\').classList.add(\'active\')\r\n      asLightboxCount++\r\n      if (asLightboxCount === 1) {\r\n        var hint = document.getElementById(\'asLightboxHint\')\r\n        hint.classList.add(\'show\')\r\n        setTimeout(function () { hint.classList.remove(\'show\') }, 3500)\r\n      }\r\n    }\r\n\r\n    function asCloseLightbox() {\r\n      document.getElementById(\'asLightbox\').classList.remove(\'active\')\r\n      asResetZoom()\r\n    }\r\n\r\n    function asResetZoom() {\r\n      asZoom.scale = 1; asZoom.x = 0; asZoom.y = 0\r\n      var lbImg = document.getElementById(\'asLightboxImg\')\r\n      lbImg.style.transform = \'scale(1) translate(0px, 0px)\'\r\n    }\r\n\r\n    function asApplyZoom() {\r\n      var lbImg = document.getElementById(\'asLightboxImg\')\r\n      lbImg.style.transform = \'scale(\' + asZoom.scale + \') translate(\' + asZoom.x + \'px, \' + asZoom.y + \'px)\'\r\n    }\r\n\r\n    document.getElementById(\'asLightbox\').addEventListener(\'wheel\', function (e) {\r\n      e.preventDefault()\r\n      asZoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n      if (asZoom.scale < 1) { asZoom.scale = 1; asZoom.x = 0; asZoom.y = 0 }\r\n      if (asZoom.scale > 5) asZoom.scale = 5\r\n      asApplyZoom()\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'dblclick\', function (e) {\r\n      e.stopPropagation()\r\n      asResetZoom()\r\n    })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'mousedown\', function (e) {\r\n      e.preventDefault()\r\n      asZoom.dragging = true\r\n      asZoom.hasDragged = false\r\n      asZoom.startX = e.clientX; asZoom.startY = e.clientY\r\n      asZoom.lastX = asZoom.x; asZoom.lastY = asZoom.y\r\n    })\r\n\r\n    document.addEventListener(\'mousemove\', function (e) {\r\n      if (!asZoom.dragging) return\r\n      var dx = e.clientX - asZoom.startX\r\n      var dy = e.clientY - asZoom.startY\r\n      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) asZoom.hasDragged = true\r\n      asZoom.x = asZoom.lastX + dx / asZoom.scale\r\n      asZoom.y = asZoom.lastY + dy / asZoom.scale\r\n      asApplyZoom()\r\n    })\r\n\r\n    document.addEventListener(\'mouseup\', function () { asZoom.dragging = false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'click\', function (e) {\r\n      e.stopPropagation()\r\n    })\r\n\r\n    // Touch pinch zoom & pan\r\n    var asTouches = { dist: 0, scale0: 1 }\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchstart\', function (e) {\r\n      if (e.touches.length === 2) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - e.touches[1].clientX\r\n        var dy = e.touches[0].clientY - e.touches[1].clientY\r\n        asTouches.dist = Math.sqrt(dx * dx + dy * dy)\r\n        asTouches.scale0 = asZoom.scale\r\n      } else if (e.touches.length === 1) {\r\n        asZoom.dragging = true\r\n        asZoom.hasDragged = false\r\n        asZoom.startX = e.touches[0].clientX; asZoom.startY = e.touches[0].clientY\r\n        asZoom.lastX = asZoom.x; asZoom.lastY = asZoom.y\r\n      }\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchmove\', function (e) {\r\n      if (e.touches.length === 2) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - e.touches[1].clientX\r\n        var dy = e.touches[0].clientY - e.touches[1].clientY\r\n        var dist = Math.sqrt(dx * dx + dy * dy)\r\n        asZoom.scale = asTouches.scale0 * (dist / asTouches.dist)\r\n        if (asZoom.scale < 1) asZoom.scale = 1\r\n        if (asZoom.scale > 5) asZoom.scale = 5\r\n        asApplyZoom()\r\n      } else if (e.touches.length === 1 && asZoom.dragging) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - asZoom.startX\r\n        var dy = e.touches[0].clientY - asZoom.startY\r\n        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) asZoom.hasDragged = true\r\n        asZoom.x = asZoom.lastX + dx / asZoom.scale\r\n        asZoom.y = asZoom.lastY + dy / asZoom.scale\r\n        asApplyZoom()\r\n      }\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchend\', function (e) {\r\n      asZoom.dragging = false\r\n      if (e.touches.length < 2) asTouches.dist = 0\r\n    })\r\n\r\n    document.getElementById(\'asLightbox\').addEventListener(\'click\', function (e) {\r\n      if (e.target === this) asCloseLightbox()\r\n    })\r\n\r\n    document.addEventListener(\'keydown\', function (e) {\r\n      if (e.key === \'Escape\') asCloseLightbox()\r\n    })\r\n\r\n    /* ========= COVERFLOW CAROUSEL ========= */\r\n    ;(function () {\r\n      var wrapper = document.getElementById(\'asCarouselWrapper\')\r\n      var items = document.querySelectorAll(\'.as-carousel-item\')\r\n      var total = items.length\r\n      var current = 0\r\n      var VISIBLE = total >= 5 ? 5 : total\r\n\r\n      function layout(animated) {\r\n        var w = window.innerWidth\r\n        var half = Math.floor(VISIBLE / 2)\r\n        for (var i = 0; i < total; i++) {\r\n          var offset = i - current\r\n          if (offset > total / 2) offset -= total\r\n          if (offset < -total / 2) offset += total\r\n          var abs = Math.abs(offset)\r\n          var item = items[i]\r\n\r\n          if (abs > half) {\r\n            item.style.opacity = \'0\'\r\n            item.style.zIndex = \'0\'\r\n            item.style.transform = \'translateX(\' + (offset > 0 ? 800 : -800) + \'px) rotateY(0deg) scale(0.5)\'\r\n            item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n            continue\r\n          }\r\n\r\n          var spacing = w <= 480 ? 160 : (w <= 768 ? 190 : (w <= 1024 ? 220 : 280))\r\n          var tx = offset * spacing\r\n          var rotY = offset === 0 ? 0 : (offset < 0 ? 40 : -40)\r\n          var sc = offset === 0 ? 1 : 0.72 - abs * 0.06\r\n          var z = 100 - abs * 20\r\n\r\n          item.style.opacity = \'1\'\r\n          item.style.zIndex = \'\' + z\r\n          item.style.transform = \'translateX(\' + tx + \'px) rotateY(\' + rotY + \'deg) scale(\' + sc + \')\'\r\n          item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n          item.classList.toggle(\'as-active\', offset === 0)\r\n        }\r\n      }\r\n\r\n      function goTo(idx) {\r\n        current = ((idx % total) + total) % total\r\n        layout(true)\r\n      }\r\n\r\n      layout(false)\r\n\r\n      document.getElementById(\'asCarNext\').addEventListener(\'click\', function () {\r\n        goTo(current + 1)\r\n      })\r\n      document.getElementById(\'asCarPrev\').addEventListener(\'click\', function () {\r\n        goTo(current - 1)\r\n      })\r\n\r\n      for (var i = 0; i < total; i++) {\r\n        ;(function (idx) {\r\n          items[idx].addEventListener(\'click\', function () {\r\n            if (idx === current) {\r\n              document.getElementById(\'asLightboxImg\').src = items[idx].querySelector(\'img\').src\r\n              document.getElementById(\'asLightbox\').classList.add(\'active\')\r\n            } else {\r\n              var diff = idx - current\r\n              if (diff > total / 2) diff -= total\r\n              if (diff < -total / 2) diff += total\r\n              goTo(current + diff)\r\n            }\r\n          })\r\n        })(i)\r\n      }\r\n\r\n      /* Drag / Swipe */\r\n      var dragging = false, startX = 0, moved = false\r\n\r\n      wrapper.addEventListener(\'mousedown\', function (e) {\r\n        dragging = true; startX = e.clientX; moved = false\r\n      })\r\n      window.addEventListener(\'mousemove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.clientX - startX) > 10) moved = true\r\n      })\r\n      window.addEventListener(\'mouseup\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = e.clientX - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      wrapper.addEventListener(\'touchstart\', function (e) {\r\n        dragging = true; startX = e.touches[0].clientX; moved = false\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchmove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.touches[0].clientX - startX) > 10) moved = true\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchend\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = (e.changedTouches[0] ? e.changedTouches[0].clientX : startX) - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      function adjustSpacing() {\r\n        var w = window.innerWidth\r\n        if (w <= 480) VISIBLE = Math.min(3, total)\r\n        else if (w <= 768) VISIBLE = Math.min(3, total)\r\n        else VISIBLE = Math.min(5, total)\r\n        layout(false)\r\n      }\r\n      window.addEventListener(\'resize\', adjustSpacing)\r\n      adjustSpacing()\r\n    })()\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Asian Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====ASIAN RESTAURANT=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .as-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .as-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .as-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-title-section .as-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .as-title-divider::before,\r\n    .as-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-title-divider .as-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .as-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .as-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .as-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n      border-radius: 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .as-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line::before,\r\n    .as-gallery-heading .as-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      border-radius: 8px;\r\n      cursor: pointer;\r\n      background: #e8f0f8;\r\n      position: relative;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /* Placeholder squares (no image yet) */\r\n    .as-gallery-grid .as-photo.placeholder::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      inset: 0;\r\n      background: linear-gradient(135deg, #e8f0f8 0%, #d0e2f3 50%, #e8f0f8 100%);\r\n    }\r\n\r\n    .as-gallery-grid .as-photo.placeholder::after {\r\n      content: \"\\1F3E8\";\r\n      position: absolute;\r\n      top: 50%;\r\n      left: 50%;\r\n      transform: translate(-50%, -50%);\r\n      font-size: 40px;\r\n      opacity: 0.25;\r\n    }\r\n\r\n    /*--Sec5: Menu Carousel--*/\r\n    .as-menu-section {\r\n      background: #0e4d97;\r\n      padding: 50px 0 0;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .as-menu-heading {\r\n      text-align: center;\r\n      padding: 0 30px 40px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line::before,\r\n    .as-menu-heading .as-mh-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, rgba(255,255,255,0.5), #00adef, transparent);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #fff);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 52px;\r\n      font-weight: 200;\r\n      letter-spacing: 10px;\r\n      color: #fff;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 12px;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::before,\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 50px;\r\n      background: linear-gradient(to right, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      background: linear-gradient(to left, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 11px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      color: rgba(0, 173, 239, 0.7);\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .as-carousel-wrapper {\r\n      position: relative;\r\n      height: 620px;\r\n      perspective: 1400px;\r\n      cursor: grab;\r\n      user-select: none;\r\n      overflow: visible;\r\n    }\r\n\r\n    .as-carousel-wrapper:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-carousel {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n      transform-style: preserve-3d;\r\n    }\r\n\r\n    .as-carousel-item {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      width: 380px;\r\n      height: 540px;\r\n      margin-left: -190px;\r\n      margin-top: -270px;\r\n      border-radius: 8px;\r\n      overflow: hidden;\r\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.5);\r\n      cursor: pointer;\r\n      transition: transform 0.5s ease, opacity 0.5s ease, z-index 0s;\r\n      opacity: 0;\r\n    }\r\n\r\n    .as-carousel-item img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n    }\r\n\r\n    .as-carousel-nav {\r\n      display: flex;\r\n      justify-content: center;\r\n      gap: 30px;\r\n      padding: 20px 0 40px;\r\n    }\r\n\r\n    .as-carousel-nav button {\r\n      background: rgba(0, 0, 0, 0.4);\r\n      border: 1.5px solid #00adef;\r\n      color: #00adef;\r\n      font-size: 24px;\r\n      width: 50px;\r\n      height: 50px;\r\n      border-radius: 50%;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n      box-shadow: 0 0 12px rgba(0, 173, 239, 0.15), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    .as-carousel-nav button:hover {\r\n      background: #083a72;\r\n      border-color: #fff;\r\n      color: #fff;\r\n      box-shadow: 0 0 18px rgba(0, 173, 239, 0.3), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    /*--Reservation Bar--*/\r\n    .as-reservation-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #083a72;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 3.33vw;\r\n      font-weight: 100;\r\n      height: 6.6vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease, color .35s ease;\r\n      margin-top: 30px;\r\n      position: relative;\r\n      z-index: 3;\r\n    }\r\n\r\n    .as-reservation-bar:hover {\r\n      background: #00adef;\r\n      color: #fff;\r\n    }\r\n\r\n    /*--LIGHTBOX--*/\r\n    .as-lightbox {\r\n      display: none;\r\n      position: fixed;\r\n      inset: 0;\r\n      background: rgba(0, 0, 0, 0.92);\r\n      z-index: 9999;\r\n      justify-content: center;\r\n      align-items: center;\r\n    }\r\n\r\n    .as-lightbox.active {\r\n      display: flex;\r\n    }\r\n\r\n    .as-lightbox img {\r\n      max-width: 90vw;\r\n      max-height: 90vh;\r\n      object-fit: contain;\r\n      border-radius: 6px;\r\n      cursor: grab;\r\n    }\r\n\r\n    .as-lightbox img:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-lightbox-close {\r\n      position: absolute;\r\n      top: 20px;\r\n      right: 30px;\r\n      font-size: 40px;\r\n      color: white;\r\n      background: none;\r\n      border: none;\r\n      cursor: pointer;\r\n      z-index: 10000;\r\n      transition: color 0.3s;\r\n    }\r\n\r\n    .as-lightbox-close:hover {\r\n      color: #00adef;\r\n    }\r\n\r\n    .as-lightbox-hint {\r\n      position: absolute;\r\n      bottom: 30px;\r\n      left: 50%;\r\n      transform: translateX(-50%);\r\n      background: rgba(0, 0, 0, 0.7);\r\n      color: rgba(255, 255, 255, 0.85);\r\n      font-size: 13px;\r\n      padding: 8px 20px;\r\n      border-radius: 20px;\r\n      pointer-events: none;\r\n      opacity: 0;\r\n      transition: opacity 0.5s ease;\r\n      white-space: nowrap;\r\n      z-index: 10000;\r\n    }\r\n\r\n    .as-lightbox-hint.show {\r\n      opacity: 1;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 350px;\r\n        margin-left: -120px;\r\n        margin-top: -175px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .as-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 36px;\r\n        letter-spacing: 6px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n        perspective: 800px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 340px;\r\n        margin-left: -120px;\r\n        margin-top: -170px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 5.5vw;\r\n        height: auto;\r\n        padding: 15px 0;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .as-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-title-section .as-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .as-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 28px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-sub {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 380px;\r\n        perspective: 600px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 200px;\r\n        height: 290px;\r\n        margin-left: -100px;\r\n        margin-top: -145px;\r\n      }\r\n\r\n      .as-carousel-nav button {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 18px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 6vw;\r\n        padding: 12px 0;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"as-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"as-title-section\">\r\n    <div class=\"as-label\">Ruby 68 Hotel</div>\r\n    <h1>Asian Restaurant</h1>\r\n    <div class=\"as-title-divider\">\r\n      <div class=\"as-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"as-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 8 khách sạn Ruby 68 với tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu, nhà hàng Asian mang đến hành trình ẩm thực tinh tế, nơi vị giác và cảm xúc được nâng tầm trong không gian sang trọng và đầy cảm hứng.\r\n    </p>\r\n    <p>\r\n      Thực đơn à la carte đa dạng từ Á đến Âu, được chế biến bởi đội ngũ đầu bếp chuẩn 3 sao, kết hợp hài hòa giữa nguyên liệu cao cấp và nghệ thuật trình bày tinh xảo. Mỗi món ăn không chỉ là hương vị, mà còn là một trải nghiệm ẩm thực trọn vẹn.\r\n    </p>\r\n    <p>\r\n      Dù là bữa tối lãng mạn, buổi gặp gỡ đối tác hay khoảnh khắc thư giãn bên gia đình, Asian Restaurant luôn là lựa chọn hoàn hảo để tận hưởng ẩm thực đẳng cấp giữa khung cảnh biển trời tuyệt đẹp.\r\n    </p>\r\n    <div class=\"as-time\">Mở cửa hàng ngày từ 6:30 đến 11:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"as-gallery-section\">\r\n    <div class=\"as-gallery-heading\">\r\n      <div class=\"as-heading-line\">\r\n        <div class=\"as-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-heading-sub\">Asian</div>\r\n      <div class=\"as-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"as-gallery-grid\">\r\n      <div class=\"as-photo\" onclick=\"asOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\" alt=\"Asian Restaurant\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec5: Menu Carousel -->\r\n  <section class=\"as-menu-section\">\r\n    <div class=\"as-menu-heading\">\r\n      <div class=\"as-mh-line\">\r\n        <div class=\"as-mh-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-mh-sub\">Asian</div>\r\n      <div class=\"as-mh-main\">Our Menu</div>\r\n      <div class=\"as-mh-bottom\"><span>Signature Dishes</span></div>\r\n    </div>\r\n    <div class=\"as-carousel-wrapper\" id=\"asCarouselWrapper\">\r\n      <div class=\"as-carousel\" id=\"asCarousel\">\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/1.jpg\" alt=\"Menu 1\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/2.jpg\" alt=\"Menu 2\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/3.jpg\" alt=\"Menu 3\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"as-carousel-nav\">\r\n      <button id=\"asCarPrev\">❮</button>\r\n      <button id=\"asCarNext\">❯</button>\r\n    </div>\r\n    <a class=\"as-reservation-bar\" href=\"/reservation\"><span>MAKE A RESERVATION</span></a>\r\n  </section>\r\n\r\n  <!-- Lightbox -->\r\n  <div class=\"as-lightbox\" id=\"asLightbox\">\r\n    <button class=\"as-lightbox-close\" onclick=\"asCloseLightbox()\">×</button>\r\n    <img id=\"asLightboxImg\" src=\"\" alt=\"Zoom\">\r\n    <div class=\"as-lightbox-hint\" id=\"asLightboxHint\">Scroll to zoom · Drag to pan · Double-click to reset</div>\r\n  </div>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX WITH ZOOM ========= */\r\n    var asZoom = { scale: 1, x: 0, y: 0, dragging: false, startX: 0, startY: 0, lastX: 0, lastY: 0, hasDragged: false }\r\n    var asLightboxCount = 0\r\n\r\n    function asOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\')\r\n      if (!img) return\r\n      document.getElementById(\'asLightboxImg\').src = img.src\r\n      asResetZoom()\r\n      document.getElementById(\'asLightbox\').classList.add(\'active\')\r\n      asLightboxCount++\r\n      if (asLightboxCount === 1) {\r\n        var hint = document.getElementById(\'asLightboxHint\')\r\n        hint.classList.add(\'show\')\r\n        setTimeout(function () { hint.classList.remove(\'show\') }, 3500)\r\n      }\r\n    }\r\n\r\n    function asCloseLightbox() {\r\n      document.getElementById(\'asLightbox\').classList.remove(\'active\')\r\n      asResetZoom()\r\n    }\r\n\r\n    function asResetZoom() {\r\n      asZoom.scale = 1; asZoom.x = 0; asZoom.y = 0\r\n      var lbImg = document.getElementById(\'asLightboxImg\')\r\n      lbImg.style.transform = \'scale(1) translate(0px, 0px)\'\r\n    }\r\n\r\n    function asApplyZoom() {\r\n      var lbImg = document.getElementById(\'asLightboxImg\')\r\n      lbImg.style.transform = \'scale(\' + asZoom.scale + \') translate(\' + asZoom.x + \'px, \' + asZoom.y + \'px)\'\r\n    }\r\n\r\n    document.getElementById(\'asLightbox\').addEventListener(\'wheel\', function (e) {\r\n      e.preventDefault()\r\n      asZoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n      if (asZoom.scale < 1) { asZoom.scale = 1; asZoom.x = 0; asZoom.y = 0 }\r\n      if (asZoom.scale > 5) asZoom.scale = 5\r\n      asApplyZoom()\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'dblclick\', function (e) {\r\n      e.stopPropagation()\r\n      asResetZoom()\r\n    })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'mousedown\', function (e) {\r\n      e.preventDefault()\r\n      asZoom.dragging = true\r\n      asZoom.hasDragged = false\r\n      asZoom.startX = e.clientX; asZoom.startY = e.clientY\r\n      asZoom.lastX = asZoom.x; asZoom.lastY = asZoom.y\r\n    })\r\n\r\n    document.addEventListener(\'mousemove\', function (e) {\r\n      if (!asZoom.dragging) return\r\n      var dx = e.clientX - asZoom.startX\r\n      var dy = e.clientY - asZoom.startY\r\n      if (Math.abs(dx) > 3 || Math.abs(dy) > 3) asZoom.hasDragged = true\r\n      asZoom.x = asZoom.lastX + dx / asZoom.scale\r\n      asZoom.y = asZoom.lastY + dy / asZoom.scale\r\n      asApplyZoom()\r\n    })\r\n\r\n    document.addEventListener(\'mouseup\', function () { asZoom.dragging = false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'click\', function (e) {\r\n      e.stopPropagation()\r\n    })\r\n\r\n    // Touch pinch zoom & pan\r\n    var asTouches = { dist: 0, scale0: 1 }\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchstart\', function (e) {\r\n      if (e.touches.length === 2) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - e.touches[1].clientX\r\n        var dy = e.touches[0].clientY - e.touches[1].clientY\r\n        asTouches.dist = Math.sqrt(dx * dx + dy * dy)\r\n        asTouches.scale0 = asZoom.scale\r\n      } else if (e.touches.length === 1) {\r\n        asZoom.dragging = true\r\n        asZoom.hasDragged = false\r\n        asZoom.startX = e.touches[0].clientX; asZoom.startY = e.touches[0].clientY\r\n        asZoom.lastX = asZoom.x; asZoom.lastY = asZoom.y\r\n      }\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchmove\', function (e) {\r\n      if (e.touches.length === 2) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - e.touches[1].clientX\r\n        var dy = e.touches[0].clientY - e.touches[1].clientY\r\n        var dist = Math.sqrt(dx * dx + dy * dy)\r\n        asZoom.scale = asTouches.scale0 * (dist / asTouches.dist)\r\n        if (asZoom.scale < 1) asZoom.scale = 1\r\n        if (asZoom.scale > 5) asZoom.scale = 5\r\n        asApplyZoom()\r\n      } else if (e.touches.length === 1 && asZoom.dragging) {\r\n        e.preventDefault()\r\n        var dx = e.touches[0].clientX - asZoom.startX\r\n        var dy = e.touches[0].clientY - asZoom.startY\r\n        if (Math.abs(dx) > 3 || Math.abs(dy) > 3) asZoom.hasDragged = true\r\n        asZoom.x = asZoom.lastX + dx / asZoom.scale\r\n        asZoom.y = asZoom.lastY + dy / asZoom.scale\r\n        asApplyZoom()\r\n      }\r\n    }, { passive: false })\r\n\r\n    document.getElementById(\'asLightboxImg\').addEventListener(\'touchend\', function (e) {\r\n      asZoom.dragging = false\r\n      if (e.touches.length < 2) asTouches.dist = 0\r\n    })\r\n\r\n    document.getElementById(\'asLightbox\').addEventListener(\'click\', function (e) {\r\n      if (e.target === this) asCloseLightbox()\r\n    })\r\n\r\n    document.addEventListener(\'keydown\', function (e) {\r\n      if (e.key === \'Escape\') asCloseLightbox()\r\n    })\r\n\r\n    /* ========= COVERFLOW CAROUSEL ========= */\r\n    ;(function () {\r\n      var wrapper = document.getElementById(\'asCarouselWrapper\')\r\n      var items = document.querySelectorAll(\'.as-carousel-item\')\r\n      var total = items.length\r\n      var current = 0\r\n      var VISIBLE = total >= 5 ? 5 : total\r\n\r\n      function layout(animated) {\r\n        var w = window.innerWidth\r\n        var half = Math.floor(VISIBLE / 2)\r\n        for (var i = 0; i < total; i++) {\r\n          var offset = i - current\r\n          if (offset > total / 2) offset -= total\r\n          if (offset < -total / 2) offset += total\r\n          var abs = Math.abs(offset)\r\n          var item = items[i]\r\n\r\n          if (abs > half) {\r\n            item.style.opacity = \'0\'\r\n            item.style.zIndex = \'0\'\r\n            item.style.transform = \'translateX(\' + (offset > 0 ? 800 : -800) + \'px) rotateY(0deg) scale(0.5)\'\r\n            item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n            continue\r\n          }\r\n\r\n          var spacing = w <= 480 ? 160 : (w <= 768 ? 190 : (w <= 1024 ? 220 : 280))\r\n          var tx = offset * spacing\r\n          var rotY = offset === 0 ? 0 : (offset < 0 ? 40 : -40)\r\n          var sc = offset === 0 ? 1 : 0.72 - abs * 0.06\r\n          var z = 100 - abs * 20\r\n\r\n          item.style.opacity = \'1\'\r\n          item.style.zIndex = \'\' + z\r\n          item.style.transform = \'translateX(\' + tx + \'px) rotateY(\' + rotY + \'deg) scale(\' + sc + \')\'\r\n          item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n          item.classList.toggle(\'as-active\', offset === 0)\r\n        }\r\n      }\r\n\r\n      function goTo(idx) {\r\n        current = ((idx % total) + total) % total\r\n        layout(true)\r\n      }\r\n\r\n      layout(false)\r\n\r\n      document.getElementById(\'asCarNext\').addEventListener(\'click\', function () {\r\n        goTo(current + 1)\r\n      })\r\n      document.getElementById(\'asCarPrev\').addEventListener(\'click\', function () {\r\n        goTo(current - 1)\r\n      })\r\n\r\n      for (var i = 0; i < total; i++) {\r\n        ;(function (idx) {\r\n          items[idx].addEventListener(\'click\', function () {\r\n            if (idx === current) {\r\n              document.getElementById(\'asLightboxImg\').src = items[idx].querySelector(\'img\').src\r\n              document.getElementById(\'asLightbox\').classList.add(\'active\')\r\n            } else {\r\n              var diff = idx - current\r\n              if (diff > total / 2) diff -= total\r\n              if (diff < -total / 2) diff += total\r\n              goTo(current + diff)\r\n            }\r\n          })\r\n        })(i)\r\n      }\r\n\r\n      /* Drag / Swipe */\r\n      var dragging = false, startX = 0, moved = false\r\n\r\n      wrapper.addEventListener(\'mousedown\', function (e) {\r\n        dragging = true; startX = e.clientX; moved = false\r\n      })\r\n      window.addEventListener(\'mousemove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.clientX - startX) > 10) moved = true\r\n      })\r\n      window.addEventListener(\'mouseup\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = e.clientX - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      wrapper.addEventListener(\'touchstart\', function (e) {\r\n        dragging = true; startX = e.touches[0].clientX; moved = false\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchmove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.touches[0].clientX - startX) > 10) moved = true\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchend\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = (e.changedTouches[0] ? e.changedTouches[0].clientX : startX) - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      function adjustSpacing() {\r\n        var w = window.innerWidth\r\n        if (w <= 480) VISIBLE = Math.min(3, total)\r\n        else if (w <= 768) VISIBLE = Math.min(3, total)\r\n        else VISIBLE = Math.min(5, total)\r\n        layout(false)\r\n      }\r\n      window.addEventListener(\'resize\', adjustSpacing)\r\n      adjustSpacing()\r\n    })()\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 07:50:32', '2026-03-25 07:50:32');
