INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(81, 'Botble\\Page\\Models\\Page', 15, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Guangdong Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GUANGDONG=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n    }\r\n\r\n    /*--Sec1--*/\r\n    .guangdong-bar {\r\n      background: url(https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/background-gangdong.jpg) center/cover no-repeat;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      padding: 130px 60px 25px;\r\n      position: relative;\r\n    }\r\n\r\n    .guangdong-bar table {\r\n      width: 100%;\r\n    }\r\n\r\n    .gd-title {\r\n      text-transform: uppercase;\r\n      font-weight: 800;\r\n      font-size: 30px;\r\n      line-height: 1.2;\r\n      background: repeating-linear-gradient(100deg,\r\n          #6e4f1c 0px, #8a6525 8px, #b8892e 16px, #e6d072 24px,\r\n          #fff4a3 32px, #e6d072 40px, #c99a35 48px, #a8792a 56px, #6e4f1c 64px);\r\n      -webkit-background-clip: text;\r\n      -webkit-text-fill-color: transparent;\r\n    }\r\n\r\n    .gd-sub {\r\n      color: white;\r\n      font-size: 15px;\r\n      margin-top: 6px;\r\n    }\r\n\r\n    .gd-phone {\r\n      color: white;\r\n      font-size: 17px;\r\n      margin-top: 6px;\r\n    }\r\n\r\n    .gd-icon {\r\n      background: white;\r\n      color: #8b0000;\r\n      padding: 3px 7px;\r\n      border-radius: 3px;\r\n      margin-right: 6px;\r\n    }\r\n\r\n    .guangdong-bar table,\r\n    .guangdong-bar td,\r\n    .guangdong-bar tr {\r\n      border: none !important;\r\n    }\r\n\r\n    .guangdong-bar::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      transform: translate(-50%, -50%);\r\n      width: 250px;\r\n      height: 250px;\r\n      top: 210px;\r\n      z-index: 10;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/logo-gangdong-3.png\") center/contain no-repeat;\r\n      pointer-events: none;\r\n    }\r\n\r\n    /*--SLIDER--*/\r\n    .gd-slider {\r\n      width: 100%;\r\n      height: 41.67vw;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .gd-slide {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n      top: 0;\r\n      left: 0;\r\n      background-size: cover;\r\n      background-position: center;\r\n      opacity: 0;\r\n    }\r\n\r\n    .slide1 {\r\n      background-image: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/vit-quay-bac-kinh-01-1.jpg?v=1773634619\");\r\n      animation: slide1 8s infinite;\r\n    }\r\n\r\n    .slide2 {\r\n      background-image: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/tom-hum-01-1.jpg?v=1773634587\");\r\n      animation: slide2 8s infinite;\r\n    }\r\n\r\n    @keyframes slide1 {\r\n      0% { opacity: 1; }\r\n      45% { opacity: 1; }\r\n      50% { opacity: 0; }\r\n      95% { opacity: 0; }\r\n      100% { opacity: 1; }\r\n    }\r\n\r\n    @keyframes slide2 {\r\n      0% { opacity: 0; }\r\n      45% { opacity: 0; }\r\n      50% { opacity: 1; }\r\n      95% { opacity: 1; }\r\n      100% { opacity: 0; }\r\n    }\r\n\r\n    /*--Sec3--*/\r\n    .gd-restaurant-title {\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/bg-black.jpg\") center/cover no-repeat;\r\n      text-align: center;\r\n      padding: 20px 20px;\r\n      position: relative;\r\n    }\r\n\r\n    .gd-restaurant-title span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-weight: 150;\r\n      font-size: 70px;\r\n      letter-spacing: -2px;\r\n      position: relative;\r\n      display: inline-block;\r\n      padding: 30px 120px 40px;\r\n      background-image: linear-gradient(to right, #73541f, #845f1d, #926719, #ca9627, #cda33a, #e9e26b, #a97820, #926719, #ca9627, #cda33a);\r\n      -webkit-background-clip: text;\r\n      -webkit-text-fill-color: transparent;\r\n    }\r\n\r\n    .gd-restaurant-title span::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      inset: 0;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/frame-gangdong.png\") center/100% 100% no-repeat;\r\n      z-index: 102;\r\n    }\r\n\r\n    /*--Sec4: Photo Grid + Text--*/\r\n    .gd-menu-section {\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/background-gangdong.jpg\") repeat;\r\n      padding: 20px 0 0;\r\n      position: relative;\r\n    }\r\n\r\n    .gd-menu-inner {\r\n      max-width: 97.22vw;\r\n      margin: auto;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 2.78vw;\r\n    }\r\n\r\n    /* Photo Grid (thay menu slider) */\r\n    .gd-photo-grid {\r\n      width: 50%;\r\n      flex-shrink: 0;\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr 1fr;\r\n      grid-template-rows: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo:nth-child(1) {\r\n      grid-column: 1 / 2;\r\n      grid-row: 1 / 4;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo:nth-child(1) img {\r\n      object-position: 68% center;\r\n    }\r\n\r\n    /* text */\r\n    .gd-menu-text {\r\n      max-width: 29.17vw;\r\n      color: white;\r\n      line-height: 1.8;\r\n      font-size: 18px;\r\n      padding-top: 2.08vw;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    .gd-menu-text p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .gd-time {\r\n      margin-top: 1.39vw;\r\n      font-style: italic;\r\n      color: #e6d072;\r\n    }\r\n\r\n    /*--Sec5: Coverflow Carousel--*/\r\n    .gd-carousel-section {\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/background-gangdong.jpg\") repeat;\r\n      padding: 50px 0 0;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n\r\n    .gd-carousel-heading {\r\n      text-align: center;\r\n      padding: 0 30px 40px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-line::before,\r\n    .gd-carousel-heading .gd-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #ca9627, #e9e26b, #ca9627, transparent);\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #e9e26b, #ca9627);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #ca9627;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 52px;\r\n      font-weight: 200;\r\n      letter-spacing: 10px;\r\n      background-image: linear-gradient(to right, #6e4f1c, #a8792a, #c99a35, #e6d072, #c99a35, #a8792a, #6e4f1c);\r\n      -webkit-background-clip: text;\r\n      -webkit-text-fill-color: transparent;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 12px;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line::before,\r\n    .gd-carousel-heading .gd-heading-bottom-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 50px;\r\n      background: linear-gradient(to right, transparent, #ca9627);\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line::after {\r\n      background: linear-gradient(to left, transparent, #ca9627);\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 11px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      color: rgba(202, 150, 39, 0.7);\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .gd-carousel-wrapper {\r\n      position: relative;\r\n      height: 620px;\r\n      perspective: 1400px;\r\n      cursor: grab;\r\n      user-select: none;\r\n      overflow: visible;\r\n    }\r\n\r\n    .gd-carousel-wrapper:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .gd-carousel {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n      transform-style: preserve-3d;\r\n    }\r\n\r\n    .gd-carousel-item {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      width: 380px;\r\n      height: 540px;\r\n      margin-left: -190px;\r\n      margin-top: -270px;\r\n      border-radius: 8px;\r\n      overflow: hidden;\r\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.6);\r\n      cursor: pointer;\r\n      transition: transform 0.5s ease, opacity 0.5s ease, z-index 0s;\r\n      opacity: 0;\r\n    }\r\n\r\n    .gd-carousel-item img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n    }\r\n\r\n    .gd-carousel-nav {\r\n      display: flex;\r\n      justify-content: center;\r\n      gap: 30px;\r\n      padding: 20px 0 40px;\r\n    }\r\n\r\n    .gd-carousel-nav button {\r\n      background: rgba(0, 0, 0, 0.7);\r\n      border: 1.5px solid #a8792a;\r\n      color: #c99a35;\r\n      font-size: 24px;\r\n      width: 50px;\r\n      height: 50px;\r\n      border-radius: 50%;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n      box-shadow: 0 0 12px rgba(202, 150, 39, 0.15), inset 0 0 8px rgba(0, 0, 0, 0.5);\r\n    }\r\n\r\n    .gd-carousel-nav button:hover {\r\n      background: rgba(0, 0, 0, 0.9);\r\n      border-color: #e6d072;\r\n      color: #e6d072;\r\n      box-shadow: 0 0 18px rgba(230, 208, 114, 0.3), inset 0 0 8px rgba(0, 0, 0, 0.5);\r\n    }\r\n\r\n    /* waves on menu section */\r\n    .gd-menu-section::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 34.47vw;\r\n      height: 17.55vw;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/make-left.png\") no-repeat;\r\n      background-size: contain;\r\n      z-index: 6;\r\n    }\r\n\r\n    .gd-menu-section::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      right: 0;\r\n      width: 34.36vw;\r\n      height: 14.82vw;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/make-right.png\") no-repeat;\r\n      background-size: contain;\r\n      z-index: 6;\r\n    }\r\n\r\n    .gd-reservation-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #000;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 3.33vw;\r\n      font-weight: 100;\r\n      height: 6.6vw;\r\n      text-decoration: none;\r\n      transition: color .35s ease;\r\n      margin-top: 6.94vw;\r\n      position: relative;\r\n      z-index: 3;\r\n    }\r\n\r\n    .gd-reservation-bar:hover {\r\n      color: #cda33a;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n\r\n    @media (max-width: 1024px) {\r\n      .gd-menu-inner {\r\n        flex-direction: column;\r\n        padding: 20px;\r\n      }\r\n\r\n      .gd-photo-grid {\r\n        width: 80vw;\r\n      }\r\n\r\n      .gd-menu-text {\r\n        max-width: 80vw;\r\n        text-align: center;\r\n        padding-top: 3vw;\r\n      }\r\n\r\n      .gd-restaurant-title span {\r\n        font-size: 50px;\r\n        padding: 25px 80px 35px;\r\n      }\r\n\r\n      .guangdong-bar::after {\r\n        width: 200px;\r\n        height: 200px;\r\n        top: 200px;\r\n      }\r\n\r\n      .gd-carousel-wrapper {\r\n        height: 420px;\r\n      }\r\n\r\n      .gd-carousel-item {\r\n        width: 240px;\r\n        height: 350px;\r\n        margin-left: -120px;\r\n        margin-top: -175px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .guangdong-bar {\r\n        padding: 130px 30px 20px;\r\n      }\r\n\r\n      .gd-title {\r\n        font-size: 22px;\r\n      }\r\n\r\n      .gd-sub {\r\n        font-size: 13px;\r\n      }\r\n\r\n      .gd-phone {\r\n        font-size: 14px;\r\n      }\r\n\r\n      .guangdong-bar::after {\r\n        width: 150px;\r\n        height: 150px;\r\n        top: 150px;\r\n      }\r\n\r\n      .gd-restaurant-title span {\r\n        font-size: 36px;\r\n        padding: 20px 50px 28px;\r\n      }\r\n\r\n      .gd-photo-grid {\r\n        width: 90vw;\r\n        grid-template-columns: repeat(2, 1fr);\r\n        grid-template-rows: auto;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo:nth-child(1) {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo img {\r\n        height: 180px;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo:nth-child(1) img {\r\n        height: 250px;\r\n      }\r\n\r\n      .gd-menu-text {\r\n        max-width: 90vw;\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gd-menu-section::before,\r\n      .gd-menu-section::after {\r\n        display: none;\r\n      }\r\n\r\n      .gd-carousel-wrapper {\r\n        height: 420px;\r\n        perspective: 800px;\r\n      }\r\n\r\n      .gd-carousel-item {\r\n        width: 240px;\r\n        height: 340px;\r\n        margin-left: -120px;\r\n        margin-top: -170px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-main {\r\n        font-size: 36px;\r\n        letter-spacing: 6px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-line::before,\r\n      .gd-carousel-heading .gd-heading-line::after {\r\n        width: 50px;\r\n      }\r\n\r\n      .gd-reservation-bar {\r\n        font-size: 5.5vw;\r\n        height: auto;\r\n        padding: 15px 0;\r\n        margin-top: 8vw;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .guangdong-bar {\r\n        padding: 130px 15px 15px;\r\n      }\r\n\r\n      .gd-title {\r\n        font-size: 18px;\r\n      }\r\n\r\n      .gd-sub {\r\n        font-size: 11px;\r\n      }\r\n\r\n      .gd-phone {\r\n        font-size: 12px;\r\n      }\r\n\r\n      .gd-icon {\r\n        padding: 2px 5px;\r\n        font-size: 12px;\r\n      }\r\n\r\n      .guangdong-bar::after {\r\n        width: 80px;\r\n        height: 80px;\r\n        top: 140px;\r\n      }\r\n\r\n      .gd-restaurant-title span {\r\n        font-size: 24px;\r\n        padding: 15px 30px 20px;\r\n        letter-spacing: -1px;\r\n      }\r\n\r\n      .gd-photo-grid {\r\n        width: 95vw;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo img {\r\n        height: 130px;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo:nth-child(1) img {\r\n        height: 180px;\r\n      }\r\n\r\n      .gd-menu-text {\r\n        max-width: 95vw;\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .gd-carousel-wrapper {\r\n        height: 380px;\r\n        perspective: 600px;\r\n      }\r\n\r\n      .gd-carousel-item {\r\n        width: 200px;\r\n        height: 290px;\r\n        margin-left: -100px;\r\n        margin-top: -145px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-main {\r\n        font-size: 28px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-sub {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-line::before,\r\n      .gd-carousel-heading .gd-heading-line::after {\r\n        width: 35px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-bottom-line::before,\r\n      .gd-carousel-heading .gd-heading-bottom-line::after {\r\n        width: 30px;\r\n      }\r\n\r\n      .gd-carousel-nav button {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 18px;\r\n      }\r\n\r\n      .gd-reservation-bar {\r\n        font-size: 6vw;\r\n        padding: 12px 0;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Bar -->\r\n  <div class=\"guangdong-bar\">\r\n    <figure class=\"table\" style=\"width:100%;\">\r\n      <table>\r\n        <tbody>\r\n          <tr>\r\n            <td style=\"text-align:left;\">\r\n              <div class=\"gd-title\">OPENING HOURS</div>\r\n              <div class=\"gd-sub\">MONDAY - SUNDAY: 16:30 - 22:00</div>\r\n            </td>\r\n            <td style=\"text-align:right;\">\r\n              <div class=\"gd-title\">HOTLINE</div>\r\n              <div class=\"gd-phone\"><span class=\"gd-icon\">☎</span> 0254 386 8668</div>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </figure>\r\n  </div>\r\n\r\n  <!-- Sec2: Hero Slider (giữ nguyên) -->\r\n  <div class=\"gd-slider\">\r\n    <div class=\"gd-slides\">\r\n      <div class=\"gd-slide slide1 active\"> </div>\r\n      <div class=\"gd-slide slide2\"> </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Title -->\r\n  <div class=\"gd-restaurant-title\">\r\n    <span>GUANGDONG RESTAURANT</span>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Grid + Text (thay gd-menu-slider) -->\r\n  <section class=\"gd-menu-section\">\r\n    <div class=\"gd-menu-inner\">\r\n      <div class=\"gd-photo-grid\">\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/19.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/18.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/16.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/15.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/17.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/14.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/13.png\" alt=\"Guangdong\"></div>\r\n      </div>\r\n      <div class=\"gd-menu-text\">\r\n        <p>\r\n          Thưởng thức tinh hoa ẩm thực Trung Hoa tại nhà hàng Guangdong – nơi hội tụ hương vị truyền thống trong không gian sang trọng với tầm nhìn bao quát đại dương.\r\n        </p>\r\n        <p>\r\n          Nhà hàng gây ấn tượng với thiết kế đỏ – đen đặc trưng cùng đèn lồng truyền thống, mang đến trải nghiệm ẩm thực đậm chất Á Đông, tinh tế và khác biệt. Với sức chứa lên đến 150 khách, không gian được phân chia linh hoạt cùng các phòng VIP riêng tư, phù hợp cho tiệc gia đình, tiếp khách hay những buổi gặp gỡ quan trọng.\r\n        </p>\r\n        <p class=\"gd-time\">\r\n          Mở cửa hàng ngày từ 11:00 đến 22:00\r\n        </p>\r\n      </div>\r\n    </div>\r\n    <p>\r\n      <a class=\"gd-reservation-bar\" href=\"/reservation\"><span>MAKE A RESERVATION</span></a>\r\n    </p>\r\n  </section>\r\n\r\n  <!-- Sec5: 3D Carousel Menu -->\r\n  <section class=\"gd-carousel-section\">\r\n    <div class=\"gd-carousel-heading\">\r\n      <div class=\"gd-heading-line\"><div class=\"gd-heading-diamond\"></div></div>\r\n      <div class=\"gd-heading-sub\">Guangdong</div>\r\n      <div class=\"gd-heading-main\">Our Menu</div>\r\n      <div class=\"gd-heading-bottom-line\"><span>Signature Dishes</span></div>\r\n    </div>\r\n    <div class=\"gd-carousel-wrapper\" id=\"gdCarouselWrapper\">\r\n      <div class=\"gd-carousel\" id=\"gdCarousel\">\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/1.jpg\" alt=\"Menu 1\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/2.jpg\" alt=\"Menu 2\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/3.jpg\" alt=\"Menu 3\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/4.jpg\" alt=\"Menu 4\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/5.jpg\" alt=\"Menu 5\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/6.jpg\" alt=\"Menu 6\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/7.jpg\" alt=\"Menu 7\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/8.jpg\" alt=\"Menu 8\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/9.jpg\" alt=\"Menu 9\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/10.jpg\" alt=\"Menu 10\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/11.jpg\" alt=\"Menu 11\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/12.jpg\" alt=\"Menu 12\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/13.jpg\" alt=\"Menu 13\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/14.jpg\" alt=\"Menu 14\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/15.jpg\" alt=\"Menu 15\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/16.jpg\" alt=\"Menu 16\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/17.jpg\" alt=\"Menu 17\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"gd-carousel-nav\">\r\n      <button id=\"gdCarPrev\">❮</button>\r\n      <button id=\"gdCarNext\">❯</button>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= HERO SLIDER ========= */\r\n    document.addEventListener(\"DOMContentLoaded\", function () {\r\n      var gdSlides = document.querySelectorAll(\".gd-slide\")\r\n      if (gdSlides.length) {\r\n        var gdIndex = 0\r\n        function gdShowSlide() {\r\n          gdSlides.forEach(function (s) { s.classList.remove(\"active\") })\r\n          gdSlides[gdIndex].classList.add(\"active\")\r\n          gdIndex++\r\n          if (gdIndex >= gdSlides.length) gdIndex = 0\r\n        }\r\n        setInterval(gdShowSlide, 4000)\r\n      }\r\n    })\r\n\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gdLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gdGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gdCreateOverlay() {\r\n      if (gdLB.dialog) return\r\n      var pDoc = gdGetParentDoc()\r\n      gdLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gdCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:6px;cursor:grab;\'\r\n      gdLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gdLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gdCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gdCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gdLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gdLB.zoom.scale < 1) { gdLB.zoom.scale = 1; gdLB.zoom.x = 0; gdLB.zoom.y = 0 }\r\n        if (gdLB.zoom.scale > 5) gdLB.zoom.scale = 5\r\n        gdApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gdResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gdLB.zoom.dragging = true\r\n        gdLB.zoom.startX = e.clientX; gdLB.zoom.startY = e.clientY\r\n        gdLB.zoom.lastX = gdLB.zoom.x; gdLB.zoom.lastY = gdLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gdLB.zoom.dragging) return\r\n        gdLB.zoom.x = gdLB.zoom.lastX + (e.clientX - gdLB.zoom.startX) / gdLB.zoom.scale\r\n        gdLB.zoom.y = gdLB.zoom.lastY + (e.clientY - gdLB.zoom.startY) / gdLB.zoom.scale\r\n        gdApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gdLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gdLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gdLB.touches.scale0=gdLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gdLB.zoom.dragging=true; gdLB.zoom.startX=e.touches[0].clientX; gdLB.zoom.startY=e.touches[0].clientY; gdLB.zoom.lastX=gdLB.zoom.x; gdLB.zoom.lastY=gdLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gdLB.zoom.scale=gdLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gdLB.touches.dist); if(gdLB.zoom.scale<1)gdLB.zoom.scale=1;if(gdLB.zoom.scale>5)gdLB.zoom.scale=5; gdApplyZoom() }\r\n        else if (e.touches.length===1&&gdLB.zoom.dragging) { e.preventDefault(); gdLB.zoom.x=gdLB.zoom.lastX+(e.touches[0].clientX-gdLB.zoom.startX)/gdLB.zoom.scale; gdLB.zoom.y=gdLB.zoom.lastY+(e.touches[0].clientY-gdLB.zoom.startY)/gdLB.zoom.scale; gdApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gdLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gdCloseLightbox() })\r\n    }\r\n    function gdResetZoom() { gdLB.zoom.scale=1;gdLB.zoom.x=0;gdLB.zoom.y=0; if(gdLB.img)gdLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gdApplyZoom() { if(gdLB.img)gdLB.img.style.transform=\'scale(\'+gdLB.zoom.scale+\') translate(\'+gdLB.zoom.x+\'px,\'+gdLB.zoom.y+\'px)\' }\r\n    function gdOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gdCreateOverlay()\r\n      gdLB.img.src = img.src; gdResetZoom()\r\n      gdLB.dialog.showModal()\r\n      gdLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gdCloseLightbox() {\r\n      if (gdLB.dialog && gdLB.dialog.open) { gdLB.dialog.close(); gdLB.dialog.style.display = \'\'; gdResetZoom() }\r\n    }\r\n\r\n    /* ========= COVERFLOW CAROUSEL ========= */\r\n    ;(function () {\r\n      var wrapper = document.getElementById(\'gdCarouselWrapper\')\r\n      var items = document.querySelectorAll(\'.gd-carousel-item\')\r\n      var total = items.length\r\n      var current = 0\r\n      var VISIBLE = 5\r\n      var w = window.innerWidth\r\n\r\n      function layout(animated) {\r\n        w = window.innerWidth\r\n        var half = Math.floor(VISIBLE / 2)\r\n        for (var i = 0; i < total; i++) {\r\n          var offset = i - current\r\n          /* wrap around for looping */\r\n          if (offset > total / 2) offset -= total\r\n          if (offset < -total / 2) offset += total\r\n          var abs = Math.abs(offset)\r\n          var item = items[i]\r\n\r\n          if (abs > half) {\r\n            item.style.opacity = \'0\'\r\n            item.style.zIndex = \'0\'\r\n            item.style.transform = \'translateX(\' + (offset > 0 ? 800 : -800) + \'px) rotateY(0deg) scale(0.5)\'\r\n            item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n            continue\r\n          }\r\n\r\n          var spacing = w <= 480 ? 160 : (w <= 768 ? 190 : (w <= 1024 ? 220 : 280))\r\n          var tx = offset * spacing\r\n          var rotY = offset === 0 ? 0 : (offset < 0 ? 40 : -40)\r\n          var sc = offset === 0 ? 1 : 0.72 - abs * 0.06\r\n          var z = 100 - abs * 20\r\n\r\n          item.style.opacity = \'1\'\r\n          item.style.zIndex = \'\' + z\r\n          item.style.transform = \'translateX(\' + tx + \'px) rotateY(\' + rotY + \'deg) scale(\' + sc + \')\'\r\n          item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n          item.classList.toggle(\'gd-active\', offset === 0)\r\n        }\r\n      }\r\n\r\n      function goTo(idx) {\r\n        current = ((idx % total) + total) % total\r\n        layout(true)\r\n      }\r\n\r\n      layout(false)\r\n\r\n      document.getElementById(\'gdCarNext\').addEventListener(\'click\', function () {\r\n        goTo(current + 1)\r\n      })\r\n      document.getElementById(\'gdCarPrev\').addEventListener(\'click\', function () {\r\n        goTo(current - 1)\r\n      })\r\n\r\n      /* Click: center = zoom, other = navigate to shortest path */\r\n      for (var i = 0; i < total; i++) {\r\n        ;(function (idx) {\r\n          items[idx].addEventListener(\'click\', function () {\r\n            if (idx === current) {\r\n              gdCreateOverlay()\r\n              gdLB.img.src = items[idx].querySelector(\'img\').src\r\n              gdResetZoom(); gdLB.dialog.showModal(); gdLB.dialog.style.display = \'flex\'\r\n            } else {\r\n              /* find shortest direction */\r\n              var diff = idx - current\r\n              if (diff > total / 2) diff -= total\r\n              if (diff < -total / 2) diff += total\r\n              goTo(current + diff)\r\n            }\r\n          })\r\n        })(i)\r\n      }\r\n\r\n      /* Drag / Swipe */\r\n      var dragging = false, startX = 0, moved = false\r\n\r\n      wrapper.addEventListener(\'mousedown\', function (e) {\r\n        dragging = true; startX = e.clientX; moved = false\r\n      })\r\n      window.addEventListener(\'mousemove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.clientX - startX) > 10) moved = true\r\n      })\r\n      window.addEventListener(\'mouseup\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = e.clientX - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      wrapper.addEventListener(\'touchstart\', function (e) {\r\n        dragging = true; startX = e.touches[0].clientX; moved = false\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchmove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.touches[0].clientX - startX) > 10) moved = true\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchend\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = (e.changedTouches[0] ? e.changedTouches[0].clientX : startX) - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      /* Responsive: adjust spacing on resize */\r\n      function adjustSpacing() {\r\n        var w = window.innerWidth\r\n        if (w <= 480) VISIBLE = 3\r\n        else if (w <= 768) VISIBLE = 3\r\n        else VISIBLE = 5\r\n        layout(false)\r\n      }\r\n      window.addEventListener(\'resize\', adjustSpacing)\r\n      adjustSpacing()\r\n    })()\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Guangdong Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GUANGDONG=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n    }\r\n\r\n    /*--Sec1--*/\r\n    .guangdong-bar {\r\n      background: url(https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/background-gangdong.jpg) center/cover no-repeat;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      padding: 130px 60px 25px;\r\n      position: relative;\r\n    }\r\n\r\n    .guangdong-bar table {\r\n      width: 100%;\r\n    }\r\n\r\n    .gd-title {\r\n      text-transform: uppercase;\r\n      font-weight: 800;\r\n      font-size: 30px;\r\n      line-height: 1.2;\r\n      background: repeating-linear-gradient(100deg,\r\n          #6e4f1c 0px, #8a6525 8px, #b8892e 16px, #e6d072 24px,\r\n          #fff4a3 32px, #e6d072 40px, #c99a35 48px, #a8792a 56px, #6e4f1c 64px);\r\n      -webkit-background-clip: text;\r\n      -webkit-text-fill-color: transparent;\r\n    }\r\n\r\n    .gd-sub {\r\n      color: white;\r\n      font-size: 15px;\r\n      margin-top: 6px;\r\n    }\r\n\r\n    .gd-phone {\r\n      color: white;\r\n      font-size: 17px;\r\n      margin-top: 6px;\r\n    }\r\n\r\n    .gd-icon {\r\n      background: white;\r\n      color: #8b0000;\r\n      padding: 3px 7px;\r\n      border-radius: 0;\r\n      margin-right: 6px;\r\n    }\r\n\r\n    .guangdong-bar table,\r\n    .guangdong-bar td,\r\n    .guangdong-bar tr {\r\n      border: none !important;\r\n    }\r\n\r\n    .guangdong-bar::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      transform: translate(-50%, -50%);\r\n      width: 250px;\r\n      height: 250px;\r\n      top: 210px;\r\n      z-index: 10;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/logo-gangdong-3.png\") center/contain no-repeat;\r\n      pointer-events: none;\r\n    }\r\n\r\n    /*--SLIDER--*/\r\n    .gd-slider {\r\n      width: 100%;\r\n      height: 41.67vw;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .gd-slide {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n      top: 0;\r\n      left: 0;\r\n      background-size: cover;\r\n      background-position: center;\r\n      opacity: 0;\r\n    }\r\n\r\n    .slide1 {\r\n      background-image: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/vit-quay-bac-kinh-01-1.jpg?v=1773634619\");\r\n      animation: slide1 8s infinite;\r\n    }\r\n\r\n    .slide2 {\r\n      background-image: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/tom-hum-01-1.jpg?v=1773634587\");\r\n      animation: slide2 8s infinite;\r\n    }\r\n\r\n    @keyframes slide1 {\r\n      0% { opacity: 1; }\r\n      45% { opacity: 1; }\r\n      50% { opacity: 0; }\r\n      95% { opacity: 0; }\r\n      100% { opacity: 1; }\r\n    }\r\n\r\n    @keyframes slide2 {\r\n      0% { opacity: 0; }\r\n      45% { opacity: 0; }\r\n      50% { opacity: 1; }\r\n      95% { opacity: 1; }\r\n      100% { opacity: 0; }\r\n    }\r\n\r\n    /*--Sec3--*/\r\n    .gd-restaurant-title {\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/bg-black.jpg\") center/cover no-repeat;\r\n      text-align: center;\r\n      padding: 20px 20px;\r\n      position: relative;\r\n    }\r\n\r\n    .gd-restaurant-title span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-weight: 150;\r\n      font-size: 70px;\r\n      letter-spacing: -2px;\r\n      position: relative;\r\n      display: inline-block;\r\n      padding: 30px 120px 40px;\r\n      background-image: linear-gradient(to right, #73541f, #845f1d, #926719, #ca9627, #cda33a, #e9e26b, #a97820, #926719, #ca9627, #cda33a);\r\n      -webkit-background-clip: text;\r\n      -webkit-text-fill-color: transparent;\r\n    }\r\n\r\n    .gd-restaurant-title span::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      inset: 0;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/frame-gangdong.png\") center/100% 100% no-repeat;\r\n      z-index: 102;\r\n    }\r\n\r\n    /*--Sec4: Photo Grid + Text--*/\r\n    .gd-menu-section {\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/background-gangdong.jpg\") repeat;\r\n      padding: 20px 0 0;\r\n      position: relative;\r\n    }\r\n\r\n    .gd-menu-inner {\r\n      max-width: 97.22vw;\r\n      margin: auto;\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 2.78vw;\r\n    }\r\n\r\n    /* Photo Grid (thay menu slider) */\r\n    .gd-photo-grid {\r\n      width: 50%;\r\n      flex-shrink: 0;\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr 1fr;\r\n      grid-template-rows: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo:nth-child(1) {\r\n      grid-column: 1 / 2;\r\n      grid-row: 1 / 4;\r\n    }\r\n\r\n    .gd-photo-grid .gd-photo:nth-child(1) img {\r\n      object-position: 68% center;\r\n    }\r\n\r\n    /* text */\r\n    .gd-menu-text {\r\n      max-width: 29.17vw;\r\n      color: white;\r\n      line-height: 1.8;\r\n      font-size: 18px;\r\n      padding-top: 2.08vw;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    .gd-menu-text p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .gd-time {\r\n      margin-top: 1.39vw;\r\n      font-style: italic;\r\n      color: #e6d072;\r\n    }\r\n\r\n    /*--Sec5: Coverflow Carousel--*/\r\n    .gd-carousel-section {\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/background-gangdong.jpg\") repeat;\r\n      padding: 50px 0 0;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n\r\n    .gd-carousel-heading {\r\n      text-align: center;\r\n      padding: 0 30px 40px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-line::before,\r\n    .gd-carousel-heading .gd-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #ca9627, #e9e26b, #ca9627, transparent);\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #e9e26b, #ca9627);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #ca9627;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 52px;\r\n      font-weight: 200;\r\n      letter-spacing: 10px;\r\n      background-image: linear-gradient(to right, #6e4f1c, #a8792a, #c99a35, #e6d072, #c99a35, #a8792a, #6e4f1c);\r\n      -webkit-background-clip: text;\r\n      -webkit-text-fill-color: transparent;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 12px;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line::before,\r\n    .gd-carousel-heading .gd-heading-bottom-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 50px;\r\n      background: linear-gradient(to right, transparent, #ca9627);\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line::after {\r\n      background: linear-gradient(to left, transparent, #ca9627);\r\n    }\r\n\r\n    .gd-carousel-heading .gd-heading-bottom-line span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 11px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      color: rgba(202, 150, 39, 0.7);\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .gd-carousel-wrapper {\r\n      position: relative;\r\n      height: 620px;\r\n      perspective: 1400px;\r\n      cursor: grab;\r\n      user-select: none;\r\n      overflow: visible;\r\n    }\r\n\r\n    .gd-carousel-wrapper:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .gd-carousel {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n      transform-style: preserve-3d;\r\n    }\r\n\r\n    .gd-carousel-item {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      width: 380px;\r\n      height: 540px;\r\n      margin-left: -190px;\r\n      margin-top: -270px;\r\n      border-radius: 0;\r\n      overflow: hidden;\r\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.6);\r\n      cursor: pointer;\r\n      transition: transform 0.5s ease, opacity 0.5s ease, z-index 0s;\r\n      opacity: 0;\r\n    }\r\n\r\n    .gd-carousel-item img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n    }\r\n\r\n    .gd-carousel-nav {\r\n      display: flex;\r\n      justify-content: center;\r\n      gap: 30px;\r\n      padding: 20px 0 40px;\r\n    }\r\n\r\n    .gd-carousel-nav button {\r\n      background: rgba(0, 0, 0, 0.7);\r\n      border: 1.5px solid #a8792a;\r\n      color: #c99a35;\r\n      font-size: 24px;\r\n      width: 50px;\r\n      height: 50px;\r\n      border-radius: 50%;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n      box-shadow: 0 0 12px rgba(202, 150, 39, 0.15), inset 0 0 8px rgba(0, 0, 0, 0.5);\r\n    }\r\n\r\n    .gd-carousel-nav button:hover {\r\n      background: rgba(0, 0, 0, 0.9);\r\n      border-color: #e6d072;\r\n      color: #e6d072;\r\n      box-shadow: 0 0 18px rgba(230, 208, 114, 0.3), inset 0 0 8px rgba(0, 0, 0, 0.5);\r\n    }\r\n\r\n    /* waves on menu section */\r\n    .gd-menu-section::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 34.47vw;\r\n      height: 17.55vw;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/make-left.png\") no-repeat;\r\n      background-size: contain;\r\n      z-index: 6;\r\n    }\r\n\r\n    .gd-menu-section::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      right: 0;\r\n      width: 34.36vw;\r\n      height: 14.82vw;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/make-right.png\") no-repeat;\r\n      background-size: contain;\r\n      z-index: 6;\r\n    }\r\n\r\n    .gd-reservation-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #000;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 3.33vw;\r\n      font-weight: 100;\r\n      height: 6.6vw;\r\n      text-decoration: none;\r\n      transition: color .35s ease;\r\n      margin-top: 6.94vw;\r\n      position: relative;\r\n      z-index: 3;\r\n    }\r\n\r\n    .gd-reservation-bar:hover {\r\n      color: #cda33a;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n\r\n    @media (max-width: 1024px) {\r\n      .gd-menu-inner {\r\n        flex-direction: column;\r\n        padding: 20px;\r\n      }\r\n\r\n      .gd-photo-grid {\r\n        width: 80vw;\r\n      }\r\n\r\n      .gd-menu-text {\r\n        max-width: 80vw;\r\n        text-align: center;\r\n        padding-top: 3vw;\r\n      }\r\n\r\n      .gd-restaurant-title span {\r\n        font-size: 50px;\r\n        padding: 25px 80px 35px;\r\n      }\r\n\r\n      .guangdong-bar::after {\r\n        width: 200px;\r\n        height: 200px;\r\n        top: 200px;\r\n      }\r\n\r\n      .gd-carousel-wrapper {\r\n        height: 420px;\r\n      }\r\n\r\n      .gd-carousel-item {\r\n        width: 240px;\r\n        height: 350px;\r\n        margin-left: -120px;\r\n        margin-top: -175px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .guangdong-bar {\r\n        padding: 130px 30px 20px;\r\n      }\r\n\r\n      .gd-title {\r\n        font-size: 22px;\r\n      }\r\n\r\n      .gd-sub {\r\n        font-size: 13px;\r\n      }\r\n\r\n      .gd-phone {\r\n        font-size: 14px;\r\n      }\r\n\r\n      .guangdong-bar::after {\r\n        width: 150px;\r\n        height: 150px;\r\n        top: 150px;\r\n      }\r\n\r\n      .gd-restaurant-title span {\r\n        font-size: 36px;\r\n        padding: 20px 50px 28px;\r\n      }\r\n\r\n      .gd-photo-grid {\r\n        width: 90vw;\r\n        grid-template-columns: repeat(2, 1fr);\r\n        grid-template-rows: auto;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo:nth-child(1) {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo img {\r\n        height: 180px;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo:nth-child(1) img {\r\n        height: 250px;\r\n      }\r\n\r\n      .gd-menu-text {\r\n        max-width: 90vw;\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gd-menu-section::before,\r\n      .gd-menu-section::after {\r\n        display: none;\r\n      }\r\n\r\n      .gd-carousel-wrapper {\r\n        height: 420px;\r\n        perspective: 800px;\r\n      }\r\n\r\n      .gd-carousel-item {\r\n        width: 240px;\r\n        height: 340px;\r\n        margin-left: -120px;\r\n        margin-top: -170px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-main {\r\n        font-size: 36px;\r\n        letter-spacing: 6px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-line::before,\r\n      .gd-carousel-heading .gd-heading-line::after {\r\n        width: 50px;\r\n      }\r\n\r\n      .gd-reservation-bar {\r\n        font-size: 5.5vw;\r\n        height: auto;\r\n        padding: 15px 0;\r\n        margin-top: 8vw;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .guangdong-bar {\r\n        padding: 100px 15px 15px;\r\n      }\r\n\r\n      .gd-title {\r\n        font-size: 18px;\r\n      }\r\n\r\n      .gd-sub {\r\n        font-size: 11px;\r\n      }\r\n\r\n      .gd-phone {\r\n        font-size: 12px;\r\n      }\r\n\r\n      .gd-icon {\r\n        padding: 2px 5px;\r\n        font-size: 12px;\r\n      }\r\n\r\n      .guangdong-bar::after {\r\n        width: 80px;\r\n        height: 80px;\r\n        top: 140px;\r\n      }\r\n\r\n      .gd-restaurant-title span {\r\n        font-size: 24px;\r\n        padding: 15px 30px 20px;\r\n        letter-spacing: -1px;\r\n      }\r\n\r\n      .gd-photo-grid {\r\n        width: 95vw;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo img {\r\n        height: 130px;\r\n      }\r\n\r\n      .gd-photo-grid .gd-photo:nth-child(1) img {\r\n        height: 180px;\r\n      }\r\n\r\n      .gd-menu-text {\r\n        max-width: 95vw;\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .gd-carousel-wrapper {\r\n        height: 380px;\r\n        perspective: 600px;\r\n      }\r\n\r\n      .gd-carousel-item {\r\n        width: 200px;\r\n        height: 290px;\r\n        margin-left: -100px;\r\n        margin-top: -145px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-main {\r\n        font-size: 28px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-sub {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-line::before,\r\n      .gd-carousel-heading .gd-heading-line::after {\r\n        width: 35px;\r\n      }\r\n\r\n      .gd-carousel-heading .gd-heading-bottom-line::before,\r\n      .gd-carousel-heading .gd-heading-bottom-line::after {\r\n        width: 30px;\r\n      }\r\n\r\n      .gd-carousel-nav button {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 18px;\r\n      }\r\n\r\n      .gd-reservation-bar {\r\n        font-size: 6vw;\r\n        padding: 12px 0;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Bar -->\r\n  <div class=\"guangdong-bar\">\r\n    <figure class=\"table\" style=\"width:100%;\">\r\n      <table>\r\n        <tbody>\r\n          <tr>\r\n            <td style=\"text-align:left;\">\r\n              <div class=\"gd-title\">OPENING HOURS</div>\r\n              <div class=\"gd-sub\">MONDAY - SUNDAY: 16:30 - 22:00</div>\r\n            </td>\r\n            <td style=\"text-align:right;\">\r\n              <div class=\"gd-title\">HOTLINE</div>\r\n              <div class=\"gd-phone\"><span class=\"gd-icon\">&#9742;</span> 0254 386 8668</div>\r\n            </td>\r\n          </tr>\r\n        </tbody>\r\n      </table>\r\n    </figure>\r\n  </div>\r\n\r\n  <!-- Sec2: Hero Slider (giữ nguyên) -->\r\n  <div class=\"gd-slider\">\r\n    <div class=\"gd-slides\">\r\n      <div class=\"gd-slide slide1 active\">&nbsp;</div>\r\n      <div class=\"gd-slide slide2\">&nbsp;</div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Title -->\r\n  <div class=\"gd-restaurant-title\">\r\n    <span>GUANGDONG RESTAURANT</span>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Grid + Text (thay gd-menu-slider) -->\r\n  <section class=\"gd-menu-section\">\r\n    <div class=\"gd-menu-inner\">\r\n      <div class=\"gd-photo-grid\">\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/19.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/18.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/16.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/15.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/17.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/14.png\" alt=\"Guangdong\"></div>\r\n        <div class=\"gd-photo\" onclick=\"gdOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/anh-1/13.png\" alt=\"Guangdong\"></div>\r\n      </div>\r\n      <div class=\"gd-menu-text\">\r\n        <p>\r\n          Thưởng thức tinh hoa ẩm thực Trung Hoa tại nhà hàng Guangdong &ndash; nơi hội tụ hương vị truyền thống trong không gian sang trọng với tầm nhìn bao quát đại dương.\r\n        </p>\r\n        <p>\r\n          Nhà hàng gây ấn tượng với thiết kế đỏ &ndash; đen đặc trưng cùng đèn lồng truyền thống, mang đến trải nghiệm ẩm thực đậm chất Á Đông, tinh tế và khác biệt. Với sức chứa lên đến 150 khách, không gian được phân chia linh hoạt cùng các phòng VIP riêng tư, phù hợp cho tiệc gia đình, tiếp khách hay những buổi gặp gỡ quan trọng.\r\n        </p>\r\n        <p class=\"gd-time\">\r\n          Mở cửa hàng ngày từ 11:00 đến 22:00\r\n        </p>\r\n      </div>\r\n    </div>\r\n    <p>\r\n      <a class=\"gd-reservation-bar\" href=\"/reservation\"><span>MAKE A RESERVATION</span></a>\r\n    </p>\r\n  </section>\r\n\r\n  <!-- Sec5: 3D Carousel Menu -->\r\n  <section class=\"gd-carousel-section\">\r\n    <div class=\"gd-carousel-heading\">\r\n      <div class=\"gd-heading-line\"><div class=\"gd-heading-diamond\"></div></div>\r\n      <div class=\"gd-heading-sub\">Guangdong</div>\r\n      <div class=\"gd-heading-main\">Our Menu</div>\r\n      <div class=\"gd-heading-bottom-line\"><span>Signature Dishes</span></div>\r\n    </div>\r\n    <div class=\"gd-carousel-wrapper\" id=\"gdCarouselWrapper\">\r\n      <div class=\"gd-carousel\" id=\"gdCarousel\">\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/1.jpg\" alt=\"Menu 1\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/2.jpg\" alt=\"Menu 2\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/3.jpg\" alt=\"Menu 3\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/4.jpg\" alt=\"Menu 4\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/5.jpg\" alt=\"Menu 5\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/6.jpg\" alt=\"Menu 6\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/7.jpg\" alt=\"Menu 7\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/8.jpg\" alt=\"Menu 8\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/9.jpg\" alt=\"Menu 9\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/10.jpg\" alt=\"Menu 10\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/11.jpg\" alt=\"Menu 11\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/12.jpg\" alt=\"Menu 12\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/13.jpg\" alt=\"Menu 13\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/14.jpg\" alt=\"Menu 14\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/15.jpg\" alt=\"Menu 15\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/16.jpg\" alt=\"Menu 16\"></div>\r\n        <div class=\"gd-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/guangdong-restaurant/menu/17.jpg\" alt=\"Menu 17\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"gd-carousel-nav\">\r\n      <button id=\"gdCarPrev\">&#10094;</button>\r\n      <button id=\"gdCarNext\">&#10095;</button>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= HERO SLIDER ========= */\r\n    document.addEventListener(\"DOMContentLoaded\", function () {\r\n      var gdSlides = document.querySelectorAll(\".gd-slide\")\r\n      if (gdSlides.length) {\r\n        var gdIndex = 0\r\n        function gdShowSlide() {\r\n          gdSlides.forEach(function (s) { s.classList.remove(\"active\") })\r\n          gdSlides[gdIndex].classList.add(\"active\")\r\n          gdIndex++\r\n          if (gdIndex >= gdSlides.length) gdIndex = 0\r\n        }\r\n        setInterval(gdShowSlide, 4000)\r\n      }\r\n    })\r\n\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gdLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gdGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gdCreateOverlay() {\r\n      if (gdLB.dialog) return\r\n      var pDoc = gdGetParentDoc()\r\n      gdLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gdCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      gdLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gdLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gdCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gdCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gdLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gdLB.zoom.scale < 1) { gdLB.zoom.scale = 1; gdLB.zoom.x = 0; gdLB.zoom.y = 0 }\r\n        if (gdLB.zoom.scale > 5) gdLB.zoom.scale = 5\r\n        gdApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gdResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gdLB.zoom.dragging = true\r\n        gdLB.zoom.startX = e.clientX; gdLB.zoom.startY = e.clientY\r\n        gdLB.zoom.lastX = gdLB.zoom.x; gdLB.zoom.lastY = gdLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gdLB.zoom.dragging) return\r\n        gdLB.zoom.x = gdLB.zoom.lastX + (e.clientX - gdLB.zoom.startX) / gdLB.zoom.scale\r\n        gdLB.zoom.y = gdLB.zoom.lastY + (e.clientY - gdLB.zoom.startY) / gdLB.zoom.scale\r\n        gdApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gdLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gdLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gdLB.touches.scale0=gdLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gdLB.zoom.dragging=true; gdLB.zoom.startX=e.touches[0].clientX; gdLB.zoom.startY=e.touches[0].clientY; gdLB.zoom.lastX=gdLB.zoom.x; gdLB.zoom.lastY=gdLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gdLB.zoom.scale=gdLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gdLB.touches.dist); if(gdLB.zoom.scale<1)gdLB.zoom.scale=1;if(gdLB.zoom.scale>5)gdLB.zoom.scale=5; gdApplyZoom() }\r\n        else if (e.touches.length===1&&gdLB.zoom.dragging) { e.preventDefault(); gdLB.zoom.x=gdLB.zoom.lastX+(e.touches[0].clientX-gdLB.zoom.startX)/gdLB.zoom.scale; gdLB.zoom.y=gdLB.zoom.lastY+(e.touches[0].clientY-gdLB.zoom.startY)/gdLB.zoom.scale; gdApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gdLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gdCloseLightbox() })\r\n    }\r\n    function gdResetZoom() { gdLB.zoom.scale=1;gdLB.zoom.x=0;gdLB.zoom.y=0; if(gdLB.img)gdLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gdApplyZoom() { if(gdLB.img)gdLB.img.style.transform=\'scale(\'+gdLB.zoom.scale+\') translate(\'+gdLB.zoom.x+\'px,\'+gdLB.zoom.y+\'px)\' }\r\n    function gdOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gdCreateOverlay()\r\n      gdLB.img.src = img.src; gdResetZoom()\r\n      gdLB.dialog.showModal()\r\n      gdLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gdCloseLightbox() {\r\n      if (gdLB.dialog && gdLB.dialog.open) { gdLB.dialog.close(); gdLB.dialog.style.display = \'\'; gdResetZoom() }\r\n    }\r\n\r\n    /* ========= COVERFLOW CAROUSEL ========= */\r\n    ;(function () {\r\n      var wrapper = document.getElementById(\'gdCarouselWrapper\')\r\n      var items = document.querySelectorAll(\'.gd-carousel-item\')\r\n      var total = items.length\r\n      var current = 0\r\n      var VISIBLE = 5\r\n      var w = window.innerWidth\r\n\r\n      function layout(animated) {\r\n        w = window.innerWidth\r\n        var half = Math.floor(VISIBLE / 2)\r\n        for (var i = 0; i < total; i++) {\r\n          var offset = i - current\r\n          /* wrap around for looping */\r\n          if (offset > total / 2) offset -= total\r\n          if (offset < -total / 2) offset += total\r\n          var abs = Math.abs(offset)\r\n          var item = items[i]\r\n\r\n          if (abs > half) {\r\n            item.style.opacity = \'0\'\r\n            item.style.zIndex = \'0\'\r\n            item.style.transform = \'translateX(\' + (offset > 0 ? 800 : -800) + \'px) rotateY(0deg) scale(0.5)\'\r\n            item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n            continue\r\n          }\r\n\r\n          var spacing = w <= 480 ? 160 : (w <= 768 ? 190 : (w <= 1024 ? 220 : 280))\r\n          var tx = offset * spacing\r\n          var rotY = offset === 0 ? 0 : (offset < 0 ? 40 : -40)\r\n          var sc = offset === 0 ? 1 : 0.72 - abs * 0.06\r\n          var z = 100 - abs * 20\r\n\r\n          item.style.opacity = \'1\'\r\n          item.style.zIndex = \'\' + z\r\n          item.style.transform = \'translateX(\' + tx + \'px) rotateY(\' + rotY + \'deg) scale(\' + sc + \')\'\r\n          item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n          item.classList.toggle(\'gd-active\', offset === 0)\r\n        }\r\n      }\r\n\r\n      function goTo(idx) {\r\n        current = ((idx % total) + total) % total\r\n        layout(true)\r\n      }\r\n\r\n      layout(false)\r\n\r\n      document.getElementById(\'gdCarNext\').addEventListener(\'click\', function () {\r\n        goTo(current + 1)\r\n      })\r\n      document.getElementById(\'gdCarPrev\').addEventListener(\'click\', function () {\r\n        goTo(current - 1)\r\n      })\r\n\r\n      /* Click: center = zoom, other = navigate to shortest path */\r\n      for (var i = 0; i < total; i++) {\r\n        ;(function (idx) {\r\n          items[idx].addEventListener(\'click\', function () {\r\n            if (idx === current) {\r\n              gdCreateOverlay()\r\n              gdLB.img.src = items[idx].querySelector(\'img\').src\r\n              gdResetZoom(); gdLB.dialog.showModal(); gdLB.dialog.style.display = \'flex\'\r\n            } else {\r\n              /* find shortest direction */\r\n              var diff = idx - current\r\n              if (diff > total / 2) diff -= total\r\n              if (diff < -total / 2) diff += total\r\n              goTo(current + diff)\r\n            }\r\n          })\r\n        })(i)\r\n      }\r\n\r\n      /* Drag / Swipe */\r\n      var dragging = false, startX = 0, moved = false\r\n\r\n      wrapper.addEventListener(\'mousedown\', function (e) {\r\n        dragging = true; startX = e.clientX; moved = false\r\n      })\r\n      window.addEventListener(\'mousemove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.clientX - startX) > 10) moved = true\r\n      })\r\n      window.addEventListener(\'mouseup\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = e.clientX - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      wrapper.addEventListener(\'touchstart\', function (e) {\r\n        dragging = true; startX = e.touches[0].clientX; moved = false\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchmove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.touches[0].clientX - startX) > 10) moved = true\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchend\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = (e.changedTouches[0] ? e.changedTouches[0].clientX : startX) - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      /* Responsive: adjust spacing on resize */\r\n      function adjustSpacing() {\r\n        var w = window.innerWidth\r\n        if (w <= 480) VISIBLE = 3\r\n        else if (w <= 768) VISIBLE = 3\r\n        else VISIBLE = 5\r\n        layout(false)\r\n      }\r\n      window.addEventListener(\'resize\', adjustSpacing)\r\n      adjustSpacing()\r\n    })()\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 16:13:41', '2026-03-25 16:13:41');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(82, 'Botble\\Page\\Models\\Page', 16, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Asian Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====ASIAN RESTAURANT=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .as-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .as-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .as-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-title-section .as-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .as-title-divider::before,\r\n    .as-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-title-divider .as-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .as-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .as-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .as-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n      border-radius: 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .as-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line::before,\r\n    .as-gallery-heading .as-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      border-radius: 8px;\r\n      cursor: pointer;\r\n      background: #e8f0f8;\r\n      position: relative;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /* Placeholder squares (no image yet) */\r\n    .as-gallery-grid .as-photo.placeholder::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      inset: 0;\r\n      background: linear-gradient(135deg, #e8f0f8 0%, #d0e2f3 50%, #e8f0f8 100%);\r\n    }\r\n\r\n    .as-gallery-grid .as-photo.placeholder::after {\r\n      content: \"\\1F3E8\";\r\n      position: absolute;\r\n      top: 50%;\r\n      left: 50%;\r\n      transform: translate(-50%, -50%);\r\n      font-size: 40px;\r\n      opacity: 0.25;\r\n    }\r\n\r\n    /*--Sec5: Menu Carousel--*/\r\n    .as-menu-section {\r\n      background: #0e4d97;\r\n      padding: 50px 0 0;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .as-menu-heading {\r\n      text-align: center;\r\n      padding: 0 30px 40px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line::before,\r\n    .as-menu-heading .as-mh-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, rgba(255,255,255,0.5), #00adef, transparent);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #fff);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 52px;\r\n      font-weight: 200;\r\n      letter-spacing: 10px;\r\n      color: #fff;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 12px;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::before,\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 50px;\r\n      background: linear-gradient(to right, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      background: linear-gradient(to left, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 11px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      color: rgba(0, 173, 239, 0.7);\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .as-carousel-wrapper {\r\n      position: relative;\r\n      height: 620px;\r\n      perspective: 1400px;\r\n      cursor: grab;\r\n      user-select: none;\r\n      overflow: visible;\r\n    }\r\n\r\n    .as-carousel-wrapper:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-carousel {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n    }\r\n\r\n    .as-carousel-item {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      width: 380px;\r\n      height: 540px;\r\n      margin-left: -190px;\r\n      margin-top: -270px;\r\n      border-radius: 8px;\r\n      overflow: hidden;\r\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.5);\r\n      cursor: pointer;\r\n      transition: transform 0.5s ease, opacity 0.5s ease;\r\n      opacity: 0;\r\n      z-index: 1;\r\n    }\r\n\r\n    .as-carousel-item.as-active {\r\n      z-index: 200 !important;\r\n    }\r\n\r\n    .as-carousel-item img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n    }\r\n\r\n    .as-carousel-nav {\r\n      display: flex;\r\n      justify-content: center;\r\n      gap: 30px;\r\n      padding: 20px 0 40px;\r\n    }\r\n\r\n    .as-carousel-nav button {\r\n      background: rgba(0, 0, 0, 0.4);\r\n      border: 1.5px solid #00adef;\r\n      color: #00adef;\r\n      font-size: 24px;\r\n      width: 50px;\r\n      height: 50px;\r\n      border-radius: 50%;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n      box-shadow: 0 0 12px rgba(0, 173, 239, 0.15), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    .as-carousel-nav button:hover {\r\n      background: #083a72;\r\n      border-color: #fff;\r\n      color: #fff;\r\n      box-shadow: 0 0 18px rgba(0, 173, 239, 0.3), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    /*--Reservation Bar--*/\r\n    .as-reservation-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #083a72;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 3.33vw;\r\n      font-weight: 100;\r\n      height: 6.6vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease, color .35s ease;\r\n      margin-top: 30px;\r\n      position: relative;\r\n      z-index: 3;\r\n    }\r\n\r\n    .as-reservation-bar:hover {\r\n      background: #00adef;\r\n      color: #fff;\r\n    }\r\n\r\n    /*--LIGHTBOX--*/\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 350px;\r\n        margin-left: -120px;\r\n        margin-top: -175px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .as-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 36px;\r\n        letter-spacing: 6px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n        perspective: 800px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 340px;\r\n        margin-left: -120px;\r\n        margin-top: -170px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 5.5vw;\r\n        height: auto;\r\n        padding: 15px 0;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .as-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-title-section .as-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .as-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 28px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-sub {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 380px;\r\n        perspective: 600px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 200px;\r\n        height: 290px;\r\n        margin-left: -100px;\r\n        margin-top: -145px;\r\n      }\r\n\r\n      .as-carousel-nav button {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 18px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 6vw;\r\n        padding: 12px 0;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"as-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"as-title-section\">\r\n    <div class=\"as-label\">Ruby 68 Hotel</div>\r\n    <h1>Asian Restaurant</h1>\r\n    <div class=\"as-title-divider\">\r\n      <div class=\"as-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"as-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 8 khách sạn Ruby 68 với tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu, nhà hàng Asian mang đến hành trình ẩm thực tinh tế, nơi vị giác và cảm xúc được nâng tầm trong không gian sang trọng và đầy cảm hứng.\r\n    </p>\r\n    <p>\r\n      Thực đơn à la carte đa dạng từ Á đến Âu, được chế biến bởi đội ngũ đầu bếp chuẩn 3 sao, kết hợp hài hòa giữa nguyên liệu cao cấp và nghệ thuật trình bày tinh xảo. Mỗi món ăn không chỉ là hương vị, mà còn là một trải nghiệm ẩm thực trọn vẹn.\r\n    </p>\r\n    <p>\r\n      Dù là bữa tối lãng mạn, buổi gặp gỡ đối tác hay khoảnh khắc thư giãn bên gia đình, Asian Restaurant luôn là lựa chọn hoàn hảo để tận hưởng ẩm thực đẳng cấp giữa khung cảnh biển trời tuyệt đẹp.\r\n    </p>\r\n    <div class=\"as-time\">Mở cửa hàng ngày từ 6:30 đến 11:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"as-gallery-section\">\r\n    <div class=\"as-gallery-heading\">\r\n      <div class=\"as-heading-line\">\r\n        <div class=\"as-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-heading-sub\">Asian</div>\r\n      <div class=\"as-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"as-gallery-grid\">\r\n      <div class=\"as-photo\" onclick=\"asOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\" alt=\"Asian Restaurant\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec5: Menu Carousel -->\r\n  <section class=\"as-menu-section\">\r\n    <div class=\"as-menu-heading\">\r\n      <div class=\"as-mh-line\">\r\n        <div class=\"as-mh-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-mh-sub\">Asian</div>\r\n      <div class=\"as-mh-main\">Our Menu</div>\r\n      <div class=\"as-mh-bottom\"><span>Signature Dishes</span></div>\r\n    </div>\r\n    <div class=\"as-carousel-wrapper\" id=\"asCarouselWrapper\">\r\n      <div class=\"as-carousel\" id=\"asCarousel\">\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/1.jpg\" alt=\"Menu 1\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/2.jpg\" alt=\"Menu 2\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/3.jpg\" alt=\"Menu 3\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"as-carousel-nav\">\r\n      <button id=\"asCarPrev\">&#10094;</button>\r\n      <button id=\"asCarNext\">&#10095;</button>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var asLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function asGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function asCreateOverlay() {\r\n      if (asLB.dialog) return\r\n      var pDoc = asGetParentDoc()\r\n      asLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { asCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:6px;cursor:grab;\'\r\n      asLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      asLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) asCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); asCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        asLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (asLB.zoom.scale < 1) { asLB.zoom.scale = 1; asLB.zoom.x = 0; asLB.zoom.y = 0 }\r\n        if (asLB.zoom.scale > 5) asLB.zoom.scale = 5\r\n        asApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); asResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); asLB.zoom.dragging = true\r\n        asLB.zoom.startX = e.clientX; asLB.zoom.startY = e.clientY\r\n        asLB.zoom.lastX = asLB.zoom.x; asLB.zoom.lastY = asLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!asLB.zoom.dragging) return\r\n        asLB.zoom.x = asLB.zoom.lastX + (e.clientX - asLB.zoom.startX) / asLB.zoom.scale\r\n        asLB.zoom.y = asLB.zoom.lastY + (e.clientY - asLB.zoom.startY) / asLB.zoom.scale\r\n        asApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { asLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; asLB.touches.dist=Math.sqrt(dx*dx+dy*dy); asLB.touches.scale0=asLB.zoom.scale }\r\n        else if (e.touches.length === 1) { asLB.zoom.dragging=true; asLB.zoom.startX=e.touches[0].clientX; asLB.zoom.startY=e.touches[0].clientY; asLB.zoom.lastX=asLB.zoom.x; asLB.zoom.lastY=asLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; asLB.zoom.scale=asLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/asLB.touches.dist); if(asLB.zoom.scale<1)asLB.zoom.scale=1;if(asLB.zoom.scale>5)asLB.zoom.scale=5; asApplyZoom() }\r\n        else if (e.touches.length===1&&asLB.zoom.dragging) { e.preventDefault(); asLB.zoom.x=asLB.zoom.lastX+(e.touches[0].clientX-asLB.zoom.startX)/asLB.zoom.scale; asLB.zoom.y=asLB.zoom.lastY+(e.touches[0].clientY-asLB.zoom.startY)/asLB.zoom.scale; asApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { asLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') asCloseLightbox() })\r\n    }\r\n    function asResetZoom() { asLB.zoom.scale=1;asLB.zoom.x=0;asLB.zoom.y=0; if(asLB.img)asLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function asApplyZoom() { if(asLB.img)asLB.img.style.transform=\'scale(\'+asLB.zoom.scale+\') translate(\'+asLB.zoom.x+\'px,\'+asLB.zoom.y+\'px)\' }\r\n    function asOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      asCreateOverlay()\r\n      asLB.img.src = img.src; asResetZoom()\r\n      asLB.dialog.showModal()\r\n      asLB.dialog.style.display = \'flex\'\r\n    }\r\n    function asCloseLightbox() {\r\n      if (asLB.dialog && asLB.dialog.open) { asLB.dialog.close(); asLB.dialog.style.display = \'\'; asResetZoom() }\r\n    }\r\n\r\n    /* ========= COVERFLOW CAROUSEL ========= */\r\n    ;(function () {\r\n      var wrapper = document.getElementById(\'asCarouselWrapper\')\r\n      var items = document.querySelectorAll(\'.as-carousel-item\')\r\n      var total = items.length\r\n      var current = 0\r\n      var VISIBLE = total >= 5 ? 5 : total\r\n\r\n      function layout(animated) {\r\n        var w = window.innerWidth\r\n        var half = Math.floor(VISIBLE / 2)\r\n\r\n        for (var i = 0; i < total; i++) {\r\n          var offset = i - current\r\n          if (offset > total / 2) offset -= total\r\n          if (offset < -total / 2) offset += total\r\n          var abs = Math.abs(offset)\r\n          var item = items[i]\r\n\r\n          /* Only toggle class — z-index handled purely by CSS */\r\n          item.style.zIndex = \'\'\r\n          item.classList.toggle(\'as-active\', offset === 0)\r\n\r\n          if (abs > half) {\r\n            item.style.opacity = \'0\'\r\n            item.style.transform = \'translateX(\' + (offset > 0 ? 800 : -800) + \'px) rotateY(0deg) scale(0.5)\'\r\n            item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n            continue\r\n          }\r\n\r\n          var spacing = w <= 480 ? 160 : (w <= 768 ? 190 : (w <= 1024 ? 220 : 280))\r\n          var tx = offset * spacing\r\n          var rotY = offset === 0 ? 0 : (offset < 0 ? 40 : -40)\r\n          var sc = offset === 0 ? 1 : 0.72 - abs * 0.06\r\n\r\n          item.style.opacity = \'1\'\r\n          item.style.transform = \'translateX(\' + tx + \'px) rotateY(\' + rotY + \'deg) scale(\' + sc + \')\'\r\n          item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n        }\r\n      }\r\n\r\n      function goTo(idx) {\r\n        current = ((idx % total) + total) % total\r\n        layout(true)\r\n      }\r\n\r\n      layout(false)\r\n\r\n      document.getElementById(\'asCarNext\').addEventListener(\'click\', function () {\r\n        goTo(current + 1)\r\n      })\r\n      document.getElementById(\'asCarPrev\').addEventListener(\'click\', function () {\r\n        goTo(current - 1)\r\n      })\r\n\r\n      for (var i = 0; i < total; i++) {\r\n        ;(function (idx) {\r\n          items[idx].addEventListener(\'click\', function () {\r\n            if (idx === current) {\r\n              asCreateOverlay()\r\n              asLB.img.src = items[idx].querySelector(\'img\').src\r\n              asResetZoom(); asLB.dialog.showModal(); asLB.dialog.style.display = \'flex\'\r\n            } else {\r\n              var diff = idx - current\r\n              if (diff > total / 2) diff -= total\r\n              if (diff < -total / 2) diff += total\r\n              goTo(current + diff)\r\n            }\r\n          })\r\n        })(i)\r\n      }\r\n\r\n      /* Drag / Swipe */\r\n      var dragging = false, startX = 0, moved = false\r\n\r\n      wrapper.addEventListener(\'mousedown\', function (e) {\r\n        dragging = true; startX = e.clientX; moved = false\r\n      })\r\n      window.addEventListener(\'mousemove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.clientX - startX) > 10) moved = true\r\n      })\r\n      window.addEventListener(\'mouseup\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = e.clientX - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      wrapper.addEventListener(\'touchstart\', function (e) {\r\n        dragging = true; startX = e.touches[0].clientX; moved = false\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchmove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.touches[0].clientX - startX) > 10) moved = true\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchend\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = (e.changedTouches[0] ? e.changedTouches[0].clientX : startX) - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      function adjustSpacing() {\r\n        var w = window.innerWidth\r\n        if (w <= 480) VISIBLE = Math.min(3, total)\r\n        else if (w <= 768) VISIBLE = Math.min(3, total)\r\n        else VISIBLE = Math.min(5, total)\r\n        layout(false)\r\n      }\r\n      window.addEventListener(\'resize\', adjustSpacing)\r\n      adjustSpacing()\r\n    })()\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Asian Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====ASIAN RESTAURANT=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .as-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .as-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .as-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-title-section .as-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .as-title-divider::before,\r\n    .as-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-title-divider .as-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .as-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .as-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .as-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n      border-radius: 0;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .as-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .as-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-line::before,\r\n    .as-gallery-heading .as-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-gallery-heading .as-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      border-radius: 0;\r\n      cursor: pointer;\r\n      background: #e8f0f8;\r\n      position: relative;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .as-gallery-grid .as-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /* Placeholder squares (no image yet) */\r\n    .as-gallery-grid .as-photo.placeholder::before {\r\n      content: \"\";\r\n      position: absolute;\r\n      inset: 0;\r\n      background: linear-gradient(135deg, #e8f0f8 0%, #d0e2f3 50%, #e8f0f8 100%);\r\n    }\r\n\r\n    .as-gallery-grid .as-photo.placeholder::after {\r\n      content: \"\\1F3E8\";\r\n      position: absolute;\r\n      top: 50%;\r\n      left: 50%;\r\n      transform: translate(-50%, -50%);\r\n      font-size: 40px;\r\n      opacity: 0.25;\r\n    }\r\n\r\n    /*--Sec5: Menu Carousel--*/\r\n    .as-menu-section {\r\n      background: #0e4d97;\r\n      padding: 50px 0 0;\r\n      position: relative;\r\n      overflow: hidden;\r\n    }\r\n\r\n    .as-menu-heading {\r\n      text-align: center;\r\n      padding: 0 30px 40px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-line::before,\r\n    .as-menu-heading .as-mh-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, rgba(255,255,255,0.5), #00adef, transparent);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #fff);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 52px;\r\n      font-weight: 200;\r\n      letter-spacing: 10px;\r\n      color: #fff;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 12px;\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::before,\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 50px;\r\n      background: linear-gradient(to right, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom::after {\r\n      background: linear-gradient(to left, transparent, #00adef);\r\n    }\r\n\r\n    .as-menu-heading .as-mh-bottom span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 11px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      color: rgba(0, 173, 239, 0.7);\r\n      text-transform: uppercase;\r\n    }\r\n\r\n    .as-carousel-wrapper {\r\n      position: relative;\r\n      height: 620px;\r\n      perspective: 1400px;\r\n      cursor: grab;\r\n      user-select: none;\r\n      overflow: visible;\r\n    }\r\n\r\n    .as-carousel-wrapper:active {\r\n      cursor: grabbing;\r\n    }\r\n\r\n    .as-carousel {\r\n      position: absolute;\r\n      width: 100%;\r\n      height: 100%;\r\n    }\r\n\r\n    .as-carousel-item {\r\n      position: absolute;\r\n      left: 50%;\r\n      top: 50%;\r\n      width: 380px;\r\n      height: 540px;\r\n      margin-left: -190px;\r\n      margin-top: -270px;\r\n      border-radius: 0;\r\n      overflow: hidden;\r\n      box-shadow: 0 15px 50px rgba(0, 0, 0, 0.5);\r\n      cursor: pointer;\r\n      transition: transform 0.5s ease, opacity 0.5s ease;\r\n      opacity: 0;\r\n      z-index: 1;\r\n    }\r\n\r\n    .as-carousel-item.as-active {\r\n      z-index: 200 !important;\r\n    }\r\n\r\n    .as-carousel-item img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n    }\r\n\r\n    .as-carousel-nav {\r\n      display: flex;\r\n      justify-content: center;\r\n      gap: 30px;\r\n      padding: 20px 0 40px;\r\n    }\r\n\r\n    .as-carousel-nav button {\r\n      background: rgba(0, 0, 0, 0.4);\r\n      border: 1.5px solid #00adef;\r\n      color: #00adef;\r\n      font-size: 24px;\r\n      width: 50px;\r\n      height: 50px;\r\n      border-radius: 50%;\r\n      cursor: pointer;\r\n      transition: all 0.3s ease;\r\n      box-shadow: 0 0 12px rgba(0, 173, 239, 0.15), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    .as-carousel-nav button:hover {\r\n      background: #083a72;\r\n      border-color: #fff;\r\n      color: #fff;\r\n      box-shadow: 0 0 18px rgba(0, 173, 239, 0.3), inset 0 0 8px rgba(0, 0, 0, 0.3);\r\n    }\r\n\r\n    /*--Reservation Bar--*/\r\n    .as-reservation-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #083a72;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 3.33vw;\r\n      font-weight: 100;\r\n      height: 6.6vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease, color .35s ease;\r\n      margin-top: 30px;\r\n      position: relative;\r\n      z-index: 3;\r\n    }\r\n\r\n    .as-reservation-bar:hover {\r\n      background: #00adef;\r\n      color: #fff;\r\n    }\r\n\r\n    /*--LIGHTBOX--*/\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 350px;\r\n        margin-left: -120px;\r\n        margin-top: -175px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .as-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 36px;\r\n        letter-spacing: 6px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 420px;\r\n        perspective: 800px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 240px;\r\n        height: 340px;\r\n        margin-left: -120px;\r\n        margin-top: -170px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 5.5vw;\r\n        height: auto;\r\n        padding: 15px 0;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .as-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .as-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-title-section .as-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .as-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .as-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .as-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .as-gallery-heading .as-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-main {\r\n        font-size: 28px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-menu-heading .as-mh-sub {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .as-carousel-wrapper {\r\n        height: 380px;\r\n        perspective: 600px;\r\n      }\r\n\r\n      .as-carousel-item {\r\n        width: 200px;\r\n        height: 290px;\r\n        margin-left: -100px;\r\n        margin-top: -145px;\r\n      }\r\n\r\n      .as-carousel-nav button {\r\n        width: 40px;\r\n        height: 40px;\r\n        font-size: 18px;\r\n      }\r\n\r\n      .as-reservation-bar {\r\n        font-size: 6vw;\r\n        padding: 12px 0;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"as-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"as-title-section\">\r\n    <div class=\"as-label\">Ruby 68 Hotel</div>\r\n    <h1>Asian Restaurant</h1>\r\n    <div class=\"as-title-divider\">\r\n      <div class=\"as-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"as-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 8 khách sạn Ruby 68 với tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu, nhà hàng Asian mang đến hành trình ẩm thực tinh tế, nơi vị giác và cảm xúc được nâng tầm trong không gian sang trọng và đầy cảm hứng.\r\n    </p>\r\n    <p>\r\n      Thực đơn à la carte đa dạng từ Á đến Âu, được chế biến bởi đội ngũ đầu bếp chuẩn 3 sao, kết hợp hài hòa giữa nguyên liệu cao cấp và nghệ thuật trình bày tinh xảo. Mỗi món ăn không chỉ là hương vị, mà còn là một trải nghiệm ẩm thực trọn vẹn.\r\n    </p>\r\n    <p>\r\n      Dù là bữa tối lãng mạn, buổi gặp gỡ đối tác hay khoảnh khắc thư giãn bên gia đình, Asian Restaurant luôn là lựa chọn hoàn hảo để tận hưởng ẩm thực đẳng cấp giữa khung cảnh biển trời tuyệt đẹp.\r\n    </p>\r\n    <div class=\"as-time\">Mở cửa hàng ngày từ 6:30 đến 11:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"as-gallery-section\">\r\n    <div class=\"as-gallery-heading\">\r\n      <div class=\"as-heading-line\">\r\n        <div class=\"as-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-heading-sub\">Asian</div>\r\n      <div class=\"as-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"as-gallery-grid\">\r\n      <div class=\"as-photo\" onclick=\"asOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/view-nha-hang-tang-8.jpg\" alt=\"Asian Restaurant\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n      <div class=\"as-photo placeholder\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec5: Menu Carousel -->\r\n  <section class=\"as-menu-section\">\r\n    <div class=\"as-menu-heading\">\r\n      <div class=\"as-mh-line\">\r\n        <div class=\"as-mh-diamond\"></div>\r\n      </div>\r\n      <div class=\"as-mh-sub\">Asian</div>\r\n      <div class=\"as-mh-main\">Our Menu</div>\r\n      <div class=\"as-mh-bottom\"><span>Signature Dishes</span></div>\r\n    </div>\r\n    <div class=\"as-carousel-wrapper\" id=\"asCarouselWrapper\">\r\n      <div class=\"as-carousel\" id=\"asCarousel\">\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/1.jpg\" alt=\"Menu 1\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/2.jpg\" alt=\"Menu 2\"></div>\r\n        <div class=\"as-carousel-item\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/asian/menu/3.jpg\" alt=\"Menu 3\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"as-carousel-nav\">\r\n      <button id=\"asCarPrev\">&#10094;</button>\r\n      <button id=\"asCarNext\">&#10095;</button>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var asLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function asGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function asCreateOverlay() {\r\n      if (asLB.dialog) return\r\n      var pDoc = asGetParentDoc()\r\n      asLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { asCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      asLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      asLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) asCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); asCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        asLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (asLB.zoom.scale < 1) { asLB.zoom.scale = 1; asLB.zoom.x = 0; asLB.zoom.y = 0 }\r\n        if (asLB.zoom.scale > 5) asLB.zoom.scale = 5\r\n        asApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); asResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); asLB.zoom.dragging = true\r\n        asLB.zoom.startX = e.clientX; asLB.zoom.startY = e.clientY\r\n        asLB.zoom.lastX = asLB.zoom.x; asLB.zoom.lastY = asLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!asLB.zoom.dragging) return\r\n        asLB.zoom.x = asLB.zoom.lastX + (e.clientX - asLB.zoom.startX) / asLB.zoom.scale\r\n        asLB.zoom.y = asLB.zoom.lastY + (e.clientY - asLB.zoom.startY) / asLB.zoom.scale\r\n        asApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { asLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; asLB.touches.dist=Math.sqrt(dx*dx+dy*dy); asLB.touches.scale0=asLB.zoom.scale }\r\n        else if (e.touches.length === 1) { asLB.zoom.dragging=true; asLB.zoom.startX=e.touches[0].clientX; asLB.zoom.startY=e.touches[0].clientY; asLB.zoom.lastX=asLB.zoom.x; asLB.zoom.lastY=asLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; asLB.zoom.scale=asLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/asLB.touches.dist); if(asLB.zoom.scale<1)asLB.zoom.scale=1;if(asLB.zoom.scale>5)asLB.zoom.scale=5; asApplyZoom() }\r\n        else if (e.touches.length===1&&asLB.zoom.dragging) { e.preventDefault(); asLB.zoom.x=asLB.zoom.lastX+(e.touches[0].clientX-asLB.zoom.startX)/asLB.zoom.scale; asLB.zoom.y=asLB.zoom.lastY+(e.touches[0].clientY-asLB.zoom.startY)/asLB.zoom.scale; asApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { asLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') asCloseLightbox() })\r\n    }\r\n    function asResetZoom() { asLB.zoom.scale=1;asLB.zoom.x=0;asLB.zoom.y=0; if(asLB.img)asLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function asApplyZoom() { if(asLB.img)asLB.img.style.transform=\'scale(\'+asLB.zoom.scale+\') translate(\'+asLB.zoom.x+\'px,\'+asLB.zoom.y+\'px)\' }\r\n    function asOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      asCreateOverlay()\r\n      asLB.img.src = img.src; asResetZoom()\r\n      asLB.dialog.showModal()\r\n      asLB.dialog.style.display = \'flex\'\r\n    }\r\n    function asCloseLightbox() {\r\n      if (asLB.dialog && asLB.dialog.open) { asLB.dialog.close(); asLB.dialog.style.display = \'\'; asResetZoom() }\r\n    }\r\n\r\n    /* ========= COVERFLOW CAROUSEL ========= */\r\n    ;(function () {\r\n      var wrapper = document.getElementById(\'asCarouselWrapper\')\r\n      var items = document.querySelectorAll(\'.as-carousel-item\')\r\n      var total = items.length\r\n      var current = 0\r\n      var VISIBLE = total >= 5 ? 5 : total\r\n\r\n      function layout(animated) {\r\n        var w = window.innerWidth\r\n        var half = Math.floor(VISIBLE / 2)\r\n\r\n        for (var i = 0; i < total; i++) {\r\n          var offset = i - current\r\n          if (offset > total / 2) offset -= total\r\n          if (offset < -total / 2) offset += total\r\n          var abs = Math.abs(offset)\r\n          var item = items[i]\r\n\r\n          /* Only toggle class — z-index handled purely by CSS */\r\n          item.style.zIndex = \'\'\r\n          item.classList.toggle(\'as-active\', offset === 0)\r\n\r\n          if (abs > half) {\r\n            item.style.opacity = \'0\'\r\n            item.style.transform = \'translateX(\' + (offset > 0 ? 800 : -800) + \'px) rotateY(0deg) scale(0.5)\'\r\n            item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n            continue\r\n          }\r\n\r\n          var spacing = w <= 480 ? 160 : (w <= 768 ? 190 : (w <= 1024 ? 220 : 280))\r\n          var tx = offset * spacing\r\n          var rotY = offset === 0 ? 0 : (offset < 0 ? 40 : -40)\r\n          var sc = offset === 0 ? 1 : 0.72 - abs * 0.06\r\n\r\n          item.style.opacity = \'1\'\r\n          item.style.transform = \'translateX(\' + tx + \'px) rotateY(\' + rotY + \'deg) scale(\' + sc + \')\'\r\n          item.style.transition = animated ? \'transform 0.5s ease, opacity 0.5s ease\' : \'none\'\r\n        }\r\n      }\r\n\r\n      function goTo(idx) {\r\n        current = ((idx % total) + total) % total\r\n        layout(true)\r\n      }\r\n\r\n      layout(false)\r\n\r\n      document.getElementById(\'asCarNext\').addEventListener(\'click\', function () {\r\n        goTo(current + 1)\r\n      })\r\n      document.getElementById(\'asCarPrev\').addEventListener(\'click\', function () {\r\n        goTo(current - 1)\r\n      })\r\n\r\n      for (var i = 0; i < total; i++) {\r\n        ;(function (idx) {\r\n          items[idx].addEventListener(\'click\', function () {\r\n            if (idx === current) {\r\n              asCreateOverlay()\r\n              asLB.img.src = items[idx].querySelector(\'img\').src\r\n              asResetZoom(); asLB.dialog.showModal(); asLB.dialog.style.display = \'flex\'\r\n            } else {\r\n              var diff = idx - current\r\n              if (diff > total / 2) diff -= total\r\n              if (diff < -total / 2) diff += total\r\n              goTo(current + diff)\r\n            }\r\n          })\r\n        })(i)\r\n      }\r\n\r\n      /* Drag / Swipe */\r\n      var dragging = false, startX = 0, moved = false\r\n\r\n      wrapper.addEventListener(\'mousedown\', function (e) {\r\n        dragging = true; startX = e.clientX; moved = false\r\n      })\r\n      window.addEventListener(\'mousemove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.clientX - startX) > 10) moved = true\r\n      })\r\n      window.addEventListener(\'mouseup\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = e.clientX - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      wrapper.addEventListener(\'touchstart\', function (e) {\r\n        dragging = true; startX = e.touches[0].clientX; moved = false\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchmove\', function (e) {\r\n        if (!dragging) return\r\n        if (Math.abs(e.touches[0].clientX - startX) > 10) moved = true\r\n      }, { passive: true })\r\n      wrapper.addEventListener(\'touchend\', function (e) {\r\n        if (!dragging) return\r\n        dragging = false\r\n        if (!moved) return\r\n        var delta = (e.changedTouches[0] ? e.changedTouches[0].clientX : startX) - startX\r\n        if (Math.abs(delta) > 50) {\r\n          goTo(current + (delta < 0 ? 1 : -1))\r\n        }\r\n      })\r\n\r\n      function adjustSpacing() {\r\n        var w = window.innerWidth\r\n        if (w <= 480) VISIBLE = Math.min(3, total)\r\n        else if (w <= 768) VISIBLE = Math.min(3, total)\r\n        else VISIBLE = Math.min(5, total)\r\n        layout(false)\r\n      }\r\n      window.addEventListener(\'resize\', adjustSpacing)\r\n      adjustSpacing()\r\n    })()\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 16:14:08', '2026-03-25 16:14:08');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(83, 'Botble\\Page\\Models\\Page', 17, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Sunflower Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====SUNFLOWER RESTAURANT=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/buffet-breakfast-11.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sf-title-section .sf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sf-title-divider::before,\r\n    .sf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sf-title-divider .sf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sf-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sf-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sf-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n      border-radius: 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sf-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sf-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-line::before,\r\n    .sf-gallery-heading .sf-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sf-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sf-gallery-grid .sf-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      border-radius: 8px;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sf-gallery-grid .sf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sf-gallery-grid .sf-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sf-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sf-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sf-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sf-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sf-gallery-grid .sf-photo:nth-child(1) {\r\n        grid-row: auto;\r\n      }\r\n\r\n      .sf-gallery-heading .sf-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sf-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sf-title-section .sf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sf-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sf-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sf-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sf-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sf-gallery-heading .sf-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sf-title-section\">\r\n    <div class=\"sf-label\">Ruby 68 Hotel</div>\r\n    <h1>Sunflower Restaurant</h1>\r\n    <div class=\"sf-title-divider\">\r\n      <div class=\"sf-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sf-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 5 của Ruby 68 Hotel, Sunflower Restaurant sở hữu tầm nhìn toàn cảnh biển Bãi Sau, mang đến không gian lý tưởng để khởi đầu ngày mới trong ánh nắng và làn gió biển dịu nhẹ.\r\n    </p>\r\n    <p>\r\n      Nhà hàng phục vụ buffet sáng thịnh soạn với thực đơn phong phú từ Âu đến Á, được chế biến theo tiêu chuẩn ẩm thực 3 sao. Bên cạnh đó, Sunflower còn là địa điểm lý tưởng cho các tiệc buffet, sự kiện và chương trình ẩm thực đặc biệt trong các dịp lễ, Tết.\r\n    </p>\r\n    <div class=\"sf-time\">Mở cửa hàng ngày từ 6:30 đến 10:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sf-gallery-section\">\r\n    <div class=\"sf-gallery-heading\">\r\n      <div class=\"sf-heading-line\">\r\n        <div class=\"sf-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sf-heading-sub\">Sunflower</div>\r\n      <div class=\"sf-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sf-gallery-grid\">\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/1.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/2.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/3.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/4.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/5.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/6.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/buffet-breakfast-11.jpg\" alt=\"Sunflower Restaurant\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var sfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function sfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function sfCreateOverlay() {\r\n      if (sfLB.dialog) return\r\n      var pDoc = sfGetParentDoc()\r\n      sfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { sfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:6px;cursor:grab;\'\r\n      sfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      sfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) sfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); sfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        sfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (sfLB.zoom.scale < 1) { sfLB.zoom.scale = 1; sfLB.zoom.x = 0; sfLB.zoom.y = 0 }\r\n        if (sfLB.zoom.scale > 5) sfLB.zoom.scale = 5\r\n        sfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); sfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); sfLB.zoom.dragging = true\r\n        sfLB.zoom.startX = e.clientX; sfLB.zoom.startY = e.clientY\r\n        sfLB.zoom.lastX = sfLB.zoom.x; sfLB.zoom.lastY = sfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!sfLB.zoom.dragging) return\r\n        sfLB.zoom.x = sfLB.zoom.lastX + (e.clientX - sfLB.zoom.startX) / sfLB.zoom.scale\r\n        sfLB.zoom.y = sfLB.zoom.lastY + (e.clientY - sfLB.zoom.startY) / sfLB.zoom.scale\r\n        sfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { sfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; sfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); sfLB.touches.scale0=sfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { sfLB.zoom.dragging=true; sfLB.zoom.startX=e.touches[0].clientX; sfLB.zoom.startY=e.touches[0].clientY; sfLB.zoom.lastX=sfLB.zoom.x; sfLB.zoom.lastY=sfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; sfLB.zoom.scale=sfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/sfLB.touches.dist); if(sfLB.zoom.scale<1)sfLB.zoom.scale=1;if(sfLB.zoom.scale>5)sfLB.zoom.scale=5; sfApplyZoom() }\r\n        else if (e.touches.length===1&&sfLB.zoom.dragging) { e.preventDefault(); sfLB.zoom.x=sfLB.zoom.lastX+(e.touches[0].clientX-sfLB.zoom.startX)/sfLB.zoom.scale; sfLB.zoom.y=sfLB.zoom.lastY+(e.touches[0].clientY-sfLB.zoom.startY)/sfLB.zoom.scale; sfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { sfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') sfCloseLightbox() })\r\n    }\r\n    function sfResetZoom() { sfLB.zoom.scale=1;sfLB.zoom.x=0;sfLB.zoom.y=0; if(sfLB.img)sfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function sfApplyZoom() { if(sfLB.img)sfLB.img.style.transform=\'scale(\'+sfLB.zoom.scale+\') translate(\'+sfLB.zoom.x+\'px,\'+sfLB.zoom.y+\'px)\' }\r\n    function sfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      sfCreateOverlay()\r\n      sfLB.img.src = img.src; sfResetZoom()\r\n      sfLB.dialog.showModal()\r\n      sfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function sfCloseLightbox() {\r\n      if (sfLB.dialog && sfLB.dialog.open) { sfLB.dialog.close(); sfLB.dialog.style.display = \'\'; sfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Sunflower Restaurant</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====SUNFLOWER RESTAURANT=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/buffet-breakfast-11.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sf-title-section .sf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sf-title-divider::before,\r\n    .sf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sf-title-divider .sf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sf-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sf-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sf-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n      border-radius: 0;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sf-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sf-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-line::before,\r\n    .sf-gallery-heading .sf-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sf-gallery-heading .sf-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sf-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sf-gallery-grid .sf-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      border-radius: 0;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sf-gallery-grid .sf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sf-gallery-grid .sf-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sf-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sf-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sf-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sf-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sf-gallery-grid .sf-photo:nth-child(1) {\r\n        grid-row: auto;\r\n      }\r\n\r\n      .sf-gallery-heading .sf-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sf-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sf-title-section .sf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sf-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sf-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sf-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sf-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sf-gallery-heading .sf-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sf-title-section\">\r\n    <div class=\"sf-label\">Ruby 68 Hotel</div>\r\n    <h1>Sunflower Restaurant</h1>\r\n    <div class=\"sf-title-divider\">\r\n      <div class=\"sf-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sf-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 5 của Ruby 68 Hotel, Sunflower Restaurant sở hữu tầm nhìn toàn cảnh biển Bãi Sau, mang đến không gian lý tưởng để khởi đầu ngày mới trong ánh nắng và làn gió biển dịu nhẹ.\r\n    </p>\r\n    <p>\r\n      Nhà hàng phục vụ buffet sáng thịnh soạn với thực đơn phong phú từ Âu đến Á, được chế biến theo tiêu chuẩn ẩm thực 3 sao. Bên cạnh đó, Sunflower còn là địa điểm lý tưởng cho các tiệc buffet, sự kiện và chương trình ẩm thực đặc biệt trong các dịp lễ, Tết.\r\n    </p>\r\n    <div class=\"sf-time\">Mở cửa hàng ngày từ 6:30 đến 10:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sf-gallery-section\">\r\n    <div class=\"sf-gallery-heading\">\r\n      <div class=\"sf-heading-line\">\r\n        <div class=\"sf-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sf-heading-sub\">Sunflower</div>\r\n      <div class=\"sf-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sf-gallery-grid\">\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/1.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/2.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/3.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/4.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/5.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/6.png\" alt=\"Sunflower Restaurant\"></div>\r\n      <div class=\"sf-photo\" onclick=\"sfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/sunflower-restaurant/buffet-breakfast-11.jpg\" alt=\"Sunflower Restaurant\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var sfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function sfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function sfCreateOverlay() {\r\n      if (sfLB.dialog) return\r\n      var pDoc = sfGetParentDoc()\r\n      sfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { sfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      sfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      sfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) sfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); sfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        sfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (sfLB.zoom.scale < 1) { sfLB.zoom.scale = 1; sfLB.zoom.x = 0; sfLB.zoom.y = 0 }\r\n        if (sfLB.zoom.scale > 5) sfLB.zoom.scale = 5\r\n        sfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); sfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); sfLB.zoom.dragging = true\r\n        sfLB.zoom.startX = e.clientX; sfLB.zoom.startY = e.clientY\r\n        sfLB.zoom.lastX = sfLB.zoom.x; sfLB.zoom.lastY = sfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!sfLB.zoom.dragging) return\r\n        sfLB.zoom.x = sfLB.zoom.lastX + (e.clientX - sfLB.zoom.startX) / sfLB.zoom.scale\r\n        sfLB.zoom.y = sfLB.zoom.lastY + (e.clientY - sfLB.zoom.startY) / sfLB.zoom.scale\r\n        sfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { sfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; sfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); sfLB.touches.scale0=sfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { sfLB.zoom.dragging=true; sfLB.zoom.startX=e.touches[0].clientX; sfLB.zoom.startY=e.touches[0].clientY; sfLB.zoom.lastX=sfLB.zoom.x; sfLB.zoom.lastY=sfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; sfLB.zoom.scale=sfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/sfLB.touches.dist); if(sfLB.zoom.scale<1)sfLB.zoom.scale=1;if(sfLB.zoom.scale>5)sfLB.zoom.scale=5; sfApplyZoom() }\r\n        else if (e.touches.length===1&&sfLB.zoom.dragging) { e.preventDefault(); sfLB.zoom.x=sfLB.zoom.lastX+(e.touches[0].clientX-sfLB.zoom.startX)/sfLB.zoom.scale; sfLB.zoom.y=sfLB.zoom.lastY+(e.touches[0].clientY-sfLB.zoom.startY)/sfLB.zoom.scale; sfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { sfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') sfCloseLightbox() })\r\n    }\r\n    function sfResetZoom() { sfLB.zoom.scale=1;sfLB.zoom.x=0;sfLB.zoom.y=0; if(sfLB.img)sfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function sfApplyZoom() { if(sfLB.img)sfLB.img.style.transform=\'scale(\'+sfLB.zoom.scale+\') translate(\'+sfLB.zoom.x+\'px,\'+sfLB.zoom.y+\'px)\' }\r\n    function sfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      sfCreateOverlay()\r\n      sfLB.img.src = img.src; sfResetZoom()\r\n      sfLB.dialog.showModal()\r\n      sfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function sfCloseLightbox() {\r\n      if (sfLB.dialog && sfLB.dialog.open) { sfLB.dialog.close(); sfLB.dialog.style.display = \'\'; sfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 16:14:21', '2026-03-25 16:14:21'),
(84, 'Botble\\Page\\Models\\Page', 18, 1, 'custom_html', NULL, '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Conference & Meeting</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====CONFERENCE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .cf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .cf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .cf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .cf-title-section .cf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .cf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .cf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .cf-title-divider::before,\r\n    .cf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .cf-title-divider .cf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Room Section--*/\r\n    .cf-room {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 50px 30px 30px;\r\n    }\r\n\r\n    .cf-room + .cf-room {\r\n      padding-top: 20px;\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-room-header {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .cf-room-header h2 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 40px;\r\n      font-weight: 200;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .cf-room-header .cf-room-sub {\r\n      font-size: 14px;\r\n      color: #00adef;\r\n      margin-top: 6px;\r\n      letter-spacing: 2px;\r\n    }\r\n\r\n    /*--Room Layout--*/\r\n    .cf-room-body {\r\n      display: flex;\r\n      gap: 40px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .cf-room-gallery {\r\n      flex: 1;\r\n      min-width: 0;\r\n    }\r\n\r\n    .cf-room-info {\r\n      width: 360px;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .cf-room-info p {\r\n      font-size: 16px;\r\n      line-height: 1.8;\r\n      color: #333;\r\n    }\r\n\r\n    .cf-room-info p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .cf-room-specs {\r\n      margin-top: 24px;\r\n      border-top: 1px solid #d9dee5;\r\n      border-bottom: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding: 12px 0;\r\n    }\r\n\r\n    .cf-spec + .cf-spec {\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec-label {\r\n      font-size: 14px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n    }\r\n\r\n    .cf-spec-value {\r\n      font-size: 14px;\r\n      color: #333;\r\n      text-align: right;\r\n    }\r\n\r\n    /*--Photo Grid--*/\r\n    .cf-photo-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n      aspect-ratio: 4/3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    /* First photo spans 2 columns */\r\n    .cf-photo-grid .cf-photo:first-child {\r\n      grid-column: 1 / 3;\r\n      grid-row: 1 / 3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:first-child img {\r\n      aspect-ratio: auto;\r\n      height: 100%;\r\n    }\r\n\r\n    /*--Tulip single image--*/\r\n    .cf-photo-single {\r\n      max-width: 700px;\r\n      margin: 0 auto;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo img {\r\n      width: 100%;\r\n      display: block;\r\n      border-radius: 0;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo:hover img {\r\n      transform: scale(1.02);\r\n    }\r\n\r\n    /*--CTA Bar--*/\r\n    .cf-cta-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #0e4d97;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 2.6vw;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      height: 5.5vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .cf-cta-bar:hover {\r\n      background: #083a72;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .cf-room-body {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .cf-room-info {\r\n        width: 100%;\r\n        text-align: center;\r\n      }\r\n\r\n      .cf-title-section h1 {\r\n        font-size: 44px;\r\n        letter-spacing: 5px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 32px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .cf-title-section h1 {\r\n        font-size: 34px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 26px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 30px 20px 20px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-photo-grid .cf-photo:first-child {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 4.5vw;\r\n        height: auto;\r\n        padding: 14px 0;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .cf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-section .cf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 22px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 20px 15px 15px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .cf-spec-label,\r\n      .cf-spec-value {\r\n        font-size: 13px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 5.5vw;\r\n        padding: 12px 0;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-divider::before,\r\n      .cf-title-divider::after {\r\n        width: 50px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"cf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"cf-title-section\">\r\n    <div class=\"cf-label\">Ruby 68 Hotel</div>\r\n    <h1>Conference & Meeting</h1>\r\n    <div class=\"cf-title-divider\"><div class=\"cf-diamond\"></div></div>\r\n  </div>\r\n\r\n  <!-- Sec3: Ruby Ballroom -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Ruby Ballroom</h2>\r\n      <div class=\"cf-room-sub\">FLOOR 3 &bull; EVENT &amp; BANQUET HALL</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-grid\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/14.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/15.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/16.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/17.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/18.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/19.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/20.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/21.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/22.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/23.png\" alt=\"Ruby Ballroom\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Tọa lạc tại tầng 3, Ruby Ballroom là lựa chọn lý tưởng cho tiệc cưới, hội nghị và sự kiện tại Vũng Tàu với sức chứa 120 &ndash; 150 khách.\r\n        </p>\r\n        <p>\r\n          Không gian được thiết kế hiện đại, tinh tế, kết hợp hệ thống âm thanh &ndash; ánh sáng chuẩn 3 sao và tầm nhìn hướng biển ấn tượng. Thực đơn Á &ndash; Âu đa dạng, dịch vụ chuyên nghiệp, chỉn chu từng chi tiết cùng không gian linh hoạt cho nhiều concept sự kiện.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Vị tr&iacute;</span>\r\n            <span class=\"cf-spec-value\">Tầng 3</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">120 &ndash; 150 kh&aacute;ch</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">&Acirc;m thanh &ndash; &aacute;nh s&aacute;ng chuẩn 3 sao</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Ph&ugrave; hợp</span>\r\n            <span class=\"cf-spec-value\">Tiệc cưới, hội nghị, sự kiện</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec4: Tulip Meeting Room -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Tulip Meeting Room</h2>\r\n      <div class=\"cf-room-sub\">VIP MEETING ROOM</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-single\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/tulip/phong-hop-hoi-nghi-tulip.jpg\" alt=\"Tulip Meeting Room\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Không gian phòng họp VIP riêng tư tại Ruby 68 Hotel, sảnh Tulip phù hợp cho các buổi họp cấp cao với sức chứa 15 &ndash; 20 khách.\r\n        </p>\r\n        <p>\r\n          Sảnh trang bị màn hình LED hiện đại, hệ thống âm thanh chất lượng cao cùng khả năng hỗ trợ họp online &amp; offline linh hoạt, đảm bảo mọi cuộc họp diễn ra hiệu quả, chuyên nghiệp và liền mạch.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">15 &ndash; 20 kh&aacute;ch</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">M&agrave;n h&igrave;nh LED, &acirc;m thanh cao cấp</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Hỗ trợ</span>\r\n            <span class=\"cf-spec-value\">Họp online &amp; offline</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Ph&ugrave; hợp</span>\r\n            <span class=\"cf-spec-value\">Họp cấp cao, VIP</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var cfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function cfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function cfCreateOverlay() {\r\n      if (cfLB.dialog) return\r\n      var pDoc = cfGetParentDoc()\r\n      cfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { cfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      cfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      cfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) cfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); cfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        cfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (cfLB.zoom.scale < 1) { cfLB.zoom.scale = 1; cfLB.zoom.x = 0; cfLB.zoom.y = 0 }\r\n        if (cfLB.zoom.scale > 5) cfLB.zoom.scale = 5\r\n        cfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); cfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); cfLB.zoom.dragging = true\r\n        cfLB.zoom.startX = e.clientX; cfLB.zoom.startY = e.clientY\r\n        cfLB.zoom.lastX = cfLB.zoom.x; cfLB.zoom.lastY = cfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!cfLB.zoom.dragging) return\r\n        cfLB.zoom.x = cfLB.zoom.lastX + (e.clientX - cfLB.zoom.startX) / cfLB.zoom.scale\r\n        cfLB.zoom.y = cfLB.zoom.lastY + (e.clientY - cfLB.zoom.startY) / cfLB.zoom.scale\r\n        cfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { cfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); cfLB.touches.scale0=cfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { cfLB.zoom.dragging=true; cfLB.zoom.startX=e.touches[0].clientX; cfLB.zoom.startY=e.touches[0].clientY; cfLB.zoom.lastX=cfLB.zoom.x; cfLB.zoom.lastY=cfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.zoom.scale=cfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/cfLB.touches.dist); if(cfLB.zoom.scale<1)cfLB.zoom.scale=1;if(cfLB.zoom.scale>5)cfLB.zoom.scale=5; cfApplyZoom() }\r\n        else if (e.touches.length===1&&cfLB.zoom.dragging) { e.preventDefault(); cfLB.zoom.x=cfLB.zoom.lastX+(e.touches[0].clientX-cfLB.zoom.startX)/cfLB.zoom.scale; cfLB.zoom.y=cfLB.zoom.lastY+(e.touches[0].clientY-cfLB.zoom.startY)/cfLB.zoom.scale; cfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { cfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') cfCloseLightbox() })\r\n    }\r\n    function cfResetZoom() { cfLB.zoom.scale=1;cfLB.zoom.x=0;cfLB.zoom.y=0; if(cfLB.img)cfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function cfApplyZoom() { if(cfLB.img)cfLB.img.style.transform=\'scale(\'+cfLB.zoom.scale+\') translate(\'+cfLB.zoom.x+\'px,\'+cfLB.zoom.y+\'px)\' }\r\n    function cfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      cfCreateOverlay()\r\n      cfLB.img.src = img.src; cfResetZoom()\r\n      cfLB.dialog.showModal()\r\n      cfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function cfCloseLightbox() {\r\n      if (cfLB.dialog && cfLB.dialog.open) { cfLB.dialog.close(); cfLB.dialog.style.display = \'\'; cfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 16:21:58', '2026-03-25 16:21:58'),
(85, 'Botble\\Page\\Models\\Page', 22, 1, 'description', '', 'Với tầm nhìn bao quát toàn đại dương, câu lạc bộ sức khỏe của chúng tôi mang đến cho quý khách một trải nghiệm luyện tập hoàn hảo. Khám phá các thiết bị luyện tập hiện đại bao gồm đầy đủ các tiện nghi, quý khách có thể tự luyện tập hoặc tham khảo các bài tập từ các huấn luyện viên của chúng tôi.', '2026-03-25 16:26:49', '2026-03-25 16:26:49');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(86, 'Botble\\Page\\Models\\Page', 18, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Conference & Meeting</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====CONFERENCE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .cf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .cf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .cf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .cf-title-section .cf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .cf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .cf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .cf-title-divider::before,\r\n    .cf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .cf-title-divider .cf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Room Section--*/\r\n    .cf-room {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 50px 30px 30px;\r\n    }\r\n\r\n    .cf-room + .cf-room {\r\n      padding-top: 20px;\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-room-header {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .cf-room-header h2 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 40px;\r\n      font-weight: 200;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .cf-room-header .cf-room-sub {\r\n      font-size: 14px;\r\n      color: #00adef;\r\n      margin-top: 6px;\r\n      letter-spacing: 2px;\r\n    }\r\n\r\n    /*--Room Layout--*/\r\n    .cf-room-body {\r\n      display: flex;\r\n      gap: 40px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .cf-room-gallery {\r\n      flex: 1;\r\n      min-width: 0;\r\n    }\r\n\r\n    .cf-room-info {\r\n      width: 360px;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .cf-room-info p {\r\n      font-size: 16px;\r\n      line-height: 1.8;\r\n      color: #333;\r\n    }\r\n\r\n    .cf-room-info p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .cf-room-specs {\r\n      margin-top: 24px;\r\n      border-top: 1px solid #d9dee5;\r\n      border-bottom: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding: 12px 0;\r\n    }\r\n\r\n    .cf-spec + .cf-spec {\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec-label {\r\n      font-size: 14px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n    }\r\n\r\n    .cf-spec-value {\r\n      font-size: 14px;\r\n      color: #333;\r\n      text-align: right;\r\n    }\r\n\r\n    /*--Photo Grid--*/\r\n    .cf-photo-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n      aspect-ratio: 4/3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    /* First photo spans 2 columns */\r\n    .cf-photo-grid .cf-photo:first-child {\r\n      grid-column: 1 / 3;\r\n      grid-row: 1 / 3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:first-child img {\r\n      aspect-ratio: auto;\r\n      height: 100%;\r\n    }\r\n\r\n    /*--Tulip single image--*/\r\n    .cf-photo-single {\r\n      max-width: 700px;\r\n      margin: 0 auto;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo img {\r\n      width: 100%;\r\n      display: block;\r\n      border-radius: 0;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo:hover img {\r\n      transform: scale(1.02);\r\n    }\r\n\r\n    /*--CTA Bar--*/\r\n    .cf-cta-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #0e4d97;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 2.6vw;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      height: 5.5vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .cf-cta-bar:hover {\r\n      background: #083a72;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .cf-room-body {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .cf-room-info {\r\n        width: 100%;\r\n        text-align: center;\r\n      }\r\n\r\n      .cf-title-section h1 {\r\n        font-size: 44px;\r\n        letter-spacing: 5px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 32px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .cf-title-section h1 {\r\n        font-size: 34px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 26px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 30px 20px 20px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-photo-grid .cf-photo:first-child {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 4.5vw;\r\n        height: auto;\r\n        padding: 14px 0;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .cf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-section .cf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 22px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 20px 15px 15px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .cf-spec-label,\r\n      .cf-spec-value {\r\n        font-size: 13px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 5.5vw;\r\n        padding: 12px 0;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-divider::before,\r\n      .cf-title-divider::after {\r\n        width: 50px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"cf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"cf-title-section\">\r\n    <div class=\"cf-label\">Ruby 68 Hotel</div>\r\n    <h1>Conference & Meeting</h1>\r\n    <div class=\"cf-title-divider\"><div class=\"cf-diamond\"></div></div>\r\n  </div>\r\n\r\n  <!-- Sec3: Ruby Ballroom -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Ruby Ballroom</h2>\r\n      <div class=\"cf-room-sub\">FLOOR 3 &bull; EVENT &amp; BANQUET HALL</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-grid\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/14.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/15.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/16.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/17.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/18.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/19.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/20.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/21.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/22.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/23.png\" alt=\"Ruby Ballroom\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Tọa lạc tại tầng 3, Ruby Ballroom là lựa chọn lý tưởng cho tiệc cưới, hội nghị và sự kiện tại Vũng Tàu với sức chứa 120 &ndash; 150 khách.\r\n        </p>\r\n        <p>\r\n          Không gian được thiết kế hiện đại, tinh tế, kết hợp hệ thống âm thanh &ndash; ánh sáng chuẩn 3 sao và tầm nhìn hướng biển ấn tượng. Thực đơn Á &ndash; Âu đa dạng, dịch vụ chuyên nghiệp, chỉn chu từng chi tiết cùng không gian linh hoạt cho nhiều concept sự kiện.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Vị tr&iacute;</span>\r\n            <span class=\"cf-spec-value\">Tầng 3</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">120 &ndash; 150 kh&aacute;ch</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">&Acirc;m thanh &ndash; &aacute;nh s&aacute;ng chuẩn 3 sao</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Ph&ugrave; hợp</span>\r\n            <span class=\"cf-spec-value\">Tiệc cưới, hội nghị, sự kiện</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec4: Tulip Meeting Room -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Tulip Meeting Room</h2>\r\n      <div class=\"cf-room-sub\">VIP MEETING ROOM</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-single\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/tulip/phong-hop-hoi-nghi-tulip.jpg\" alt=\"Tulip Meeting Room\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Không gian phòng họp VIP riêng tư tại Ruby 68 Hotel, sảnh Tulip phù hợp cho các buổi họp cấp cao với sức chứa 15 &ndash; 20 khách.\r\n        </p>\r\n        <p>\r\n          Sảnh trang bị màn hình LED hiện đại, hệ thống âm thanh chất lượng cao cùng khả năng hỗ trợ họp online &amp; offline linh hoạt, đảm bảo mọi cuộc họp diễn ra hiệu quả, chuyên nghiệp và liền mạch.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">15 &ndash; 20 kh&aacute;ch</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">M&agrave;n h&igrave;nh LED, &acirc;m thanh cao cấp</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Hỗ trợ</span>\r\n            <span class=\"cf-spec-value\">Họp online &amp; offline</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Ph&ugrave; hợp</span>\r\n            <span class=\"cf-spec-value\">Họp cấp cao, VIP</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var cfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function cfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function cfCreateOverlay() {\r\n      if (cfLB.dialog) return\r\n      var pDoc = cfGetParentDoc()\r\n      cfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { cfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      cfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      cfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) cfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); cfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        cfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (cfLB.zoom.scale < 1) { cfLB.zoom.scale = 1; cfLB.zoom.x = 0; cfLB.zoom.y = 0 }\r\n        if (cfLB.zoom.scale > 5) cfLB.zoom.scale = 5\r\n        cfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); cfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); cfLB.zoom.dragging = true\r\n        cfLB.zoom.startX = e.clientX; cfLB.zoom.startY = e.clientY\r\n        cfLB.zoom.lastX = cfLB.zoom.x; cfLB.zoom.lastY = cfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!cfLB.zoom.dragging) return\r\n        cfLB.zoom.x = cfLB.zoom.lastX + (e.clientX - cfLB.zoom.startX) / cfLB.zoom.scale\r\n        cfLB.zoom.y = cfLB.zoom.lastY + (e.clientY - cfLB.zoom.startY) / cfLB.zoom.scale\r\n        cfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { cfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); cfLB.touches.scale0=cfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { cfLB.zoom.dragging=true; cfLB.zoom.startX=e.touches[0].clientX; cfLB.zoom.startY=e.touches[0].clientY; cfLB.zoom.lastX=cfLB.zoom.x; cfLB.zoom.lastY=cfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.zoom.scale=cfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/cfLB.touches.dist); if(cfLB.zoom.scale<1)cfLB.zoom.scale=1;if(cfLB.zoom.scale>5)cfLB.zoom.scale=5; cfApplyZoom() }\r\n        else if (e.touches.length===1&&cfLB.zoom.dragging) { e.preventDefault(); cfLB.zoom.x=cfLB.zoom.lastX+(e.touches[0].clientX-cfLB.zoom.startX)/cfLB.zoom.scale; cfLB.zoom.y=cfLB.zoom.lastY+(e.touches[0].clientY-cfLB.zoom.startY)/cfLB.zoom.scale; cfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { cfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') cfCloseLightbox() })\r\n    }\r\n    function cfResetZoom() { cfLB.zoom.scale=1;cfLB.zoom.x=0;cfLB.zoom.y=0; if(cfLB.img)cfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function cfApplyZoom() { if(cfLB.img)cfLB.img.style.transform=\'scale(\'+cfLB.zoom.scale+\') translate(\'+cfLB.zoom.x+\'px,\'+cfLB.zoom.y+\'px)\' }\r\n    function cfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      cfCreateOverlay()\r\n      cfLB.img.src = img.src; cfResetZoom()\r\n      cfLB.dialog.showModal()\r\n      cfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function cfCloseLightbox() {\r\n      if (cfLB.dialog && cfLB.dialog.open) { cfLB.dialog.close(); cfLB.dialog.style.display = \'\'; cfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Conference & Meeting</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====CONFERENCE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .cf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .cf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .cf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .cf-title-section .cf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .cf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .cf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .cf-title-divider::before,\r\n    .cf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .cf-title-divider .cf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Room Section--*/\r\n    .cf-room {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 50px 30px 30px;\r\n    }\r\n\r\n    .cf-room + .cf-room {\r\n      padding-top: 20px;\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-room-header {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .cf-room-header h2 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 40px;\r\n      font-weight: 200;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .cf-room-header .cf-room-sub {\r\n      font-size: 14px;\r\n      color: #00adef;\r\n      margin-top: 6px;\r\n      letter-spacing: 2px;\r\n    }\r\n\r\n    /*--Room Layout--*/\r\n    .cf-room-body {\r\n      display: flex;\r\n      gap: 40px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .cf-room-gallery {\r\n      flex: 1;\r\n      min-width: 0;\r\n    }\r\n\r\n    .cf-room-info {\r\n      width: 360px;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .cf-room-info p {\r\n      font-size: 16px;\r\n      line-height: 1.8;\r\n      color: #333;\r\n    }\r\n\r\n    .cf-room-info p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .cf-room-specs {\r\n      margin-top: 24px;\r\n      border-top: 1px solid #d9dee5;\r\n      border-bottom: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding: 12px 0;\r\n    }\r\n\r\n    .cf-spec + .cf-spec {\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec-label {\r\n      font-size: 14px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n    }\r\n\r\n    .cf-spec-value {\r\n      font-size: 14px;\r\n      color: #333;\r\n      text-align: right;\r\n    }\r\n\r\n    /*--Photo Grid--*/\r\n    .cf-photo-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n      aspect-ratio: 4/3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    /* First photo spans 2 columns */\r\n    .cf-photo-grid .cf-photo:first-child {\r\n      grid-column: 1 / 3;\r\n      grid-row: 1 / 3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:first-child img {\r\n      aspect-ratio: auto;\r\n      height: 100%;\r\n    }\r\n\r\n    /*--Tulip single image--*/\r\n    .cf-photo-single {\r\n      max-width: 700px;\r\n      margin: 0 auto;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo img {\r\n      width: 100%;\r\n      display: block;\r\n      border-radius: 0;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo:hover img {\r\n      transform: scale(1.02);\r\n    }\r\n\r\n    /*--CTA Bar--*/\r\n    .cf-cta-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #0e4d97;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 2.6vw;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      height: 5.5vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .cf-cta-bar:hover {\r\n      background: #083a72;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .cf-room-body {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .cf-room-info {\r\n        width: 100%;\r\n        text-align: center;\r\n      }\r\n\r\n      .cf-title-section h1 {\r\n        font-size: 44px;\r\n        letter-spacing: 5px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 32px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .cf-title-section h1 {\r\n        font-size: 34px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 26px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 30px 20px 20px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-photo-grid .cf-photo:first-child {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 4.5vw;\r\n        height: auto;\r\n        padding: 14px 0;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .cf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-section .cf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 22px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 20px 15px 15px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .cf-spec-label,\r\n      .cf-spec-value {\r\n        font-size: 13px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 5.5vw;\r\n        padding: 12px 0;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-divider::before,\r\n      .cf-title-divider::after {\r\n        width: 50px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"cf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"cf-title-section\">\r\n    <div class=\"cf-label\">Ruby 68 Hotel</div>\r\n    <h1>Conference & Meeting</h1>\r\n    <div class=\"cf-title-divider\"><div class=\"cf-diamond\"></div></div>\r\n  </div>\r\n\r\n  <!-- Sec3: Ruby Ballroom -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Ruby Ballroom</h2>\r\n      <div class=\"cf-room-sub\">FLOOR 3 • EVENT & BANQUET HALL</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-grid\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/14.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/15.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/16.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/17.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/18.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/19.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/20.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/21.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/22.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/23.png\" alt=\"Ruby Ballroom\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Tọa lạc tại tầng 3, Ruby Ballroom là lựa chọn lý tưởng cho tiệc cưới, hội nghị và sự kiện tại Vũng Tàu với sức chứa 120 – 150 khách.\r\n        </p>\r\n        <p>\r\n          Không gian được thiết kế hiện đại, tinh tế, kết hợp hệ thống âm thanh – ánh sáng chuẩn 3 sao và tầm nhìn hướng biển ấn tượng. Thực đơn Á – Âu đa dạng, dịch vụ chuyên nghiệp, chỉn chu từng chi tiết cùng không gian linh hoạt cho nhiều concept sự kiện.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Vị trí</span>\r\n            <span class=\"cf-spec-value\">Tầng 3</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">120 – 150 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Âm thanh – ánh sáng chuẩn 3 sao</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Tiệc cưới, hội nghị, sự kiện</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec4: Tulip Meeting Room -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Tulip Meeting Room</h2>\r\n      <div class=\"cf-room-sub\">VIP MEETING ROOM</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-single\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/tulip/phong-hop-hoi-nghi-tulip.jpg\" alt=\"Tulip Meeting Room\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Không gian phòng họp VIP riêng tư tại Ruby 68 Hotel, sảnh Tulip phù hợp cho các buổi họp cấp cao với sức chứa 15 – 20 khách.\r\n        </p>\r\n        <p>\r\n          Sảnh trang bị màn hình LED hiện đại, hệ thống âm thanh chất lượng cao cùng khả năng hỗ trợ họp online & offline linh hoạt, đảm bảo mọi cuộc họp diễn ra hiệu quả, chuyên nghiệp và liền mạch.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">15 – 20 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Màn hình LED, âm thanh cao cấp</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Hỗ trợ</span>\r\n            <span class=\"cf-spec-value\">Họp online & offline</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Họp cấp cao, VIP</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var cfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function cfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function cfCreateOverlay() {\r\n      if (cfLB.dialog) return\r\n      var pDoc = cfGetParentDoc()\r\n      cfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { cfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      cfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      cfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) cfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); cfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        cfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (cfLB.zoom.scale < 1) { cfLB.zoom.scale = 1; cfLB.zoom.x = 0; cfLB.zoom.y = 0 }\r\n        if (cfLB.zoom.scale > 5) cfLB.zoom.scale = 5\r\n        cfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); cfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); cfLB.zoom.dragging = true\r\n        cfLB.zoom.startX = e.clientX; cfLB.zoom.startY = e.clientY\r\n        cfLB.zoom.lastX = cfLB.zoom.x; cfLB.zoom.lastY = cfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!cfLB.zoom.dragging) return\r\n        cfLB.zoom.x = cfLB.zoom.lastX + (e.clientX - cfLB.zoom.startX) / cfLB.zoom.scale\r\n        cfLB.zoom.y = cfLB.zoom.lastY + (e.clientY - cfLB.zoom.startY) / cfLB.zoom.scale\r\n        cfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { cfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); cfLB.touches.scale0=cfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { cfLB.zoom.dragging=true; cfLB.zoom.startX=e.touches[0].clientX; cfLB.zoom.startY=e.touches[0].clientY; cfLB.zoom.lastX=cfLB.zoom.x; cfLB.zoom.lastY=cfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.zoom.scale=cfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/cfLB.touches.dist); if(cfLB.zoom.scale<1)cfLB.zoom.scale=1;if(cfLB.zoom.scale>5)cfLB.zoom.scale=5; cfApplyZoom() }\r\n        else if (e.touches.length===1&&cfLB.zoom.dragging) { e.preventDefault(); cfLB.zoom.x=cfLB.zoom.lastX+(e.touches[0].clientX-cfLB.zoom.startX)/cfLB.zoom.scale; cfLB.zoom.y=cfLB.zoom.lastY+(e.touches[0].clientY-cfLB.zoom.startY)/cfLB.zoom.scale; cfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { cfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') cfCloseLightbox() })\r\n    }\r\n    function cfResetZoom() { cfLB.zoom.scale=1;cfLB.zoom.x=0;cfLB.zoom.y=0; if(cfLB.img)cfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function cfApplyZoom() { if(cfLB.img)cfLB.img.style.transform=\'scale(\'+cfLB.zoom.scale+\') translate(\'+cfLB.zoom.x+\'px,\'+cfLB.zoom.y+\'px)\' }\r\n    function cfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      cfCreateOverlay()\r\n      cfLB.img.src = img.src; cfResetZoom()\r\n      cfLB.dialog.showModal()\r\n      cfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function cfCloseLightbox() {\r\n      if (cfLB.dialog && cfLB.dialog.open) { cfLB.dialog.close(); cfLB.dialog.style.display = \'\'; cfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 16:29:15', '2026-03-25 16:29:15'),
(87, 'Botble\\Page\\Models\\Page', 21, 1, 'description', '', 'Khu vực được trang bị sauna khô, sauna ướt và jacuzzi nóng – lạnh, mang đến trải nghiệm thư giãn toàn diện, hỗ trợ tuần hoàn và phục hồi cơ thể hiệu quả. Không gian yên tĩnh, riêng tư kết hợp cùng tiện nghi chuẩn 3 sao giúp mỗi khoảnh khắc thư giãn trở nên trọn vẹn và tinh tế.\nMở cửa hàng ngày từ 10:00 đến 23:00', '2026-03-25 16:33:36', '2026-03-25 16:33:36');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(88, 'Botble\\Page\\Models\\Page', 18, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Conference & Meeting</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====CONFERENCE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .cf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .cf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .cf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .cf-title-section .cf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .cf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .cf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .cf-title-divider::before,\r\n    .cf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .cf-title-divider .cf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Room Section--*/\r\n    .cf-room {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 50px 30px 30px;\r\n    }\r\n\r\n    .cf-room + .cf-room {\r\n      padding-top: 20px;\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-room-header {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .cf-room-header h2 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 40px;\r\n      font-weight: 200;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .cf-room-header .cf-room-sub {\r\n      font-size: 14px;\r\n      color: #00adef;\r\n      margin-top: 6px;\r\n      letter-spacing: 2px;\r\n    }\r\n\r\n    /*--Room Layout--*/\r\n    .cf-room-body {\r\n      display: flex;\r\n      gap: 40px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .cf-room-gallery {\r\n      flex: 1;\r\n      min-width: 0;\r\n    }\r\n\r\n    .cf-room-info {\r\n      width: 360px;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .cf-room-info p {\r\n      font-size: 16px;\r\n      line-height: 1.8;\r\n      color: #333;\r\n    }\r\n\r\n    .cf-room-info p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .cf-room-specs {\r\n      margin-top: 24px;\r\n      border-top: 1px solid #d9dee5;\r\n      border-bottom: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding: 12px 0;\r\n    }\r\n\r\n    .cf-spec + .cf-spec {\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec-label {\r\n      font-size: 14px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n    }\r\n\r\n    .cf-spec-value {\r\n      font-size: 14px;\r\n      color: #333;\r\n      text-align: right;\r\n    }\r\n\r\n    /*--Photo Grid--*/\r\n    .cf-photo-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n      aspect-ratio: 4/3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    /* First photo spans 2 columns */\r\n    .cf-photo-grid .cf-photo:first-child {\r\n      grid-column: 1 / 3;\r\n      grid-row: 1 / 3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:first-child img {\r\n      aspect-ratio: auto;\r\n      height: 100%;\r\n    }\r\n\r\n    /*--Tulip single image--*/\r\n    .cf-photo-single {\r\n      max-width: 700px;\r\n      margin: 0 auto;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo img {\r\n      width: 100%;\r\n      display: block;\r\n      border-radius: 0;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo:hover img {\r\n      transform: scale(1.02);\r\n    }\r\n\r\n    /*--CTA Bar--*/\r\n    .cf-cta-bar {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      width: 100%;\r\n      background: #0e4d97;\r\n      color: white;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 2.6vw;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      height: 5.5vw;\r\n      text-decoration: none;\r\n      transition: background .35s ease;\r\n      margin-top: 40px;\r\n    }\r\n\r\n    .cf-cta-bar:hover {\r\n      background: #083a72;\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .cf-room-body {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .cf-room-info {\r\n        width: 100%;\r\n        text-align: center;\r\n      }\r\n\r\n      .cf-title-section h1 {\r\n        font-size: 44px;\r\n        letter-spacing: 5px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 32px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .cf-title-section h1 {\r\n        font-size: 34px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 26px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 30px 20px 20px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-photo-grid .cf-photo:first-child {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 4.5vw;\r\n        height: auto;\r\n        padding: 14px 0;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .cf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-section .cf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 22px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 20px 15px 15px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .cf-spec-label,\r\n      .cf-spec-value {\r\n        font-size: 13px;\r\n      }\r\n\r\n      .cf-cta-bar {\r\n        font-size: 5.5vw;\r\n        padding: 12px 0;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-divider::before,\r\n      .cf-title-divider::after {\r\n        width: 50px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"cf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"cf-title-section\">\r\n    <div class=\"cf-label\">Ruby 68 Hotel</div>\r\n    <h1>Conference & Meeting</h1>\r\n    <div class=\"cf-title-divider\"><div class=\"cf-diamond\"></div></div>\r\n  </div>\r\n\r\n  <!-- Sec3: Ruby Ballroom -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Ruby Ballroom</h2>\r\n      <div class=\"cf-room-sub\">FLOOR 3 • EVENT & BANQUET HALL</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-grid\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/14.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/15.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/16.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/17.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/18.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/19.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/20.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/21.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/22.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/23.png\" alt=\"Ruby Ballroom\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Tọa lạc tại tầng 3, Ruby Ballroom là lựa chọn lý tưởng cho tiệc cưới, hội nghị và sự kiện tại Vũng Tàu với sức chứa 120 – 150 khách.\r\n        </p>\r\n        <p>\r\n          Không gian được thiết kế hiện đại, tinh tế, kết hợp hệ thống âm thanh – ánh sáng chuẩn 3 sao và tầm nhìn hướng biển ấn tượng. Thực đơn Á – Âu đa dạng, dịch vụ chuyên nghiệp, chỉn chu từng chi tiết cùng không gian linh hoạt cho nhiều concept sự kiện.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Vị trí</span>\r\n            <span class=\"cf-spec-value\">Tầng 3</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">120 – 150 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Âm thanh – ánh sáng chuẩn 3 sao</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Tiệc cưới, hội nghị, sự kiện</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec4: Tulip Meeting Room -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Tulip Meeting Room</h2>\r\n      <div class=\"cf-room-sub\">VIP MEETING ROOM</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-single\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/tulip/phong-hop-hoi-nghi-tulip.jpg\" alt=\"Tulip Meeting Room\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Không gian phòng họp VIP riêng tư tại Ruby 68 Hotel, sảnh Tulip phù hợp cho các buổi họp cấp cao với sức chứa 15 – 20 khách.\r\n        </p>\r\n        <p>\r\n          Sảnh trang bị màn hình LED hiện đại, hệ thống âm thanh chất lượng cao cùng khả năng hỗ trợ họp online & offline linh hoạt, đảm bảo mọi cuộc họp diễn ra hiệu quả, chuyên nghiệp và liền mạch.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">15 – 20 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Màn hình LED, âm thanh cao cấp</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Hỗ trợ</span>\r\n            <span class=\"cf-spec-value\">Họp online & offline</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Họp cấp cao, VIP</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var cfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function cfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function cfCreateOverlay() {\r\n      if (cfLB.dialog) return\r\n      var pDoc = cfGetParentDoc()\r\n      cfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { cfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      cfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      cfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) cfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); cfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        cfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (cfLB.zoom.scale < 1) { cfLB.zoom.scale = 1; cfLB.zoom.x = 0; cfLB.zoom.y = 0 }\r\n        if (cfLB.zoom.scale > 5) cfLB.zoom.scale = 5\r\n        cfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); cfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); cfLB.zoom.dragging = true\r\n        cfLB.zoom.startX = e.clientX; cfLB.zoom.startY = e.clientY\r\n        cfLB.zoom.lastX = cfLB.zoom.x; cfLB.zoom.lastY = cfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!cfLB.zoom.dragging) return\r\n        cfLB.zoom.x = cfLB.zoom.lastX + (e.clientX - cfLB.zoom.startX) / cfLB.zoom.scale\r\n        cfLB.zoom.y = cfLB.zoom.lastY + (e.clientY - cfLB.zoom.startY) / cfLB.zoom.scale\r\n        cfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { cfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); cfLB.touches.scale0=cfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { cfLB.zoom.dragging=true; cfLB.zoom.startX=e.touches[0].clientX; cfLB.zoom.startY=e.touches[0].clientY; cfLB.zoom.lastX=cfLB.zoom.x; cfLB.zoom.lastY=cfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.zoom.scale=cfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/cfLB.touches.dist); if(cfLB.zoom.scale<1)cfLB.zoom.scale=1;if(cfLB.zoom.scale>5)cfLB.zoom.scale=5; cfApplyZoom() }\r\n        else if (e.touches.length===1&&cfLB.zoom.dragging) { e.preventDefault(); cfLB.zoom.x=cfLB.zoom.lastX+(e.touches[0].clientX-cfLB.zoom.startX)/cfLB.zoom.scale; cfLB.zoom.y=cfLB.zoom.lastY+(e.touches[0].clientY-cfLB.zoom.startY)/cfLB.zoom.scale; cfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { cfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') cfCloseLightbox() })\r\n    }\r\n    function cfResetZoom() { cfLB.zoom.scale=1;cfLB.zoom.x=0;cfLB.zoom.y=0; if(cfLB.img)cfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function cfApplyZoom() { if(cfLB.img)cfLB.img.style.transform=\'scale(\'+cfLB.zoom.scale+\') translate(\'+cfLB.zoom.x+\'px,\'+cfLB.zoom.y+\'px)\' }\r\n    function cfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      cfCreateOverlay()\r\n      cfLB.img.src = img.src; cfResetZoom()\r\n      cfLB.dialog.showModal()\r\n      cfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function cfCloseLightbox() {\r\n      if (cfLB.dialog && cfLB.dialog.open) { cfLB.dialog.close(); cfLB.dialog.style.display = \'\'; cfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Conference & Meeting</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====CONFERENCE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .cf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .cf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .cf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .cf-title-section .cf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .cf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .cf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .cf-title-divider::before,\r\n    .cf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .cf-title-divider .cf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Room Section--*/\r\n    .cf-room {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 50px 30px 30px;\r\n    }\r\n\r\n    .cf-room + .cf-room {\r\n      padding-top: 20px;\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-room-header {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .cf-room-header h2 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 40px;\r\n      font-weight: 200;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .cf-room-header .cf-room-sub {\r\n      font-size: 14px;\r\n      color: #00adef;\r\n      margin-top: 6px;\r\n      letter-spacing: 2px;\r\n    }\r\n\r\n    /*--Room Layout--*/\r\n    .cf-room-body {\r\n      display: flex;\r\n      gap: 40px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .cf-room-gallery {\r\n      flex: 1;\r\n      min-width: 0;\r\n    }\r\n\r\n    .cf-room-info {\r\n      width: 360px;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .cf-room-info p {\r\n      font-size: 16px;\r\n      line-height: 1.8;\r\n      color: #333;\r\n    }\r\n\r\n    .cf-room-info p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .cf-room-specs {\r\n      margin-top: 24px;\r\n      border-top: 1px solid #d9dee5;\r\n      border-bottom: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding: 12px 0;\r\n    }\r\n\r\n    .cf-spec + .cf-spec {\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec-label {\r\n      font-size: 14px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n    }\r\n\r\n    .cf-spec-value {\r\n      font-size: 14px;\r\n      color: #333;\r\n      text-align: right;\r\n    }\r\n\r\n    /*--Photo Grid--*/\r\n    .cf-photo-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n      aspect-ratio: 4/3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    /* First photo spans 2 columns */\r\n    .cf-photo-grid .cf-photo:first-child {\r\n      grid-column: 1 / 3;\r\n      grid-row: 1 / 3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:first-child img {\r\n      aspect-ratio: auto;\r\n      height: 100%;\r\n    }\r\n\r\n    /*--Tulip single image--*/\r\n    .cf-photo-single {\r\n      max-width: 700px;\r\n      margin: 0 auto;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo img {\r\n      width: 100%;\r\n      display: block;\r\n      border-radius: 0;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo:hover img {\r\n      transform: scale(1.02);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .cf-room-body {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .cf-room-info {\r\n        width: 100%;\r\n        text-align: center;\r\n      }\r\n\r\n      .cf-title-section h1 {\r\n        font-size: 44px;\r\n        letter-spacing: 5px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 32px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .cf-title-section h1 {\r\n        font-size: 34px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 26px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 30px 20px 20px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-photo-grid .cf-photo:first-child {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 15px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .cf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-section .cf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 22px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 20px 15px 15px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .cf-spec-label,\r\n      .cf-spec-value {\r\n        font-size: 13px;\r\n      }\r\n      \r\n      .cf-title-divider::before,\r\n      .cf-title-divider::after {\r\n        width: 50px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"cf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"cf-title-section\">\r\n    <div class=\"cf-label\">Ruby 68 Hotel</div>\r\n    <h1>Conference & Meeting</h1>\r\n    <div class=\"cf-title-divider\"><div class=\"cf-diamond\"></div></div>\r\n  </div>\r\n\r\n  <!-- Sec3: Ruby Ballroom -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Ruby Ballroom</h2>\r\n      <div class=\"cf-room-sub\">FLOOR 3 &bull; EVENT &amp; BANQUET HALL</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-grid\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/14.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/15.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/16.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/17.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/18.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/19.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/20.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/21.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/22.png\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/lotus/23.png\" alt=\"Ruby Ballroom\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Tọa lạc tại tầng 3, Ruby Ballroom là lựa chọn lý tưởng cho tiệc cưới, hội nghị và sự kiện tại Vũng Tàu với sức chứa 120 &ndash; 150 khách.\r\n        </p>\r\n        <p>\r\n          Không gian được thiết kế hiện đại, tinh tế, kết hợp hệ thống âm thanh &ndash; ánh sáng chuẩn 3 sao và tầm nhìn hướng biển ấn tượng. Thực đơn Á &ndash; Âu đa dạng, dịch vụ chuyên nghiệp, chỉn chu từng chi tiết cùng không gian linh hoạt cho nhiều concept sự kiện.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Vị tr&iacute;</span>\r\n            <span class=\"cf-spec-value\">Tầng 3</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">120 &ndash; 150 kh&aacute;ch</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">&Acirc;m thanh &ndash; &aacute;nh s&aacute;ng chuẩn 3 sao</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Ph&ugrave; hợp</span>\r\n            <span class=\"cf-spec-value\">Tiệc cưới, hội nghị, sự kiện</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec4: Tulip Meeting Room -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Tulip Meeting Room</h2>\r\n      <div class=\"cf-room-sub\">VIP MEETING ROOM</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-single\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/hoi-nghi/tulip/phong-hop-hoi-nghi-tulip.jpg\" alt=\"Tulip Meeting Room\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Không gian phòng họp VIP riêng tư tại Ruby 68 Hotel, sảnh Tulip phù hợp cho các buổi họp cấp cao với sức chứa 15 &ndash; 20 khách.\r\n        </p>\r\n        <p>\r\n          Sảnh trang bị màn hình LED hiện đại, hệ thống âm thanh chất lượng cao cùng khả năng hỗ trợ họp online &amp; offline linh hoạt, đảm bảo mọi cuộc họp diễn ra hiệu quả, chuyên nghiệp và liền mạch.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">15 &ndash; 20 kh&aacute;ch</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">M&agrave;n h&igrave;nh LED, &acirc;m thanh cao cấp</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Hỗ trợ</span>\r\n            <span class=\"cf-spec-value\">Họp online &amp; offline</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Ph&ugrave; hợp</span>\r\n            <span class=\"cf-spec-value\">Họp cấp cao, VIP</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var cfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function cfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function cfCreateOverlay() {\r\n      if (cfLB.dialog) return\r\n      var pDoc = cfGetParentDoc()\r\n      cfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { cfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      cfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      cfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) cfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); cfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        cfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (cfLB.zoom.scale < 1) { cfLB.zoom.scale = 1; cfLB.zoom.x = 0; cfLB.zoom.y = 0 }\r\n        if (cfLB.zoom.scale > 5) cfLB.zoom.scale = 5\r\n        cfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); cfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); cfLB.zoom.dragging = true\r\n        cfLB.zoom.startX = e.clientX; cfLB.zoom.startY = e.clientY\r\n        cfLB.zoom.lastX = cfLB.zoom.x; cfLB.zoom.lastY = cfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!cfLB.zoom.dragging) return\r\n        cfLB.zoom.x = cfLB.zoom.lastX + (e.clientX - cfLB.zoom.startX) / cfLB.zoom.scale\r\n        cfLB.zoom.y = cfLB.zoom.lastY + (e.clientY - cfLB.zoom.startY) / cfLB.zoom.scale\r\n        cfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { cfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); cfLB.touches.scale0=cfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { cfLB.zoom.dragging=true; cfLB.zoom.startX=e.touches[0].clientX; cfLB.zoom.startY=e.touches[0].clientY; cfLB.zoom.lastX=cfLB.zoom.x; cfLB.zoom.lastY=cfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.zoom.scale=cfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/cfLB.touches.dist); if(cfLB.zoom.scale<1)cfLB.zoom.scale=1;if(cfLB.zoom.scale>5)cfLB.zoom.scale=5; cfApplyZoom() }\r\n        else if (e.touches.length===1&&cfLB.zoom.dragging) { e.preventDefault(); cfLB.zoom.x=cfLB.zoom.lastX+(e.touches[0].clientX-cfLB.zoom.startX)/cfLB.zoom.scale; cfLB.zoom.y=cfLB.zoom.lastY+(e.touches[0].clientY-cfLB.zoom.startY)/cfLB.zoom.scale; cfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { cfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') cfCloseLightbox() })\r\n    }\r\n    function cfResetZoom() { cfLB.zoom.scale=1;cfLB.zoom.x=0;cfLB.zoom.y=0; if(cfLB.img)cfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function cfApplyZoom() { if(cfLB.img)cfLB.img.style.transform=\'scale(\'+cfLB.zoom.scale+\') translate(\'+cfLB.zoom.x+\'px,\'+cfLB.zoom.y+\'px)\' }\r\n    function cfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      cfCreateOverlay()\r\n      cfLB.img.src = img.src; cfResetZoom()\r\n      cfLB.dialog.showModal()\r\n      cfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function cfCloseLightbox() {\r\n      if (cfLB.dialog && cfLB.dialog.open) { cfLB.dialog.close(); cfLB.dialog.style.display = \'\'; cfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-25 16:35:27', '2026-03-25 16:35:27');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(89, 'Botble\\Page\\Models\\Page', 19, 1, 'custom_html', NULL, '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Infinity Pool &amp; Ruby Ocean Bar</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====INFINITY POOL & RUBY OCEAN BAR=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .pl-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/4.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .pl-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-title-section .pl-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .pl-title-divider::before,\r\n    .pl-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-title-divider .pl-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .pl-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .pl-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .pl-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .pl-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line::before,\r\n    .pl-gallery-heading .pl-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .pl-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .pl-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .pl-title-section .pl-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .pl-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"pl-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"pl-title-section\">\r\n    <div class=\"pl-label\">Ruby 68 Hotel</div>\r\n    <h1>Infinity Pool &amp; Ruby Ocean Bar</h1>\r\n    <div class=\"pl-title-divider\">\r\n      <div class=\"pl-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"pl-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7 kh&aacute;ch sạn Ruby 68, hồ bơi v&ocirc; cực g&acirc;y ấn tượng với thiết kế k&iacute;nh trong suốt độc đ&aacute;o, mở ra tầm nh&igrave;n to&agrave;n cảnh biển Bãi Sau Vũng Tàu đầy ngoạn mục. Thả m&igrave;nh trong l&agrave;n nước xanh m&aacute;t, tận hưởng &aacute;nh nắng ấm &aacute;p v&agrave; nh&acirc;m nhi cocktail tại Ruby Ocean Bar, đ&acirc;y l&agrave; trải nghiệm thư gi&atilde;n kh&ocirc;ng thể bỏ lỡ khi lưu tr&uacute; tại kh&aacute;ch sạn.\r\n    </p>\r\n    <p>\r\n      Được xem l&agrave; một trong những hồ bơi v&ocirc; cực đẹp nhất Vũng Tàu, nơi đ&acirc;y mang đến khoảnh khắc nghỉ dưỡng đẳng cấp giữa biển trời bao la.\r\n    </p>\r\n    <div class=\"pl-time\">Mở cửa h&agrave;ng ng&agrave;y từ 9:00 đến 19:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"pl-gallery-section\">\r\n    <div class=\"pl-gallery-heading\">\r\n      <div class=\"pl-heading-line\">\r\n        <div class=\"pl-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"pl-heading-sub\">Infinity Pool</div>\r\n      <div class=\"pl-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"pl-gallery-grid\">\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/4.png\" alt=\"Infinity Pool\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/1.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/2.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/3.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/4.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/5.png\" alt=\"Ruby Ocean Bar\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var plLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function plGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function plCreateOverlay() {\r\n      if (plLB.dialog) return\r\n      var pDoc = plGetParentDoc()\r\n      plLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { plCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      plLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      plLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) plCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); plCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        plLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (plLB.zoom.scale < 1) { plLB.zoom.scale = 1; plLB.zoom.x = 0; plLB.zoom.y = 0 }\r\n        if (plLB.zoom.scale > 5) plLB.zoom.scale = 5\r\n        plApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); plResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); plLB.zoom.dragging = true\r\n        plLB.zoom.startX = e.clientX; plLB.zoom.startY = e.clientY\r\n        plLB.zoom.lastX = plLB.zoom.x; plLB.zoom.lastY = plLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!plLB.zoom.dragging) return\r\n        plLB.zoom.x = plLB.zoom.lastX + (e.clientX - plLB.zoom.startX) / plLB.zoom.scale\r\n        plLB.zoom.y = plLB.zoom.lastY + (e.clientY - plLB.zoom.startY) / plLB.zoom.scale\r\n        plApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { plLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.touches.dist=Math.sqrt(dx*dx+dy*dy); plLB.touches.scale0=plLB.zoom.scale }\r\n        else if (e.touches.length === 1) { plLB.zoom.dragging=true; plLB.zoom.startX=e.touches[0].clientX; plLB.zoom.startY=e.touches[0].clientY; plLB.zoom.lastX=plLB.zoom.x; plLB.zoom.lastY=plLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.zoom.scale=plLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/plLB.touches.dist); if(plLB.zoom.scale<1)plLB.zoom.scale=1;if(plLB.zoom.scale>5)plLB.zoom.scale=5; plApplyZoom() }\r\n        else if (e.touches.length===1&&plLB.zoom.dragging) { e.preventDefault(); plLB.zoom.x=plLB.zoom.lastX+(e.touches[0].clientX-plLB.zoom.startX)/plLB.zoom.scale; plLB.zoom.y=plLB.zoom.lastY+(e.touches[0].clientY-plLB.zoom.startY)/plLB.zoom.scale; plApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { plLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') plCloseLightbox() })\r\n    }\r\n    function plResetZoom() { plLB.zoom.scale=1;plLB.zoom.x=0;plLB.zoom.y=0; if(plLB.img)plLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function plApplyZoom() { if(plLB.img)plLB.img.style.transform=\'scale(\'+plLB.zoom.scale+\') translate(\'+plLB.zoom.x+\'px,\'+plLB.zoom.y+\'px)\' }\r\n    function plOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      plCreateOverlay()\r\n      plLB.img.src = img.src; plResetZoom()\r\n      plLB.dialog.showModal()\r\n      plLB.dialog.style.display = \'flex\'\r\n    }\r\n    function plCloseLightbox() {\r\n      if (plLB.dialog && plLB.dialog.open) { plLB.dialog.close(); plLB.dialog.style.display = \'\'; plResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 01:44:17', '2026-03-26 01:44:17'),
(91, 'Botble\\Page\\Models\\Page', 20, 1, 'template', 'default', 'full-width', '2026-03-26 01:44:51', '2026-03-26 01:44:51'),
(92, 'Botble\\Page\\Models\\Page', 19, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Infinity Pool &amp; Ruby Ocean Bar</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====INFINITY POOL & RUBY OCEAN BAR=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .pl-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/4.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .pl-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-title-section .pl-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .pl-title-divider::before,\r\n    .pl-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-title-divider .pl-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .pl-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .pl-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .pl-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .pl-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line::before,\r\n    .pl-gallery-heading .pl-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .pl-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .pl-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .pl-title-section .pl-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .pl-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"pl-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"pl-title-section\">\r\n    <div class=\"pl-label\">Ruby 68 Hotel</div>\r\n    <h1>Infinity Pool &amp; Ruby Ocean Bar</h1>\r\n    <div class=\"pl-title-divider\">\r\n      <div class=\"pl-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"pl-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7 kh&aacute;ch sạn Ruby 68, hồ bơi v&ocirc; cực g&acirc;y ấn tượng với thiết kế k&iacute;nh trong suốt độc đ&aacute;o, mở ra tầm nh&igrave;n to&agrave;n cảnh biển Bãi Sau Vũng Tàu đầy ngoạn mục. Thả m&igrave;nh trong l&agrave;n nước xanh m&aacute;t, tận hưởng &aacute;nh nắng ấm &aacute;p v&agrave; nh&acirc;m nhi cocktail tại Ruby Ocean Bar, đ&acirc;y l&agrave; trải nghiệm thư gi&atilde;n kh&ocirc;ng thể bỏ lỡ khi lưu tr&uacute; tại kh&aacute;ch sạn.\r\n    </p>\r\n    <p>\r\n      Được xem l&agrave; một trong những hồ bơi v&ocirc; cực đẹp nhất Vũng Tàu, nơi đ&acirc;y mang đến khoảnh khắc nghỉ dưỡng đẳng cấp giữa biển trời bao la.\r\n    </p>\r\n    <div class=\"pl-time\">Mở cửa h&agrave;ng ng&agrave;y từ 9:00 đến 19:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"pl-gallery-section\">\r\n    <div class=\"pl-gallery-heading\">\r\n      <div class=\"pl-heading-line\">\r\n        <div class=\"pl-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"pl-heading-sub\">Infinity Pool</div>\r\n      <div class=\"pl-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"pl-gallery-grid\">\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/4.png\" alt=\"Infinity Pool\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/1.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/2.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/3.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/4.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/5.png\" alt=\"Ruby Ocean Bar\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var plLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function plGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function plCreateOverlay() {\r\n      if (plLB.dialog) return\r\n      var pDoc = plGetParentDoc()\r\n      plLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { plCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      plLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      plLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) plCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); plCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        plLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (plLB.zoom.scale < 1) { plLB.zoom.scale = 1; plLB.zoom.x = 0; plLB.zoom.y = 0 }\r\n        if (plLB.zoom.scale > 5) plLB.zoom.scale = 5\r\n        plApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); plResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); plLB.zoom.dragging = true\r\n        plLB.zoom.startX = e.clientX; plLB.zoom.startY = e.clientY\r\n        plLB.zoom.lastX = plLB.zoom.x; plLB.zoom.lastY = plLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!plLB.zoom.dragging) return\r\n        plLB.zoom.x = plLB.zoom.lastX + (e.clientX - plLB.zoom.startX) / plLB.zoom.scale\r\n        plLB.zoom.y = plLB.zoom.lastY + (e.clientY - plLB.zoom.startY) / plLB.zoom.scale\r\n        plApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { plLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.touches.dist=Math.sqrt(dx*dx+dy*dy); plLB.touches.scale0=plLB.zoom.scale }\r\n        else if (e.touches.length === 1) { plLB.zoom.dragging=true; plLB.zoom.startX=e.touches[0].clientX; plLB.zoom.startY=e.touches[0].clientY; plLB.zoom.lastX=plLB.zoom.x; plLB.zoom.lastY=plLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.zoom.scale=plLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/plLB.touches.dist); if(plLB.zoom.scale<1)plLB.zoom.scale=1;if(plLB.zoom.scale>5)plLB.zoom.scale=5; plApplyZoom() }\r\n        else if (e.touches.length===1&&plLB.zoom.dragging) { e.preventDefault(); plLB.zoom.x=plLB.zoom.lastX+(e.touches[0].clientX-plLB.zoom.startX)/plLB.zoom.scale; plLB.zoom.y=plLB.zoom.lastY+(e.touches[0].clientY-plLB.zoom.startY)/plLB.zoom.scale; plApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { plLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') plCloseLightbox() })\r\n    }\r\n    function plResetZoom() { plLB.zoom.scale=1;plLB.zoom.x=0;plLB.zoom.y=0; if(plLB.img)plLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function plApplyZoom() { if(plLB.img)plLB.img.style.transform=\'scale(\'+plLB.zoom.scale+\') translate(\'+plLB.zoom.x+\'px,\'+plLB.zoom.y+\'px)\' }\r\n    function plOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      plCreateOverlay()\r\n      plLB.img.src = img.src; plResetZoom()\r\n      plLB.dialog.showModal()\r\n      plLB.dialog.style.display = \'flex\'\r\n    }\r\n    function plCloseLightbox() {\r\n      if (plLB.dialog && plLB.dialog.open) { plLB.dialog.close(); plLB.dialog.style.display = \'\'; plResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Infinity Pool & Ruby Ocean Bar</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====INFINITY POOL & RUBY OCEAN BAR=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .pl-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/4.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .pl-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-title-section .pl-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .pl-title-divider::before,\r\n    .pl-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-title-divider .pl-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .pl-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .pl-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .pl-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .pl-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line::before,\r\n    .pl-gallery-heading .pl-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .pl-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .pl-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .pl-title-section .pl-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .pl-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"pl-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"pl-title-section\">\r\n    <div class=\"pl-label\">Ruby 68 Hotel</div>\r\n    <h1>Infinity Pool & Ruby Ocean Bar</h1>\r\n    <div class=\"pl-title-divider\">\r\n      <div class=\"pl-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"pl-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7 khách sạn Ruby 68, hồ bơi vô cực gây ấn tượng với thiết kế kính trong suốt độc đáo, mở ra tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu đầy ngoạn mục. Thả mình trong làn nước xanh mát, tận hưởng ánh nắng ấm áp và nhâm nhi cocktail tại Ruby Ocean Bar, đây là trải nghiệm thư giãn không thể bỏ lỡ khi lưu trú tại khách sạn.\r\n    </p>\r\n    <p>\r\n      Được xem là một trong những hồ bơi vô cực đẹp nhất Vũng Tàu, nơi đây mang đến khoảnh khắc nghỉ dưỡng đẳng cấp giữa biển trời bao la.\r\n    </p>\r\n    <div class=\"pl-time\">Mở cửa hàng ngày từ 9:00 đến 19:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"pl-gallery-section\">\r\n    <div class=\"pl-gallery-heading\">\r\n      <div class=\"pl-heading-line\">\r\n        <div class=\"pl-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"pl-heading-sub\">Infinity Pool</div>\r\n      <div class=\"pl-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"pl-gallery-grid\">\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/4.png\" alt=\"Infinity Pool\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/1.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/2.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/3.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/4.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/5.png\" alt=\"Ruby Ocean Bar\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var plLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function plGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function plCreateOverlay() {\r\n      if (plLB.dialog) return\r\n      var pDoc = plGetParentDoc()\r\n      plLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { plCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      plLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      plLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) plCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); plCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        plLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (plLB.zoom.scale < 1) { plLB.zoom.scale = 1; plLB.zoom.x = 0; plLB.zoom.y = 0 }\r\n        if (plLB.zoom.scale > 5) plLB.zoom.scale = 5\r\n        plApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); plResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); plLB.zoom.dragging = true\r\n        plLB.zoom.startX = e.clientX; plLB.zoom.startY = e.clientY\r\n        plLB.zoom.lastX = plLB.zoom.x; plLB.zoom.lastY = plLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!plLB.zoom.dragging) return\r\n        plLB.zoom.x = plLB.zoom.lastX + (e.clientX - plLB.zoom.startX) / plLB.zoom.scale\r\n        plLB.zoom.y = plLB.zoom.lastY + (e.clientY - plLB.zoom.startY) / plLB.zoom.scale\r\n        plApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { plLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.touches.dist=Math.sqrt(dx*dx+dy*dy); plLB.touches.scale0=plLB.zoom.scale }\r\n        else if (e.touches.length === 1) { plLB.zoom.dragging=true; plLB.zoom.startX=e.touches[0].clientX; plLB.zoom.startY=e.touches[0].clientY; plLB.zoom.lastX=plLB.zoom.x; plLB.zoom.lastY=plLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.zoom.scale=plLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/plLB.touches.dist); if(plLB.zoom.scale<1)plLB.zoom.scale=1;if(plLB.zoom.scale>5)plLB.zoom.scale=5; plApplyZoom() }\r\n        else if (e.touches.length===1&&plLB.zoom.dragging) { e.preventDefault(); plLB.zoom.x=plLB.zoom.lastX+(e.touches[0].clientX-plLB.zoom.startX)/plLB.zoom.scale; plLB.zoom.y=plLB.zoom.lastY+(e.touches[0].clientY-plLB.zoom.startY)/plLB.zoom.scale; plApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { plLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') plCloseLightbox() })\r\n    }\r\n    function plResetZoom() { plLB.zoom.scale=1;plLB.zoom.x=0;plLB.zoom.y=0; if(plLB.img)plLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function plApplyZoom() { if(plLB.img)plLB.img.style.transform=\'scale(\'+plLB.zoom.scale+\') translate(\'+plLB.zoom.x+\'px,\'+plLB.zoom.y+\'px)\' }\r\n    function plOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      plCreateOverlay()\r\n      plLB.img.src = img.src; plResetZoom()\r\n      plLB.dialog.showModal()\r\n      plLB.dialog.style.display = \'flex\'\r\n    }\r\n    function plCloseLightbox() {\r\n      if (plLB.dialog && plLB.dialog.open) { plLB.dialog.close(); plLB.dialog.style.display = \'\'; plResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 01:45:05', '2026-03-26 01:45:05'),
