(95, 'Botble\\Page\\Models\\Page', 21, 1, 'content_mode', 'blocks', 'html', '2026-03-26 02:06:17', '2026-03-26 02:06:17');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(96, 'Botble\\Page\\Models\\Page', 21, 1, 'custom_html', NULL, '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Sauna &amp; Jacuzzi</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====SAUNA & JACUZZI=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sa-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sa-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sa-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sa-title-section .sa-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sa-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sa-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sa-title-divider::before,\r\n    .sa-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sa-title-divider .sa-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sa-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sa-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sa-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sa-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sa-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-line::before,\r\n    .sa-gallery-heading .sa-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sa-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sa-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sa-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sa-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sa-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sa-gallery-heading .sa-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sa-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sa-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sa-title-section .sa-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sa-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sa-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sa-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sa-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sa-gallery-heading .sa-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sa-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sa-title-section\">\r\n    <div class=\"sa-label\">Ruby 68 Hotel</div>\r\n    <h1>Sauna &amp; Jacuzzi</h1>\r\n    <div class=\"sa-title-divider\">\r\n      <div class=\"sa-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sa-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7, Sauna Zone tại Ruby 68 Hotel l&agrave; kh&ocirc;ng gian thư gi&atilde;n l&yacute; tưởng gi&uacute;p t&aacute;i tạo năng lượng sau một ng&agrave;y d&agrave;i kh&aacute;m ph&aacute; Vũng Tàu.\r\n    </p>\r\n    <p>\r\n      Khu vực được trang bị sauna kh&ocirc;, sauna ướt v&agrave; jacuzzi n&oacute;ng &ndash; lạnh, mang đến trải nghiệm thư gi&atilde;n to&agrave;n diện, hỗ trợ tuần ho&agrave;n v&agrave; phục hồi cơ thể hiệu quả.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng gian y&ecirc;n tĩnh, ri&ecirc;ng tư kết hợp c&ugrave;ng tiện nghi chuẩn 3 sao gi&uacute;p mỗi khoảnh khắc thư gi&atilde;n trở n&ecirc;n trọn vẹn v&agrave; tinh tế.\r\n    </p>\r\n    <div class=\"sa-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 23:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sa-gallery-section\">\r\n    <div class=\"sa-gallery-heading\">\r\n      <div class=\"sa-heading-line\">\r\n        <div class=\"sa-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sa-heading-sub\">Sauna &amp; Jacuzzi</div>\r\n      <div class=\"sa-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sa-gallery-grid\">\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/13.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/14.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/15.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/16.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/17.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/18.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/19.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/20.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/21.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var saLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function saGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function saCreateOverlay() {\r\n      if (saLB.dialog) return\r\n      var pDoc = saGetParentDoc()\r\n      saLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { saCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      saLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      saLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) saCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); saCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        saLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (saLB.zoom.scale < 1) { saLB.zoom.scale = 1; saLB.zoom.x = 0; saLB.zoom.y = 0 }\r\n        if (saLB.zoom.scale > 5) saLB.zoom.scale = 5\r\n        saApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); saResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); saLB.zoom.dragging = true\r\n        saLB.zoom.startX = e.clientX; saLB.zoom.startY = e.clientY\r\n        saLB.zoom.lastX = saLB.zoom.x; saLB.zoom.lastY = saLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!saLB.zoom.dragging) return\r\n        saLB.zoom.x = saLB.zoom.lastX + (e.clientX - saLB.zoom.startX) / saLB.zoom.scale\r\n        saLB.zoom.y = saLB.zoom.lastY + (e.clientY - saLB.zoom.startY) / saLB.zoom.scale\r\n        saApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { saLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; saLB.touches.dist=Math.sqrt(dx*dx+dy*dy); saLB.touches.scale0=saLB.zoom.scale }\r\n        else if (e.touches.length === 1) { saLB.zoom.dragging=true; saLB.zoom.startX=e.touches[0].clientX; saLB.zoom.startY=e.touches[0].clientY; saLB.zoom.lastX=saLB.zoom.x; saLB.zoom.lastY=saLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; saLB.zoom.scale=saLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/saLB.touches.dist); if(saLB.zoom.scale<1)saLB.zoom.scale=1;if(saLB.zoom.scale>5)saLB.zoom.scale=5; saApplyZoom() }\r\n        else if (e.touches.length===1&&saLB.zoom.dragging) { e.preventDefault(); saLB.zoom.x=saLB.zoom.lastX+(e.touches[0].clientX-saLB.zoom.startX)/saLB.zoom.scale; saLB.zoom.y=saLB.zoom.lastY+(e.touches[0].clientY-saLB.zoom.startY)/saLB.zoom.scale; saApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { saLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') saCloseLightbox() })\r\n    }\r\n    function saResetZoom() { saLB.zoom.scale=1;saLB.zoom.x=0;saLB.zoom.y=0; if(saLB.img)saLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function saApplyZoom() { if(saLB.img)saLB.img.style.transform=\'scale(\'+saLB.zoom.scale+\') translate(\'+saLB.zoom.x+\'px,\'+saLB.zoom.y+\'px)\' }\r\n    function saOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      saCreateOverlay()\r\n      saLB.img.src = img.src; saResetZoom()\r\n      saLB.dialog.showModal()\r\n      saLB.dialog.style.display = \'flex\'\r\n    }\r\n    function saCloseLightbox() {\r\n      if (saLB.dialog && saLB.dialog.open) { saLB.dialog.close(); saLB.dialog.style.display = \'\'; saResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:06:17', '2026-03-26 02:06:17'),
(97, 'Botble\\Page\\Models\\Page', 22, 1, 'content_mode', 'blocks', 'html', '2026-03-26 02:24:02', '2026-03-26 02:24:02'),
(98, 'Botble\\Page\\Models\\Page', 22, 1, 'custom_html', NULL, '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Gym Center</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GYM CENTER=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .gm-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .gm-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-title-section .gm-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .gm-title-divider::before,\r\n    .gm-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-title-divider .gm-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .gm-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .gm-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .gm-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .gm-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line::before,\r\n    .gm-gallery-heading .gm-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .gm-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gm-gallery-grid {\r\n        grid-template-columns: 1fr;\r\n        gap: 8px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .gm-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .gm-title-section .gm-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .gm-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"gm-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"gm-title-section\">\r\n    <div class=\"gm-label\">Ruby 68 Hotel</div>\r\n    <h1>Gym Center</h1>\r\n    <div class=\"gm-title-divider\">\r\n      <div class=\"gm-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"gm-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn Ruby 68, Gym Center mang đến kh&ocirc;ng gian luyện tập hiện đại với tầm nh&igrave;n hướng biển Bãi Sau v&agrave; th&agrave;nh phố, ngập tr&agrave;n &aacute;nh s&aacute;ng tự nhi&ecirc;n.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng chỉ l&agrave; nơi r&egrave;n luyện thể lực, mỗi buổi tập tại đ&acirc;y c&ograve;n l&agrave; trải nghiệm thư gi&atilde;n đầy cảm hứng trong kh&ocirc;ng gian rộng r&atilde;i, tinh tế.\r\n    </p>\r\n    <p>\r\n      Trang bị hệ thống m&aacute;y m&oacute;c đạt chuẩn quốc tế, ph&ugrave; hợp từ c&aacute;c b&agrave;i tập nhẹ nh&agrave;ng đến luyện tập chuy&ecirc;n s&acirc;u, gi&uacute;p bạn duy tr&igrave; phong độ v&agrave; c&acirc;n bằng năng lượng trong suốt kỳ nghỉ.\r\n    </p>\r\n    <div class=\"gm-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"gm-gallery-section\">\r\n    <div class=\"gm-gallery-heading\">\r\n      <div class=\"gm-heading-line\">\r\n        <div class=\"gm-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"gm-heading-sub\">Gym Center</div>\r\n      <div class=\"gm-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"gm-gallery-grid\">\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym-2.jpg\" alt=\"Gym Center\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gmLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gmGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gmCreateOverlay() {\r\n      if (gmLB.dialog) return\r\n      var pDoc = gmGetParentDoc()\r\n      gmLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gmCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      gmLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gmLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gmCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gmCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gmLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gmLB.zoom.scale < 1) { gmLB.zoom.scale = 1; gmLB.zoom.x = 0; gmLB.zoom.y = 0 }\r\n        if (gmLB.zoom.scale > 5) gmLB.zoom.scale = 5\r\n        gmApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gmResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gmLB.zoom.dragging = true\r\n        gmLB.zoom.startX = e.clientX; gmLB.zoom.startY = e.clientY\r\n        gmLB.zoom.lastX = gmLB.zoom.x; gmLB.zoom.lastY = gmLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gmLB.zoom.dragging) return\r\n        gmLB.zoom.x = gmLB.zoom.lastX + (e.clientX - gmLB.zoom.startX) / gmLB.zoom.scale\r\n        gmLB.zoom.y = gmLB.zoom.lastY + (e.clientY - gmLB.zoom.startY) / gmLB.zoom.scale\r\n        gmApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gmLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gmLB.touches.scale0=gmLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gmLB.zoom.dragging=true; gmLB.zoom.startX=e.touches[0].clientX; gmLB.zoom.startY=e.touches[0].clientY; gmLB.zoom.lastX=gmLB.zoom.x; gmLB.zoom.lastY=gmLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.zoom.scale=gmLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gmLB.touches.dist); if(gmLB.zoom.scale<1)gmLB.zoom.scale=1;if(gmLB.zoom.scale>5)gmLB.zoom.scale=5; gmApplyZoom() }\r\n        else if (e.touches.length===1&&gmLB.zoom.dragging) { e.preventDefault(); gmLB.zoom.x=gmLB.zoom.lastX+(e.touches[0].clientX-gmLB.zoom.startX)/gmLB.zoom.scale; gmLB.zoom.y=gmLB.zoom.lastY+(e.touches[0].clientY-gmLB.zoom.startY)/gmLB.zoom.scale; gmApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gmLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gmCloseLightbox() })\r\n    }\r\n    function gmResetZoom() { gmLB.zoom.scale=1;gmLB.zoom.x=0;gmLB.zoom.y=0; if(gmLB.img)gmLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gmApplyZoom() { if(gmLB.img)gmLB.img.style.transform=\'scale(\'+gmLB.zoom.scale+\') translate(\'+gmLB.zoom.x+\'px,\'+gmLB.zoom.y+\'px)\' }\r\n    function gmOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gmCreateOverlay()\r\n      gmLB.img.src = img.src; gmResetZoom()\r\n      gmLB.dialog.showModal()\r\n      gmLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gmCloseLightbox() {\r\n      if (gmLB.dialog && gmLB.dialog.open) { gmLB.dialog.close(); gmLB.dialog.style.display = \'\'; gmResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:24:02', '2026-03-26 02:24:02');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(99, 'Botble\\Page\\Models\\Page', 21, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Sauna &amp; Jacuzzi</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====SAUNA & JACUZZI=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sa-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sa-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sa-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sa-title-section .sa-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sa-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sa-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sa-title-divider::before,\r\n    .sa-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sa-title-divider .sa-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sa-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sa-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sa-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sa-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sa-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-line::before,\r\n    .sa-gallery-heading .sa-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sa-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sa-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sa-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sa-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sa-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sa-gallery-heading .sa-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sa-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sa-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sa-title-section .sa-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sa-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sa-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sa-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sa-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sa-gallery-heading .sa-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sa-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sa-title-section\">\r\n    <div class=\"sa-label\">Ruby 68 Hotel</div>\r\n    <h1>Sauna &amp; Jacuzzi</h1>\r\n    <div class=\"sa-title-divider\">\r\n      <div class=\"sa-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sa-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7, Sauna Zone tại Ruby 68 Hotel l&agrave; kh&ocirc;ng gian thư gi&atilde;n l&yacute; tưởng gi&uacute;p t&aacute;i tạo năng lượng sau một ng&agrave;y d&agrave;i kh&aacute;m ph&aacute; Vũng Tàu.\r\n    </p>\r\n    <p>\r\n      Khu vực được trang bị sauna kh&ocirc;, sauna ướt v&agrave; jacuzzi n&oacute;ng &ndash; lạnh, mang đến trải nghiệm thư gi&atilde;n to&agrave;n diện, hỗ trợ tuần ho&agrave;n v&agrave; phục hồi cơ thể hiệu quả.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng gian y&ecirc;n tĩnh, ri&ecirc;ng tư kết hợp c&ugrave;ng tiện nghi chuẩn 3 sao gi&uacute;p mỗi khoảnh khắc thư gi&atilde;n trở n&ecirc;n trọn vẹn v&agrave; tinh tế.\r\n    </p>\r\n    <div class=\"sa-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 23:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sa-gallery-section\">\r\n    <div class=\"sa-gallery-heading\">\r\n      <div class=\"sa-heading-line\">\r\n        <div class=\"sa-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sa-heading-sub\">Sauna &amp; Jacuzzi</div>\r\n      <div class=\"sa-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sa-gallery-grid\">\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/13.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/14.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/15.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/16.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/17.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/18.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/19.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/20.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/21.png\" alt=\"Sauna &amp; Jacuzzi\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var saLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function saGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function saCreateOverlay() {\r\n      if (saLB.dialog) return\r\n      var pDoc = saGetParentDoc()\r\n      saLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { saCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      saLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      saLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) saCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); saCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        saLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (saLB.zoom.scale < 1) { saLB.zoom.scale = 1; saLB.zoom.x = 0; saLB.zoom.y = 0 }\r\n        if (saLB.zoom.scale > 5) saLB.zoom.scale = 5\r\n        saApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); saResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); saLB.zoom.dragging = true\r\n        saLB.zoom.startX = e.clientX; saLB.zoom.startY = e.clientY\r\n        saLB.zoom.lastX = saLB.zoom.x; saLB.zoom.lastY = saLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!saLB.zoom.dragging) return\r\n        saLB.zoom.x = saLB.zoom.lastX + (e.clientX - saLB.zoom.startX) / saLB.zoom.scale\r\n        saLB.zoom.y = saLB.zoom.lastY + (e.clientY - saLB.zoom.startY) / saLB.zoom.scale\r\n        saApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { saLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; saLB.touches.dist=Math.sqrt(dx*dx+dy*dy); saLB.touches.scale0=saLB.zoom.scale }\r\n        else if (e.touches.length === 1) { saLB.zoom.dragging=true; saLB.zoom.startX=e.touches[0].clientX; saLB.zoom.startY=e.touches[0].clientY; saLB.zoom.lastX=saLB.zoom.x; saLB.zoom.lastY=saLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; saLB.zoom.scale=saLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/saLB.touches.dist); if(saLB.zoom.scale<1)saLB.zoom.scale=1;if(saLB.zoom.scale>5)saLB.zoom.scale=5; saApplyZoom() }\r\n        else if (e.touches.length===1&&saLB.zoom.dragging) { e.preventDefault(); saLB.zoom.x=saLB.zoom.lastX+(e.touches[0].clientX-saLB.zoom.startX)/saLB.zoom.scale; saLB.zoom.y=saLB.zoom.lastY+(e.touches[0].clientY-saLB.zoom.startY)/saLB.zoom.scale; saApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { saLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') saCloseLightbox() })\r\n    }\r\n    function saResetZoom() { saLB.zoom.scale=1;saLB.zoom.x=0;saLB.zoom.y=0; if(saLB.img)saLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function saApplyZoom() { if(saLB.img)saLB.img.style.transform=\'scale(\'+saLB.zoom.scale+\') translate(\'+saLB.zoom.x+\'px,\'+saLB.zoom.y+\'px)\' }\r\n    function saOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      saCreateOverlay()\r\n      saLB.img.src = img.src; saResetZoom()\r\n      saLB.dialog.showModal()\r\n      saLB.dialog.style.display = \'flex\'\r\n    }\r\n    function saCloseLightbox() {\r\n      if (saLB.dialog && saLB.dialog.open) { saLB.dialog.close(); saLB.dialog.style.display = \'\'; saResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Sauna & Jacuzzi</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====SAUNA & JACUZZI=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sa-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/13.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sa-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sa-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sa-title-section .sa-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sa-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sa-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sa-title-divider::before,\r\n    .sa-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sa-title-divider .sa-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sa-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sa-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sa-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sa-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sa-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-line::before,\r\n    .sa-gallery-heading .sa-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sa-gallery-heading .sa-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sa-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sa-gallery-grid .sa-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sa-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sa-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sa-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sa-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sa-gallery-heading .sa-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sa-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sa-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sa-title-section .sa-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sa-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sa-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sa-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sa-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sa-gallery-heading .sa-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sa-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sa-title-section\">\r\n    <div class=\"sa-label\">Ruby 68 Hotel</div>\r\n    <h1>Sauna & Jacuzzi</h1>\r\n    <div class=\"sa-title-divider\">\r\n      <div class=\"sa-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sa-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7, Sauna Zone tại Ruby 68 Hotel là không gian thư giãn lý tưởng giúp tái tạo năng lượng sau một ngày dài khám phá Vũng Tàu.\r\n    </p>\r\n    <p>\r\n      Khu vực được trang bị sauna khô, sauna ướt và jacuzzi nóng – lạnh, mang đến trải nghiệm thư giãn toàn diện, hỗ trợ tuần hoàn và phục hồi cơ thể hiệu quả.\r\n    </p>\r\n    <p>\r\n      Không gian yên tĩnh, riêng tư kết hợp cùng tiện nghi chuẩn 3 sao giúp mỗi khoảnh khắc thư giãn trở nên trọn vẹn và tinh tế.\r\n    </p>\r\n    <div class=\"sa-time\">Mở cửa hàng ngày từ 10:00 đến 23:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sa-gallery-section\">\r\n    <div class=\"sa-gallery-heading\">\r\n      <div class=\"sa-heading-line\">\r\n        <div class=\"sa-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sa-heading-sub\">Sauna & Jacuzzi</div>\r\n      <div class=\"sa-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sa-gallery-grid\">\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/13.png\" alt=\"Sauna & Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/14.png\" alt=\"Sauna & Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/15.png\" alt=\"Sauna & Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/16.png\" alt=\"Sauna & Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" onclick=\"saOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/sauna-and-jacuzzi/17.png\" alt=\"Sauna & Jacuzzi\"></div>\r\n      <div class=\"sa-photo\" o