(104, 'Botble\\Page\\Models\\Page', 23, 1, 'custom_html', NULL, '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Spa</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SPA=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sp-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sp-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-title-section .sp-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sp-title-divider::before,\r\n    .sp-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-title-divider .sp-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sp-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sp-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sp-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sp-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line::before,\r\n    .sp-gallery-heading .sp-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sp-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sp-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sp-title-section .sp-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sp-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sp-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sp-title-section\">\r\n    <div class=\"sp-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby Spa</h1>\r\n    <div class=\"sp-title-divider\">\r\n      <div class=\"sp-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sp-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn, trong kh&ocirc;ng gian y&ecirc;n tĩnh v&agrave; ri&ecirc;ng tư, Ruby Spa l&agrave; điểm đến l&yacute; tưởng để t&aacute;i tạo năng lượng v&agrave; c&acirc;n bằng cảm x&uacute;c.\r\n    </p>\r\n    <p>\r\n      C&aacute;c liệu tr&igrave;nh được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuy&ecirc;n s&acirc;u v&agrave; nguy&ecirc;n liệu cao cấp, mang đến trải nghiệm thư gi&atilde;n to&agrave;n diện cho cơ thể v&agrave; t&acirc;m tr&iacute;.\r\n    </p>\r\n    <p>\r\n      Từ massage thư gi&atilde;n, chăm s&oacute;c da đến c&aacute;c liệu ph&aacute;p phục hồi, mỗi h&agrave;nh tr&igrave;nh tại Ruby Spa đều được chăm ch&uacute;t tỉ mỉ, gi&uacute;p bạn tận hưởng trọn vẹn sự an y&ecirc;n trong chuẩn mực dịch vụ 3 sao.\r\n    </p>\r\n    <div class=\"sp-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sp-gallery-section\">\r\n    <div class=\"sp-gallery-heading\">\r\n      <div class=\"sp-heading-line\">\r\n        <div class=\"sp-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sp-heading-sub\">Ruby Spa</div>\r\n      <div class=\"sp-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sp-gallery-grid\">\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa-2.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/16.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/17.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/18.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/19.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/20.png\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var spLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function spGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function spCreateOverlay() {\r\n      if (spLB.dialog) return\r\n      var pDoc = spGetParentDoc()\r\n      spLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { spCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      spLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      spLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) spCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); spCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        spLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (spLB.zoom.scale < 1) { spLB.zoom.scale = 1; spLB.zoom.x = 0; spLB.zoom.y = 0 }\r\n        if (spLB.zoom.scale > 5) spLB.zoom.scale = 5\r\n        spApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); spResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); spLB.zoom.dragging = true\r\n        spLB.zoom.startX = e.clientX; spLB.zoom.startY = e.clientY\r\n        spLB.zoom.lastX = spLB.zoom.x; spLB.zoom.lastY = spLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!spLB.zoom.dragging) return\r\n        spLB.zoom.x = spLB.zoom.lastX + (e.clientX - spLB.zoom.startX) / spLB.zoom.scale\r\n        spLB.zoom.y = spLB.zoom.lastY + (e.clientY - spLB.zoom.startY) / spLB.zoom.scale\r\n        spApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { spLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.touches.dist=Math.sqrt(dx*dx+dy*dy); spLB.touches.scale0=spLB.zoom.scale }\r\n        else if (e.touches.length === 1) { spLB.zoom.dragging=true; spLB.zoom.startX=e.touches[0].clientX; spLB.zoom.startY=e.touches[0].clientY; spLB.zoom.lastX=spLB.zoom.x; spLB.zoom.lastY=spLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.zoom.scale=spLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/spLB.touches.dist); if(spLB.zoom.scale<1)spLB.zoom.scale=1;if(spLB.zoom.scale>5)spLB.zoom.scale=5; spApplyZoom() }\r\n        else if (e.touches.length===1&&spLB.zoom.dragging) { e.preventDefault(); spLB.zoom.x=spLB.zoom.lastX+(e.touches[0].clientX-spLB.zoom.startX)/spLB.zoom.scale; spLB.zoom.y=spLB.zoom.lastY+(e.touches[0].clientY-spLB.zoom.startY)/spLB.zoom.scale; spApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { spLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') spCloseLightbox() })\r\n    }\r\n    function spResetZoom() { spLB.zoom.scale=1;spLB.zoom.x=0;spLB.zoom.y=0; if(spLB.img)spLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function spApplyZoom() { if(spLB.img)spLB.img.style.transform=\'scale(\'+spLB.zoom.scale+\') translate(\'+spLB.zoom.x+\'px,\'+spLB.zoom.y+\'px)\' }\r\n    function spOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      spCreateOverlay()\r\n      spLB.img.src = img.src; spResetZoom()\r\n      spLB.dialog.showModal()\r\n      spLB.dialog.style.display = \'flex\'\r\n    }\r\n    function spCloseLightbox() {\r\n      if (spLB.dialog && spLB.dialog.open) { spLB.dialog.close(); spLB.dialog.style.display = \'\'; spResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:51:07', '2026-03-26 02:51:07');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(105, 'Botble\\Page\\Models\\Page', 23, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Spa</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SPA=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sp-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sp-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-title-section .sp-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sp-title-divider::before,\r\n    .sp-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-title-divider .sp-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sp-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sp-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sp-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sp-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line::before,\r\n    .sp-gallery-heading .sp-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sp-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sp-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sp-title-section .sp-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sp-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sp-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sp-title-section\">\r\n    <div class=\"sp-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby Spa</h1>\r\n    <div class=\"sp-title-divider\">\r\n      <div class=\"sp-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sp-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn, trong kh&ocirc;ng gian y&ecirc;n tĩnh v&agrave; ri&ecirc;ng tư, Ruby Spa l&agrave; điểm đến l&yacute; tưởng để t&aacute;i tạo năng lượng v&agrave; c&acirc;n bằng cảm x&uacute;c.\r\n    </p>\r\n    <p>\r\n      C&aacute;c liệu tr&igrave;nh được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuy&ecirc;n s&acirc;u v&agrave; nguy&ecirc;n liệu cao cấp, mang đến trải nghiệm thư gi&atilde;n to&agrave;n diện cho cơ thể v&agrave; t&acirc;m tr&iacute;.\r\n    </p>\r\n    <p>\r\n      Từ massage thư gi&atilde;n, chăm s&oacute;c da đến c&aacute;c liệu ph&aacute;p phục hồi, mỗi h&agrave;nh tr&igrave;nh tại Ruby Spa đều được chăm ch&uacute;t tỉ mỉ, gi&uacute;p bạn tận hưởng trọn vẹn sự an y&ecirc;n trong chuẩn mực dịch vụ 3 sao.\r\n    </p>\r\n    <div class=\"sp-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sp-gallery-section\">\r\n    <div class=\"sp-gallery-heading\">\r\n      <div class=\"sp-heading-line\">\r\n        <div class=\"sp-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sp-heading-sub\">Ruby Spa</div>\r\n      <div class=\"sp-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sp-gallery-grid\">\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa-2.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/16.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/17.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/18.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/19.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/20.png\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var spLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function spGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function spCreateOverlay() {\r\n      if (spLB.dialog) return\r\n      var pDoc = spGetParentDoc()\r\n      spLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { spCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      spLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      spLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) spCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); spCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        spLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (spLB.zoom.scale < 1) { spLB.zoom.scale = 1; spLB.zoom.x = 0; spLB.zoom.y = 0 }\r\n        if (spLB.zoom.scale > 5) spLB.zoom.scale = 5\r\n        spApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); spResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); spLB.zoom.dragging = true\r\n        spLB.zoom.startX = e.clientX; spLB.zoom.startY = e.clientY\r\n        spLB.zoom.lastX = spLB.zoom.x; spLB.zoom.lastY = spLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!spLB.zoom.dragging) return\r\n        spLB.zoom.x = spLB.zoom.lastX + (e.clientX - spLB.zoom.startX) / spLB.zoom.scale\r\n        spLB.zoom.y = spLB.zoom.lastY + (e.clientY - spLB.zoom.startY) / spLB.zoom.scale\r\n        spApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { spLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.touches.dist=Math.sqrt(dx*dx+dy*dy); spLB.touches.scale0=spLB.zoom.scale }\r\n        else if (e.touches.length === 1) { spLB.zoom.dragging=true; spLB.zoom.startX=e.touches[0].clientX; spLB.zoom.startY=e.touches[0].clientY; spLB.zoom.lastX=spLB.zoom.x; spLB.zoom.lastY=spLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.zoom.scale=spLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/spLB.touches.dist); if(spLB.zoom.scale<1)spLB.zoom.scale=1;if(spLB.zoom.scale>5)spLB.zoom.scale=5; spApplyZoom() }\r\n        else if (e.touches.length===1&&spLB.zoom.dragging) { e.preventDefault(); spLB.zoom.x=spLB.zoom.lastX+(e.touches[0].clientX-spLB.zoom.startX)/spLB.zoom.scale; spLB.zoom.y=spLB.zoom.lastY+(e.touches[0].clientY-spLB.zoom.startY)/spLB.zoom.scale; spApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { spLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') spCloseLightbox() })\r\n    }\r\n    function spResetZoom() { spLB.zoom.scale=1;spLB.zoom.x=0;spLB.zoom.y=0; if(spLB.img)spLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function spApplyZoom() { if(spLB.img)spLB.img.style.transform=\'scale(\'+spLB.zoom.scale+\') translate(\'+spLB.zoom.x+\'px,\'+spLB.zoom.y+\'px)\' }\r\n    function spOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      spCreateOverlay()\r\n      spLB.img.src = img.src; spResetZoom()\r\n      spLB.dialog.showModal()\r\n      spLB.dialog.style.display = \'flex\'\r\n    }\r\n    function spCloseLightbox() {\r\n      if (spLB.dialog && spLB.dialog.open) { spLB.dialog.close(); spLB.dialog.style.display = \'\'; spResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Spa</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SPA=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sp-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sp-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-title-section .sp-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sp-title-divider::before,\r\n    .sp-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-title-divider .sp-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sp-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sp-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sp-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sp-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line::before,\r\n    .sp-gallery-heading .sp-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sp-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sp-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sp-title-section .sp-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sp-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sp-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sp-title-section\">\r\n    <div class=\"sp-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby Spa</h1>\r\n    <div class=\"sp-title-divider\">\r\n      <div class=\"sp-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sp-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 khách sạn, trong không gian yên tĩnh và riêng tư, Ruby Spa là điểm đến lý tưởng để tái tạo năng lượng và cân bằng cảm xúc.\r\n    </p>\r\n    <p>\r\n      Các liệu trình được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuyên sâu và nguyên liệu cao cấp, mang đến trải nghiệm thư giãn toàn diện cho cơ thể và tâm trí.\r\n    </p>\r\n    <p>\r\n      Từ massage thư giãn, chăm sóc da đến các liệu pháp phục hồi, mỗi hành trình tại Ruby Spa đều được chăm chút tỉ mỉ, giúp bạn tận hưởng trọn vẹn sự an yên trong chuẩn mực dịch vụ 3 sao.\r\n    </p>\r\n    <div class=\"sp-time\">Mở cửa hàng ngày từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sp-gallery-section\">\r\n    <div class=\"sp-gallery-heading\">\r\n      <div class=\"sp-heading-line\">\r\n        <div class=\"sp-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sp-heading-sub\">Ruby Spa</div>\r\n      <div class=\"sp-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sp-gallery-grid\">\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa-2.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/16.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/17.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/18.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/19.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/20.png\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var spLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function spGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function spCreateOverlay() {\r\n      if (spLB.dialog) return\r\n      var pDoc = spGetParentDoc()\r\n      spLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { spCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      spLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      spLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) spCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); spCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        spLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (spLB.zoom.scale < 1) { spLB.zoom.scale = 1; spLB.zoom.x = 0; spLB.zoom.y = 0 }\r\n        if (spLB.zoom.scale > 5) spLB.zoom.scale = 5\r\n        spApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); spResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); spLB.zoom.dragging = true\r\n        spLB.zoom.startX = e.clientX; spLB.zoom.startY = e.clientY\r\n        spLB.zoom.lastX = spLB.zoom.x; spLB.zoom.lastY = spLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!spLB.zoom.dragging) return\r\n        spLB.zoom.x = spLB.zoom.lastX + (e.clientX - spLB.zoom.startX) / spLB.zoom.scale\r\n        spLB.zoom.y = spLB.zoom.lastY + (e.clientY - spLB.zoom.startY) / spLB.zoom.scale\r\n        spApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { spLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.touches.dist=Math.sqrt(dx*dx+dy*dy); spLB.touches.scale0=spLB.zoom.scale }\r\n        else if (e.touches.length === 1) { spLB.zoom.dragging=true; spLB.zoom.startX=e.touches[0].clientX; spLB.zoom.startY=e.touches[0].clientY; spLB.zoom.lastX=spLB.zoom.x; spLB.zoom.lastY=spLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.zoom.scale=spLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/spLB.touches.dist); if(spLB.zoom.scale<1)spLB.zoom.scale=1;if(spLB.zoom.scale>5)spLB.zoom.scale=5; spApplyZoom() }\r\n        else if (e.touches.length===1&&spLB.zoom.dragging) { e.preventDefault(); spLB.zoom.x=spLB.zoom.lastX+(e.touches[0].clientX-spLB.zoom.startX)/spLB.zoom.scale; spLB.zoom.y=spLB.zoom.lastY+(e.touches[0].clientY-spLB.zoom.startY)/spLB.zoom.scale; spApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { spLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') spCloseLightbox() })\r\n    }\r\n    function spResetZoom() { spLB.zoom.scale=1;spLB.zoom.x=0;spLB.zoom.y=0; if(spLB.img)spLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function spApplyZoom() { if(spLB.img)spLB.img.style.transform=\'scale(\'+spLB.zoom.scale+\') translate(\'+spLB.zoom.x+\'px,\'+spLB.zoom.y+\'px)\' }\r\n    function spOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      spCreateOverlay()\r\n      spLB.img.src = img.src; spResetZoom()\r\n      spLB.dialog.showModal()\r\n      spLB.dialog.style.display = \'flex\'\r\n    }\r\n    function spCloseLightbox() {\r\n      if (spLB.dialog && spLB.dialog.open) { spLB.dialog.close(); spLB.dialog.style.display = \'\'; spResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:51:14', '2026-03-26 02:51:14'),
(106, 'Botble\\Page\\Models\\Page', 23, 1, 'template', 'default', 'full-width', '2026-03-26 02:51:14', '2026-03-26 02:51:14');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(107, 'Botble\\Page\\Models\\Page', 23, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Spa</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SPA=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sp-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sp-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-title-section .sp-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sp-title-divider::before,\r\n    .sp-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-title-divider .sp-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sp-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sp-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sp-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sp-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line::before,\r\n    .sp-gallery-heading .sp-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sp-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sp-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sp-title-section .sp-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sp-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sp-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sp-title-section\">\r\n    <div class=\"sp-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby Spa</h1>\r\n    <div class=\"sp-title-divider\">\r\n      <div class=\"sp-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sp-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 khách sạn, trong không gian yên tĩnh và riêng tư, Ruby Spa là điểm đến lý tưởng để tái tạo năng lượng và cân bằng cảm xúc.\r\n    </p>\r\n    <p>\r\n      Các liệu trình được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuyên sâu và nguyên liệu cao cấp, mang đến trải nghiệm thư giãn toàn diện cho cơ thể và tâm trí.\r\n    </p>\r\n    <p>\r\n      Từ massage thư giãn, chăm sóc da đến các liệu pháp phục hồi, mỗi hành trình tại Ruby Spa đều được chăm chút tỉ mỉ, giúp bạn tận hưởng trọn vẹn sự an yên trong chuẩn mực dịch vụ 3 sao.\r\n    </p>\r\n    <div class=\"sp-time\">Mở cửa hàng ngày từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sp-gallery-section\">\r\n    <div class=\"sp-gallery-heading\">\r\n      <div class=\"sp-heading-line\">\r\n        <div class=\"sp-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sp-heading-sub\">Ruby Spa</div>\r\n      <div class=\"sp-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sp-gallery-grid\">\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa-2.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/16.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/17.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/18.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/19.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/20.png\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var spLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function spGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function spCreateOverlay() {\r\n      if (spLB.dialog) return\r\n      var pDoc = spGetParentDoc()\r\n      spLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { spCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      spLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      spLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) spCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); spCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        spLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (spLB.zoom.scale < 1) { spLB.zoom.scale = 1; spLB.zoom.x = 0; spLB.zoom.y = 0 }\r\n        if (spLB.zoom.scale > 5) spLB.zoom.scale = 5\r\n        spApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); spResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); spLB.zoom.dragging = true\r\n        spLB.zoom.startX = e.clientX; spLB.zoom.startY = e.clientY\r\n        spLB.zoom.lastX = spLB.zoom.x; spLB.zoom.lastY = spLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!spLB.zoom.dragging) return\r\n        spLB.zoom.x = spLB.zoom.lastX + (e.clientX - spLB.zoom.startX) / spLB.zoom.scale\r\n        spLB.zoom.y = spLB.zoom.lastY + (e.clientY - spLB.zoom.startY) / spLB.zoom.scale\r\n        spApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { spLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.touches.dist=Math.sqrt(dx*dx+dy*dy); spLB.touches.scale0=spLB.zoom.scale }\r\n        else if (e.touches.length === 1) { spLB.zoom.dragging=true; spLB.zoom.startX=e.touches[0].clientX; spLB.zoom.startY=e.touches[0].clientY; spLB.zoom.lastX=spLB.zoom.x; spLB.zoom.lastY=spLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.zoom.scale=spLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/spLB.touches.dist); if(spLB.zoom.scale<1)spLB.zoom.scale=1;if(spLB.zoom.scale>5)spLB.zoom.scale=5; spApplyZoom() }\r\n        else if (e.touches.length===1&&spLB.zoom.dragging) { e.preventDefault(); spLB.zoom.x=spLB.zoom.lastX+(e.touches[0].clientX-spLB.zoom.startX)/spLB.zoom.scale; spLB.zoom.y=spLB.zoom.lastY+(e.touches[0].clientY-spLB.zoom.startY)/spLB.zoom.scale; spApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { spLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') spCloseLightbox() })\r\n    }\r\n    function spResetZoom() { spLB.zoom.scale=1;spLB.zoom.x=0;spLB.zoom.y=0; if(spLB.img)spLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function spApplyZoom() { if(spLB.img)spLB.img.style.transform=\'scale(\'+spLB.zoom.scale+\') translate(\'+spLB.zoom.x+\'px,\'+spLB.zoom.y+\'px)\' }\r\n    function spOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      spCreateOverlay()\r\n      spLB.img.src = img.src; spResetZoom()\r\n      spLB.dialog.showModal()\r\n      spLB.dialog.style.display = \'flex\'\r\n    }\r\n    function spCloseLightbox() {\r\n      if (spLB.dialog && spLB.dialog.open) { spLB.dialog.close(); spLB.dialog.style.display = \'\'; spResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Spa</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SPA=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sp-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sp-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-title-section .sp-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sp-title-divider::before,\r\n    .sp-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-title-divider .sp-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sp-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sp-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sp-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sp-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line::before,\r\n    .sp-gallery-heading .sp-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sp-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sp-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sp-title-section .sp-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sp-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sp-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sp-title-section\">\r\n    <div class=\"sp-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby Spa</h1>\r\n    <div class=\"sp-title-divider\">\r\n      <div class=\"sp-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sp-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn, trong kh&ocirc;ng gian y&ecirc;n tĩnh v&agrave; ri&ecirc;ng tư, Ruby Spa l&agrave; điểm đến l&yacute; tưởng để t&aacute;i tạo năng lượng v&agrave; c&acirc;n bằng cảm x&uacute;c.\r\n    </p>\r\n    <p>\r\n      C&aacute;c liệu tr&igrave;nh được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuy&ecirc;n s&acirc;u v&agrave; nguy&ecirc;n liệu cao cấp, mang đến trải nghiệm thư gi&atilde;n to&agrave;n diện cho cơ thể v&agrave; t&acirc;m tr&iacute;.\r\n    </p>\r\n    <p>\r\n      Từ massage thư gi&atilde;n, chăm s&oacute;c da đến c&aacute;c liệu ph&aacute;p phục hồi, mỗi h&agrave;nh tr&igrave;nh tại Ruby Spa đều được chăm ch&uacute;t tỉ mỉ, gi&uacute;p bạn tận hưởng trọn vẹn sự an y&ecirc;n trong chuẩn mực dịch vụ 3 sao.\r\n    </p>\r\n    <div class=\"sp-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sp-gallery-section\">\r\n    <div class=\"sp-gallery-heading\">\r\n      <div class=\"sp-heading-line\">\r\n        <div class=\"sp-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sp-heading-sub\">Ruby Spa</div>\r\n      <div class=\"sp-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sp-gallery-grid\">\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/spa-2.jpg\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/16.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/17.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/18.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/19.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/20.png\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var spLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function spGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function spCreateOverlay() {\r\n      if (spLB.dialog) return\r\n      var pDoc = spGetParentDoc()\r\n      spLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { spCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      spLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      spLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) spCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); spCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        spLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (spLB.zoom.scale < 1) { spLB.zoom.scale = 1; spLB.zoom.x = 0; spLB.zoom.y = 0 }\r\n        if (spLB.zoom.scale > 5) spLB.zoom.scale = 5\r\n        spApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); spResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); spLB.zoom.dragging = true\r\n        spLB.zoom.startX = e.clientX; spLB.zoom.startY = e.clientY\r\n        spLB.zoom.lastX = spLB.zoom.x; spLB.zoom.lastY = spLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!spLB.zoom.dragging) return\r\n        spLB.zoom.x = spLB.zoom.lastX + (e.clientX - spLB.zoom.startX) / spLB.zoom.scale\r\n        spLB.zoom.y = spLB.zoom.lastY + (e.clientY - spLB.zoom.startY) / spLB.zoom.scale\r\n        spApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { spLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.touches.dist=Math.sqrt(dx*dx+dy*dy); spLB.touches.scale0=spLB.zoom.scale }\r\n        else if (e.touches.length === 1) { spLB.zoom.dragging=true; spLB.zoom.startX=e.touches[0].clientX; spLB.zoom.startY=e.touches[0].clientY; spLB.zoom.lastX=spLB.zoom.x; spLB.zoom.lastY=spLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.zoom.scale=spLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/spLB.touches.dist); if(spLB.zoom.scale<1)spLB.zoom.scale=1;if(spLB.zoom.scale>5)spLB.zoom.scale=5; spApplyZoom() }\r\n        else if (e.touches.length===1&&spLB.zoom.dragging) { e.preventDefault(); spLB.zoom.x=spLB.zoom.lastX+(e.touches[0].clientX-spLB.zoom.startX)/spLB.zoom.scale; spLB.zoom.y=spLB.zoom.lastY+(e.touches[0].clientY-spLB.zoom.startY)/spLB.zoom.scale; spApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { spLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') spCloseLightbox() })\r\n    }\r\n    function spResetZoom() { spLB.zoom.scale=1;spLB.zoom.x=0;spLB.zoom.y=0; if(spLB.img)spLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function spApplyZoom() { if(spLB.img)spLB.img.style.transform=\'scale(\'+spLB.zoom.scale+\') translate(\'+spLB.zoom.x+\'px,\'+spLB.zoom.y+\'px)\' }\r\n    function spOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      spCreateOverlay()\r\n      spLB.img.src = img.src; spResetZoom()\r\n      spLB.dialog.showModal()\r\n      spLB.dialog.style.display = \'flex\'\r\n    }\r\n    function spCloseLightbox() {\r\n      if (spLB.dialog && spLB.dialog.open) { spLB.dialog.close(); spLB.dialog.style.display = \'\'; spResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:52:30', '2026-03-26 02:52:30');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(108, 'Botble\\Page\\Models\\Page', 22, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Gym Center</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GYM CENTER=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .gm-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .gm-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-title-section .gm-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .gm-title-divider::before,\r\n    .gm-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-title-divider .gm-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .gm-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .gm-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .gm-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .gm-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line::before,\r\n    .gm-gallery-heading .gm-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .gm-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gm-gallery-grid {\r\n        grid-template-columns: 1fr;\r\n        gap: 8px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .gm-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .gm-title-section .gm-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .gm-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"gm-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"gm-title-section\">\r\n    <div class=\"gm-label\">Ruby 68 Hotel</div>\r\n    <h1>Gym Center</h1>\r\n    <div class=\"gm-title-divider\">\r\n      <div class=\"gm-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"gm-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 khách sạn Ruby 68, Gym Center mang đến không gian luyện tập hiện đại với tầm nhìn hướng biển Bãi Sau và thành phố, ngập tràn ánh sáng tự nhiên.\r\n    </p>\r\n    <p>\r\n      Không chỉ là nơi rèn luyện thể lực, mỗi buổi tập tại đây còn là trải nghiệm thư giãn đầy cảm hứng trong không gian rộng rãi, tinh tế.\r\n    </p>\r\n    <p>\r\n      Trang bị hệ thống máy móc đạt chuẩn quốc tế, phù hợp từ các bài tập nhẹ nhàng đến luyện tập chuyên sâu, giúp bạn duy trì phong độ và cân bằng năng lượng trong suốt kỳ nghỉ.\r\n    </p>\r\n    <div class=\"gm-time\">Mở cửa hàng ngày từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"gm-gallery-section\">\r\n    <div class=\"gm-gallery-heading\">\r\n      <div class=\"gm-heading-line\">\r\n        <div class=\"gm-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"gm-heading-sub\">Gym Center</div>\r\n      <div class=\"gm-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"gm-gallery-grid\">\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym-2.jpg\" alt=\"Gym Center\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gmLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gmGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gmCreateOverlay() {\r\n      if (gmLB.dialog) return\r\n      var pDoc = gmGetParentDoc()\r\n      gmLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gmCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      gmLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gmLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gmCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gmCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gmLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gmLB.zoom.scale < 1) { gmLB.zoom.scale = 1; gmLB.zoom.x = 0; gmLB.zoom.y = 0 }\r\n        if (gmLB.zoom.scale > 5) gmLB.zoom.scale = 5\r\n        gmApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gmResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gmLB.zoom.dragging = true\r\n        gmLB.zoom.startX = e.clientX; gmLB.zoom.startY = e.clientY\r\n        gmLB.zoom.lastX = gmLB.zoom.x; gmLB.zoom.lastY = gmLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gmLB.zoom.dragging) return\r\n        gmLB.zoom.x = gmLB.zoom.lastX + (e.clientX - gmLB.zoom.startX) / gmLB.zoom.scale\r\n        gmLB.zoom.y = gmLB.zoom.lastY + (e.clientY - gmLB.zoom.startY) / gmLB.zoom.scale\r\n        gmApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gmLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gmLB.touches.scale0=gmLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gmLB.zoom.dragging=true; gmLB.zoom.startX=e.touches[0].clientX; gmLB.zoom.startY=e.touches[0].clientY; gmLB.zoom.lastX=gmLB.zoom.x; gmLB.zoom.lastY=gmLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.zoom.scale=gmLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gmLB.touches.dist); if(gmLB.zoom.scale<1)gmLB.zoom.scale=1;if(gmLB.zoom.scale>5)gmLB.zoom.scale=5; gmApplyZoom() }\r\n        else if (e.touches.length===1&&gmLB.zoom.dragging) { e.preventDefault(); gmLB.zoom.x=gmLB.zoom.lastX+(e.touches[0].clientX-gmLB.zoom.startX)/gmLB.zoom.scale; gmLB.zoom.y=gmLB.zoom.lastY+(e.touches[0].clientY-gmLB.zoom.startY)/gmLB.zoom.scale; gmApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gmLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gmCloseLightbox() })\r\n    }\r\n    function gmResetZoom() { gmLB.zoom.scale=1;gmLB.zoom.x=0;gmLB.zoom.y=0; if(gmLB.img)gmLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gmApplyZoom() { if(gmLB.img)gmLB.img.style.transform=\'scale(\'+gmLB.zoom.scale+\') translate(\'+gmLB.zoom.x+\'px,\'+gmLB.zoom.y+\'px)\' }\r\n    function gmOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gmCreateOverlay()\r\n      gmLB.img.src = img.src; gmResetZoom()\r\n      gmLB.dialog.showModal()\r\n      gmLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gmCloseLightbox() {\r\n      if (gmLB.dialog && gmLB.dialog.open) { gmLB.dialog.close(); gmLB.dialog.style.display = \'\'; gmResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Gym Center</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GYM CENTER=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .gm-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .gm-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-title-section .gm-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .gm-title-divider::before,\r\n    .gm-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-title-divider .gm-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .gm-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .gm-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .gm-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .gm-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line::before,\r\n    .gm-gallery-heading .gm-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .gm-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gm-gallery-grid {\r\n        grid-template-columns: 1fr;\r\n        gap: 8px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .gm-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .gm-title-section .gm-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .gm-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"gm-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"gm-title-section\">\r\n    <div class=\"gm-label\">Ruby 68 Hotel</div>\r\n    <h1>Gym Center</h1>\r\n    <div class=\"gm-title-divider\">\r\n      <div class=\"gm-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"gm-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn Ruby 68, Gym Center mang đến kh&ocirc;ng gian luyện tập hiện đại với tầm nh&igrave;n hướng biển Bãi Sau v&agrave; th&agrave;nh phố, ngập tr&agrave;n &aacute;nh s&aacute;ng tự nhi&ecirc;n.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng chỉ l&agrave; nơi r&egrave;n luyện thể lực, mỗi buổi tập tại đ&acirc;y c&ograve;n l&agrave; trải nghiệm thư gi&atilde;n đầy cảm hứng trong kh&ocirc;ng gian rộng r&atilde;i, tinh tế.\r\n    </p>\r\n    <p>\r\n      Trang bị hệ thống m&aacute;y m&oacute;c đạt chuẩn quốc tế, ph&ugrave; hợp từ c&aacute;c b&agrave;i tập nhẹ nh&agrave;ng đến luyện tập chuy&ecirc;n s&acirc;u, gi&uacute;p bạn duy tr&igrave; phong độ v&agrave; c&acirc;n bằng năng lượng trong suốt kỳ nghỉ.\r\n    </p>\r\n    <div class=\"gm-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"gm-gallery-section\">\r\n    <div class=\"gm-gallery-heading\">\r\n      <div class=\"gm-heading-line\">\r\n        <div class=\"gm-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"gm-heading-sub\">Gym Center</div>\r\n      <div class=\"gm-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"gm-gallery-grid\">\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym-2.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gmLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gmGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gmCreateOverlay() {\r\n      if (gmLB.dialog) return\r\n      var pDoc = gmGetParentDoc()\r\n      gmLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gmCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      gmLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gmLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gmCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gmCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gmLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gmLB.zoom.scale < 1) { gmLB.zoom.scale = 1; gmLB.zoom.x = 0; gmLB.zoom.y = 0 }\r\n        if (gmLB.zoom.scale > 5) gmLB.zoom.scale = 5\r\n        gmApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gmResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gmLB.zoom.dragging = true\r\n        gmLB.zoom.startX = e.clientX; gmLB.zoom.startY = e.clientY\r\n        gmLB.zoom.lastX = gmLB.zoom.x; gmLB.zoom.lastY = gmLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gmLB.zoom.dragging) return\r\n        gmLB.zoom.x = gmLB.zoom.lastX + (e.clientX - gmLB.zoom.startX) / gmLB.zoom.scale\r\n        gmLB.zoom.y = gmLB.zoom.lastY + (e.clientY - gmLB.zoom.startY) / gmLB.zoom.scale\r\n        gmApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gmLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gmLB.touches.scale0=gmLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gmLB.zoom.dragging=true; gmLB.zoom.startX=e.touches[0].clientX; gmLB.zoom.startY=e.touches[0].clientY; gmLB.zoom.lastX=gmLB.zoom.x; gmLB.zoom.lastY=gmLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.zoom.scale=gmLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gmLB.touches.dist); if(gmLB.zoom.scale<1)gmLB.zoom.scale=1;if(gmLB.zoom.scale>5)gmLB.zoom.scale=5; gmApplyZoom() }\r\n        else if (e.touches.length===1&&gmLB.zoom.dragging) { e.preventDefault(); gmLB.zoom.x=gmLB.zoom.lastX+(e.touches[0].clientX-gmLB.zoom.startX)/gmLB.zoom.scale; gmLB.zoom.y=gmLB.zoom.lastY+(e.touches[0].clientY-gmLB.zoom.startY)/gmLB.zoom.scale; gmApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gmLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gmCloseLightbox() })\r\n    }\r\n    function gmResetZoom() { gmLB.zoom.scale=1;gmLB.zoom.x=0;gmLB.zoom.y=0; if(gmLB.img)gmLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gmApplyZoom() { if(gmLB.img)gmLB.img.style.transform=\'scale(\'+gmLB.zoom.scale+\') translate(\'+gmLB.zoom.x+\'px,\'+gmLB.zoom.y+\'px)\' }\r\n    function gmOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gmCreateOverlay()\r\n      gmLB.img.src = img.src; gmResetZoom()\r\n      gmLB.dialog.showModal()\r\n      gmLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gmCloseLightbox() {\r\n      if (gmLB.dialog && gmLB.dialog.open) { gmLB.dialog.close(); gmLB.dialog.style.display = \'\'; gmResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:52:40', '2026-03-26 02:52:40');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(109, 'Botble\\Page\\Models\\Page', 22, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Gym Center</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GYM CENTER=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .gm-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .gm-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-title-section .gm-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .gm-title-divider::before,\r\n    .gm-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-title-divider .gm-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .gm-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .gm-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .gm-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .gm-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line::before,\r\n    .gm-gallery-heading .gm-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .gm-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gm-gallery-grid {\r\n        grid-template-columns: 1fr;\r\n        gap: 8px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .gm-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .gm-title-section .gm-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .gm-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"gm-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"gm-title-section\">\r\n    <div class=\"gm-label\">Ruby 68 Hotel</div>\r\n    <h1>Gym Center</h1>\r\n    <div class=\"gm-title-divider\">\r\n      <div class=\"gm-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"gm-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn Ruby 68, Gym Center mang đến kh&ocirc;ng gian luyện tập hiện đại với tầm nh&igrave;n hướng biển Bãi Sau v&agrave; th&agrave;nh phố, ngập tr&agrave;n &aacute;nh s&aacute;ng tự nhi&ecirc;n.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng chỉ l&agrave; nơi r&egrave;n luyện thể lực, mỗi buổi tập tại đ&acirc;y c&ograve;n l&agrave; trải nghiệm thư gi&atilde;n đầy cảm hứng trong kh&ocirc;ng gian rộng r&atilde;i, tinh tế.\r\n    </p>\r\n    <p>\r\n      Trang bị hệ thống m&aacute;y m&oacute;c đạt chuẩn quốc tế, ph&ugrave; hợp từ c&aacute;c b&agrave;i tập nhẹ nh&agrave;ng đến luyện tập chuy&ecirc;n s&acirc;u, gi&uacute;p bạn duy tr&igrave; phong độ v&agrave; c&acirc;n bằng năng lượng trong suốt kỳ nghỉ.\r\n    </p>\r\n    <div class=\"gm-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"gm-gallery-section\">\r\n    <div class=\"gm-gallery-heading\">\r\n      <div class=\"gm-heading-line\">\r\n        <div class=\"gm-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"gm-heading-sub\">Gym Center</div>\r\n      <div class=\"gm-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"gm-gallery-grid\">\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym-2.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gmLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gmGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gmCreateOverlay() {\r\n      if (gmLB.dialog) return\r\n      var pDoc = gmGetParentDoc()\r\n      gmLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gmCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      gmLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gmLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gmCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gmCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gmLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gmLB.zoom.scale < 1) { gmLB.zoom.scale = 1; gmLB.zoom.x = 0; gmLB.zoom.y = 0 }\r\n        if (gmLB.zoom.scale > 5) gmLB.zoom.scale = 5\r\n        gmApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gmResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gmLB.zoom.dragging = true\r\n        gmLB.zoom.startX = e.clientX; gmLB.zoom.startY = e.clientY\r\n        gmLB.zoom.lastX = gmLB.zoom.x; gmLB.zoom.lastY = gmLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gmLB.zoom.dragging) return\r\n        gmLB.zoom.x = gmLB.zoom.lastX + (e.clientX - gmLB.zoom.startX) / gmLB.zoom.scale\r\n        gmLB.zoom.y = gmLB.zoom.lastY + (e.clientY - gmLB.zoom.startY) / gmLB.zoom.scale\r\n        gmApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gmLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gmLB.touches.scale0=gmLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gmLB.zoom.dragging=true; gmLB.zoom.startX=e.touches[0].clientX; gmLB.zoom.startY=e.touches[0].clientY; gmLB.zoom.lastX=gmLB.zoom.x; gmLB.zoom.lastY=gmLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.zoom.scale=gmLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gmLB.touches.dist); if(gmLB.zoom.scale<1)gmLB.zoom.scale=1;if(gmLB.zoom.scale>5)gmLB.zoom.scale=5; gmApplyZoom() }\r\n        else if (e.touches.length===1&&gmLB.zoom.dragging) { e.preventDefault(); gmLB.zoom.x=gmLB.zoom.lastX+(e.touches[0].clientX-gmLB.zoom.startX)/gmLB.zoom.scale; gmLB.zoom.y=gmLB.zoom.lastY+(e.touches[0].clientY-gmLB.zoom.startY)/gmLB.zoom.scale; gmApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gmLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gmCloseLightbox() })\r\n    }\r\n    function gmResetZoom() { gmLB.zoom.scale=1;gmLB.zoom.x=0;gmLB.zoom.y=0; if(gmLB.img)gmLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gmApplyZoom() { if(gmLB.img)gmLB.img.style.transform=\'scale(\'+gmLB.zoom.scale+\') translate(\'+gmLB.zoom.x+\'px,\'+gmLB.zoom.y+\'px)\' }\r\n    function gmOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gmCreateOverlay()\r\n      gmLB.img.src = img.src; gmResetZoom()\r\n      gmLB.dialog.showModal()\r\n      gmLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gmCloseLightbox() {\r\n      if (gmLB.dialog && gmLB.dialog.open) { gmLB.dialog.close(); gmLB.dialog.style.display = \'\'; gmResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Gym Center</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GYM CENTER=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .gm-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .gm-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-title-section .gm-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .gm-title-divider::before,\r\n    .gm-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-title-divider .gm-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .gm-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .gm-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .gm-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .gm-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line::before,\r\n    .gm-gallery-heading .gm-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .gm-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gm-gallery-grid {\r\n        grid-template-columns: 1fr;\r\n        gap: 8px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .gm-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .gm-title-section .gm-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .gm-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"gm-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"gm-title-section\">\r\n    <div class=\"gm-label\">Ruby 68 Hotel</div>\r\n    <h1>Gym Center</h1>\r\n    <div class=\"gm-title-divider\">\r\n      <div class=\"gm-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"gm-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn Ruby 68, Gym Center mang đến kh&ocirc;ng gian luyện tập hiện đại với tầm nh&igrave;n hướng biển Bãi Sau v&agrave; th&agrave;nh phố, ngập tr&agrave;n &aacute;nh s&aacute;ng tự nhi&ecirc;n.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng chỉ l&agrave; nơi r&egrave;n luyện thể lực, mỗi buổi tập tại đ&acirc;y c&ograve;n l&agrave; trải nghiệm thư gi&atilde;n đầy cảm hứng trong kh&ocirc;ng gian rộng r&atilde;i, tinh tế.\r\n    </p>\r\n    <p>\r\n      Trang bị hệ thống m&aacute;y m&oacute;c đạt chuẩn quốc tế, ph&ugrave; hợp từ c&aacute;c b&agrave;i tập nhẹ nh&agrave;ng đến luyện tập chuy&ecirc;n s&acirc;u, gi&uacute;p bạn duy tr&igrave; phong độ v&agrave; c&acirc;n bằng năng lượng trong suốt kỳ nghỉ.\r\n    </p>\r\n    <div class=\"gm-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"gm-gallery-section\">\r\n    <div class=\"gm-gallery-heading\">\r\n      <div class=\"gm-heading-line\">\r\n        <div class=\"gm-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"gm-heading-sub\">Gym Center</div>\r\n      <div class=\"gm-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"gm-gallery-grid\">\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym-2.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Gym Center\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gmLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gmGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gmCreateOverlay() {\r\n      if (gmLB.dialog) return\r\n      var pDoc = gmGetParentDoc()\r\n      gmLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gmCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      gmLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gmLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gmCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gmCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gmLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gmLB.zoom.scale < 1) { gmLB.zoom.scale = 1; gmLB.zoom.x = 0; gmLB.zoom.y = 0 }\r\n        if (gmLB.zoom.scale > 5) gmLB.zoom.scale = 5\r\n        gmApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gmResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gmLB.zoom.dragging = true\r\n        gmLB.zoom.startX = e.clientX; gmLB.zoom.startY = e.clientY\r\n        gmLB.zoom.lastX = gmLB.zoom.x; gmLB.zoom.lastY = gmLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gmLB.zoom.dragging) return\r\n        gmLB.zoom.x = gmLB.zoom.lastX + (e.clientX - gmLB.zoom.startX) / gmLB.zoom.scale\r\n        gmLB.zoom.y = gmLB.zoom.lastY + (e.clientY - gmLB.zoom.startY) / gmLB.zoom.scale\r\n        gmApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gmLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gmLB.touches.scale0=gmLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gmLB.zoom.dragging=true; gmLB.zoom.startX=e.touches[0].clientX; gmLB.zoom.startY=e.touches[0].clientY; gmLB.zoom.lastX=gmLB.zoom.x; gmLB.zoom.lastY=gmLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.zoom.scale=gmLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gmLB.touches.dist); if(gmLB.zoom.scale<1)gmLB.zoom.scale=1;if(gmLB.zoom.scale>5)gmLB.zoom.scale=5; gmApplyZoom() }\r\n        else if (e.touches.length===1&&gmLB.zoom.dragging) { e.preventDefault(); gmLB.zoom.x=gmLB.zoom.lastX+(e.touches[0].clientX-gmLB.zoom.startX)/gmLB.zoom.scale; gmLB.zoom.y=gmLB.zoom.lastY+(e.touches[0].clientY-gmLB.zoom.startY)/gmLB.zoom.scale; gmApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gmLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gmCloseLightbox() })\r\n    }\r\n    function gmResetZoom() { gmLB.zoom.scale=1;gmLB.zoom.x=0;gmLB.zoom.y=0; if(gmLB.img)gmLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gmApplyZoom() { if(gmLB.img)gmLB.img.style.transform=\'scale(\'+gmLB.zoom.scale+\') translate(\'+gmLB.zoom.x+\'px,\'+gmLB.zoom.y+\'px)\' }\r\n    function gmOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gmCreateOverlay()\r\n      gmLB.img.src = img.src; gmResetZoom()\r\n      gmLB.dialog.showModal()\r\n      gmLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gmCloseLightbox() {\r\n      if (gmLB.dialog && gmLB.dialog.open) { gmLB.dialog.close(); gmLB.dialog.style.display = \'\'; gmResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:55:38', '2026-03-26 02:55:38');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(110, 'Botble\\Page\\Models\\Page', 22, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Gym Center</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GYM CENTER=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .gm-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .gm-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-title-section .gm-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .gm-title-divider::before,\r\n    .gm-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-title-divider .gm-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .gm-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .gm-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .gm-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .gm-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line::before,\r\n    .gm-gallery-heading .gm-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(2, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .gm-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gm-gallery-grid {\r\n        grid-template-columns: 1fr;\r\n        gap: 8px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .gm-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .gm-title-section .gm-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .gm-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"gm-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"gm-title-section\">\r\n    <div class=\"gm-label\">Ruby 68 Hotel</div>\r\n    <h1>Gym Center</h1>\r\n    <div class=\"gm-title-divider\">\r\n      <div class=\"gm-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"gm-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn Ruby 68, Gym Center mang đến kh&ocirc;ng gian luyện tập hiện đại với tầm nh&igrave;n hướng biển Bãi Sau v&agrave; th&agrave;nh phố, ngập tr&agrave;n &aacute;nh s&aacute;ng tự nhi&ecirc;n.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng chỉ l&agrave; nơi r&egrave;n luyện thể lực, mỗi buổi tập tại đ&acirc;y c&ograve;n l&agrave; trải nghiệm thư gi&atilde;n đầy cảm hứng trong kh&ocirc;ng gian rộng r&atilde;i, tinh tế.\r\n    </p>\r\n    <p>\r\n      Trang bị hệ thống m&aacute;y m&oacute;c đạt chuẩn quốc tế, ph&ugrave; hợp từ c&aacute;c b&agrave;i tập nhẹ nh&agrave;ng đến luyện tập chuy&ecirc;n s&acirc;u, gi&uacute;p bạn duy tr&igrave; phong độ v&agrave; c&acirc;n bằng năng lượng trong suốt kỳ nghỉ.\r\n    </p>\r\n    <div class=\"gm-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"gm-gallery-section\">\r\n    <div class=\"gm-gallery-heading\">\r\n      <div class=\"gm-heading-line\">\r\n        <div class=\"gm-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"gm-heading-sub\">Gym Center</div>\r\n      <div class=\"gm-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"gm-gallery-grid\">\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym-2.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Gym Center\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gmLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gmGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gmCreateOverlay() {\r\n      if (gmLB.dialog) return\r\n      var pDoc = gmGetParentDoc()\r\n      gmLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gmCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      gmLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gmLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gmCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gmCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gmLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gmLB.zoom.scale < 1) { gmLB.zoom.scale = 1; gmLB.zoom.x = 0; gmLB.zoom.y = 0 }\r\n        if (gmLB.zoom.scale > 5) gmLB.zoom.scale = 5\r\n        gmApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gmResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gmLB.zoom.dragging = true\r\n        gmLB.zoom.startX = e.clientX; gmLB.zoom.startY = e.clientY\r\n        gmLB.zoom.lastX = gmLB.zoom.x; gmLB.zoom.lastY = gmLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gmLB.zoom.dragging) return\r\n        gmLB.zoom.x = gmLB.zoom.lastX + (e.clientX - gmLB.zoom.startX) / gmLB.zoom.scale\r\n        gmLB.zoom.y = gmLB.zoom.lastY + (e.clientY - gmLB.zoom.startY) / gmLB.zoom.scale\r\n        gmApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gmLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gmLB.touches.scale0=gmLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gmLB.zoom.dragging=true; gmLB.zoom.startX=e.touches[0].clientX; gmLB.zoom.startY=e.touches[0].clientY; gmLB.zoom.lastX=gmLB.zoom.x; gmLB.zoom.lastY=gmLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.zoom.scale=gmLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gmLB.touches.dist); if(gmLB.zoom.scale<1)gmLB.zoom.scale=1;if(gmLB.zoom.scale>5)gmLB.zoom.scale=5; gmApplyZoom() }\r\n        else if (e.touches.length===1&&gmLB.zoom.dragging) { e.preventDefault(); gmLB.zoom.x=gmLB.zoom.lastX+(e.touches[0].clientX-gmLB.zoom.startX)/gmLB.zoom.scale; gmLB.zoom.y=gmLB.zoom.lastY+(e.touches[0].clientY-gmLB.zoom.startY)/gmLB.zoom.scale; gmApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gmLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gmCloseLightbox() })\r\n    }\r\n    function gmResetZoom() { gmLB.zoom.scale=1;gmLB.zoom.x=0;gmLB.zoom.y=0; if(gmLB.img)gmLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gmApplyZoom() { if(gmLB.img)gmLB.img.style.transform=\'scale(\'+gmLB.zoom.scale+\') translate(\'+gmLB.zoom.x+\'px,\'+gmLB.zoom.y+\'px)\' }\r\n    function gmOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gmCreateOverlay()\r\n      gmLB.img.src = img.src; gmResetZoom()\r\n      gmLB.dialog.showModal()\r\n      gmLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gmCloseLightbox() {\r\n      if (gmLB.dialog && gmLB.dialog.open) { gmLB.dialog.close(); gmLB.dialog.style.display = \'\'; gmResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Gym Center</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====GYM CENTER=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .gm-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .gm-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-title-section .gm-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .gm-title-divider::before,\r\n    .gm-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-title-divider .gm-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .gm-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .gm-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .gm-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .gm-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .gm-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-line::before,\r\n    .gm-gallery-heading .gm-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .gm-gallery-heading .gm-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .gm-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .gm-gallery-grid .gm-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .gm-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .gm-gallery-grid {\r\n        grid-template-columns: 1fr;\r\n        gap: 8px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .gm-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .gm-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .gm-title-section .gm-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .gm-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .gm-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .gm-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .gm-gallery-heading .gm-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"gm-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"gm-title-section\">\r\n    <div class=\"gm-label\">Ruby 68 Hotel</div>\r\n    <h1>Gym Center</h1>\r\n    <div class=\"gm-title-divider\">\r\n      <div class=\"gm-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"gm-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 kh&aacute;ch sạn Ruby 68, Gym Center mang đến kh&ocirc;ng gian luyện tập hiện đại với tầm nh&igrave;n hướng biển Bãi Sau v&agrave; th&agrave;nh phố, ngập tr&agrave;n &aacute;nh s&aacute;ng tự nhi&ecirc;n.\r\n    </p>\r\n    <p>\r\n      Kh&ocirc;ng chỉ l&agrave; nơi r&egrave;n luyện thể lực, mỗi buổi tập tại đ&acirc;y c&ograve;n l&agrave; trải nghiệm thư gi&atilde;n đầy cảm hứng trong kh&ocirc;ng gian rộng r&atilde;i, tinh tế.\r\n    </p>\r\n    <p>\r\n      Trang bị hệ thống m&aacute;y m&oacute;c đạt chuẩn quốc tế, ph&ugrave; hợp từ c&aacute;c b&agrave;i tập nhẹ nh&agrave;ng đến luyện tập chuy&ecirc;n s&acirc;u, gi&uacute;p bạn duy tr&igrave; phong độ v&agrave; c&acirc;n bằng năng lượng trong suốt kỳ nghỉ.\r\n    </p>\r\n    <div class=\"gm-time\">Mở cửa h&agrave;ng ng&agrave;y từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"gm-gallery-section\">\r\n    <div class=\"gm-gallery-heading\">\r\n      <div class=\"gm-heading-line\">\r\n        <div class=\"gm-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"gm-heading-sub\">Gym Center</div>\r\n      <div class=\"gm-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"gm-gallery-grid\">\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/gym/gym-2.jpg\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/13.png\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/14.png\" alt=\"Gym Center\"></div>\r\n      <div class=\"gm-photo\" onclick=\"gmOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/spa/15.png\" alt=\"Gym Center\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var gmLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function gmGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function gmCreateOverlay() {\r\n      if (gmLB.dialog) return\r\n      var pDoc = gmGetParentDoc()\r\n      gmLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { gmCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      gmLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      gmLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) gmCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); gmCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        gmLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (gmLB.zoom.scale < 1) { gmLB.zoom.scale = 1; gmLB.zoom.x = 0; gmLB.zoom.y = 0 }\r\n        if (gmLB.zoom.scale > 5) gmLB.zoom.scale = 5\r\n        gmApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); gmResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); gmLB.zoom.dragging = true\r\n        gmLB.zoom.startX = e.clientX; gmLB.zoom.startY = e.clientY\r\n        gmLB.zoom.lastX = gmLB.zoom.x; gmLB.zoom.lastY = gmLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!gmLB.zoom.dragging) return\r\n        gmLB.zoom.x = gmLB.zoom.lastX + (e.clientX - gmLB.zoom.startX) / gmLB.zoom.scale\r\n        gmLB.zoom.y = gmLB.zoom.lastY + (e.clientY - gmLB.zoom.startY) / gmLB.zoom.scale\r\n        gmApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { gmLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.touches.dist=Math.sqrt(dx*dx+dy*dy); gmLB.touches.scale0=gmLB.zoom.scale }\r\n        else if (e.touches.length === 1) { gmLB.zoom.dragging=true; gmLB.zoom.startX=e.touches[0].clientX; gmLB.zoom.startY=e.touches[0].clientY; gmLB.zoom.lastX=gmLB.zoom.x; gmLB.zoom.lastY=gmLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; gmLB.zoom.scale=gmLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/gmLB.touches.dist); if(gmLB.zoom.scale<1)gmLB.zoom.scale=1;if(gmLB.zoom.scale>5)gmLB.zoom.scale=5; gmApplyZoom() }\r\n        else if (e.touches.length===1&&gmLB.zoom.dragging) { e.preventDefault(); gmLB.zoom.x=gmLB.zoom.lastX+(e.touches[0].clientX-gmLB.zoom.startX)/gmLB.zoom.scale; gmLB.zoom.y=gmLB.zoom.lastY+(e.touches[0].clientY-gmLB.zoom.startY)/gmLB.zoom.scale; gmApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { gmLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') gmCloseLightbox() })\r\n    }\r\n    function gmResetZoom() { gmLB.zoom.scale=1;gmLB.zoom.x=0;gmLB.zoom.y=0; if(gmLB.img)gmLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function gmApplyZoom() { if(gmLB.img)gmLB.img.style.transform=\'scale(\'+gmLB.zoom.scale+\') translate(\'+gmLB.zoom.x+\'px,\'+gmLB.zoom.y+\'px)\' }\r\n    function gmOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      gmCreateOverlay()\r\n      gmLB.img.src = img.src; gmResetZoom()\r\n      gmLB.dialog.showModal()\r\n      gmLB.dialog.style.display = \'flex\'\r\n    }\r\n    function gmCloseLightbox() {\r\n      if (gmLB.dialog && gmLB.dialog.open) { gmLB.dialog.close(); gmLB.dialog.style.display = \'\'; gmResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 02:56:27', '2026-03-26 02:56:27'),
(111, 'Botble\\Page\\Models\\Page', 24, 1, 'content_mode', 'blocks', 'html', '2026-03-26 03:04:46', '2026-03-26 03:04:46');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(112, 'Botble\\Page\\Models\\Page', 19, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Infinity Pool & Ruby Ocean Bar</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====INFINITY POOL & RUBY OCEAN BAR=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .pl-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/4.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .pl-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-title-section .pl-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .pl-title-divider::before,\r\n    .pl-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-title-divider .pl-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .pl-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .pl-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .pl-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .pl-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line::before,\r\n    .pl-gallery-heading .pl-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .pl-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .pl-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .pl-title-section .pl-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .pl-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"pl-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"pl-title-section\">\r\n    <div class=\"pl-label\">Ruby 68 Hotel</div>\r\n    <h1>Infinity Pool & Ruby Ocean Bar</h1>\r\n    <div class=\"pl-title-divider\">\r\n      <div class=\"pl-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"pl-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7 khách sạn Ruby 68, hồ bơi vô cực gây ấn tượng với thiết kế kính trong suốt độc đáo, mở ra tầm nhìn toàn cảnh biển Bãi Sau Vũng Tàu đầy ngoạn mục. Thả mình trong làn nước xanh mát, tận hưởng ánh nắng ấm áp và nhâm nhi cocktail tại Ruby Ocean Bar, đây là trải nghiệm thư giãn không thể bỏ lỡ khi lưu trú tại khách sạn.\r\n    </p>\r\n    <p>\r\n      Được xem là một trong những hồ bơi vô cực đẹp nhất Vũng Tàu, nơi đây mang đến khoảnh khắc nghỉ dưỡng đẳng cấp giữa biển trời bao la.\r\n    </p>\r\n    <div class=\"pl-time\">Mở cửa hàng ngày từ 9:00 đến 19:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"pl-gallery-section\">\r\n    <div class=\"pl-gallery-heading\">\r\n      <div class=\"pl-heading-line\">\r\n        <div class=\"pl-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"pl-heading-sub\">Infinity Pool</div>\r\n      <div class=\"pl-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"pl-gallery-grid\">\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/4.png\" alt=\"Infinity Pool\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/1.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/2.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/3.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/4.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/5.png\" alt=\"Ruby Ocean Bar\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var plLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function plGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function plCreateOverlay() {\r\n      if (plLB.dialog) return\r\n      var pDoc = plGetParentDoc()\r\n      plLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { plCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      plLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      plLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) plCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); plCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        plLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (plLB.zoom.scale < 1) { plLB.zoom.scale = 1; plLB.zoom.x = 0; plLB.zoom.y = 0 }\r\n        if (plLB.zoom.scale > 5) plLB.zoom.scale = 5\r\n        plApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); plResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); plLB.zoom.dragging = true\r\n        plLB.zoom.startX = e.clientX; plLB.zoom.startY = e.clientY\r\n        plLB.zoom.lastX = plLB.zoom.x; plLB.zoom.lastY = plLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!plLB.zoom.dragging) return\r\n        plLB.zoom.x = plLB.zoom.lastX + (e.clientX - plLB.zoom.startX) / plLB.zoom.scale\r\n        plLB.zoom.y = plLB.zoom.lastY + (e.clientY - plLB.zoom.startY) / plLB.zoom.scale\r\n        plApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { plLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.touches.dist=Math.sqrt(dx*dx+dy*dy); plLB.touches.scale0=plLB.zoom.scale }\r\n        else if (e.touches.length === 1) { plLB.zoom.dragging=true; plLB.zoom.startX=e.touches[0].clientX; plLB.zoom.startY=e.touches[0].clientY; plLB.zoom.lastX=plLB.zoom.x; plLB.zoom.lastY=plLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.zoom.scale=plLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/plLB.touches.dist); if(plLB.zoom.scale<1)plLB.zoom.scale=1;if(plLB.zoom.scale>5)plLB.zoom.scale=5; plApplyZoom() }\r\n        else if (e.touches.length===1&&plLB.zoom.dragging) { e.preventDefault(); plLB.zoom.x=plLB.zoom.lastX+(e.touches[0].clientX-plLB.zoom.startX)/plLB.zoom.scale; plLB.zoom.y=plLB.zoom.lastY+(e.touches[0].clientY-plLB.zoom.startY)/plLB.zoom.scale; plApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { plLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') plCloseLightbox() })\r\n    }\r\n    function plResetZoom() { plLB.zoom.scale=1;plLB.zoom.x=0;plLB.zoom.y=0; if(plLB.img)plLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function plApplyZoom() { if(plLB.img)plLB.img.style.transform=\'scale(\'+plLB.zoom.scale+\') translate(\'+plLB.zoom.x+\'px,\'+plLB.zoom.y+\'px)\' }\r\n    function plOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      plCreateOverlay()\r\n      plLB.img.src = img.src; plResetZoom()\r\n      plLB.dialog.showModal()\r\n      plLB.dialog.style.display = \'flex\'\r\n    }\r\n    function plCloseLightbox() {\r\n      if (plLB.dialog && plLB.dialog.open) { plLB.dialog.close(); plLB.dialog.style.display = \'\'; plResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Infinity Pool &amp; Ruby Ocean Bar</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====INFINITY POOL & RUBY OCEAN BAR=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .pl-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/4.png\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .pl-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-title-section .pl-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .pl-title-divider::before,\r\n    .pl-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-title-divider .pl-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .pl-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .pl-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .pl-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .pl-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .pl-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-line::before,\r\n    .pl-gallery-heading .pl-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .pl-gallery-heading .pl-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .pl-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .pl-gallery-grid .pl-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .pl-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .pl-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .pl-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .pl-title-section .pl-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .pl-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .pl-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .pl-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .pl-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .pl-gallery-heading .pl-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"pl-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"pl-title-section\">\r\n    <div class=\"pl-label\">Ruby 68 Hotel</div>\r\n    <h1>Infinity Pool &amp; Ruby Ocean Bar</h1>\r\n    <div class=\"pl-title-divider\">\r\n      <div class=\"pl-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"pl-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 7 kh&aacute;ch sạn Ruby 68, hồ bơi v&ocirc; cực g&acirc;y ấn tượng với thiết kế k&iacute;nh trong suốt độc đ&aacute;o, mở ra tầm nh&igrave;n to&agrave;n cảnh biển Bãi Sau Vũng Tàu đầy ngoạn mục. Thả m&igrave;nh trong l&agrave;n nước xanh m&aacute;t, tận hưởng &aacute;nh nắng ấm &aacute;p v&agrave; nh&acirc;m nhi cocktail tại Ruby Ocean Bar, đ&acirc;y l&agrave; trải nghiệm thư gi&atilde;n kh&ocirc;ng thể bỏ lỡ khi lưu tr&uacute; tại kh&aacute;ch sạn.\r\n    </p>\r\n    <p>\r\n      Được xem l&agrave; một trong những hồ bơi v&ocirc; cực đẹp nhất Vũng Tàu, nơi đ&acirc;y mang đến khoảnh khắc nghỉ dưỡng đẳng cấp giữa biển trời bao la.\r\n    </p>\r\n    <div class=\"pl-time\">Mở cửa h&agrave;ng ng&agrave;y từ 9:00 đến 19:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"pl-gallery-section\">\r\n    <div class=\"pl-gallery-heading\">\r\n      <div class=\"pl-heading-line\">\r\n        <div class=\"pl-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"pl-heading-sub\">Infinity Pool</div>\r\n      <div class=\"pl-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"pl-gallery-grid\">\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/4.png\" alt=\"Infinity Pool\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/1.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/2.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/3.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/4.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/5.png\" alt=\"Ruby Ocean Bar\"></div>\r\n      <div class=\"pl-photo\" onclick=\"plOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/dinning/blue-ocean-bar/boton-blue-hotel-spa.jpg\" alt=\"Ruby Ocean Bar\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var plLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function plGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function plCreateOverlay() {\r\n      if (plLB.dialog) return\r\n      var pDoc = plGetParentDoc()\r\n      plLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { plCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      plLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      plLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) plCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); plCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        plLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (plLB.zoom.scale < 1) { plLB.zoom.scale = 1; plLB.zoom.x = 0; plLB.zoom.y = 0 }\r\n        if (plLB.zoom.scale > 5) plLB.zoom.scale = 5\r\n        plApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); plResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); plLB.zoom.dragging = true\r\n        plLB.zoom.startX = e.clientX; plLB.zoom.startY = e.clientY\r\n        plLB.zoom.lastX = plLB.zoom.x; plLB.zoom.lastY = plLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!plLB.zoom.dragging) return\r\n        plLB.zoom.x = plLB.zoom.lastX + (e.clientX - plLB.zoom.startX) / plLB.zoom.scale\r\n        plLB.zoom.y = plLB.zoom.lastY + (e.clientY - plLB.zoom.startY) / plLB.zoom.scale\r\n        plApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { plLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.touches.dist=Math.sqrt(dx*dx+dy*dy); plLB.touches.scale0=plLB.zoom.scale }\r\n        else if (e.touches.length === 1) { plLB.zoom.dragging=true; plLB.zoom.startX=e.touches[0].clientX; plLB.zoom.startY=e.touches[0].clientY; plLB.zoom.lastX=plLB.zoom.x; plLB.zoom.lastY=plLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; plLB.zoom.scale=plLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/plLB.touches.dist); if(plLB.zoom.scale<1)plLB.zoom.scale=1;if(plLB.zoom.scale>5)plLB.zoom.scale=5; plApplyZoom() }\r\n        else if (e.touches.length===1&&plLB.zoom.dragging) { e.preventDefault(); plLB.zoom.x=plLB.zoom.lastX+(e.touches[0].clientX-plLB.zoom.startX)/plLB.zoom.scale; plLB.zoom.y=plLB.zoom.lastY+(e.touches[0].clientY-plLB.zoom.startY)/plLB.zoom.scale; plApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { plLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') plCloseLightbox() })\r\n    }\r\n    function plResetZoom() { plLB.zoom.scale=1;plLB.zoom.x=0;plLB.zoom.y=0; if(plLB.img)plLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function plApplyZoom() { if(plLB.img)plLB.img.style.transform=\'scale(\'+plLB.zoom.scale+\') translate(\'+plLB.zoom.x+\'px,\'+plLB.zoom.y+\'px)\' }\r\n    function plOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      plCreateOverlay()\r\n      plLB.img.src = img.src; plResetZoom()\r\n      plLB.dialog.showModal()\r\n      plLB.dialog.style.display = \'flex\'\r\n    }\r\n    function plCloseLightbox() {\r\n      if (plLB.dialog && plLB.dialog.open) { plLB.dialog.close(); plLB.dialog.style.display = \'\'; plResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 03:04:58', '2026-03-26 03:04:58'),
(113, 'Botble\\Page\\Models\\Page', 24, 1, 'custom_html', NULL, '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>B&atilde;i biển Ruby 68</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====BÃI BIỂN RUBY 68=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .bb-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/203fcacc.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .bb-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .bb-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .bb-title-section .bb-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .bb-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .bb-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .bb-title-divider::before,\r\n    .bb-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .bb-title-divider .bb-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .bb-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .bb-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .bb-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .bb-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-line::before,\r\n    .bb-gallery-heading .bb-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .bb-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .bb-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .bb-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .bb-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .bb-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .bb-gallery-heading .bb-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .bb-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .bb-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .bb-title-section .bb-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .bb-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .bb-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .bb-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .bb-gallery-heading .bb-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"bb-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"bb-title-section\">\r\n    <div class=\"bb-label\">Ruby 68 Hotel</div>\r\n    <h1>B&atilde;i biển Ruby 68</h1>\r\n    <div class=\"bb-title-divider\">\r\n      <div class=\"bb-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"bb-content\">\r\n    <p>\r\n      Tận hưởng trọn vẹn kỳ nghỉ b&ecirc;n l&agrave;n nước xanh thẳm v&agrave; b&atilde;i c&aacute;t trắng mịn tại khu vực b&atilde;i biển ri&ecirc;ng mang t&ecirc;n Ruby 68.\r\n    </p>\r\n    <p>\r\n      Dưới &aacute;nh nắng nhiệt đới dịu nhẹ, mọi khoảnh khắc thư gi&atilde;n trở n&ecirc;n trọn vẹn hơn với ghế tắm nắng, d&ugrave; che v&agrave; khăn tắm lu&ocirc;n sẵn s&agrave;ng phục vụ.\r\n    </p>\r\n    <p>\r\n      Đ&acirc;y l&agrave; kh&ocirc;ng gian l&yacute; tưởng để thả m&igrave;nh v&agrave;o thi&ecirc;n nhi&ecirc;n, tận hưởng vẻ đẹp biển Vũng Tàu theo c&aacute;ch ri&ecirc;ng đầy tinh tế v&agrave; thư th&aacute;i.\r\n    </p>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"bb-gallery-section\">\r\n    <div class=\"bb-gallery-heading\">\r\n      <div class=\"bb-heading-line\">\r\n        <div class=\"bb-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"bb-heading-sub\">Ruby 68 Beach</div>\r\n      <div class=\"bb-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"bb-gallery-grid\">\r\n      <div class=\"bb-photo\" onclick=\"bbOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/203fcacc.jpg\" alt=\"B&atilde;i biển Ruby 68\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var bbLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function bbGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function bbCreateOverlay() {\r\n      if (bbLB.dialog) return\r\n      var pDoc = bbGetParentDoc()\r\n      bbLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { bbCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      bbLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      bbLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) bbCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); bbCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        bbLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (bbLB.zoom.scale < 1) { bbLB.zoom.scale = 1; bbLB.zoom.x = 0; bbLB.zoom.y = 0 }\r\n        if (bbLB.zoom.scale > 5) bbLB.zoom.scale = 5\r\n        bbApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); bbResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); bbLB.zoom.dragging = true\r\n        bbLB.zoom.startX = e.clientX; bbLB.zoom.startY = e.clientY\r\n        bbLB.zoom.lastX = bbLB.zoom.x; bbLB.zoom.lastY = bbLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!bbLB.zoom.dragging) return\r\n        bbLB.zoom.x = bbLB.zoom.lastX + (e.clientX - bbLB.zoom.startX) / bbLB.zoom.scale\r\n        bbLB.zoom.y = bbLB.zoom.lastY + (e.clientY - bbLB.zoom.startY) / bbLB.zoom.scale\r\n        bbApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { bbLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; bbLB.touches.dist=Math.sqrt(dx*dx+dy*dy); bbLB.touches.scale0=bbLB.zoom.scale }\r\n        else if (e.touches.length === 1) { bbLB.zoom.dragging=true; bbLB.zoom.startX=e.touches[0].clientX; bbLB.zoom.startY=e.touches[0].clientY; bbLB.zoom.lastX=bbLB.zoom.x; bbLB.zoom.lastY=bbLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; bbLB.zoom.scale=bbLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/bbLB.touches.dist); if(bbLB.zoom.scale<1)bbLB.zoom.scale=1;if(bbLB.zoom.scale>5)bbLB.zoom.scale=5; bbApplyZoom() }\r\n        else if (e.touches.length===1&&bbLB.zoom.dragging) { e.preventDefault(); bbLB.zoom.x=bbLB.zoom.lastX+(e.touches[0].clientX-bbLB.zoom.startX)/bbLB.zoom.scale; bbLB.zoom.y=bbLB.zoom.lastY+(e.touches[0].clientY-bbLB.zoom.startY)/bbLB.zoom.scale; bbApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { bbLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') bbCloseLightbox() })\r\n    }\r\n    function bbResetZoom() { bbLB.zoom.scale=1;bbLB.zoom.x=0;bbLB.zoom.y=0; if(bbLB.img)bbLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function bbApplyZoom() { if(bbLB.img)bbLB.img.style.transform=\'scale(\'+bbLB.zoom.scale+\') translate(\'+bbLB.zoom.x+\'px,\'+bbLB.zoom.y+\'px)\' }\r\n    function bbOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      bbCreateOverlay()\r\n      bbLB.img.src = img.src; bbResetZoom()\r\n      bbLB.dialog.showModal()\r\n      bbLB.dialog.style.display = \'flex\'\r\n    }\r\n    function bbCloseLightbox() {\r\n      if (bbLB.dialog && bbLB.dialog.open) { bbLB.dialog.close(); bbLB.dialog.style.display = \'\'; bbResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-26 03:08:58', '2026-03-26 03:08:58'),
