INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(140, 'Botble\\Page\\Models\\Page', 25, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Sky Lounge</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SKY LOUNGE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #0b0b0b;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      color: #ccc;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .ts-hero {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      background: #0b0b0b;\r\n      display: grid;\r\n      grid-template-columns: 1fr 28%;\r\n      grid-template-rows: auto auto;\r\n      padding: 150px 50px 50px;\r\n      gap: 0 16px;\r\n    }\r\n\r\n    /* Welcome text row */\r\n    .ts-hero-welcome {\r\n      grid-column: 1 / -1;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 14px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 10px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-hero-welcome::before {\r\n      content: \'\';\r\n      width: 40px;\r\n      height: 1px;\r\n      background: #c9a84c;\r\n    }\r\n\r\n    /* Main area: h1 + image overlap */\r\n    .ts-hero-main {\r\n      grid-column: 1 / 2;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-hero h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: clamp(60px, 9vw, 130px);\r\n      font-weight: 200;\r\n      color: #fff;\r\n      line-height: 0.95;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      position: relative;\r\n      z-index: 2;\r\n    }\r\n\r\n    .ts-hero-img1 {\r\n      overflow: hidden;\r\n      margin-top: 2vw;\r\n      position: relative;\r\n      z-index: 1;\r\n      max-height: 500px;\r\n    }\r\n\r\n    .ts-hero-img1 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    /* Right: image + desc + tags */\r\n    .ts-hero-right {\r\n      grid-column: 2 / 3;\r\n      grid-row: 2 / 3;\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .ts-hero-img2 {\r\n      overflow: hidden;\r\n      aspect-ratio: 16 / 9;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-hero-img2 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-hero-desc {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #888;\r\n      margin-bottom: 20px;\r\n      border-top: 1px solid #2a2a2a;\r\n      padding-top: 20px;\r\n    }\r\n\r\n    .ts-hero-tags {\r\n      display: flex;\r\n      gap: 20px;\r\n      margin-top: auto;\r\n    }\r\n\r\n    .ts-hero-tags span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 12px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #555;\r\n    }\r\n\r\n    /*--Sec2: About--*/\r\n    .ts-about {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 70px 50px 60px;\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 40px;\r\n      align-items: center;\r\n    }\r\n\r\n    .ts-about-images {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 10px;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img {\r\n      overflow: hidden;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:first-child {\r\n      grid-row: 1 / 3;\r\n      aspect-ratio: 9 / 16;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(2) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(3) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-about-text .ts-section-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .ts-about-text .ts-section-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 65px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.2;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-about-text p {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 18px;\r\n      line-height: 2;\r\n      color: #999;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    /*--Sec3: Photo Gallery--*/\r\n    .ts-gallery-section {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 0 50px 60px;\r\n      background: #0b0b0b;\r\n    }\r\n\r\n    .ts-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 70px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.3;\r\n      margin-bottom: 10px;\r\n    }\r\n\r\n    .ts-gallery-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-gallery-divider::before,\r\n    .ts-gallery-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 60px;\r\n      background: linear-gradient(to right, transparent, rgba(201, 168, 76, 0.5), transparent);\r\n    }\r\n\r\n    .ts-gallery-divider .ts-gallery-diamond {\r\n      width: 8px;\r\n      height: 8px;\r\n      background: #c9a84c;\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .ts-gallery-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 5px;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo::after {\r\n      content: \'\';\r\n      position: absolute;\r\n      inset: 0;\r\n      background: rgba(0, 0, 0, 0.3);\r\n      transition: background .4s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover::after {\r\n      background: rgba(0, 0, 0, 0);\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .5s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover img {\r\n      transform: scale(1.1);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 960px) {\r\n      .ts-hero {\r\n        grid-template-columns: 1fr;\r\n        padding: 130px 30px 40px;\r\n      }\r\n\r\n      .ts-hero-right {\r\n        display: none;\r\n      }\r\n\r\n      .ts-hero-main {\r\n        grid-column: 1;\r\n      }\r\n\r\n      .ts-about {\r\n        grid-template-columns: 1fr;\r\n        padding: 50px 30px 40px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 30px 60px;\r\n      }\r\n\r\n      .ts-about-images {\r\n        max-width: 500px;\r\n        margin: 0 auto;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .ts-hero {\r\n        padding: 120px 20px 30px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 20px 30px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 20px 50px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 28px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 14px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 4px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 28px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .ts-hero-text {\r\n        padding: 30px 15px 15px;\r\n      }\r\n\r\n      .ts-hero-welcome {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 15px 30px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 24px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 13px;\r\n        line-height: 1.8;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 3px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 24px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"ts-hero\">\r\n    <div class=\"ts-hero-welcome\">Welcome to</div>\r\n    <div class=\"ts-hero-main\">\r\n      <h1>Ruby Sky Lounge</h1>\r\n      <div class=\"ts-hero-img1\">\r\n        <img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/8.jpg\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-hero-right\">\r\n      <div class=\"ts-hero-img2\">\r\n        <img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/10.jpg\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n      <div class=\"ts-hero-desc\">\r\n        Trải nghiệm giải tr&iacute; đẳng cấp tr&ecirc;n tầng cao nhất, nơi bầu trời h&ograve;a v&agrave;o biển cả c&ugrave;ng &acirc;m nhạc v&agrave; cocktail.\r\n      </div>\r\n      <div class=\"ts-hero-tags\">\r\n        <span>Rooftop</span>\r\n        <span>Cocktails</span>\r\n        <span>Live Music</span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec2: About -->\r\n  <div class=\"ts-about\">\r\n    <div class=\"ts-about-images\">\r\n      <div class=\"ts-about-img\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/4.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/15.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/20.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n    </div>\r\n    <div class=\"ts-about-text\">\r\n      <div class=\"ts-section-label\">About</div>\r\n      <div class=\"ts-section-title\">Where the Sky Meets the Sea</div>\r\n      <p>\r\n        Tọa lạc tr&ecirc;n tầng cao nhất của Ruby 68 Hotel, Ruby Sky Lounge mang đến trải nghiệm giải tr&iacute; đẳng cấp với tầm nh&igrave;n to&agrave;n cảnh biển Bãi Sau rực rỡ về đ&ecirc;m.\r\n      </p>\r\n      <p>\r\n        Kh&ocirc;ng gian rooftop hiện đại, &acirc;m nhạc s&ocirc;i động c&ugrave;ng thực đơn cocktail s&aacute;ng tạo tạo n&ecirc;n điểm hẹn l&yacute; tưởng cho những buổi tối đầy cảm hứng.\r\n      </p>\r\n      <p>\r\n        D&ugrave; l&agrave; thư gi&atilde;n nhẹ nh&agrave;ng hay h&ograve;a m&igrave;nh v&agrave;o nhịp sống về đ&ecirc;m, Ruby Sky Lounge lu&ocirc;n l&agrave; nơi lưu giữ những khoảnh khắc đ&aacute;ng nhớ giữa bầu trời v&agrave; biển cả.\r\n      </p>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Photo Gallery -->\r\n  <section class=\"ts-gallery-section\">\r\n    <div class=\"ts-gallery-heading\">\r\n      <div class=\"ts-heading-label\">Ruby Sky Lounge</div>\r\n      <div class=\"ts-heading-title\">Gallery</div>\r\n      <div class=\"ts-gallery-divider\">\r\n        <div class=\"ts-gallery-diamond\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-gallery-grid\">\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/1.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/2.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/3.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/4.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/5.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/6.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/7.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/8.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/9.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/10.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/11.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/12.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/13.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/14.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/15.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/16.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/17.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/18.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/19.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/20.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/21.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/22.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/23.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/24.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/25.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/26.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/27.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/28.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/29.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/30.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/31.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/32.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/33.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/34.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/35.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/36.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/37.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/38.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/39.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/40.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/41.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/42.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/43.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/44.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/45.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/46.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/47.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/48.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/49.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var tsLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function tsGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function tsCreateOverlay() {\r\n      if (tsLB.dialog) return\r\n      var pDoc = tsGetParentDoc()\r\n      tsLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.95);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { tsCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      tsLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      tsLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) tsCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); tsCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        tsLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (tsLB.zoom.scale < 1) { tsLB.zoom.scale = 1; tsLB.zoom.x = 0; tsLB.zoom.y = 0 }\r\n        if (tsLB.zoom.scale > 5) tsLB.zoom.scale = 5\r\n        tsApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); tsResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); tsLB.zoom.dragging = true\r\n        tsLB.zoom.startX = e.clientX; tsLB.zoom.startY = e.clientY\r\n        tsLB.zoom.lastX = tsLB.zoom.x; tsLB.zoom.lastY = tsLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!tsLB.zoom.dragging) return\r\n        tsLB.zoom.x = tsLB.zoom.lastX + (e.clientX - tsLB.zoom.startX) / tsLB.zoom.scale\r\n        tsLB.zoom.y = tsLB.zoom.lastY + (e.clientY - tsLB.zoom.startY) / tsLB.zoom.scale\r\n        tsApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { tsLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; tsLB.touches.dist=Math.sqrt(dx*dx+dy*dy); tsLB.touches.scale0=tsLB.zoom.scale }\r\n        else if (e.touches.length === 1) { tsLB.zoom.dragging=true; tsLB.zoom.startX=e.touches[0].clientX; tsLB.zoom.startY=e.touches[0].clientY; tsLB.zoom.lastX=tsLB.zoom.x; tsLB.zoom.lastY=tsLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; tsLB.zoom.scale=tsLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/tsLB.touches.dist); if(tsLB.zoom.scale<1)tsLB.zoom.scale=1;if(tsLB.zoom.scale>5)tsLB.zoom.scale=5; tsApplyZoom() }\r\n        else if (e.touches.length===1&&tsLB.zoom.dragging) { e.preventDefault(); tsLB.zoom.x=tsLB.zoom.lastX+(e.touches[0].clientX-tsLB.zoom.startX)/tsLB.zoom.scale; tsLB.zoom.y=tsLB.zoom.lastY+(e.touches[0].clientY-tsLB.zoom.startY)/tsLB.zoom.scale; tsApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { tsLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') tsCloseLightbox() })\r\n    }\r\n    function tsResetZoom() { tsLB.zoom.scale=1;tsLB.zoom.x=0;tsLB.zoom.y=0; if(tsLB.img)tsLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function tsApplyZoom() { if(tsLB.img)tsLB.img.style.transform=\'scale(\'+tsLB.zoom.scale+\') translate(\'+tsLB.zoom.x+\'px,\'+tsLB.zoom.y+\'px)\' }\r\n    function tsOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      tsCreateOverlay()\r\n      tsLB.img.src = img.src; tsResetZoom()\r\n      tsLB.dialog.showModal()\r\n      tsLB.dialog.style.display = \'flex\'\r\n    }\r\n    function tsCloseLightbox() {\r\n      if (tsLB.dialog && tsLB.dialog.open) { tsLB.dialog.close(); tsLB.dialog.style.display = \'\'; tsResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby 68 Beach</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====BÃI BIỂN RUBY 68=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .bb-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/203fcacc.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .bb-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .bb-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .bb-title-section .bb-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .bb-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .bb-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .bb-title-divider::before,\r\n    .bb-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .bb-title-divider .bb-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .bb-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .bb-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .bb-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .bb-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-line::before,\r\n    .bb-gallery-heading .bb-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .bb-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .bb-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .bb-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .bb-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .bb-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .bb-gallery-heading .bb-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .bb-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .bb-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .bb-title-section .bb-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .bb-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .bb-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .bb-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .bb-gallery-heading .bb-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"bb-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"bb-title-section\">\r\n    <div class=\"bb-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby 68 Beach</h1>\r\n    <div class=\"bb-title-divider\">\r\n      <div class=\"bb-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"bb-content\">\r\n    <p>\r\n      Enjoy your holiday beside deep blue waters and pristine white sand at the private beach of Ruby 68.\r\n    </p>\r\n    <p>\r\n      Under the gentle tropical sunlight, every moment of relaxation is enhanced with sun loungers, parasols and towels always at your service.\r\n    </p>\r\n    <p>\r\n      An ideal space to immerse yourself in nature, enjoying the beauty of Vũng Tàu\'s sea in a refined and tranquil way.\r\n    </p>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"bb-gallery-section\">\r\n    <div class=\"bb-gallery-heading\">\r\n      <div class=\"bb-heading-line\">\r\n        <div class=\"bb-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"bb-heading-sub\">Ruby 68 Beach</div>\r\n      <div class=\"bb-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"bb-gallery-grid\">\r\n      <div class=\"bb-photo\" onclick=\"bbOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/203fcacc.jpg\" alt=\"Ruby 68 Beach\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var bbLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function bbGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function bbCreateOverlay() {\r\n      if (bbLB.dialog) return\r\n      var pDoc = bbGetParentDoc()\r\n      bbLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { bbCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      bbLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      bbLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) bbCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); bbCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        bbLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (bbLB.zoom.scale < 1) { bbLB.zoom.scale = 1; bbLB.zoom.x = 0; bbLB.zoom.y = 0 }\r\n        if (bbLB.zoom.scale > 5) bbLB.zoom.scale = 5\r\n        bbApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); bbResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); bbLB.zoom.dragging = true\r\n        bbLB.zoom.startX = e.clientX; bbLB.zoom.startY = e.clientY\r\n        bbLB.zoom.lastX = bbLB.zoom.x; bbLB.zoom.lastY = bbLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!bbLB.zoom.dragging) return\r\n        bbLB.zoom.x = bbLB.zoom.lastX + (e.clientX - bbLB.zoom.startX) / bbLB.zoom.scale\r\n        bbLB.zoom.y = bbLB.zoom.lastY + (e.clientY - bbLB.zoom.startY) / bbLB.zoom.scale\r\n        bbApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { bbLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; bbLB.touches.dist=Math.sqrt(dx*dx+dy*dy); bbLB.touches.scale0=bbLB.zoom.scale }\r\n        else if (e.touches.length === 1) { bbLB.zoom.dragging=true; bbLB.zoom.startX=e.touches[0].clientX; bbLB.zoom.startY=e.touches[0].clientY; bbLB.zoom.lastX=bbLB.zoom.x; bbLB.zoom.lastY=bbLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; bbLB.zoom.scale=bbLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/bbLB.touches.dist); if(bbLB.zoom.scale<1)bbLB.zoom.scale=1;if(bbLB.zoom.scale>5)bbLB.zoom.scale=5; bbApplyZoom() }\r\n        else if (e.touches.length===1&&bbLB.zoom.dragging) { e.preventDefault(); bbLB.zoom.x=bbLB.zoom.lastX+(e.touches[0].clientX-bbLB.zoom.startX)/bbLB.zoom.scale; bbLB.zoom.y=bbLB.zoom.lastY+(e.touches[0].clientY-bbLB.zoom.startY)/bbLB.zoom.scale; bbApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { bbLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') bbCloseLightbox() })\r\n    }\r\n    function bbResetZoom() { bbLB.zoom.scale=1;bbLB.zoom.x=0;bbLB.zoom.y=0; if(bbLB.img)bbLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function bbApplyZoom() { if(bbLB.img)bbLB.img.style.transform=\'scale(\'+bbLB.zoom.scale+\') translate(\'+bbLB.zoom.x+\'px,\'+bbLB.zoom.y+\'px)\' }\r\n    function bbOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      bbCreateOverlay()\r\n      bbLB.img.src = img.src; bbResetZoom()\r\n      bbLB.dialog.showModal()\r\n      bbLB.dialog.style.display = \'flex\'\r\n    }\r\n    function bbCloseLightbox() {\r\n      if (bbLB.dialog && bbLB.dialog.open) { bbLB.dialog.close(); bbLB.dialog.style.display = \'\'; bbResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-03-27 04:04:04', '2026-03-27 04:04:04'),
(141, 'Botble\\Page\\Models\\Page', 25, 1, 'description', 'Tọa lạc trên tầng cao nhất của Ruby 68 Hotel, Ruby Sky Lounge mang đến trải nghiệm giải trí đẳng cấp với tầm nhìn toàn cảnh biển Bãi Sau rực rỡ về đêm. Không gian rooftop hiện đại, âm nhạc sôi động cùng thực đơn cocktail sáng tạo tạo nên điểm hẹn lý tưởng cho những buổi tối đầy cảm hứng.', 'Located on the top floor of Ruby 68 Hotel, Ruby Sky Lounge offers a premium entertainment experience with a breathtaking panoramic view of Back Beach Vung Tau at night. The modern rooftop setting, vibrant music, and creative cocktail menu make it an ideal destination for inspiring evenings.', '2026-03-27 04:04:04', '2026-03-27 04:04:04');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(142, 'Botble\\Page\\Models\\Page', 25, 1, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby 68 Beach</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====BÃI BIỂN RUBY 68=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .bb-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://botonbluehotel.vt360.vn/storage/services/203fcacc.jpg\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .bb-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .bb-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .bb-title-section .bb-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .bb-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .bb-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .bb-title-divider::before,\r\n    .bb-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .bb-title-divider .bb-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .bb-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .bb-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .bb-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .bb-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-line::before,\r\n    .bb-gallery-heading .bb-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .bb-gallery-heading .bb-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .bb-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo {\r\n      aspect-ratio: 16 / 10;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .bb-gallery-grid .bb-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .bb-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .bb-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .bb-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .bb-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .bb-gallery-heading .bb-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .bb-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .bb-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .bb-title-section .bb-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .bb-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .bb-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .bb-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .bb-gallery-heading .bb-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"bb-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"bb-title-section\">\r\n    <div class=\"bb-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby 68 Beach</h1>\r\n    <div class=\"bb-title-divider\">\r\n      <div class=\"bb-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"bb-content\">\r\n    <p>\r\n      Enjoy your holiday beside deep blue waters and pristine white sand at the private beach of Ruby 68.\r\n    </p>\r\n    <p>\r\n      Under the gentle tropical sunlight, every moment of relaxation is enhanced with sun loungers, parasols and towels always at your service.\r\n    </p>\r\n    <p>\r\n      An ideal space to immerse yourself in nature, enjoying the beauty of Vũng Tàu\'s sea in a refined and tranquil way.\r\n    </p>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"bb-gallery-section\">\r\n    <div class=\"bb-gallery-heading\">\r\n      <div class=\"bb-heading-line\">\r\n        <div class=\"bb-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"bb-heading-sub\">Ruby 68 Beach</div>\r\n      <div class=\"bb-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"bb-gallery-grid\">\r\n      <div class=\"bb-photo\" onclick=\"bbOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/203fcacc.jpg\" alt=\"Ruby 68 Beach\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var bbLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function bbGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function bbCreateOverlay() {\r\n      if (bbLB.dialog) return\r\n      var pDoc = bbGetParentDoc()\r\n      bbLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'&times;\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { bbCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      bbLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      bbLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) bbCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); bbCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        bbLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (bbLB.zoom.scale < 1) { bbLB.zoom.scale = 1; bbLB.zoom.x = 0; bbLB.zoom.y = 0 }\r\n        if (bbLB.zoom.scale > 5) bbLB.zoom.scale = 5\r\n        bbApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); bbResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); bbLB.zoom.dragging = true\r\n        bbLB.zoom.startX = e.clientX; bbLB.zoom.startY = e.clientY\r\n        bbLB.zoom.lastX = bbLB.zoom.x; bbLB.zoom.lastY = bbLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!bbLB.zoom.dragging) return\r\n        bbLB.zoom.x = bbLB.zoom.lastX + (e.clientX - bbLB.zoom.startX) / bbLB.zoom.scale\r\n        bbLB.zoom.y = bbLB.zoom.lastY + (e.clientY - bbLB.zoom.startY) / bbLB.zoom.scale\r\n        bbApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { bbLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; bbLB.touches.dist=Math.sqrt(dx*dx+dy*dy); bbLB.touches.scale0=bbLB.zoom.scale }\r\n        else if (e.touches.length === 1) { bbLB.zoom.dragging=true; bbLB.zoom.startX=e.touches[0].clientX; bbLB.zoom.startY=e.touches[0].clientY; bbLB.zoom.lastX=bbLB.zoom.x; bbLB.zoom.lastY=bbLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; bbLB.zoom.scale=bbLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/bbLB.touches.dist); if(bbLB.zoom.scale<1)bbLB.zoom.scale=1;if(bbLB.zoom.scale>5)bbLB.zoom.scale=5; bbApplyZoom() }\r\n        else if (e.touches.length===1&&bbLB.zoom.dragging) { e.preventDefault(); bbLB.zoom.x=bbLB.zoom.lastX+(e.touches[0].clientX-bbLB.zoom.startX)/bbLB.zoom.scale; bbLB.zoom.y=bbLB.zoom.lastY+(e.touches[0].clientY-bbLB.zoom.startY)/bbLB.zoom.scale; bbApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { bbLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') bbCloseLightbox() })\r\n    }\r\n    function bbResetZoom() { bbLB.zoom.scale=1;bbLB.zoom.x=0;bbLB.zoom.y=0; if(bbLB.img)bbLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function bbApplyZoom() { if(bbLB.img)bbLB.img.style.transform=\'scale(\'+bbLB.zoom.scale+\') translate(\'+bbLB.zoom.x+\'px,\'+bbLB.zoom.y+\'px)\' }\r\n    function bbOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      bbCreateOverlay()\r\n      bbLB.img.src = img.src; bbResetZoom()\r\n      bbLB.dialog.showModal()\r\n      bbLB.dialog.style.display = \'flex\'\r\n    }\r\n    function bbCloseLightbox() {\r\n      if (bbLB.dialog && bbLB.dialog.open) { bbLB.dialog.close(); bbLB.dialog.style.display = \'\'; bbResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Sky Lounge</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SKY LOUNGE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #0b0b0b;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      color: #ccc;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .ts-hero {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      background: #0b0b0b;\r\n      display: grid;\r\n      grid-template-columns: 1fr 28%;\r\n      grid-template-rows: auto auto;\r\n      padding: 150px 50px 50px;\r\n      gap: 0 16px;\r\n    }\r\n\r\n    /* Welcome text row */\r\n    .ts-hero-welcome {\r\n      grid-column: 1 / -1;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 14px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 10px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-hero-welcome::before {\r\n      content: \'\';\r\n      width: 40px;\r\n      height: 1px;\r\n      background: #c9a84c;\r\n    }\r\n\r\n    /* Main area: h1 + image overlap */\r\n    .ts-hero-main {\r\n      grid-column: 1 / 2;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-hero h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: clamp(60px, 9vw, 130px);\r\n      font-weight: 200;\r\n      color: #fff;\r\n      line-height: 0.95;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      position: relative;\r\n      z-index: 2;\r\n    }\r\n\r\n    .ts-hero-img1 {\r\n      overflow: hidden;\r\n      margin-top: 2vw;\r\n      position: relative;\r\n      z-index: 1;\r\n      max-height: 500px;\r\n    }\r\n\r\n    .ts-hero-img1 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    /* Right: image + desc + tags */\r\n    .ts-hero-right {\r\n      grid-column: 2 / 3;\r\n      grid-row: 2 / 3;\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .ts-hero-img2 {\r\n      overflow: hidden;\r\n      aspect-ratio: 16 / 9;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-hero-img2 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-hero-desc {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #888;\r\n      margin-bottom: 20px;\r\n      border-top: 1px solid #2a2a2a;\r\n      padding-top: 20px;\r\n    }\r\n\r\n    .ts-hero-tags {\r\n      display: flex;\r\n      gap: 20px;\r\n      margin-top: auto;\r\n    }\r\n\r\n    .ts-hero-tags span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 12px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #555;\r\n    }\r\n\r\n    /*--Sec2: About--*/\r\n    .ts-about {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 70px 50px 60px;\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 40px;\r\n      align-items: center;\r\n    }\r\n\r\n    .ts-about-images {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 10px;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img {\r\n      overflow: hidden;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:first-child {\r\n      grid-row: 1 / 3;\r\n      aspect-ratio: 9 / 16;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(2) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(3) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-about-text .ts-section-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .ts-about-text .ts-section-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 65px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.2;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-about-text p {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 18px;\r\n      line-height: 2;\r\n      color: #999;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    /*--Sec3: Photo Gallery--*/\r\n    .ts-gallery-section {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 0 50px 60px;\r\n      background: #0b0b0b;\r\n    }\r\n\r\n    .ts-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 70px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.3;\r\n      margin-bottom: 10px;\r\n    }\r\n\r\n    .ts-gallery-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-gallery-divider::before,\r\n    .ts-gallery-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 60px;\r\n      background: linear-gradient(to right, transparent, rgba(201, 168, 76, 0.5), transparent);\r\n    }\r\n\r\n    .ts-gallery-divider .ts-gallery-diamond {\r\n      width: 8px;\r\n      height: 8px;\r\n      background: #c9a84c;\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .ts-gallery-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 5px;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo::after {\r\n      content: \'\';\r\n      position: absolute;\r\n      inset: 0;\r\n      background: rgba(0, 0, 0, 0.3);\r\n      transition: background .4s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover::after {\r\n      background: rgba(0, 0, 0, 0);\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .5s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover img {\r\n      transform: scale(1.1);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 960px) {\r\n      .ts-hero {\r\n        grid-template-columns: 1fr;\r\n        padding: 130px 30px 40px;\r\n      }\r\n\r\n      .ts-hero-right {\r\n        display: none;\r\n      }\r\n\r\n      .ts-hero-main {\r\n        grid-column: 1;\r\n      }\r\n\r\n      .ts-about {\r\n        grid-template-columns: 1fr;\r\n        padding: 50px 30px 40px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 30px 60px;\r\n      }\r\n\r\n      .ts-about-images {\r\n        max-width: 500px;\r\n        margin: 0 auto;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .ts-hero {\r\n        padding: 120px 20px 30px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 20px 30px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 20px 50px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 28px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 14px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 4px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 28px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .ts-hero-text {\r\n        padding: 30px 15px 15px;\r\n      }\r\n\r\n      .ts-hero-welcome {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 15px 30px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 24px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 13px;\r\n        line-height: 1.8;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 3px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 24px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"ts-hero\">\r\n    <div class=\"ts-hero-welcome\">Welcome to</div>\r\n    <div class=\"ts-hero-main\">\r\n      <h1>Ruby Sky Lounge</h1>\r\n      <div class=\"ts-hero-img1\">\r\n        <img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/8.jpg\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-hero-right\">\r\n      <div class=\"ts-hero-img2\">\r\n        <img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/10.jpg\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n      <div class=\"ts-hero-desc\">\r\n        Trải nghiệm giải tr&iacute; đẳng cấp tr&ecirc;n tầng cao nhất, nơi bầu trời h&ograve;a v&agrave;o biển cả c&ugrave;ng &acirc;m nhạc v&agrave; cocktail.\r\n      </div>\r\n      <div class=\"ts-hero-tags\">\r\n        <span>Rooftop</span>\r\n        <span>Cocktails</span>\r\n        <span>Live Music</span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec2: About -->\r\n  <div class=\"ts-about\">\r\n    <div class=\"ts-about-images\">\r\n      <div class=\"ts-about-img\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/4.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/15.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/20.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n    </div>\r\n    <div class=\"ts-about-text\">\r\n      <div class=\"ts-section-label\">About</div>\r\n      <div class=\"ts-section-title\">Where the Sky Meets the Sea</div>\r\n      <p>\r\n        Tọa lạc tr&ecirc;n tầng cao nhất của Ruby 68 Hotel, Ruby Sky Lounge mang đến trải nghiệm giải tr&iacute; đẳng cấp với tầm nh&igrave;n to&agrave;n cảnh biển Bãi Sau rực rỡ về đ&ecirc;m.\r\n      </p>\r\n      <p>\r\n        Kh&ocirc;ng gian rooftop hiện đại, &acirc;m nhạc s&ocirc;i động c&ugrave;ng thực đơn cocktail s&aacute;ng tạo tạo n&ecirc;n điểm hẹn l&yacute; tưởng cho những buổi tối đầy cảm hứng.\r\n      </p>\r\n      <p>\r\n        D&ugrave; l&agrave; thư gi&atilde;n nhẹ nh&agrave;ng hay h&ograve;a m&igrave;nh v&agrave;o nhịp sống về đ&ecirc;m, Ruby Sky Lounge lu&ocirc;n l&agrave; nơi lưu giữ những khoảnh khắc đ&aacute;ng nhớ giữa bầu trời v&agrave; biển cả.\r\n      </p>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Photo Gallery -->\r\n  <section class=\"ts-gallery-section\">\r\n    <div class=\"ts-gallery-heading\">\r\n      <div class=\"ts-heading-label\">Ruby Sky Lounge</div>\r\n      <div class=\"ts-heading-title\">Gallery</div>\r\n      <div class=\"ts-gallery-divider\">\r\n        <div class=\"ts-gallery-diamond\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-gallery-grid\">\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/1.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/2.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/3.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/4.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://botonbluehotel.vt360.vn/storage/services/titan-sky-lounge/5.jpg\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\