(147, 'Botble\\Page\\Models\\Page', 10, 1, 'content_mode', NULL, 'blocks', '2026-03-28 04:05:43', '2026-03-28 04:05:43'),
(148, 'Botble\\Page\\Models\\Page', 10, 1, 'description', NULL, '', '2026-03-28 04:05:43', '2026-03-28 04:05:43'),
