INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(328, 'Botble\\Page\\Models\\Page', 25, 3, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Sky Lounge</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SKY LOUNGE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #0b0b0b;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      color: #ccc;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .ts-hero {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      background: #0b0b0b;\r\n      display: grid;\r\n      grid-template-columns: 1fr 28%;\r\n      grid-template-rows: auto auto;\r\n      padding: 150px 50px 50px;\r\n      gap: 0 16px;\r\n    }\r\n\r\n    /* Welcome text row */\r\n    .ts-hero-welcome {\r\n      grid-column: 1 / -1;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 14px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 10px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-hero-welcome::before {\r\n      content: \'\';\r\n      width: 40px;\r\n      height: 1px;\r\n      background: #c9a84c;\r\n    }\r\n\r\n    /* Main area: h1 + image overlap */\r\n    .ts-hero-main {\r\n      grid-column: 1 / 2;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-hero h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: clamp(60px, 9vw, 130px);\r\n      font-weight: 200;\r\n      color: #fff;\r\n      line-height: 0.95;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      position: relative;\r\n      z-index: 2;\r\n    }\r\n\r\n    .ts-hero-img1 {\r\n      overflow: hidden;\r\n      margin-top: 2vw;\r\n      position: relative;\r\n      z-index: 1;\r\n      max-height: 500px;\r\n    }\r\n\r\n    .ts-hero-img1 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    /* Right: image + desc + tags */\r\n    .ts-hero-right {\r\n      grid-column: 2 / 3;\r\n      grid-row: 2 / 3;\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .ts-hero-img2 {\r\n      overflow: hidden;\r\n      aspect-ratio: 16 / 9;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-hero-img2 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-hero-desc {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #888;\r\n      margin-bottom: 20px;\r\n      border-top: 1px solid #2a2a2a;\r\n      padding-top: 20px;\r\n    }\r\n\r\n    .ts-hero-tags {\r\n      display: flex;\r\n      gap: 20px;\r\n      margin-top: auto;\r\n    }\r\n\r\n    .ts-hero-tags span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 12px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #555;\r\n    }\r\n\r\n    /*--Sec2: About--*/\r\n    .ts-about {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 70px 50px 60px;\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 40px;\r\n      align-items: center;\r\n    }\r\n\r\n    .ts-about-images {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 10px;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img {\r\n      overflow: hidden;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:first-child {\r\n      grid-row: 1 / 3;\r\n      aspect-ratio: 9 / 16;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(2) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(3) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-about-text .ts-section-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .ts-about-text .ts-section-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 65px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.2;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-about-text p {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 18px;\r\n      line-height: 2;\r\n      color: #999;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    /*--Sec3: Photo Gallery--*/\r\n    .ts-gallery-section {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 0 50px 60px;\r\n      background: #0b0b0b;\r\n    }\r\n\r\n    .ts-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 70px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.3;\r\n      margin-bottom: 10px;\r\n    }\r\n\r\n    .ts-gallery-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-gallery-divider::before,\r\n    .ts-gallery-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 60px;\r\n      background: linear-gradient(to right, transparent, rgba(201, 168, 76, 0.5), transparent);\r\n    }\r\n\r\n    .ts-gallery-divider .ts-gallery-diamond {\r\n      width: 8px;\r\n      height: 8px;\r\n      background: #c9a84c;\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .ts-gallery-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 5px;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo::after {\r\n      content: \'\';\r\n      position: absolute;\r\n      inset: 0;\r\n      background: rgba(0, 0, 0, 0.3);\r\n      transition: background .4s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover::after {\r\n      background: rgba(0, 0, 0, 0);\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .5s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover img {\r\n      transform: scale(1.1);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 960px) {\r\n      .ts-hero {\r\n        grid-template-columns: 1fr;\r\n        padding: 130px 30px 40px;\r\n      }\r\n\r\n      .ts-hero-right {\r\n        display: none;\r\n      }\r\n\r\n      .ts-hero-main {\r\n        grid-column: 1;\r\n      }\r\n\r\n      .ts-about {\r\n        grid-template-columns: 1fr;\r\n        padding: 50px 30px 40px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 30px 60px;\r\n      }\r\n\r\n      .ts-about-images {\r\n        max-width: 500px;\r\n        margin: 0 auto;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .ts-hero {\r\n        padding: 120px 20px 30px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 20px 30px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 20px 50px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 28px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 14px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 4px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 28px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .ts-hero-text {\r\n        padding: 30px 15px 15px;\r\n      }\r\n\r\n      .ts-hero-welcome {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 15px 30px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 24px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 13px;\r\n        line-height: 1.8;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 3px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 24px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"ts-hero\">\r\n    <div class=\"ts-hero-welcome\">Welcome to</div>\r\n    <div class=\"ts-hero-main\">\r\n      <h1>Ruby Sky Lounge</h1>\r\n      <div class=\"ts-hero-img1\">\r\n        <img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-hero-right\">\r\n      <div class=\"ts-hero-img2\">\r\n        <img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n      <div class=\"ts-hero-desc\">\r\n        Trải nghiệm giải trí đẳng cấp trên tầng cao nhất, nơi bầu trời hòa vào biển cả cùng âm nhạc và cocktail.\r\n      </div>\r\n      <div class=\"ts-hero-tags\">\r\n        <span>Rooftop</span>\r\n        <span>Cocktails</span>\r\n        <span>Live Music</span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec2: About -->\r\n  <div class=\"ts-about\">\r\n    <div class=\"ts-about-images\">\r\n      <div class=\"ts-about-img\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n    </div>\r\n    <div class=\"ts-about-text\">\r\n      <div class=\"ts-section-label\">About</div>\r\n      <div class=\"ts-section-title\">Where the Sky Meets the Sea</div>\r\n      <p>\r\n        Tọa lạc trên tầng cao nhất của Ruby 68 Hotel, Ruby Sky Lounge mang đến trải nghiệm giải trí đẳng cấp với tầm nhìn toàn cảnh biển Bãi Sau rực rỡ về đêm.\r\n      </p>\r\n      <p>\r\n        Không gian rooftop hiện đại, âm nhạc sôi động cùng thực đơn cocktail sáng tạo tạo nên điểm hẹn lý tưởng cho những buổi tối đầy cảm hứng.\r\n      </p>\r\n      <p>\r\n        Dù là thư giãn nhẹ nhàng hay hòa mình vào nhịp sống về đêm, Ruby Sky Lounge luôn là nơi lưu giữ những khoảnh khắc đáng nhớ giữa bầu trời và biển cả.\r\n      </p>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Photo Gallery -->\r\n  <section class=\"ts-gallery-section\">\r\n    <div class=\"ts-gallery-heading\">\r\n      <div class=\"ts-heading-label\">Ruby Sky Lounge</div>\r\n      <div class=\"ts-heading-title\">Gallery</div>\r\n      <div class=\"ts-gallery-divider\">\r\n        <div class=\"ts-gallery-diamond\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-gallery-grid\">\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var tsLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function tsGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function tsCreateOverlay() {\r\n      if (tsLB.dialog) return\r\n      var pDoc = tsGetParentDoc()\r\n      tsLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.95);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { tsCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      tsLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      tsLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) tsCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); tsCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        tsLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (tsLB.zoom.scale < 1) { tsLB.zoom.scale = 1; tsLB.zoom.x = 0; tsLB.zoom.y = 0 }\r\n        if (tsLB.zoom.scale > 5) tsLB.zoom.scale = 5\r\n        tsApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); tsResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); tsLB.zoom.dragging = true\r\n        tsLB.zoom.startX = e.clientX; tsLB.zoom.startY = e.clientY\r\n        tsLB.zoom.lastX = tsLB.zoom.x; tsLB.zoom.lastY = tsLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!tsLB.zoom.dragging) return\r\n        tsLB.zoom.x = tsLB.zoom.lastX + (e.clientX - tsLB.zoom.startX) / tsLB.zoom.scale\r\n        tsLB.zoom.y = tsLB.zoom.lastY + (e.clientY - tsLB.zoom.startY) / tsLB.zoom.scale\r\n        tsApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { tsLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; tsLB.touches.dist=Math.sqrt(dx*dx+dy*dy); tsLB.touches.scale0=tsLB.zoom.scale }\r\n        else if (e.touches.length === 1) { tsLB.zoom.dragging=true; tsLB.zoom.startX=e.touches[0].clientX; tsLB.zoom.startY=e.touches[0].clientY; tsLB.zoom.lastX=tsLB.zoom.x; tsLB.zoom.lastY=tsLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; tsLB.zoom.scale=tsLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/tsLB.touches.dist); if(tsLB.zoom.scale<1)tsLB.zoom.scale=1;if(tsLB.zoom.scale>5)tsLB.zoom.scale=5; tsApplyZoom() }\r\n        else if (e.touches.length===1&&tsLB.zoom.dragging) { e.preventDefault(); tsLB.zoom.x=tsLB.zoom.lastX+(e.touches[0].clientX-tsLB.zoom.startX)/tsLB.zoom.scale; tsLB.zoom.y=tsLB.zoom.lastY+(e.touches[0].clientY-tsLB.zoom.startY)/tsLB.zoom.scale; tsApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { tsLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') tsCloseLightbox() })\r\n    }\r\n    function tsResetZoom() { tsLB.zoom.scale=1;tsLB.zoom.x=0;tsLB.zoom.y=0; if(tsLB.img)tsLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function tsApplyZoom() { if(tsLB.img)tsLB.img.style.transform=\'scale(\'+tsLB.zoom.scale+\') translate(\'+tsLB.zoom.x+\'px,\'+tsLB.zoom.y+\'px)\' }\r\n    function tsOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      tsCreateOverlay()\r\n      tsLB.img.src = img.src; tsResetZoom()\r\n      tsLB.dialog.showModal()\r\n      tsLB.dialog.style.display = \'flex\'\r\n    }\r\n    function tsCloseLightbox() {\r\n      if (tsLB.dialog && tsLB.dialog.open) { tsLB.dialog.close(); tsLB.dialog.style.display = \'\'; tsResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Sky Lounge</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SKY LOUNGE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #0b0b0b;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      color: #ccc;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .ts-hero {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      background: #0b0b0b;\r\n      display: grid;\r\n      grid-template-columns: 1fr 28%;\r\n      grid-template-rows: auto auto;\r\n      padding: 150px 50px 50px;\r\n      gap: 0 16px;\r\n    }\r\n\r\n    /* Welcome text row */\r\n    .ts-hero-welcome {\r\n      grid-column: 1 / -1;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 14px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 10px;\r\n      display: flex;\r\n      align-items: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-hero-welcome::before {\r\n      content: \'\';\r\n      width: 40px;\r\n      height: 1px;\r\n      background: #c9a84c;\r\n    }\r\n\r\n    /* Main area: h1 + image overlap */\r\n    .ts-hero-main {\r\n      grid-column: 1 / 2;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-hero h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: clamp(60px, 9vw, 130px);\r\n      font-weight: 200;\r\n      color: #fff;\r\n      line-height: 0.95;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      position: relative;\r\n      z-index: 2;\r\n    }\r\n\r\n    .ts-hero-img1 {\r\n      overflow: hidden;\r\n      margin-top: 2vw;\r\n      position: relative;\r\n      z-index: 1;\r\n      max-height: 500px;\r\n    }\r\n\r\n    .ts-hero-img1 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    /* Right: image + desc + tags */\r\n    .ts-hero-right {\r\n      grid-column: 2 / 3;\r\n      grid-row: 2 / 3;\r\n      display: flex;\r\n      flex-direction: column;\r\n    }\r\n\r\n    .ts-hero-img2 {\r\n      overflow: hidden;\r\n      aspect-ratio: 16 / 9;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-hero-img2 img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-hero-desc {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #888;\r\n      margin-bottom: 20px;\r\n      border-top: 1px solid #2a2a2a;\r\n      padding-top: 20px;\r\n    }\r\n\r\n    .ts-hero-tags {\r\n      display: flex;\r\n      gap: 20px;\r\n      margin-top: auto;\r\n    }\r\n\r\n    .ts-hero-tags span {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 12px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #555;\r\n    }\r\n\r\n    /*--Sec2: About--*/\r\n    .ts-about {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 70px 50px 60px;\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 40px;\r\n      align-items: center;\r\n    }\r\n\r\n    .ts-about-images {\r\n      display: grid;\r\n      grid-template-columns: 1fr 1fr;\r\n      gap: 10px;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img {\r\n      overflow: hidden;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:first-child {\r\n      grid-row: 1 / 3;\r\n      aspect-ratio: 9 / 16;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(2) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img:nth-child(3) {\r\n      aspect-ratio: 1 / 1;\r\n    }\r\n\r\n    .ts-about-images .ts-about-img img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n    }\r\n\r\n    .ts-about-text .ts-section-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .ts-about-text .ts-section-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 65px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.2;\r\n      margin-bottom: 24px;\r\n    }\r\n\r\n    .ts-about-text p {\r\n      font-family: Arial, Helvetica, sans-serif;\r\n      font-size: 18px;\r\n      line-height: 2;\r\n      color: #999;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    /*--Sec3: Photo Gallery--*/\r\n    .ts-gallery-section {\r\n      max-width: 1320px;\r\n      margin: 0 auto;\r\n      padding: 0 50px 60px;\r\n      background: #0b0b0b;\r\n    }\r\n\r\n    .ts-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 16px;\r\n      font-weight: 300;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #c9a84c;\r\n      margin-bottom: 12px;\r\n    }\r\n\r\n    .ts-gallery-heading .ts-heading-title {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 70px;\r\n      font-weight: 200;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      color: #fff;\r\n      line-height: 1.3;\r\n      margin-bottom: 10px;\r\n    }\r\n\r\n    .ts-gallery-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n    }\r\n\r\n    .ts-gallery-divider::before,\r\n    .ts-gallery-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 60px;\r\n      background: linear-gradient(to right, transparent, rgba(201, 168, 76, 0.5), transparent);\r\n    }\r\n\r\n    .ts-gallery-divider .ts-gallery-diamond {\r\n      width: 8px;\r\n      height: 8px;\r\n      background: #c9a84c;\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .ts-gallery-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(4, 1fr);\r\n      gap: 5px;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo::after {\r\n      content: \'\';\r\n      position: absolute;\r\n      inset: 0;\r\n      background: rgba(0, 0, 0, 0.3);\r\n      transition: background .4s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover::after {\r\n      background: rgba(0, 0, 0, 0);\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .5s ease;\r\n    }\r\n\r\n    .ts-gallery-grid .ts-photo:hover img {\r\n      transform: scale(1.1);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 960px) {\r\n      .ts-hero {\r\n        grid-template-columns: 1fr;\r\n        padding: 130px 30px 40px;\r\n      }\r\n\r\n      .ts-hero-right {\r\n        display: none;\r\n      }\r\n\r\n      .ts-hero-main {\r\n        grid-column: 1;\r\n      }\r\n\r\n      .ts-about {\r\n        grid-template-columns: 1fr;\r\n        padding: 50px 30px 40px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 30px 60px;\r\n      }\r\n\r\n      .ts-about-images {\r\n        max-width: 500px;\r\n        margin: 0 auto;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .ts-hero {\r\n        padding: 120px 20px 30px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 20px 30px;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 20px 50px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 28px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 14px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 4px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 28px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .ts-hero-text {\r\n        padding: 30px 15px 15px;\r\n      }\r\n\r\n      .ts-hero-welcome {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .ts-about {\r\n        padding: 40px 15px 30px;\r\n      }\r\n\r\n      .ts-about-text .ts-section-title {\r\n        font-size: 24px;\r\n      }\r\n\r\n      .ts-about-text p {\r\n        font-size: 13px;\r\n        line-height: 1.8;\r\n      }\r\n\r\n      .ts-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .ts-gallery-grid {\r\n        grid-template-columns: repeat(3, 1fr);\r\n        gap: 3px;\r\n      }\r\n\r\n      .ts-gallery-heading .ts-heading-title {\r\n        font-size: 24px;\r\n      }\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"ts-hero\">\r\n    <div class=\"ts-hero-welcome\">Welcome to</div>\r\n    <div class=\"ts-hero-main\">\r\n      <h1>Ruby Sky Lounge</h1>\r\n      <div class=\"ts-hero-img1\">\r\n        <img src=\"https://images.unsplash.com/photo-1470337458703-46ad1756a187?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-hero-right\">\r\n      <div class=\"ts-hero-img2\">\r\n        <img src=\"https://images.unsplash.com/photo-1514933651103-005eec06c04b?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\">\r\n      </div>\r\n      <div class=\"ts-hero-desc\">\r\n        Trải nghiệm giải trí đẳng cấp trên tầng cao nhất, nơi bầu trời hòa vào biển cả cùng âm nhạc và cocktail.\r\n      </div>\r\n      <div class=\"ts-hero-tags\">\r\n        <span>Rooftop</span>\r\n        <span>Cocktails</span>\r\n        <span>Live Music</span>\r\n      </div>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec2: About -->\r\n  <div class=\"ts-about\">\r\n    <div class=\"ts-about-images\">\r\n      <div class=\"ts-about-img\"><img src=\"https://images.unsplash.com/photo-1559339352-11d035aa65de?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://images.unsplash.com/photo-1583417319070-4a69db38a482?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-about-img\"><img src=\"https://images.unsplash.com/photo-1572116469696-31de0f17cc34?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n    </div>\r\n    <div class=\"ts-about-text\">\r\n      <div class=\"ts-section-label\">About</div>\r\n      <div class=\"ts-section-title\">Where the Sky Meets the Sea</div>\r\n      <p>\r\n        Tọa lạc trên tầng cao nhất của Ruby 68 Hotel, Ruby Sky Lounge mang đến trải nghiệm giải trí đẳng cấp với tầm nhìn toàn cảnh biển Bãi Sau rực rỡ về đêm.\r\n      </p>\r\n      <p>\r\n        Không gian rooftop hiện đại, âm nhạc sôi động cùng thực đơn cocktail sáng tạo tạo nên điểm hẹn lý tưởng cho những buổi tối đầy cảm hứng.\r\n      </p>\r\n      <p>\r\n        Dù là thư giãn nhẹ nhàng hay hòa mình vào nhịp sống về đêm, Ruby Sky Lounge luôn là nơi lưu giữ những khoảnh khắc đáng nhớ giữa bầu trời và biển cả.\r\n      </p>\r\n    </div>\r\n  </div>\r\n\r\n  <!-- Sec3: Photo Gallery -->\r\n  <section class=\"ts-gallery-section\">\r\n    <div class=\"ts-gallery-heading\">\r\n      <div class=\"ts-heading-label\">Ruby Sky Lounge</div>\r\n      <div class=\"ts-heading-title\">Gallery</div>\r\n      <div class=\"ts-gallery-divider\">\r\n        <div class=\"ts-gallery-diamond\"></div>\r\n      </div>\r\n    </div>\r\n    <div class=\"ts-gallery-grid\">\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1543007630-9710e4a00a20?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1536935338788-846bb9981813?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1566417713940-fe7c737a9ef2?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1436076863939-06870fe779c2?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1546171753-97d7676e4602?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1575444758702-4a6b9222336e?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1519671482749-fd09be7ccebf?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1525268323446-0505b6fe7778?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1508253730651-e5ace80a7025?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1516450360452-9312f5e86fc7?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1517457373958-b7bdd4587205?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1538488881038-e252a119ace7?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1551538827-9c037cb4f32a?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1560624052-449f5ddf0c31?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1517090504586-fde19ea6066f?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1516997121675-4c2d1684aa3e?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1574096079513-d8259312b785?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1608270586620-248524c67de9?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1481833761820-0509d3217039?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1590846406792-0adc7f938f1d?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1554118811-1e0d58224f24?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1521017432531-fbd92d768814?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1493857671505-72967e2e2760?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1528605248644-14dd04022da1?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1533777857889-4be7c70b33f7?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1424847651672-bf20a4b0982b?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1551632436-cbf8dd35adfa?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1552566626-52f8b828add9?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1559925393-8be0ec4767c8?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1578474846511-04ba529f0b88?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1600093463592-8e36ae95ef56?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1579027989536-b7b1f875659b?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1592861956120-e524fc739696?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1554679665-f5537f187268?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1587899897387-091ebd01a6b2?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1445019980597-93fa8acb246c?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1517248135467-4c7edcad34c4?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1522798514-97ceb8c4f1c8?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1414235077428-338989a2e8c0?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1600891964092-4316c288032e?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1585937421612-70a008356fbe?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1502741224143-90386d7f8c82?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1466978913421-dad2ebd01d17?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1561758033-d89a9ad46330?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n      <div class=\"ts-photo\" onclick=\"tsOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1576867757603-05b134ebc379?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Sky Lounge\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var tsLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function tsGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function tsCreateOverlay() {\r\n      if (tsLB.dialog) return\r\n      var pDoc = tsGetParentDoc()\r\n      tsLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.95);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { tsCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      tsLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      tsLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) tsCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); tsCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        tsLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (tsLB.zoom.scale < 1) { tsLB.zoom.scale = 1; tsLB.zoom.x = 0; tsLB.zoom.y = 0 }\r\n        if (tsLB.zoom.scale > 5) tsLB.zoom.scale = 5\r\n        tsApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); tsResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); tsLB.zoom.dragging = true\r\n        tsLB.zoom.startX = e.clientX; tsLB.zoom.startY = e.clientY\r\n        tsLB.zoom.lastX = tsLB.zoom.x; tsLB.zoom.lastY = tsLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!tsLB.zoom.dragging) return\r\n        tsLB.zoom.x = tsLB.zoom.lastX + (e.clientX - tsLB.zoom.startX) / tsLB.zoom.scale\r\n        tsLB.zoom.y = tsLB.zoom.lastY + (e.clientY - tsLB.zoom.startY) / tsLB.zoom.scale\r\n        tsApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { tsLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; tsLB.touches.dist=Math.sqrt(dx*dx+dy*dy); tsLB.touches.scale0=tsLB.zoom.scale }\r\n        else if (e.touches.length === 1) { tsLB.zoom.dragging=true; tsLB.zoom.startX=e.touches[0].clientX; tsLB.zoom.startY=e.touches[0].clientY; tsLB.zoom.lastX=tsLB.zoom.x; tsLB.zoom.lastY=tsLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; tsLB.zoom.scale=tsLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/tsLB.touches.dist); if(tsLB.zoom.scale<1)tsLB.zoom.scale=1;if(tsLB.zoom.scale>5)tsLB.zoom.scale=5; tsApplyZoom() }\r\n        else if (e.touches.length===1&&tsLB.zoom.dragging) { e.preventDefault(); tsLB.zoom.x=tsLB.zoom.lastX+(e.touches[0].clientX-tsLB.zoom.startX)/tsLB.zoom.scale; tsLB.zoom.y=tsLB.zoom.lastY+(e.touches[0].clientY-tsLB.zoom.startY)/tsLB.zoom.scale; tsApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { tsLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') tsCloseLightbox() })\r\n    }\r\n    function tsResetZoom() { tsLB.zoom.scale=1;tsLB.zoom.x=0;tsLB.zoom.y=0; if(tsLB.img)tsLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function tsApplyZoom() { if(tsLB.img)tsLB.img.style.transform=\'scale(\'+tsLB.zoom.scale+\') translate(\'+tsLB.zoom.x+\'px,\'+tsLB.zoom.y+\'px)\' }\r\n    function tsOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      tsCreateOverlay()\r\n      tsLB.img.src = img.src; tsResetZoom()\r\n      tsLB.dialog.showModal()\r\n      tsLB.dialog.style.display = \'flex\'\r\n    }\r\n    function tsCloseLightbox() {\r\n      if (tsLB.dialog && tsLB.dialog.open) { tsLB.dialog.close(); tsLB.dialog.style.display = \'\'; tsResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-08-04 08:09:36', '2026-08-04 08:09:36');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(329, 'Botble\\Page\\Models\\Page', 18, 3, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Conference & Meeting</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====CONFERENCE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .cf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=80\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .cf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .cf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .cf-title-section .cf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .cf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .cf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .cf-title-divider::before,\r\n    .cf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .cf-title-divider .cf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Room Section--*/\r\n    .cf-room {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 50px 30px 30px;\r\n    }\r\n\r\n    .cf-room + .cf-room {\r\n      padding-top: 20px;\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-room-header {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .cf-room-header h2 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 40px;\r\n      font-weight: 200;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .cf-room-header .cf-room-sub {\r\n      font-size: 14px;\r\n      color: #00adef;\r\n      margin-top: 6px;\r\n      letter-spacing: 2px;\r\n    }\r\n\r\n    /*--Room Layout--*/\r\n    .cf-room-body {\r\n      display: flex;\r\n      gap: 40px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .cf-room-gallery {\r\n      flex: 1;\r\n      min-width: 0;\r\n    }\r\n\r\n    .cf-room-info {\r\n      width: 360px;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .cf-room-info p {\r\n      font-size: 16px;\r\n      line-height: 1.8;\r\n      color: #333;\r\n    }\r\n\r\n    .cf-room-info p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .cf-room-specs {\r\n      margin-top: 24px;\r\n      border-top: 1px solid #d9dee5;\r\n      border-bottom: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding: 12px 0;\r\n    }\r\n\r\n    .cf-spec + .cf-spec {\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec-label {\r\n      font-size: 14px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n    }\r\n\r\n    .cf-spec-value {\r\n      font-size: 14px;\r\n      color: #333;\r\n      text-align: right;\r\n    }\r\n\r\n    /*--Photo Grid--*/\r\n    .cf-photo-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n      aspect-ratio: 4/3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    /* First photo spans 2 columns */\r\n    .cf-photo-grid .cf-photo:first-child {\r\n      grid-column: 1 / 3;\r\n      grid-row: 1 / 3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:first-child img {\r\n      aspect-ratio: auto;\r\n      height: 100%;\r\n    }\r\n\r\n    /*--Tulip single image--*/\r\n    .cf-photo-single {\r\n      max-width: 700px;\r\n      margin: 0 auto;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo img {\r\n      width: 100%;\r\n      display: block;\r\n      border-radius: 0;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo:hover img {\r\n      transform: scale(1.02);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .cf-room-body {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .cf-room-info {\r\n        width: 100%;\r\n        text-align: center;\r\n      }\r\n\r\n      .cf-title-section h1 {\r\n        font-size: 44px;\r\n        letter-spacing: 5px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 32px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .cf-title-section h1 {\r\n        font-size: 34px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 26px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 30px 20px 20px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-photo-grid .cf-photo:first-child {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 15px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .cf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-section .cf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 22px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 20px 15px 15px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .cf-spec-label,\r\n      .cf-spec-value {\r\n        font-size: 13px;\r\n      }\r\n      \r\n      .cf-title-divider::before,\r\n      .cf-title-divider::after {\r\n        width: 50px;\r\n      }\r\n    }\r\n    /*--VR360 Button--*/\r\n    .cf-vr-btn {\r\n      display: flex;\r\n      justify-content: center;\r\n      margin: 20px 0 10px;\r\n    }\r\n\r\n    .cf-vr-btn a {\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      padding: 12px 32px;\r\n      background: #0e4d97;\r\n      color: #fff;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      text-decoration: none;\r\n      transition: background .3s ease;\r\n    }\r\n\r\n    .cf-vr-btn a:hover {\r\n      background: #00adef;\r\n    }\r\n\r\n    .cf-vr-btn a svg {\r\n      width: 18px;\r\n      height: 18px;\r\n      fill: currentColor;\r\n      flex-shrink: 0;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"cf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"cf-title-section\">\r\n    <div class=\"cf-label\">Ruby 68 Hotel</div>\r\n    <h1>Conference & Meeting</h1>\r\n    <div class=\"cf-title-divider\"><div class=\"cf-diamond\"></div></div>\r\n  </div>\r\n\r\n  <div class=\"cf-vr-btn\">\r\n    <a href=\"https://360.botonbluehotels.com/#media-name=Conference%20Lobby&yaw=-39.95&pitch=-5.25&fov=105.00\" target=\"_blank\" rel=\"noopener\">\r\n      <svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z\"/></svg>\r\n      Tham quan 360°\r\n    </a>\r\n  </div>\r\n\r\n  <!-- Sec3: Ruby Ballroom -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Ruby Ballroom</h2>\r\n      <div class=\"cf-room-sub\">FLOOR 3 • EVENT & BANQUET HALL</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-grid\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1431540015161-0bf868a2d407?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1431540015161-0bf868a2d407?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1431540015161-0bf868a2d407?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1431540015161-0bf868a2d407?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Tọa lạc tại tầng 3, Ruby Ballroom là lựa chọn lý tưởng cho tiệc cưới, hội nghị và sự kiện tại Vũng Tàu với sức chứa 120 – 150 khách.\r\n        </p>\r\n        <p>\r\n          Không gian được thiết kế hiện đại, tinh tế, kết hợp hệ thống âm thanh – ánh sáng chuẩn 3 sao và tầm nhìn hướng biển ấn tượng. Thực đơn Á – Âu đa dạng, dịch vụ chuyên nghiệp, chỉn chu từng chi tiết cùng không gian linh hoạt cho nhiều concept sự kiện.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Vị trí</span>\r\n            <span class=\"cf-spec-value\">Tầng 3</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">120 – 150 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Âm thanh – ánh sáng chuẩn 3 sao</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Tiệc cưới, hội nghị, sự kiện</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec4: Tulip Meeting Room -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Tulip Meeting Room</h2>\r\n      <div class=\"cf-room-sub\">VIP MEETING ROOM</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-single\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80\" alt=\"Tulip Meeting Room\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Không gian phòng họp VIP riêng tư tại Ruby 68 Hotel, sảnh Tulip phù hợp cho các buổi họp cấp cao với sức chứa 15 – 20 khách.\r\n        </p>\r\n        <p>\r\n          Sảnh trang bị màn hình LED hiện đại, hệ thống âm thanh chất lượng cao cùng khả năng hỗ trợ họp online & offline linh hoạt, đảm bảo mọi cuộc họp diễn ra hiệu quả, chuyên nghiệp và liền mạch.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">15 – 20 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Màn hình LED, âm thanh cao cấp</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Hỗ trợ</span>\r\n            <span class=\"cf-spec-value\">Họp online & offline</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Họp cấp cao, VIP</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var cfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function cfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function cfCreateOverlay() {\r\n      if (cfLB.dialog) return\r\n      var pDoc = cfGetParentDoc()\r\n      cfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { cfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      cfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      cfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) cfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); cfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        cfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (cfLB.zoom.scale < 1) { cfLB.zoom.scale = 1; cfLB.zoom.x = 0; cfLB.zoom.y = 0 }\r\n        if (cfLB.zoom.scale > 5) cfLB.zoom.scale = 5\r\n        cfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); cfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); cfLB.zoom.dragging = true\r\n        cfLB.zoom.startX = e.clientX; cfLB.zoom.startY = e.clientY\r\n        cfLB.zoom.lastX = cfLB.zoom.x; cfLB.zoom.lastY = cfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!cfLB.zoom.dragging) return\r\n        cfLB.zoom.x = cfLB.zoom.lastX + (e.clientX - cfLB.zoom.startX) / cfLB.zoom.scale\r\n        cfLB.zoom.y = cfLB.zoom.lastY + (e.clientY - cfLB.zoom.startY) / cfLB.zoom.scale\r\n        cfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { cfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); cfLB.touches.scale0=cfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { cfLB.zoom.dragging=true; cfLB.zoom.startX=e.touches[0].clientX; cfLB.zoom.startY=e.touches[0].clientY; cfLB.zoom.lastX=cfLB.zoom.x; cfLB.zoom.lastY=cfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.zoom.scale=cfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/cfLB.touches.dist); if(cfLB.zoom.scale<1)cfLB.zoom.scale=1;if(cfLB.zoom.scale>5)cfLB.zoom.scale=5; cfApplyZoom() }\r\n        else if (e.touches.length===1&&cfLB.zoom.dragging) { e.preventDefault(); cfLB.zoom.x=cfLB.zoom.lastX+(e.touches[0].clientX-cfLB.zoom.startX)/cfLB.zoom.scale; cfLB.zoom.y=cfLB.zoom.lastY+(e.touches[0].clientY-cfLB.zoom.startY)/cfLB.zoom.scale; cfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { cfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') cfCloseLightbox() })\r\n    }\r\n    function cfResetZoom() { cfLB.zoom.scale=1;cfLB.zoom.x=0;cfLB.zoom.y=0; if(cfLB.img)cfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function cfApplyZoom() { if(cfLB.img)cfLB.img.style.transform=\'scale(\'+cfLB.zoom.scale+\') translate(\'+cfLB.zoom.x+\'px,\'+cfLB.zoom.y+\'px)\' }\r\n    function cfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      cfCreateOverlay()\r\n      cfLB.img.src = img.src; cfResetZoom()\r\n      cfLB.dialog.showModal()\r\n      cfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function cfCloseLightbox() {\r\n      if (cfLB.dialog && cfLB.dialog.open) { cfLB.dialog.close(); cfLB.dialog.style.display = \'\'; cfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Conference & Meeting</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====CONFERENCE=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .cf-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=80\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .cf-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .cf-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .cf-title-section .cf-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .cf-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .cf-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .cf-title-divider::before,\r\n    .cf-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .cf-title-divider .cf-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Room Section--*/\r\n    .cf-room {\r\n      max-width: 1200px;\r\n      margin: 0 auto;\r\n      padding: 50px 30px 30px;\r\n    }\r\n\r\n    .cf-room + .cf-room {\r\n      padding-top: 20px;\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-room-header {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .cf-room-header h2 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 40px;\r\n      font-weight: 200;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.2;\r\n    }\r\n\r\n    .cf-room-header .cf-room-sub {\r\n      font-size: 14px;\r\n      color: #00adef;\r\n      margin-top: 6px;\r\n      letter-spacing: 2px;\r\n    }\r\n\r\n    /*--Room Layout--*/\r\n    .cf-room-body {\r\n      display: flex;\r\n      gap: 40px;\r\n      align-items: flex-start;\r\n    }\r\n\r\n    .cf-room-gallery {\r\n      flex: 1;\r\n      min-width: 0;\r\n    }\r\n\r\n    .cf-room-info {\r\n      width: 360px;\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .cf-room-info p {\r\n      font-size: 16px;\r\n      line-height: 1.8;\r\n      color: #333;\r\n    }\r\n\r\n    .cf-room-info p + p {\r\n      margin-top: 12px;\r\n    }\r\n\r\n    .cf-room-specs {\r\n      margin-top: 24px;\r\n      border-top: 1px solid #d9dee5;\r\n      border-bottom: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec {\r\n      display: flex;\r\n      justify-content: space-between;\r\n      padding: 12px 0;\r\n    }\r\n\r\n    .cf-spec + .cf-spec {\r\n      border-top: 1px solid #d9dee5;\r\n    }\r\n\r\n    .cf-spec-label {\r\n      font-size: 14px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      letter-spacing: 1px;\r\n    }\r\n\r\n    .cf-spec-value {\r\n      font-size: 14px;\r\n      color: #333;\r\n      text-align: right;\r\n    }\r\n\r\n    /*--Photo Grid--*/\r\n    .cf-photo-grid {\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 4px;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n      aspect-ratio: 4/3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:hover img {\r\n      transform: scale(1.05);\r\n    }\r\n\r\n    /* First photo spans 2 columns */\r\n    .cf-photo-grid .cf-photo:first-child {\r\n      grid-column: 1 / 3;\r\n      grid-row: 1 / 3;\r\n    }\r\n\r\n    .cf-photo-grid .cf-photo:first-child img {\r\n      aspect-ratio: auto;\r\n      height: 100%;\r\n    }\r\n\r\n    /*--Tulip single image--*/\r\n    .cf-photo-single {\r\n      max-width: 700px;\r\n      margin: 0 auto;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo {\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      border-radius: 0;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo img {\r\n      width: 100%;\r\n      display: block;\r\n      border-radius: 0;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .cf-photo-single .cf-photo:hover img {\r\n      transform: scale(1.02);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 1024px) {\r\n      .cf-room-body {\r\n        flex-direction: column;\r\n      }\r\n\r\n      .cf-room-info {\r\n        width: 100%;\r\n        text-align: center;\r\n      }\r\n\r\n      .cf-title-section h1 {\r\n        font-size: 44px;\r\n        letter-spacing: 5px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 32px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 768px) {\r\n      .cf-title-section h1 {\r\n        font-size: 34px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 26px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 30px 20px 20px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-photo-grid .cf-photo:first-child {\r\n        grid-column: 1 / 3;\r\n        grid-row: auto;\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 15px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .cf-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 2px;\r\n      }\r\n\r\n      .cf-title-section .cf-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .cf-room-header h2 {\r\n        font-size: 22px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .cf-room {\r\n        padding: 20px 15px 15px;\r\n      }\r\n\r\n      .cf-photo-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n      }\r\n\r\n      .cf-room-info p {\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n      }\r\n\r\n      .cf-spec-label,\r\n      .cf-spec-value {\r\n        font-size: 13px;\r\n      }\r\n      \r\n      .cf-title-divider::before,\r\n      .cf-title-divider::after {\r\n        width: 50px;\r\n      }\r\n    }\r\n    /*--VR360 Button--*/\r\n    .cf-vr-btn {\r\n      display: flex;\r\n      justify-content: center;\r\n      margin: 20px 0 10px;\r\n    }\r\n\r\n    .cf-vr-btn a {\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      padding: 12px 32px;\r\n      background: #0e4d97;\r\n      color: #fff;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      text-decoration: none;\r\n      transition: background .3s ease;\r\n    }\r\n\r\n    .cf-vr-btn a:hover {\r\n      background: #00adef;\r\n    }\r\n\r\n    .cf-vr-btn a svg {\r\n      width: 18px;\r\n      height: 18px;\r\n      fill: currentColor;\r\n      flex-shrink: 0;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"cf-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"cf-title-section\">\r\n    <div class=\"cf-label\">Ruby 68 Hotel</div>\r\n    <h1>Conference & Meeting</h1>\r\n    <div class=\"cf-title-divider\"><div class=\"cf-diamond\"></div></div>\r\n  </div>\r\n\r\n  \r\n\r\n  <!-- Sec3: Ruby Ballroom -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Ruby Ballroom</h2>\r\n      <div class=\"cf-room-sub\">FLOOR 3 • EVENT & BANQUET HALL</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-grid\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1431540015161-0bf868a2d407?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1497366811353-6870744d04b2?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1587825140708-dfaf72ae4b04?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1517502884422-41eaead166d4?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1524758631624-e2822e304c36?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1497366754035-f200968a6e72?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1505373877841-8d25f7d46678?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1511578314322-379afb476865?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1560439514-4e9645039924?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Ballroom\"></div>\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1521737604893-d14cc237f11d?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Ballroom\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Tọa lạc tại tầng 3, Ruby Ballroom là lựa chọn lý tưởng cho tiệc cưới, hội nghị và sự kiện tại Vũng Tàu với sức chứa 120 – 150 khách.\r\n        </p>\r\n        <p>\r\n          Không gian được thiết kế hiện đại, tinh tế, kết hợp hệ thống âm thanh – ánh sáng chuẩn 3 sao và tầm nhìn hướng biển ấn tượng. Thực đơn Á – Âu đa dạng, dịch vụ chuyên nghiệp, chỉn chu từng chi tiết cùng không gian linh hoạt cho nhiều concept sự kiện.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Vị trí</span>\r\n            <span class=\"cf-spec-value\">Tầng 3</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">120 – 150 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Âm thanh – ánh sáng chuẩn 3 sao</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Tiệc cưới, hội nghị, sự kiện</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <!-- Sec4: Tulip Meeting Room -->\r\n  <section class=\"cf-room\">\r\n    <div class=\"cf-room-header\">\r\n      <h2>Tulip Meeting Room</h2>\r\n      <div class=\"cf-room-sub\">VIP MEETING ROOM</div>\r\n    </div>\r\n    <div class=\"cf-room-body\">\r\n      <div class=\"cf-room-gallery\">\r\n        <div class=\"cf-photo-single\">\r\n          <div class=\"cf-photo\" onclick=\"cfOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1550966871-3ed3cdb5ed0c?auto=format&fit=crop&w=1200&q=80\" alt=\"Tulip Meeting Room\"></div>\r\n        </div>\r\n      </div>\r\n      <div class=\"cf-room-info\">\r\n        <p>\r\n          Không gian phòng họp VIP riêng tư tại Ruby 68 Hotel, sảnh Tulip phù hợp cho các buổi họp cấp cao với sức chứa 15 – 20 khách.\r\n        </p>\r\n        <p>\r\n          Sảnh trang bị màn hình LED hiện đại, hệ thống âm thanh chất lượng cao cùng khả năng hỗ trợ họp online & offline linh hoạt, đảm bảo mọi cuộc họp diễn ra hiệu quả, chuyên nghiệp và liền mạch.\r\n        </p>\r\n        <div class=\"cf-room-specs\">\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Sức chứa</span>\r\n            <span class=\"cf-spec-value\">15 – 20 khách</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Trang bị</span>\r\n            <span class=\"cf-spec-value\">Màn hình LED, âm thanh cao cấp</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Hỗ trợ</span>\r\n            <span class=\"cf-spec-value\">Họp online & offline</span>\r\n          </div>\r\n          <div class=\"cf-spec\">\r\n            <span class=\"cf-spec-label\">Phù hợp</span>\r\n            <span class=\"cf-spec-value\">Họp cấp cao, VIP</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var cfLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function cfGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function cfCreateOverlay() {\r\n      if (cfLB.dialog) return\r\n      var pDoc = cfGetParentDoc()\r\n      cfLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { cfCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;border-radius:0;cursor:grab;\'\r\n      cfLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      cfLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) cfCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); cfCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        cfLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (cfLB.zoom.scale < 1) { cfLB.zoom.scale = 1; cfLB.zoom.x = 0; cfLB.zoom.y = 0 }\r\n        if (cfLB.zoom.scale > 5) cfLB.zoom.scale = 5\r\n        cfApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); cfResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); cfLB.zoom.dragging = true\r\n        cfLB.zoom.startX = e.clientX; cfLB.zoom.startY = e.clientY\r\n        cfLB.zoom.lastX = cfLB.zoom.x; cfLB.zoom.lastY = cfLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!cfLB.zoom.dragging) return\r\n        cfLB.zoom.x = cfLB.zoom.lastX + (e.clientX - cfLB.zoom.startX) / cfLB.zoom.scale\r\n        cfLB.zoom.y = cfLB.zoom.lastY + (e.clientY - cfLB.zoom.startY) / cfLB.zoom.scale\r\n        cfApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { cfLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.touches.dist=Math.sqrt(dx*dx+dy*dy); cfLB.touches.scale0=cfLB.zoom.scale }\r\n        else if (e.touches.length === 1) { cfLB.zoom.dragging=true; cfLB.zoom.startX=e.touches[0].clientX; cfLB.zoom.startY=e.touches[0].clientY; cfLB.zoom.lastX=cfLB.zoom.x; cfLB.zoom.lastY=cfLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; cfLB.zoom.scale=cfLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/cfLB.touches.dist); if(cfLB.zoom.scale<1)cfLB.zoom.scale=1;if(cfLB.zoom.scale>5)cfLB.zoom.scale=5; cfApplyZoom() }\r\n        else if (e.touches.length===1&&cfLB.zoom.dragging) { e.preventDefault(); cfLB.zoom.x=cfLB.zoom.lastX+(e.touches[0].clientX-cfLB.zoom.startX)/cfLB.zoom.scale; cfLB.zoom.y=cfLB.zoom.lastY+(e.touches[0].clientY-cfLB.zoom.startY)/cfLB.zoom.scale; cfApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { cfLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') cfCloseLightbox() })\r\n    }\r\n    function cfResetZoom() { cfLB.zoom.scale=1;cfLB.zoom.x=0;cfLB.zoom.y=0; if(cfLB.img)cfLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function cfApplyZoom() { if(cfLB.img)cfLB.img.style.transform=\'scale(\'+cfLB.zoom.scale+\') translate(\'+cfLB.zoom.x+\'px,\'+cfLB.zoom.y+\'px)\' }\r\n    function cfOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      cfCreateOverlay()\r\n      cfLB.img.src = img.src; cfResetZoom()\r\n      cfLB.dialog.showModal()\r\n      cfLB.dialog.style.display = \'flex\'\r\n    }\r\n    function cfCloseLightbox() {\r\n      if (cfLB.dialog && cfLB.dialog.open) { cfLB.dialog.close(); cfLB.dialog.style.display = \'\'; cfResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-08-04 08:10:14', '2026-08-04 08:10:14');
INSERT INTO `revisions` (`id`, `revisionable_type`, `revisionable_id`, `user_id`, `key`, `old_value`, `new_value`, `created_at`, `updated_at`) VALUES
(330, 'Botble\\Page\\Models\\Page', 23, 3, 'custom_html', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Spa</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SPA=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sp-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://images.unsplash.com/photo-1560750588-73207b1ef5b8?auto=format&fit=crop&w=1600&q=80\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sp-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-title-section .sp-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sp-title-divider::before,\r\n    .sp-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-title-divider .sp-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sp-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sp-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sp-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sp-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line::before,\r\n    .sp-gallery-heading .sp-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sp-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sp-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sp-title-section .sp-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sp-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n    /*--VR360 Button--*/\r\n    .sp-vr-btn {\r\n      display: flex;\r\n      justify-content: center;\r\n      margin: 20px 0 10px;\r\n    }\r\n\r\n    .sp-vr-btn a {\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      padding: 12px 32px;\r\n      background: #0e4d97;\r\n      color: #fff;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      text-decoration: none;\r\n      transition: background .3s ease;\r\n    }\r\n\r\n    .sp-vr-btn a:hover {\r\n      background: #00adef;\r\n    }\r\n\r\n    .sp-vr-btn a svg {\r\n      width: 18px;\r\n      height: 18px;\r\n      fill: currentColor;\r\n      flex-shrink: 0;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sp-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sp-title-section\">\r\n    <div class=\"sp-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby Spa</h1>\r\n    <div class=\"sp-title-divider\">\r\n      <div class=\"sp-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  <div class=\"sp-vr-btn\">\r\n    <a href=\"https://360.botonbluehotels.com/#media=74&yaw=36.07&pitch=-0.61&fov=105.00\" target=\"_blank\" rel=\"noopener\">\r\n      <svg viewBox=\"0 0 24 24\" xmlns=\"http://www.w3.org/2000/svg\"><path d=\"M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z\"/></svg>\r\n      Tham quan 360°\r\n    </a>\r\n  </div>\r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sp-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 khách sạn, trong không gian yên tĩnh và riêng tư, Ruby Spa là điểm đến lý tưởng để tái tạo năng lượng và cân bằng cảm xúc.\r\n    </p>\r\n    <p>\r\n      Các liệu trình được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuyên sâu và nguyên liệu cao cấp, mang đến trải nghiệm thư giãn toàn diện cho cơ thể và tâm trí.\r\n    </p>\r\n    <p>\r\n      Từ massage thư giãn, chăm sóc da đến các liệu pháp phục hồi, mỗi hành trình tại Ruby Spa đều được chăm chút tỉ mỉ, giúp bạn tận hưởng trọn vẹn sự an yên trong chuẩn mực dịch vụ 3 sao.\r\n    </p>\r\n    <div class=\"sp-time\">Mở cửa hàng ngày từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sp-gallery-section\">\r\n    <div class=\"sp-gallery-heading\">\r\n      <div class=\"sp-heading-line\">\r\n        <div class=\"sp-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sp-heading-sub\">Ruby Spa</div>\r\n      <div class=\"sp-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sp-gallery-grid\">\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1560750588-73207b1ef5b8?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1620733723572-11c53f73a416?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1620733723572-11c53f73a416?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1560750588-73207b1ef5b8?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1544161515-4ab6ce6db874?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1600334089648-b0d9d3028eb2?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var spLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function spGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function spCreateOverlay() {\r\n      if (spLB.dialog) return\r\n      var pDoc = spGetParentDoc()\r\n      spLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { spCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      spLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      spLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) spCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); spCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        spLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (spLB.zoom.scale < 1) { spLB.zoom.scale = 1; spLB.zoom.x = 0; spLB.zoom.y = 0 }\r\n        if (spLB.zoom.scale > 5) spLB.zoom.scale = 5\r\n        spApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); spResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); spLB.zoom.dragging = true\r\n        spLB.zoom.startX = e.clientX; spLB.zoom.startY = e.clientY\r\n        spLB.zoom.lastX = spLB.zoom.x; spLB.zoom.lastY = spLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!spLB.zoom.dragging) return\r\n        spLB.zoom.x = spLB.zoom.lastX + (e.clientX - spLB.zoom.startX) / spLB.zoom.scale\r\n        spLB.zoom.y = spLB.zoom.lastY + (e.clientY - spLB.zoom.startY) / spLB.zoom.scale\r\n        spApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { spLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.touches.dist=Math.sqrt(dx*dx+dy*dy); spLB.touches.scale0=spLB.zoom.scale }\r\n        else if (e.touches.length === 1) { spLB.zoom.dragging=true; spLB.zoom.startX=e.touches[0].clientX; spLB.zoom.startY=e.touches[0].clientY; spLB.zoom.lastX=spLB.zoom.x; spLB.zoom.lastY=spLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.zoom.scale=spLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/spLB.touches.dist); if(spLB.zoom.scale<1)spLB.zoom.scale=1;if(spLB.zoom.scale>5)spLB.zoom.scale=5; spApplyZoom() }\r\n        else if (e.touches.length===1&&spLB.zoom.dragging) { e.preventDefault(); spLB.zoom.x=spLB.zoom.lastX+(e.touches[0].clientX-spLB.zoom.startX)/spLB.zoom.scale; spLB.zoom.y=spLB.zoom.lastY+(e.touches[0].clientY-spLB.zoom.startY)/spLB.zoom.scale; spApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { spLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') spCloseLightbox() })\r\n    }\r\n    function spResetZoom() { spLB.zoom.scale=1;spLB.zoom.x=0;spLB.zoom.y=0; if(spLB.img)spLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function spApplyZoom() { if(spLB.img)spLB.img.style.transform=\'scale(\'+spLB.zoom.scale+\') translate(\'+spLB.zoom.x+\'px,\'+spLB.zoom.y+\'px)\' }\r\n    function spOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      spCreateOverlay()\r\n      spLB.img.src = img.src; spResetZoom()\r\n      spLB.dialog.showModal()\r\n      spLB.dialog.style.display = \'flex\'\r\n    }\r\n    function spCloseLightbox() {\r\n      if (spLB.dialog && spLB.dialog.open) { spLB.dialog.close(); spLB.dialog.style.display = \'\'; spResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '<!DOCTYPE html>\r\n<html lang=\"vi\">\r\n\r\n<head>\r\n  <meta charset=\"UTF-8\">\r\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n  <title>Ruby Spa</title>\r\n  <link href=\"https://fonts.googleapis.com/css2?family=Antonio:wght@100;200;300;400;500&display=swap\" rel=\"stylesheet\">\r\n  <style>\r\n    /*=====RUBY SPA=====*/\r\n\r\n    * {\r\n      margin: 0;\r\n      padding: 0;\r\n      box-sizing: border-box;\r\n    }\r\n\r\n    body {\r\n      overflow-x: hidden;\r\n      background: #fff;\r\n      font-family: Arial, Helvetica, sans-serif;\r\n    }\r\n\r\n    /*--Sec1: Hero Banner--*/\r\n    .sp-hero {\r\n      width: 100%;\r\n      height: 55vw;\r\n      max-height: 600px;\r\n      background: url(\"https://images.unsplash.com/photo-1540555700478-4be289fbecef?auto=format&fit=crop&w=1600&q=80\") center/cover no-repeat;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-hero::after {\r\n      content: \"\";\r\n      position: absolute;\r\n      bottom: 0;\r\n      left: 0;\r\n      width: 100%;\r\n      height: 40%;\r\n      background: linear-gradient(to top, rgba(255,255,255,1) 0%, rgba(255,255,255,0) 100%);\r\n    }\r\n\r\n    /*--Sec2: Title--*/\r\n    .sp-title-section {\r\n      text-align: center;\r\n      padding: 30px 20px 10px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-title-section .sp-label {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-title-section h1 {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 56px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      text-transform: uppercase;\r\n      color: #0e4d97;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-title-divider {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 16px;\r\n      margin-top: 16px;\r\n    }\r\n\r\n    .sp-title-divider::before,\r\n    .sp-title-divider::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-title-divider .sp-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    /*--Sec3: Content--*/\r\n    .sp-content {\r\n      max-width: 900px;\r\n      margin: 0 auto;\r\n      padding: 30px 30px 40px;\r\n      text-align: center;\r\n    }\r\n\r\n    .sp-content p {\r\n      font-size: 17px;\r\n      line-height: 1.9;\r\n      color: #444;\r\n      margin-bottom: 14px;\r\n    }\r\n\r\n    .sp-time {\r\n      display: inline-block;\r\n      margin-top: 10px;\r\n      font-size: 16px;\r\n      font-style: italic;\r\n      color: #0e4d97;\r\n      font-weight: 600;\r\n      border: 1px solid #d9dee5;\r\n      padding: 10px 30px;\r\n    }\r\n\r\n    /*--Sec4: Photo Gallery--*/\r\n    .sp-gallery-section {\r\n      padding: 0 30px 50px;\r\n      background: #fff;\r\n    }\r\n\r\n    .sp-gallery-heading {\r\n      text-align: center;\r\n      margin-bottom: 30px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line {\r\n      display: flex;\r\n      align-items: center;\r\n      justify-content: center;\r\n      gap: 20px;\r\n      margin-bottom: 8px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-line::before,\r\n    .sp-gallery-heading .sp-heading-line::after {\r\n      content: \'\';\r\n      height: 1px;\r\n      width: 80px;\r\n      background: linear-gradient(to right, transparent, #00adef, #0e4d97, #00adef, transparent);\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-diamond {\r\n      width: 10px;\r\n      height: 10px;\r\n      background: linear-gradient(135deg, #00adef, #0e4d97);\r\n      transform: rotate(45deg);\r\n      flex-shrink: 0;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-sub {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 6px;\r\n      text-transform: uppercase;\r\n      color: #00adef;\r\n      margin-bottom: 6px;\r\n    }\r\n\r\n    .sp-gallery-heading .sp-heading-main {\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 42px;\r\n      font-weight: 200;\r\n      letter-spacing: 8px;\r\n      color: #0e4d97;\r\n      text-transform: uppercase;\r\n      line-height: 1.1;\r\n    }\r\n\r\n    .sp-gallery-grid {\r\n      max-width: 1100px;\r\n      margin: 0 auto;\r\n      display: grid;\r\n      grid-template-columns: repeat(3, 1fr);\r\n      gap: 12px;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo {\r\n      aspect-ratio: 1 / 1;\r\n      overflow: hidden;\r\n      cursor: pointer;\r\n      position: relative;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo img {\r\n      width: 100%;\r\n      height: 100%;\r\n      object-fit: cover;\r\n      display: block;\r\n      transition: transform .4s ease;\r\n    }\r\n\r\n    .sp-gallery-grid .sp-photo:hover img {\r\n      transform: scale(1.06);\r\n    }\r\n\r\n    /*--RESPONSIVE--*/\r\n    @media (max-width: 768px) {\r\n      .sp-hero {\r\n        height: 60vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 36px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 15px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 8px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 32px;\r\n        letter-spacing: 4px;\r\n      }\r\n    }\r\n\r\n    @media (max-width: 480px) {\r\n      .sp-hero {\r\n        height: 70vw;\r\n      }\r\n\r\n      .sp-title-section h1 {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n\r\n      .sp-title-section .sp-label {\r\n        font-size: 11px;\r\n        letter-spacing: 4px;\r\n      }\r\n\r\n      .sp-content {\r\n        padding: 20px 15px 30px;\r\n      }\r\n\r\n      .sp-content p {\r\n        font-size: 14px;\r\n        line-height: 1.7;\r\n      }\r\n\r\n      .sp-gallery-section {\r\n        padding: 0 15px 40px;\r\n      }\r\n\r\n      .sp-gallery-grid {\r\n        grid-template-columns: repeat(2, 1fr);\r\n        gap: 6px;\r\n      }\r\n\r\n      .sp-gallery-heading .sp-heading-main {\r\n        font-size: 26px;\r\n        letter-spacing: 3px;\r\n      }\r\n    }\r\n    /*--VR360 Button--*/\r\n    .sp-vr-btn {\r\n      display: flex;\r\n      justify-content: center;\r\n      margin: 20px 0 10px;\r\n    }\r\n\r\n    .sp-vr-btn a {\r\n      display: inline-flex;\r\n      align-items: center;\r\n      gap: 10px;\r\n      padding: 12px 32px;\r\n      background: #0e4d97;\r\n      color: #fff;\r\n      font-family: \'Antonio\', sans-serif;\r\n      font-size: 13px;\r\n      font-weight: 300;\r\n      letter-spacing: 4px;\r\n      text-transform: uppercase;\r\n      text-decoration: none;\r\n      transition: background .3s ease;\r\n    }\r\n\r\n    .sp-vr-btn a:hover {\r\n      background: #00adef;\r\n    }\r\n\r\n    .sp-vr-btn a svg {\r\n      width: 18px;\r\n      height: 18px;\r\n      fill: currentColor;\r\n      flex-shrink: 0;\r\n    }\r\n  </style>\r\n</head>\r\n\r\n<body>\r\n\r\n  <!-- Sec1: Hero Banner -->\r\n  <div class=\"sp-hero\"></div>\r\n\r\n  <!-- Sec2: Title -->\r\n  <div class=\"sp-title-section\">\r\n    <div class=\"sp-label\">Ruby 68 Hotel</div>\r\n    <h1>Ruby Spa</h1>\r\n    <div class=\"sp-title-divider\">\r\n      <div class=\"sp-diamond\"></div>\r\n    </div>\r\n  </div>\r\n\r\n  \r\n\r\n  <!-- Sec3: Content -->\r\n  <div class=\"sp-content\">\r\n    <p>\r\n      Tọa lạc tại tầng 6 khách sạn, trong không gian yên tĩnh và riêng tư, Ruby Spa là điểm đến lý tưởng để tái tạo năng lượng và cân bằng cảm xúc.\r\n    </p>\r\n    <p>\r\n      Các liệu trình được thiết kế tinh tế, kết hợp giữa kỹ thuật trị liệu chuyên sâu và nguyên liệu cao cấp, mang đến trải nghiệm thư giãn toàn diện cho cơ thể và tâm trí.\r\n    </p>\r\n    <p>\r\n      Từ massage thư giãn, chăm sóc da đến các liệu pháp phục hồi, mỗi hành trình tại Ruby Spa đều được chăm chút tỉ mỉ, giúp bạn tận hưởng trọn vẹn sự an yên trong chuẩn mực dịch vụ 3 sao.\r\n    </p>\r\n    <div class=\"sp-time\">Mở cửa hàng ngày từ 10:00 đến 21:00</div>\r\n  </div>\r\n\r\n  <!-- Sec4: Photo Gallery -->\r\n  <section class=\"sp-gallery-section\">\r\n    <div class=\"sp-gallery-heading\">\r\n      <div class=\"sp-heading-line\">\r\n        <div class=\"sp-heading-diamond\"></div>\r\n      </div>\r\n      <div class=\"sp-heading-sub\">Ruby Spa</div>\r\n      <div class=\"sp-heading-main\">Gallery</div>\r\n    </div>\r\n    <div class=\"sp-gallery-grid\">\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1544161515-4ab6ce6db874?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1600334089648-b0d9d3028eb2?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1620733723572-11c53f73a416?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1519823551278-64ac92734fb1?auto=format&fit=crop&w=1600&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1512290923902-8a9f81dc236c?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1515377905703-c4788e51af15?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Spa\"></div>\r\n      <div class=\"sp-photo\" onclick=\"spOpenLightbox(this)\"><img src=\"https://images.unsplash.com/photo-1613977257363-707ba9348227?auto=format&fit=crop&w=1200&q=80\" alt=\"Ruby Spa\"></div>\r\n    </div>\r\n  </section>\r\n\r\n  <script>\r\n    /* ========= LIGHTBOX (dialog in parent document to escape CMS iframe) ========= */\r\n    var spLB = { dialog: null, img: null, pDoc: null, zoom: { scale:1, x:0, y:0, dragging:false, startX:0, startY:0, lastX:0, lastY:0 }, touches: { dist:0, scale0:1 } }\r\n\r\n    function spGetParentDoc() {\r\n      try { if (window.self !== window.top && window.parent.document) return window.parent.document } catch(e) {}\r\n      return document\r\n    }\r\n\r\n    function spCreateOverlay() {\r\n      if (spLB.dialog) return\r\n      var pDoc = spGetParentDoc()\r\n      spLB.pDoc = pDoc\r\n      var d = pDoc.createElement(\'dialog\')\r\n      d.style.cssText = \'position:fixed;inset:0;border:none;padding:0;margin:0;background:rgba(0,0,0,0.92);max-width:none;max-height:none;width:100vw;height:100vh;justify-content:center;align-items:center;overflow:hidden;\'\r\n      var btn = pDoc.createElement(\'button\')\r\n      btn.innerHTML = \'×\'\r\n      btn.style.cssText = \'position:absolute;top:20px;right:30px;font-size:40px;color:#fff;background:none;border:none;cursor:pointer;z-index:10;\'\r\n      btn.onclick = function() { spCloseLightbox() }\r\n      var img = pDoc.createElement(\'img\')\r\n      img.style.cssText = \'max-width:90vw;max-height:90vh;object-fit:contain;cursor:grab;\'\r\n      spLB.img = img\r\n      d.appendChild(btn); d.appendChild(img)\r\n      spLB.dialog = d\r\n      pDoc.body.appendChild(d)\r\n      d.addEventListener(\'click\', function(e) { if (e.target === d) spCloseLightbox() })\r\n      d.addEventListener(\'cancel\', function(e) { e.preventDefault(); spCloseLightbox() })\r\n      d.addEventListener(\'wheel\', function(e) {\r\n        e.preventDefault()\r\n        spLB.zoom.scale += e.deltaY > 0 ? -0.3 : 0.3\r\n        if (spLB.zoom.scale < 1) { spLB.zoom.scale = 1; spLB.zoom.x = 0; spLB.zoom.y = 0 }\r\n        if (spLB.zoom.scale > 5) spLB.zoom.scale = 5\r\n        spApplyZoom()\r\n      }, { passive: false })\r\n      img.addEventListener(\'dblclick\', function(e) { e.stopPropagation(); spResetZoom() })\r\n      img.addEventListener(\'mousedown\', function(e) {\r\n        e.preventDefault(); spLB.zoom.dragging = true\r\n        spLB.zoom.startX = e.clientX; spLB.zoom.startY = e.clientY\r\n        spLB.zoom.lastX = spLB.zoom.x; spLB.zoom.lastY = spLB.zoom.y\r\n      })\r\n      img.addEventListener(\'click\', function(e) { e.stopPropagation() })\r\n      pDoc.addEventListener(\'mousemove\', function(e) {\r\n        if (!spLB.zoom.dragging) return\r\n        spLB.zoom.x = spLB.zoom.lastX + (e.clientX - spLB.zoom.startX) / spLB.zoom.scale\r\n        spLB.zoom.y = spLB.zoom.lastY + (e.clientY - spLB.zoom.startY) / spLB.zoom.scale\r\n        spApplyZoom()\r\n      })\r\n      pDoc.addEventListener(\'mouseup\', function() { spLB.zoom.dragging = false })\r\n      img.addEventListener(\'touchstart\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.touches.dist=Math.sqrt(dx*dx+dy*dy); spLB.touches.scale0=spLB.zoom.scale }\r\n        else if (e.touches.length === 1) { spLB.zoom.dragging=true; spLB.zoom.startX=e.touches[0].clientX; spLB.zoom.startY=e.touches[0].clientY; spLB.zoom.lastX=spLB.zoom.x; spLB.zoom.lastY=spLB.zoom.y }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchmove\', function(e) {\r\n        if (e.touches.length === 2) { e.preventDefault(); var dx=e.touches[0].clientX-e.touches[1].clientX,dy=e.touches[0].clientY-e.touches[1].clientY; spLB.zoom.scale=spLB.touches.scale0*(Math.sqrt(dx*dx+dy*dy)/spLB.touches.dist); if(spLB.zoom.scale<1)spLB.zoom.scale=1;if(spLB.zoom.scale>5)spLB.zoom.scale=5; spApplyZoom() }\r\n        else if (e.touches.length===1&&spLB.zoom.dragging) { e.preventDefault(); spLB.zoom.x=spLB.zoom.lastX+(e.touches[0].clientX-spLB.zoom.startX)/spLB.zoom.scale; spLB.zoom.y=spLB.zoom.lastY+(e.touches[0].clientY-spLB.zoom.startY)/spLB.zoom.scale; spApplyZoom() }\r\n      }, { passive: false })\r\n      img.addEventListener(\'touchend\', function() { spLB.zoom.dragging = false })\r\n      pDoc.addEventListener(\'keydown\', function(e) { if (e.key === \'Escape\') spCloseLightbox() })\r\n    }\r\n    function spResetZoom() { spLB.zoom.scale=1;spLB.zoom.x=0;spLB.zoom.y=0; if(spLB.img)spLB.img.style.transform=\'scale(1) translate(0px,0px)\' }\r\n    function spApplyZoom() { if(spLB.img)spLB.img.style.transform=\'scale(\'+spLB.zoom.scale+\') translate(\'+spLB.zoom.x+\'px,\'+spLB.zoom.y+\'px)\' }\r\n    function spOpenLightbox(el) {\r\n      var img = el.querySelector(\'img\'); if(!img) return\r\n      spCreateOverlay()\r\n      spLB.img.src = img.src; spResetZoom()\r\n      spLB.dialog.showModal()\r\n      spLB.dialog.style.display = \'flex\'\r\n    }\r\n    function spCloseLightbox() {\r\n      if (spLB.dialog && spLB.dialog.open) { spLB.dialog.close(); spLB.dialog.style.display = \'\'; spResetZoom() }\r\n    }\r\n  </script>\r\n\r\n</body>\r\n\r\n</html>', '2026-08-04 08:10:55', '2026-08-04 08:10:55');
