INSERT INTO `testimonials` (`id`, `name`, `content`, `image`, `company`, `status`, `created_at`, `updated_at`) VALUES
(1, 'Adam Williams', 'A true gem! Impeccable service, stunning views, and utmost comfort. Our stay was pure perfection. Planning our return!', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?auto=format&fit=crop&w=400&h=400&q=80', 'CEO Of Microsoft', 'published', '2025-06-10 10:38:15', '2025-06-10 10:38:15'),
(2, 'Retha Deowalim', 'Exceeded expectations in every way. Elegant rooms, delectable dining. Our stay was pure perfection. 5 stars!\"', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?auto=format&fit=crop&w=400&h=400&q=80', 'CEO Of Apple', 'published', '2025-06-10 10:38:15', '2025-06-10 10:38:15'),
(3, 'Sam J. Wasim', 'Paradise found. Serene ambiance, exceptional amenities, and warm hospitality. Already planning our return!', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?auto=format&fit=crop&w=400&h=400&q=80', 'Pio Founder', 'published', '2025-06-10 10:38:15', '2025-06-10 10:38:15'),
(4, 'Daniel Rodriguez', 'An exceptional experience from start to finish. The attention to detail, combined with breathtaking surroundings.', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?auto=format&fit=crop&w=400&h=400&q=80', 'VP Of Google', 'published', '2025-06-10 10:38:15', '2025-06-10 10:38:15'),
(5, 'Daniel Chang', 'A true haven for relaxation. Every aspect of our stay, from the luxurious rooms to the exquisite dining, was exceptional.', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?auto=format&fit=crop&w=400&h=400&q=80', 'Founder Of SpaceX', 'published', '2025-06-10 10:38:15', '2025-06-10 10:38:15'),
(6, 'Isabella Russo', 'Indulgence at its finest. The blend of modern luxury and natural beauty exceeded our expectations, was exceptional.', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?auto=format&fit=crop&w=400&h=400&q=80', 'Fashion Designer', 'published', '2025-06-10 10:38:15', '2025-06-10 10:38:15');
